    ["01-2"] = {name="Durotar: Sen'jin & Razor Hill", short="Durotar: Sen'jin +", tips={{k="取捨", text="Do Carry Your Weight. Collect Canvas Scraps alongside the other Tiragarde Keep objectives."}, {k="取捨", text="Turn in Vanquish the Betrayers to unlock From The Wreckage..... Do it alongside A Solvent Spirit."}, {k="取捨", text="Save the Cleft of Shadow dungeon chain. If you plan to run Ragefire Chasm, take Hidden Enemies ( → Hidden Enemies → Hidden Enemies) from Thrall. Get the badge for Hidden Enemies from the Burning Blade camp to the north."}, {k="提醒", text="Below level 12? Do Securing the Lines, Skull Rock, or the first few Threat from Below quests.", s={{"Below level 12?"}, {"Do Securing the Lines, Skull Rock, or the first few Threat from Below quests"}}}}, danger={[1]="The stairs and doorways in Tiragarde Keep can pull sailors from upstairs. Clear the outer wall and entrance first.", [2]="Sea giants roam the naga area on the north shore. Clear nearby mobs before pulling one. Retreat along the shore if you get in trouble."}, grind={[1]={mob="Kul Tiras Marine", note="Dense normal mobs at Tiragarde Keep. Pull outside to avoid adds in the halls. Collect Canvas Scraps for the new bag."}, [2]={mob="Razormane Battleguard", note="Normal mobs cluster west of Razor Hill. Pull along the camp edge and watch for patrols. Pair with Encroachment."}, [3]={mob="Dustwind Storm Witch", note="Normal mobs cluster in northern Durotar. Use cover to draw casters close. Do Securing the Lines or grind to 12 before Orgrimmar."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Innkeeper Grosk"}, [3]={npc="Wuark"}, [4]={npc="Innkeeper Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Look for Ukor on the road from the Valley of Trials to Sen'jin Village."}, [2]={hint="Speak with Master Gadrin in Sen'jin Village."}, [3]={npc="Master Gadrin", tgt="Master Gadrin"}, [4]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [5]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [6