    ["01-3"] = {name="Camp Narache", tips={{k="交通", text="Coming from another starting zone? Head to Bloodhoof Village, then follow the road south up Red Cloud Mesa to Camp Narache. See the travel notes above."}, {k="取捨", text="Do Rite of Strength, Break Sharptusk!, and The Battleboars on one Brambleblade Ravine loop. Accept Attack on Camp Narache if you loot the map."}, {k="提醒", text="Below level 6? Grind Battleboars or Bristleback quilboar along the edge of Brambleblade Ravine, then head to Bloodhoof Village.", s={{"Below level 6?"}, {"Grind Battleboars or Bristleback quilboar along the edge of Brambleblade Ravine, then head to Bloodhoof Village"}}}}, danger={[1]="Quilboar pack the narrow ramp in Brambleblade Ravine. Clear it before pulling Chief Sharptusk Thornmantle. Retreat toward Red Cloud Mesa."}, grind={[1]={mob="Plainstrider", note="Dense, mostly neutral normal mobs by Camp Narache's southeast well. Pull singles during The Hunt Begins."}, [2]={mob="Mountain Cougar", note="Dense, mostly neutral normal mobs on Red Cloud Mesa's south slope. Pull singles for the pelts needed in The Hunt Continues."}, [3]={mob="Bristleback Battleboar", note="Normal mobs cluster among Bristleback quilboar in Brambleblade Ravine. Clear the edges first. Pair with Battleboar and Rite of Strength."}}, supply={[1]={npc="Bronk Steelrage"}, [2]={npc="Moodan Sungrain"}, [3]={npc="Kawnie Softbreeze"}}, steps={[1]={npc="Camp Narache Gift Voucher", npcObj=true, tag="Optional, Unverified", desc="Accept only if you have a Camp Narache Gift Voucher. Right-click your race's starting voucher. There's no pickup on the map."}, [2]={hint="Bring the Camp Narache Gift Voucher to Vorn Skyseer.", tag="Optional", desc="Accept only if you have a Camp Narache Gift Voucher."}, [3]={npc="Vorn Skyseer", tgt="Vorn Skyseer", tag="Optional", desc="Accept only if you have a Camp Narache Gift Voucher."}, [4]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [5]={npc="Chief Hawkwind", tgt="Chief Hawkwind"}, [6]={hint="Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat."}, [7]={hint="Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache."}, [8]={npc="Greatmother Hawkwind", tgt="Greatmother Hawkwind"}, [9]={npc="Greatmother Hawkwind", tgt="Greatmother Hawkwind"}, [10]={hint="Take a Water Pitcher from the water well.", desc="Get the Water Pitcher from the well next to Greatmother Hawkwind."}, [11]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [12]={npc="Chief Hawkwind", tgt="Chief Hawkwind"}, [13]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [14]={npc="Chief Hawkwind", tgt="Chief Hawkwind"}, [15]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [16]={hint="Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts."}, [17]={hint="Travel to Seer Graytongue who lives in the hills directly south of Camp Narache."}, [18]={npc="Seer Graytongue", tgt="Seer Graytongue"}, [19]={npc="Seer Graytongue", tgt="Seer Graytongue"}, [20]={npc="Seer Graytongue", tgt="Seer Graytongue", tag="Optional", desc="Bring the incense to the southeast altar within 10 minutes of receiving it.", star={"Scorched Leather Pouch"}}, [21]={hint="Carry the Smoldering Incense to the shrine of An'she and Mu'sha in the southeastern hills before the incense burns to ash in ten minutes!", tag="Optional", desc="Bring the incense to the southeast altar within 10 minutes of receiving it."}, [22]={npc="Ritual Fire", npcObj=true, tag="Optional", desc="Bring the incense to the southeast altar within 10 minutes of receiving it.", star={"Scorched Leather Pouch"}}, [23]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [24]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [25]={hint="Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache."}, [26]={hint="Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa."}, [27]={hint="Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks."}, [28]={npc="Dirt-stained Map", npcObj=true, tag="Optional", desc="Loot the Dirt-Stained Map from Bristleback quilboar and right-click it."}, [29]={npc="Chief Hawkwind", tgt="Chief Hawkwind"}, [30]={npc="Brave Windfeather", tgt="Brave Windfeather"}, [31]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [32]={hint="Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", tag="Optional"}, [33]={npc="Chief Hawkwind", tgt="Chief Hawkwind", tag="Optional"}, [34]={npc="Chief Hawkwind", tgt="Chief Hawkwind"}, [35]={npc="Chief Hawkwind", tgt="Chief Hawkwind", tag="Optional"}, [36]={npc="Antur Fallow", tgt="Antur Fallow", tag="Optional", desc="Pick up from Antur Fallow on the west side of camp."}, [37]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [38]={hint="Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [39]={npc="Harutt Thunderhorn", tgt="Harutt Thunderhorn", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [40]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [41]={hint="Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [42]={npc="Meela Dawnstrider", tgt="Meela Dawnstrider", desc="Finish The Hunt Begins, then take the breadcrumb from your class trainer."}, [43]={npc="Seer Ravenfeather", tgt="Seer Ravenfeather"}, [44]={hint="Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache."}, [45]={npc="Seer Ravenfeather", tgt="Seer Ravenfeather"}, [46]={npc="Seer Ravenfeather", tgt="Seer Ravenfeather", desc="Drink the Sapta to see the Minor Manifestation of Earth."}, [47]={hint="Find Kodo Rock and drink the Earth Sapta.", desc="Drink the Sapta to see the Minor Manifestation of Earth."}, [48]={npc="Minor Manifestation of Earth", tgt="Minor Manifestation of Earth", desc="Drink the Sapta to see the Minor Manifestation of Earth."}, [49]={npc="Minor Manifestation of Earth", tgt="Minor Manifestation of Earth", desc="Finish the quest to get your Earth Totem."}, [50]={hint="Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.", desc="Finish the quest to get your Earth Totem."}, [51]={npc="Seer Ravenfeather", tgt="Seer Ravenfeather", desc="Finish the quest to get your Earth Totem."}, [52]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [53]={hint="Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa."}, [54]={npc="Lanka Farshot", tgt="Lanka Farshot"}, [55]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [56]={hint="Read the Verdant Note and speak to Gart Mistrunner in Camp Narache."}, [57]={npc="Gart Mistrunner", tgt="Gart Mistrunner"}, [58]={text="Leave Red Cloud Mesa and follow the road north to Bloodhoof Village."}}},
    ["01-4"] = {name="Mulgore: Bloodhoof Village", short="Bloodhoof Village", tips={{k="取捨", text="Do Rite of Vision ( → Rite of Vision → Rite of Vision), Rite of Wisdom, and Journey into Thunder Bluff. Unlock the flight path on the last leg."}, {k="取捨", text="Turn in each well quest before taking the next one. Tauren only. Skip the Wildmane Water Well chain if you're already level 12. Tauren only.", s={{"Turn in each well quest before taking the next one. Tauren only. Skip the Wildmane Water Well chain if you're already level 12. Tauren only.", {race={"Tauren"}}}}}, {k="取捨", text="Running Ragefire Chasm? Pick up Testing an Enemy's Strength and Searching for the Lost Satchel from Rahauro in Thunder Bluff."}, {k="提醒", text="Need XP for level 12? Grind harpies in northern Mulgore, or head to Red Rocks or the Venture Co. Mine. See the class quests below for level 10 unlocks.", s={{"Need XP for level 12?"}, {"Grind harpies in northern Mulgore, or head to Red Rocks or the Venture Co"}, {"Mine"}, {"See the class quests below for level 10 unlocks"}}}}, danger={[1]="Patrols and miners can pull together inside the Venture Co. Mine. Clear the outside first, grab the clipboard, and leave the tunnel."}, grind={[1]={mob="Prairie Stalker", note="Scattered normal mobs north of Bloodhoof Village. Pull singles in the grass and watch for roamers. Pick up Mazzranache materials."}, [2]={mob="Venture Co. Supervisor", note="Normal mobs cluster around the Venture Co. Mine. Pull from outside and watch for workers and patrols. Pair with the mine quests."}, [3]={note="Dense normal mobs at the harpy camp in northwest Mulgore. Pull along the edge to avoid casters. Grind here if close to level 12."}}, supply={[1]={npc="Innkeeper Kauth"}, [2]={npc="Harant Ironbrace"}, [3]={npc="Innkeeper Kauth"}, [4]={npc="Kennah Hawkseye"}, [5]={npc="Tal"}}, steps={[1]={hint="Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", tag="Optional"}, [2]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [3]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [4]={hint="Sit near Kaga's Basic Campfire and wait until you receive the Boosted Rest buff.", tag="Optional"}, [5]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [6]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [7]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional", desc="Learn Skinning before accepting. Turn in once you meet the skill requirement."}, [8]={hint="Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache."}, [9]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [10]={hint="Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.", tag="Optional"}, [11]={npc="Innkeeper Kauth", tgt="Innkeeper Kauth", tag="Optional"}, [12]={text="Set your hearth with Innkeeper Kauth in Bloodhoof Village (45.93, 64.16)."}, [13]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [14]={hint="Speak with Zarlman Two-Moons in Bloodhoof Village."}, [15]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [16]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [17]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [18]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [19]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [20]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [21]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [22]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Optional"}, [23]={hint="Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof.", tag="Optional"}, [24]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Optional"}, [25]={npc="Ahab Wheathoof", tgt="Ahab Wheathoof", tag="Optional"}, [26]={hint="Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook.", tag="Optional"}, [27]={npc="Pyall Silentstride", tgt="Pyall Silentstride", tag="Optional"}, [28]={hint="Speak with Yonn Deepcut in Bloodhoof Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", tag="Optional"}, [29]={npc="Yonn Deepcut", tgt="Yonn Deepcut", tag="Optional"}, [30]={text="East of Bloodhoof Village → caravan and centaurs"}, [31]={hint="Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village."}, [32]={hint="Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village."}, [33]={hint="Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village."}, [34]={hint="Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof."}, [35]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [36]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [37]={hint="Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn."}, [38]={hint="Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore."}, [39]={npc="Malah Longwind", tgt="Malah Longwind"}, [40]={npc="Malah Longwind", tgt="Malah Longwind"}, [41]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [42]={hint="Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan."}, [43]={npc="Sealed Supply Crate", npcObj=true}, [44]={npc="Sealed Supply Crate", npcObj=true}, [45]={hint="Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village."}, [46]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [47]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [48]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [49]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [50]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [51]={hint="Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village."}, [52]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [53]={npc="Brave Wildrunner", tgt="Brave Wildrunner"}, [54]={hint="Bring Longwalker Malah's Report to Baine Bloodhoof."}, [55]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [56]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [57]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [58]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [59]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [60]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [61]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [62]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Optional"}, [63]={text="West: Palemane and the dig site. Follow the vision to the seer"}, [64]={hint="Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village."}, [65]={hint="Collect 5 Prospector's Picks."}, [66]={hint="Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.", desc="Drink Water of the Seers by the campfire. Follow the vision NW; do quests en route."}, [67]={npc="Perith Stormhoof", tgt="Perith Stormhoof", tag="Optional", desc="To avoid an early city trip, escort now and turn in on your first Thunder Bluff visit."}, [68]={hint="Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff.", tag="Optional"}, [69]={npc="Seer Wiserunner", tgt="Seer Wiserunner"}, [70]={npc="Seer Wiserunner", tgt="Seer Wiserunner"}, [71]={hint="Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn."}, [72]={text="Hearth to Bloodhoof Village and turn in the western quests together."}, [73]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [74]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [75]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [76]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [77]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [78]={hint="Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.", tag="Optional", desc="Bring a Tender Strider Meat and wait for Kyle to come close before feeding him."}, [79]={npc="Ahab Wheathoof", tgt="Ahab Wheathoof", tag="Optional"}, [80]={text="Northern wells, red stones and the mine in the northeast"}, [81]={hint="Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull."}, [82]={hint="Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit."}, [83]={npc="Lorekeeper Raintotem", tgt="Lorekeeper Raintotem"}, [84]={hint="Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks."}, [85]={hint="Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village."}, [86]={npc="Ancestral Spirit", tgt="Ancestral Spirit"}, [87]={npc="Lorekeeper Raintotem", tgt="Lorekeeper Raintotem"}, [88]={npc="Ancestral Spirit", tgt="Ancestral Spirit"}, [89]={hint="Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof."}, [90]={hint="Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village."}, [91]={hint="Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village."}, [92]={npc="Mulgore Expansion Plans", npcObj=true, tag="Optional", desc="Loot Mulgore Expansion Plans from Supervisor Fizsprocket to start the quest."}, [93]={hint="Collect the rest of Supervisor Fizsprocket's pages inside The Venture Co. Mine and bring them to Morin Cloudstalker near Bloodhoof Village.", tag="Optional", desc="Collect all three notes inside the Venture Co. Mine before leaving."}, [94]={hint="Defeat Chakuyak and bring back her pelt.", tag="Optional"}, [95]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [96]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [97]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Optional"}, [98]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Optional", desc="Below level 12? Do more quests near the mine."}, [99]={hint="Bring the Clearcutter Key to Morin Cloudstalker outside Bloodhoof Village.", tag="Optional", desc="Below level 12? Do more quests near the mine."}, [100]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Optional", desc="Below level 12? Do more quests near the mine."}, [101]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [102]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [103]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Optional"}, [104]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [105]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [106]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [107]={hint="Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.", tag="Optional"}, [108]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [109]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [110]={hint="Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.", tag="Optional"}, [111]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [112]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [113]={npc="Skorn Whitecloud", tgt="Skorn Whitecloud", tag="Optional"}, [114]={hint="Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.", tag="Optional"}, [115]={text="Unlock Thunder Bluff and continue to the Crossroads"}, [116]={text="Follow Mulgore's main road to Thunder Bluff. Take the lift and learn Tal's flight path (47.00, 49.83)."}, [117]={hint="Speak with Cairne Bloodhoof in Thunder Bluff."}, [118]={hint="Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff."}, [119]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [120]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [121]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof", tag="Optional"}, [122]={hint="Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff.", tag="Optional"}, [123]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem", tag="Optional"}, [124]={npc="Melor Stonehoof", tgt="Melor Stonehoof", tag="Optional"}, [125]={npc="Eylah Sunhorn", tgt="Eylah Sunhorn", tag="Optional", desc="Buy all four materials on the bluff. Use the incense on Hunter Rise."}, [126]={hint="Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.", tag="Optional", desc="Buy all four materials on the bluff. Use the incense on Hunter Rise."}, [127]={npc="Eylah Sunhorn", tgt="Eylah Sunhorn", tag="Optional", desc="Buy all four materials on the bluff. Use the incense on Hunter Rise."}, [128]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Learn Skinning first, then turn in 12 Light Leather."}, [129]={hint="Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.", tag="Optional", desc="Learn Skinning first, then turn in 12 Light Leather. Turn in at Thunder Bluff. Skin low-level beasts for Light Leather or buy it."}, [130]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Learn Skinning first, then turn in 12 Light Leather."}, [131]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Meet the Leatherworking requirement. Bring 4 Light Leather and 4 Coarse Thread."}, [132]={hint="Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.", tag="Optional", desc="Meet the Leatherworking requirement. Bring 4 Light Leather and 4 Coarse Thread. Turn in at Thunder Bluff. Skin or buy Light Leather. Buy Coarse Thread from a vendor."}, [133]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Meet the LW req. Bring 4 Light Leather and 4 Coarse Thread. Boramu (44.08, 44.89)."}, [134]={text="At level 12, leave Mulgore by the east gate. Learn Omusa Thunderhorn's flight path in Camp Taurajo (44.45, 59.15)."}, [135]={npc="Kirge Sternhorn", tgt="Kirge Sternhorn", tag="Optional", desc="Pick up when passing Camp Taurajo. Head to the Crossroads."}, [136]=