    ["01-7"] = {tips={{k="交通", text="Coming from another starting zone? Board the Skycutter at the south dock of Skywatcher Plateau in Mulgore (34.30, 25.80). Get off at Valanaar's west dock (57.90, 80.90) and follow the road north to Thendal Grove."}, {k="提醒", text="Follow the road north from Valanaar to Thendal Grove. Other Horde races can do shared side quests. The addon hides race-locked steps and those with missing prerequisites. At levels 1-3, kill young vuldren and cirrusflies before the gathering and village quests. Still below 12? Finish in Bloodhoof Village.", s={{"Follow the road north from Valanaar to Thendal Grove"}, {"Other Horde races can do shared side quests"}, {"The addon hides race-locked steps and those with missing prerequisites"}, {"At levels 1-3, kill young vuldren and cirrusflies before the gathering and village quests"}, {"Still below 12?"}, {"Finish in Bloodhoof Village"}}}, {k="取捨", text="Follow the island chain from Thendal Grove through Shen'dar Village and Valanaar to the Shrine of Akir. Below level 12? Do the orchard or Shadowgale Forest side quests before boarding the zeppelin."}, {k="取捨", text="Pick up the apprentice and bandit quests together. Add Hippogryph Harassment if you're Skyborne. The Problem With Prideclaws rewards a Simple Leather Satchel. Meddlesome Mages offers Idol of Shifting Tides to Druids. Shamans get Totem of Charged Flames from Call of Fire.", s={{"Pick up the apprentice and bandit quests together"}, {"Add Hippogryph Harassment if you're Skyborne", {race={"天裔精靈"}}}, {"The Problem With Prideclaws rewards a Simple Leather Satchel"}, {"Meddlesome Mages offers Idol of Shifting Tides to Druids", {class={"DRUID"}}}, {"Shamans get Totem of Charged Flames from Call of Fire", {class={"SHAMAN"}}}}}, {k="提醒", text="Quests What Comes Next and The Earthen Ring show level 13 in the log, but you can pick them up from level 7 once you finish the island chain, per QuestieDB.", s={{"Quests What Comes Next and The Earthen Ring show level 13 in the log, but you can pick them up from level 7 once you finish the island chain, per QuestieDB"}}}}, danger={[1]="Put your racial on your action bar before jumping from the Thendal Grove lookout. Use it immediately after you jump.", [2]="Al'Aketh Stormchasers are mixed in with footsoldiers in the Shadowgale Forest camp. Pull one at a time from the edge and avoid the middle."}, grind={[1]={mob="Juvenile Vuldren", note="Dense normal mobs in Thendal Grove. Pull singles and watch for nearby swarms. Grind near the start at levels 1-2."}, [2]={mob="Highlands Bandit", note="Dense normal mobs in the Shen'dar Highlands. Pull bandits from the camp edge to avoid groups. Pair with The Criminal Element and Pilfered Windstones."}, [3]={mob="Al'Aketh Stormchaser", note="Dense normal mobs in Shadowgale Forest. Pull from the edge to avoid footsoldiers. Pair with Unwanted and Unworthy or grind to 12."}}, supply={[1]={npc="Fevrath Skyhammer"}, [2]={npc="Uualia Suncrest"}, [3]={npc="Uualia Suncrest"}, [4]={npc="Zephras Citizen"}, [5]={npc="Aedi Thriceforged"}, [6]={npc="Zephras Citizen"}, [7]={npc="Belandiel Farflight"}, [8]={npc="Donaal Downbreeze"}, [9]={npc="Taliaa Brightsky"}, [10]={npc="Donaal Downbreeze"}, [11]={npc="Antelariaa Cloudgaze"}, [12]={npc="Tal"}}, steps={[1]={npc="Dalia the Collector", tgt="Ailee Farheart"}, [2]={hint="Speak with Rorian the Dayseeker in Thendal Grove."}, [3]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [4]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [5]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [6]={npc="Myriaal Mistwake", tgt="Myriaal Mistwake"}, [7]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [8]={hint="Slay 8 Vuldren Juveniles in Thendal Grove."}, [9]={hint="Slay 8 Pesky Cirrusflies in Thendal Grove."}, [10]={hint="Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall.", desc="Jump from the watchtower, then use Walk on Air before landing."}, [11]={hint="Speak with Halaan Hawk-Eye and borrow his gift to view the anchor pylon in the distance."}, [12]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [13]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [14]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [15]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [16]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [17]={npc="Destin Thriceforged", tgt="Dalia the Collector"}, [18]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [19]={npc="Ventaari Brightwish", tgt="Ventaari Brightwish"}, [20]={hint="Destroy the Cirrusfly Queen in Thendal Grove."}, [21]={hint="Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove."}, [22]={hint="Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.", desc="Use the Skyborne racial Skysight by the Elemental Convergence."}, [23]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [24]={npc="Destin Thriceforged", tgt="Dalia the Collector"}, [25]={npc="Ventaari Brightwish", tgt="Ventaari Brightwish"}, [26]={hint="Speak to Yala Windwatcher in Thendal Grove."}, [27]={npc="Yala Windwatcher", tgt="Yala Windwatcher"}, [28]={npc="Yala Windwatcher", tgt="Yala Windwatcher"}, [29]={hint="Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove."}, [30]={npc="Yala Windwatcher", tgt="Yala Windwatcher"}, [31]={npc="Yala Windwatcher", tgt="Yala Windwatcher"}, [32]={hint="Bring word of the Al'Aketh to Rorian the Dayseeker in Thendal Grove."}, [33]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [34]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [35]={hint="Speak with Aetheen of the Gales in Thendal Grove."}, [36]={npc="Elatrell Featherlight", tgt="Aetheen of the Gales"}, [37]={npc="Valreaa Valewind", tgt="Valreaa Valewind"}, [38]={npc="Elatrell Featherlight", tgt="Aetheen of the Gales"}, [39]={hint="Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove."}, [40]={hint="Slay 8 Ursera Scavengers and collect the head of the 