{npc="Seena Skybreaker", tgt="Seena Skybreaker", desc="Do this class weapon quest alongside the Zephras Isle storyline.", star={"Stormforged Protector", {"WARRIOR"}}}, [262]={npc="Tai'ree Farsight", tgt="Windshaper Boro"}, [263]={hint="Bring a Signet of Akir to Windshaper Boro."}, [264]={npc="Tai'ree Farsight", tgt="Windshaper Boro"}, [265]={npc="Tai'ree Farsight", tgt="Windshaper Boro", desc="Drink the Sapta to see the Minor Manifestation of Earth. Alt. Pickup: 42.76, 23.66."}, [266]={hint="Find the Rise of Spirits and drink the Earth Sapta.", desc="Drink the Sapta to see the Minor Manifestation of Earth."}, [267]={npc="Minor Manifestation of Earth", tgt="Minor Manifestation of Earth", desc="Drink the Sapta to see the Minor Manifestation of Earth."}, [268]={npc="Minor Manifestation of Earth", tgt="Minor Manifestation of Earth", desc="Finish the quest to get your Earth Totem."}, [269]={hint="Bring the Rough Quartz to Windshaper Boros in Thendal Grove.", desc="Finish the quest to get your Earth Totem."}, [270]={npc="Tai'ree Farsight", tgt="Windshaper Boro", desc="Finish the quest to get your Earth Totem."}, [271]={npc="Sessaria Skystride", tgt="Sessaria Skystride", desc="Aarnor Galestrike also offers this quest (43.45, 44.87)."}, [272]={hint="Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands."}, [273]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn"}, [274]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn"}, [275]={hint="Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart."}, [276]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn"}, [277]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn"}, [278]={hint="Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious."}, [279]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn"}, [280]={npc="Olariaan Swiftburn", tgt="Olariaan Swiftburn", desc="Clear the route before the fire delivery. Finish it to get your Fire Totem.", star={"Totem of Charged Flames", {"SHAMAN"}}}, [281]={hint="Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.", tag="Target: Sacrificial Brazier / Brazier of Eternal Flame", desc="Clear the route before the fire delivery. Finish it to get your Fire Totem."}, [282]={npc="Sessaria Skystride", tgt="Sessaria Skystride", desc="Clear the route before the fire delivery. Finish it to get your Fire Totem.", star={"Totem of Charged Flames", {"SHAMAN"}}}, [283]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [284]={hint="Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove."}, [285]={npc="Dorii Brightwhisper", tgt="Tai'ree Farsight"}, [286]={npc="Elayaa Easewind", tgt="Elayaa Easewind", desc="In Valanaar already? Check whether Quel'ana Quickgale offers Taming the Beast."}, [287]={hint="Report to Quel'ana Quickgale in Valanaar.", desc="In Valanaar already? Check whether Quel'ana Quickgale offers Taming the Beast."}, [288]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale", desc="In Valanaar already? Check whether Quel'ana Quickgale offers Taming the Beast."}, [289]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [290]={hint="Use the Taming Rod to tame a Windsong Crawler found near bodies of water."}, [291]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [292]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [293]={hint="Use the Taming Rod to tame an Ornery Galestrider in the Gustberry Lowlands."}, [294]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [295]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [296]={hint="Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar."}, [297]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [298]={npc="Quel'ana Quickgale", tgt="Quel'ana Quickgale"}, [299]={hint="Speak to Quel'dora Quickgale in Valanaar."}, [300]={npc="Quel'dora Quickgale", tgt="Quel'dora Quickgale"}, [301]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [302]={hint="Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove."}, [303]={npc="Windshaper Boro", tgt="Xyton Silverwind"}, [304]={npc="Lotheluum Starbreeze", tgt="Lotheluum Starbreeze"}, [305]={hint="Speak with Urs'endris near the falls northeast of Valanaar."}, [306]={npc="Urs'endris", tgt="Urs'endris"}, [307]={npc="Urs'endris", tgt="Urs'endris", desc="Ur'endra patrols Shen'dar Highlands."}, [308]={hint="Find and kill Ur'endra in the Shen'dar Highlands.", desc="Ur'endra patrols Shen'dar Highlands."}, [309]={npc="Urs'endris", tgt="Urs'endris", desc="Ur'endra patrols Shen'dar Highlands."}, [310]={npc="Alaana Stormwalker", tgt="Muln Earthfury", tag="Optional", desc="Pick up on arrival in Mulgore. Alt pickup: Alaana Stormwalker (33.38, 22.51)."}, [311]={hint="Speak with Turak Runetotem in Thunder Bluff.", tag="Optional", desc="Accept the breadcrumb when the Skycutter reaches Mulgore."}, [312]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Optional", desc="Accept the breadcrumb when the Skycutter reaches Mulgore."}, [313]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Learn the teleport in Thunder Bluff, then use it to turn in at Moonglade."}, [314]={hint="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", desc="Learn the teleport in Thunder Bluff, then use it to turn in at Moonglade."}, [315]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Learn the teleport in Thunder Bluff, then use it to turn in at Moonglade."}, [316]={text="Run south from Skywatcher Plateau, take the lift to Thunder Bluff and learn Tal's flight path (47.00, 49.83). Fly to the Crossroads if unlocked. Otherwise leave Mulgore via the east pass, learn Camp Taurajo from Omusa Thunderhorn (44.45, 59.15), then follow the road north. In the Crossroads, learn Devrak's flight path (51.50, 30.34) and set your hearth with Innkeeper Boorand Plainswind (51.99, 29.89)."}}},
    ["02-8"] = {name="The Barrens: Crossroads", tips={{k="交通", text="At step 4, unlock the Crossroads flight path and set your Hearthstone. See Bragok on your first Ratchet visit. When leaving, wait on Frezza's side for the Tirisfal Glades zeppelin."}, {k="取捨", text="Do The Forgotten Pools → The Stagnant Oasis → Altered Beings to unlock Mura Runetotem for Silverpine. This route moves Altered Beings earlier than TUGs so you can turn in Mura Runetotem at the next stop."}, {k="取捨", text="Save the northern marsh escort, the mine, and Stolen Booty for the Ratchet and Camp Taurajo loop. On your first Ratchet visit, clear only the pirates near shore."}, {k="取捨", text="Do Apothecary Zamah, Hamuul Runetotem, and Until Death Do Us Part if passing through Thunder Bluff. If you're level 16 and have no Wailing Caverns group, head straight to Silverpine."}, {k="提醒", text="Ragefire Chasm is optional at 14-16. Below 16, do Echeyakee and Harpy Lieutenants early during the Ratchet and Camp Taurajo leg, or grind Altered Snapjaws at the Stagnant Oasis (around 55, 42). Turn in any finished quests before leaving.", s={{"Ragefire Chasm is optional at 14-16"}, {"Below 16, do Echeyakee and Harpy Lieutenants early during the Ratchet and Camp Taurajo leg, or grind Altered Snapjaws at the Stagnant Oasis (around 55, 42)"}, {"Turn in any finished quests before leaving"}}}}, danger={[1]="Southsea Cannoneers and pirates can pull from both levels south of Ratchet. Clear the foot of the hill before going up for the parts."}, grind={[1]={mob="Fleeting Plainstrider", note="Moderate density on the open plain southeast of the Crossroads. Pick off lone tallstriders at levels 12-13. Watch for centaur patrols."}, [2]={mob="Oasis Snapjaw", note="Dense normal mobs along Stagnant Oasis. Pull away from the shore and watch for Kolkar. Collect Altered Snapjaw Shells as you go."}}, supply={[1]={npc="Devrak"}, [2]={npc="Innkeeper Boorand Plainswind"}, [3]={npc="Jahan Hawkwing"}, [4]={npc="Innkeeper Boorand Plainswind"}, [5]={npc="Uthrok"}, [6]={npc="Hula'mahi"}, [7]={npc="Bragok"}, [8]={npc="Grazlix"}}, steps={[1]={hint="Travel to Orgrimmar and speak with Thrall in the Valley of Wisdom.", tag="Optional", desc="If already accepted, do it. If still in Orgrimmar, see Thrall in the Valley of Wisdom."}, [2]={npc="Thrall", tgt="Thrall", tag="Optional"}, [3]={npc="Thrall", tgt="Thrall", tag="Optional", desc="Turn in Welcome to Azeroth first."}, [4]={text="At the Crossroads, learn Devrak's flight path (51.50, 30.34) and set your hearth with Innkeeper Boorand Plainswind (51.99, 29.89). Keep it for the return from Silverpine, Ratchet and Camp Taurajo."}, [5]={hint="Report To Thork at The Crossroads in The Barrens.", tag="Optional"}, [6]={npc="Thork", tgt="Thork", tag="Optional"}, [7]={hint="Speak with Sergra Darkthorn at the Crossroads.", tag="Optional", desc="Do this only if you have the letter prerequisite."}, [8]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn", tag="Optional"}, [9]={hint="Speak with Tonga Runetotem at the Crossroads.", tag="Optional", desc="Do this only if you have the letter prerequisite."}, [10]={npc="Tonga Runetotem", tgt="Tonga Runetotem", tag="Optional"}, [11]={hint="Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.", tag="Optional", desc="Do this only if you have the letter prerequisite."}, [12]={npc="Apothecary Helbrim", tgt="Apothecary Helbrim", tag="Optional"}, [13]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [14]={npc="Gazrog", tgt="Gazrog"}, [15]={npc="Thork", tgt="Thork"}, [16]={npc="Thork", tgt="Thork"}, [17]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [18]={npc="Apothecary Helbrim", tgt="Apothecary Helbrim"}, [19]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger"}, [20]={npc="Apothecary Helbrim", tgt="Apothecary Helbrim"}, [21]={hint="Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads."}, [22]={hint="Bring 12 Raptor Heads to Gazrog at the Crossroads."}, [23]={hint="Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads."}, [24]={npc="Chen's Empty Keg", npcObj=true, tag="Optional", desc="Clear mobs by the barrel outside the northeast quilboar camp first."}, [25]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [26]={npc="Thork", tgt="Thork"}, [27]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [28]={npc="Thork", tgt="Thork"}, [29]={text="Eastern quilboar. Turn in supplies and the first hunts on the way back"}, [30]={hint="Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads."}, [31]={hint="Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout."}, [32]={hint="Find and return Crossroads' Supply Crates to Thork in the Barrens."}, [33]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [34]={npc="Thork", tgt="Thork"}, [35]={npc="Thork", tgt="Thork"}, [36]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [37]={npc="Gazrog", tgt="Gazrog"}, [38]={npc="Gazrog", tgt="Gazrog", desc="Save this for the raptor nests on your second Barrens visit."}, [39]={text="Forgotten Pools: start the centaur chain, then loop around the harpy camp"}, [40]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [41]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [42]={hint="Report back to Tonga Runetotem with your findings."}, [43]={hint="Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads."}, [44]={hint="Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.", desc="Kill Kolkar Wranglers at the oasis. Other nearby Kolkar can drop bracers too."}, [45]={hint="Bring Barak's Head to Regthar Deathgate, west of the Crossroads.", desc="Pull it away from the wrangler. Group up if you're underleveled."}, [46]={hint="Collect 8 Witchwing talons."}, [47]={hint="Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads."}, [48]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [49]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [50]={npc="Regthar Deathgate", tgt="Regthar Deathgate", desc="Save for Ratchet and Camp Taurajo. Summon Verog at the Stagnant Oasis camp."}, [51]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [52]={npc="Apothecary Helbrim", tgt="Apothecary Helbrim"}, [53]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger"}, [54]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [55]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [56]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger"}, [57]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [58]={text="Ratchet: pick up the dock and pirate quests on the first visit"}, [59]={text="Follow the east road to Ratchet. Learn Bragok's flight path (63.08, 37.16)."}, [60]={hint="Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet."}, [61]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig"}, [62]={npc="Gazlowe", tgt="Gazlowe"}, [63]={npc="Wrenix the Wretched", tgt="Wrenix the Wretched"}, [64]={npc="Sputtervalve", tgt="Sputtervalve"}, [65]={npc="WANTED", npcObj=true, tag="Optional", desc="The pirate captain is farther south. Skip if you're underleveled."}, [66]={hint="Find someone who knows about Chen's Empty Keg.", tag="Optional", desc="Do this only if you looted the barrel."}, [67]={npc="Brewmaster Drohn", tgt="Brewmaster Drohn", tag="Optional"}, [68]={npc="Brewmaster Drohn", tgt="Brewmaster Drohn", tag="Optional", desc="Save for Ratchet and Camp Taurajo. Loot lion fangs, bird kidneys and lizard horns."}, [69]={hint="Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet."}, [70]={hint="Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet."}, [71]={hint="Bring the head of Baron Longshore to Gazlowe in Ratchet.", tag="Optional"}, [72]={npc="Gazlowe", tgt="Gazlowe"}, [73]={npc="Wrenix the Wretched", tgt="Wrenix the Wretched"}, [74]={npc="Gazlowe", tgt="Gazlowe", tag="Optional"}, [75]={npc="Gazlowe", tgt="Gazlowe"}, [76]={hint="Bring Gazlowe's Ledger to Wharfmaster Dizzywig."}, [77]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig"}, [78]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig"}, [79]={hint="Return Gazlowe's Ledger to Gazlowe in Ratchet."}, [80]={npc="Gazlowe", tgt="Gazlowe"}, [81]={npc="Gazlowe", tgt="Gazlowe", desc="Do this with the Northwatch Hold cannons on your second Barrens visit."}, [82]={text="Take the southwest road to the Stagnant Oasis. Clear it and run back to the Crossroads to turn in. Save your hearth for the return from Silverpine."}, [83]={text="Stagnant Oasis and Altered Snapjaws. Unlock the Silverpine lead-in"}, [84]={hint="Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."}, [85]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [86]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [87]={hint="Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", tag="Target: Oasis Snapjaw / Oasis Snapjaw Hatchling", desc="Kill turtles at Lushwater Oasis southwest of the Crossroads or at Stagnant Oasis."}, [88]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [89]={npc="Tonga Runetotem", tgt="Tonga Runetotem", desc="Save this for the turn-in at the Sepulcher in Silverpine Forest."}, [90]={npc="Tonga Runetotem", tgt="Tonga Runetotem", tag="Optional", desc="Pick up for Wailing Caverns. The chain starts in Thunder Bluff."}, [91]={text="Below 16? Finish extra hunts before crossing"}, [92]={npc="Apothecary Helbrim", tgt="Apothecary Helbrim", tag="Optional", desc="Accept only if you're heading to Thunder Bluff now. You have 45 minutes."}, [93]={text="For the optional Thunder Bluff detour, fly from the Crossroads if unlocked. Otherwise enter Mulgore via Camp Taurajo, take the lift and learn Tal's flight path (47.00, 49.83). Quest Apothecary Zamah starts a timer on pickup. Take it only if you can make it."}, [94]={hint="Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.", tag="Optional"}, [95]={hint="Speak with Hamuul Runetotem.", tag="Optional"}, [96]={npc="Apothecary Zamah", tgt="Apothecary Zamah", tag="Optional"}, [97]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem", tag="Optional"}, [98]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem", tag="Optional", desc="Finish Hamuul Runetotem first. Run Wailing Caverns after returning to Kalimdor at stop 10."}, [99]={hint="Speak with Nara Wildmane.", tag="Optional", desc="Finish Hamuul Runetotem first. Run Wailing Caverns after returning to Kalimdor at stop 10."}, [100]={npc="Nara Wildmane", tgt="Nara Wildmane", tag="Optional", desc="Finish Hamuul Runetotem first. Run Wailing Caverns after returning to Kalimdor at stop 10."}, [101]={npc="Nara Wildmane", tgt="Nara Wildmane", tag="Optional", desc="Accept after Nara Wildmane only if you're running Wailing Caverns with a group.", star={"Crescent Staff", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [102]={npc="Apothecary Zamah", tgt="Apothecary Zamah", tag="Optional", desc="Accept only if you have a Wailing Caverns group."}, [103]={npc="Clarice Foster", tgt="Clarice Foster", tag="Optional", desc="Pick up from Clarice on Spirit Rise. Turn in at the Sepulcher later."}, [104]={text="Fly to Orgrimmar if unlocked. For your first visit, start at the Crossroads, cross the Southfury River and follow the Durotar road north. From Thunder Bluff, fly to the Crossroads first. Unlock Orgrimmar with Doras (45.12, 63.89)."}, [105]={npc="Zor Lonetree", tgt="Zor Lonetree", tag="Optional", desc="Pick up in Orgrimmar's Valley of Wisdom. See Seereth on the Sun Rock Retreat leg."}, [106]={npc="Tarshaw Jaggedscar", tgt="Tarshaw Jaggedscar", desc="Take the Razor Hill lead to Far Watch Post. Skip if you did Brill's Ulag the Cleaver."}, [107]={hint="Speak with Uzzek at Far Watch Post.", desc="Start at any listed Warrior trainer. Skip this branch if you did Brill's Ulag the Cleaver."}, [108]={npc="Uzzek", tgt="Uzzek", desc="Start at any listed Warrior trainer. Skip this branch if you did Brill's Ulag the Cleaver."}, [109]={npc="Uzzek", tgt="Uzzek", desc="Choose this Defensive Stance quest or Ulag the Cleaver in Brill."}, [110]={hint="Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.", desc="Choose this Defensive Stance quest or Ulag the Cleaver in Brill."}, [111]={npc="Uzzek", tgt="Uzzek", desc="Choose this Defensive Stance quest or Ulag the Cleaver in Brill."}, [112]={npc="Uzzek", tgt="Uzzek", tag="Optional", desc="Continue the weapon quest on your first pass through the Crossroads."}, [113]={hint="Speak with Thun'grim Firegaze in the Barrens.", tag="Optional", desc="Continue the weapon quest on your first pass through the Crossroads."}, [114]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Continue the weapon quest on your first pass through the Crossroads."}, [115]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Clear the guards before opening the chest in the quilboar camp."}, [116]={hint="Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.", tag="Optional", desc="Clear the guards before opening the chest in the quilboar camp."}, [117]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Clear the guards before opening the chest in the quilboar camp."}, [118]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Follow the path uphill from the foot of the mountain."}, [119]={hint="Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", desc="Follow the path uphill from the foot of the mountain."}, [120]={npc="Telf Joolam", tgt="Telf Joolam", desc="Follow the path uphill from the foot of the mountain."}, [121]={npc="Telf Joolam", tgt="Telf Joolam", desc="Loot tar from Barrens quilboar and the reagent pouch from Burning Blade cultists."}, [122]={hint="Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.", desc="Loot tar from Barrens quilboar and the reagent pouch from Burning Blade cultists."}, [123]={npc="Telf Joolam", tgt="Telf Joolam", desc="Loot tar from Barrens quilboar and the reagent pouch from Burning Blade cultists."}, [124]={npc="Telf Joolam", tgt="Telf Joolam", desc="Drink the Sapta by the shrine before fighting the fire elemental."}, [125]={hint="Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", tag="Target: Minor Manifestation of Fire / Manifestation of Flames", desc="Drink the Sapta by the shrine before fighting the fire elemental."}, [126]={npc="Brazier of the Dormant Flame", npcObj=true, desc="Drink the Sapta by the shrine before fighting the fire elemental."}, [127]={npc="Brazier of the Dormant Flame", npcObj=true, desc="Finish the quest to get your Fire Totem.", star={"Totem of Charged Flames", {"SHAMAN"}}}, [128]={hint="Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.", desc="Finish the quest to get your Fire Totem."}, [129]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Finish the quest to get your Fire Totem.", star={"Totem of Charged Flames", {"SHAMAN"}}}, [130]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Alternate pickup: Hanna Lighthoof in northern Mulgore (33.42, 22.13)."}, [131]={hint="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.", desc="Hanna Lighthoof in northern Mulgore also offers this quest."}, [132]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Hanna Lighthoof in northern Mulgore also offers this quest."}, [133]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [134]={hint="Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak."}, [135]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [136]={npc="Tonga Runetotem", tgt="Tonga Runetotem", desc="Buy or trade for Earthroot. Loot 5 Kodo Horns from Barrens kodos."}, [137]={hint="Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.", desc="Buy or trade for Earthroot. Loot 5 Kodo Horns from Barrens kodos."}, [138]={npc="Tonga Runetotem", tgt="Tonga Runetotem", desc="Buy or trade for Earthroot. Loot 5 Kodo Horns from Barrens kodos."}, [139]={npc="Tonga Runetotem", tgt="Tonga Runetotem", desc="Treat 10 Sickly Gazelles north of the Crossroads. Teleport to Dendrite to turn in."}, [140]={hint="Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.", desc="Treat 10 Sickly Gazelles north of the Crossroads. Teleport to Dendrite to turn in."}, [141]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Treat 10 Sickly Gazelles north of the Crossroads. Teleport to Dendrite to turn in."}, [142]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [143]={hint="Return to Turak Runetotem on the Elder Rise, Thunder Bluff."}, [144]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [145]={text="Leave Orgrimmar and board the Tirisfal Glades zeppelin at Frezza's platform (50.82, 13.54). Keep your hearth at the Crossroads."}}},
    ["05-d2"] = {name="Hall of Thanes", entrance="Ironforge 27.63, 47.83", pickup="Only make the Ironforge trip for an organized achievement run. From Undercity, travel through Silverpine, Hillsbrad, and Arathi, then south through the Wetlands and Dun Algaz into Dun Morogh. Horde prerequisite pickups are unverified.", pickupS={{"Only make the Ironforge trip for an organized achievement run"}, {"From Undercity, travel through Silverpine, Hillsbrad, and Arathi, then south through the Wetlands and Dun Algaz into Dun Morogh"}, {"Horde prerequisite pickups are unverified"}}, tips={{k="動線", text="Entrance → Fadlin at Anvilmar's Rest → Magmatus by the Dark Iron summoner → the patrolling Reaver → Durgan in the royal vault."}, {k="說明", text="QuestieDB Forever lists Underground Map, Old Ironforge Incursion, The Restless Dead, An Ancient Grudge, Important Heirlooms, and The Treaty of Understanding as Alliance. No Horde pickup route is verified.", s={{"QuestieDB Forever lists Underground Map, Old Ironforge Incursion, The Restless Dead, An Ancient Grudge, Important Heirlooms, and The Treaty of Understanding as Alliance"}, {"No Horde pickup route is verified"}}}, {k="說明", text="Run for loot or achievements. Bosses include Faldrim Anvilmar, Magmatus, Plunder, and Durgen Dirgehammer.", s={{"Run for loot or achievements"}, {"Bosses include Faldrim Anvilmar, Magmatus, Plunder, and Durgen Dirgehammer"}}}, {k="說明", text="Horde turn-in location unverified.", s={{"Horde turn-in location unverified"}}}, {k="取捨", text="Skip while leveling. For the Legacy achievement, form your group before heading in. Alliance capital guards and PvP rules make entry harder."}, {k="說明", text="Take the side door in Ironforge's throne room to Old Ironforge, then follow the passage to the dungeon portal. Blizzard confirms Horde can enter through Alliance territory.", s={{"Take the side door in Ironforge's throne room to Old Ironforge, then follow the passage to the dungeon portal"}, {"Blizzard confirms Horde can enter through Alliance territory"}}}}, steps={[1]={text="Hall of Thanes entrance"}}},
    ["05-d1"] = {name="Ragefire Chasm", entrance="Orgrimmar 52.60, 49.00", pickup="Unlock the Crossroads flight path, fly to Thunder Bluff for Searching for the Lost Satchel and Testing an Enemy's Strength from Rahauro, then do Hidden Enemies and Hidden Enemies with Thrall in Orgrimmar. Pick up Slaying the Beast in the Cleft of Shadow. If you've unlocked Undercity, get The Power to Destroy... from Varimathras during the crossing.", pickupS={{"Unlock the Crossroads flight path, fly to Thunder Bluff for Searching for the Lost Satchel and Testing an Enemy's Strength from Rahauro, then do Hidden Enemies and Hidden Enemies with Thrall in Orgrimmar"}, {"Pick up Slaying the Beast in the Cleft of Shadow"}, {"If you've unlocked Undercity, get The Power to Destroy... from Varimathras during the crossing"}}, tips={{k="動線", text="Clear troggs at the entrance → take the first hall's right ramp to Oggleflint and Maur → cross the lava bridge for Taragaman → clear Burning Blade cultists → Bazzalan up the right ramp, then Jergosh at the end."}, {k="取捨", text="Unlock Hidden Enemies before entering. Run Ragefire Chasm once and turn in Slaying the Beast nearby in the Cleft of Shadow. Save the Thunder Bluff and Undercity turn-ins for the city visits on the route."}, {k="說明", text="Enter the Cleft of Shadow in Orgrimmar and follow the passage down to the blue dungeon portal.", s={{"Enter the Cleft of Shadow in Orgrimmar and follow the passage down to the blue dungeon portal"}}}}, steps={[1]={npc="Rahauro", tgt="Rahauro"}, [2]={npc="Rahauro", tgt="Rahauro"}, [3]={npc="Varimathras", tgt="Varimathras", tag="Optional", desc="If you skipped Undercity, ask your group to share The Power to Destroy.... Otherwise do the other four."}, [4]={npc="Thrall", tgt="Thrall"}, [5]={hint="Bring a Lieutenant's Insignia to Thrall in Orgrimmar."}, [6]={npc="Thrall", tgt="Thrall"}, [7]={npc="Thrall", tgt="Thrall", preText="Hidden Enemies"}, [8]={hint="Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."}, [9]={npc="Thrall", tgt="Thrall"}, [10]={npc="Thrall", tgt="Thrall", preText="Hidden Enemies"}, [11]={npc="Neeru Fireblade", tgt="Neeru Fireblade"}, [12]={text="Ragefire Chasm entrance"}, [13]={hint="Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", desc="Location: Follow the slope to the first trogg hall. Kill the shamans and troggs."}, [14]={hint="Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.", desc="Location: Take the right ramp in the first trogg hall. Find the body behind Oggleflint."}, [15]={npc="Maur Grimtotem", tgt="Maur Grimtotem", tag="Unverified"}, [16]={npc="Maur Grimtotem", tgt="Maur Grimtotem", tag="Unverified", preText="Searching for the Lost Satchel"}, [17]={hint="Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", desc="DungeonsForever map 1: Taragaman the Hungerer at 41.00, 57.70. Location: Return to the main path. Taragaman is on the platform at the lava crossroads."}, [18]={hint="Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", tag="Optional", desc="Location: Cross the lava bridge and clear the Burning Blade cultists toward the last bosses."}, [19]={hint="Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", desc="Map 1: Bazzalan (41.50, 86.20), Jergosh the Invoker (33.00, 84.50). Location: Take the right ramp for Bazzalan, then return to the main path for Jergosh."}, [20]={npc="Neeru Fireblade", tgt="Neeru Fireblade"}, [21]={npc="Thrall", tgt="Thrall"}, [22]={npc="Thrall", tgt="Thrall", preText="Hidden Enemies"}, [23]={hint="Speak to Neeru Fireblade in Orgrimmar."}, [24]={npc="Neeru Fireblade", tgt="Neeru Fireblade"}, [25]={npc="Neeru Fireblade", tgt="Neeru Fireblade", preText="Hidden Enemies"}, [26]={hint="Speak to Thrall in Orgrimmar and tell him what you've learned."}, [27]={npc="Thrall", tgt="Thrall"}, [28]={hint="Take the Grimtotem Satchel to Rahauro in Thunder Bluff."}, [29]={npc="Rahauro", tgt="Rahauro"}, [30]={npc="Rahauro", tgt="Rahauro"}, [31]={npc="Varimathras", tgt="Varimathras", tag="Optional"}}},
    ["02-9"] = {name="Silverpine Forest", tips={{k="交通", text="Walk to the Sepulcher on your first visit and unlock the flight path. Hearth to the Crossroads on the way back. If your Hearthstone is on cooldown, take the Orgrimmar zeppelin."}, {k="取捨", text="Unlock Ambermill Investigations and Forever quest Watching the Roads, then do both in Ambermill on one loop. Turn in Ambermill Investigations before killing the mages for The Weaver."}, {k="取捨", text="Do 99 and A Recipe For Death together in Pyrewood Village. Turn in 99, then take Arugal's Folly and Stop the Spread and do both at the Greymane Wall."}, {k="取捨", text="Head back to the Barrens at level 20. Skip escort Escorting Erland, ambush Pyrewood Ambush, and the Shadowfang Keep chain if you haven't started them. Turn in any active Undercity quests, such as A Recipe For Death or Rot Hide Origins, when you fly back from the Sepulcher."}, {k="取捨", text="Accept Journey to Hillsbrad Foothills at level 19 and save it for Tarren Mill in Hillsbrad Foothills. Return to the Barrens first to avoid a separate trip."}, {k="提醒", text="Below level 20? Finish the solo quests and grind normal mobs at the Greymane Wall (around 43, 81) or Ambermill (around 63, 65). Run Shadowfang Keep if you have a group. Quest The Book of Ur requires level 16, while Arugal Must Die and Deathstalkers in Shadowfang require 18.", s={{"Below level 20?"}, {"Finish the solo quests and grind normal mobs at the Greymane Wall (around 43, 81) or Ambermill (around 63, 65)"}, {"Run Shadowfang Keep if you have a group"}, {"Quest The Book of Ur requires level 16, while Arugal Must Die and Deathstalkers in Shadowfang require 18"}}}}, danger={[1]="Level 24-25 elite Sons of Arugal patrol Silverpine Forest. Give them a wide berth. If one spots you, stay out of the woods.", [2]="Sons of Arugal also patrol the road from Pyrewood Village to the Greymane Wall. Leave after the ambush and don't chase mobs along the wall."}, grind={[1]={mob="Dalaran Conjuror", note="Moderate density of normal ranged mobs outside Ambermill. Clear the roadside first. Use terrain to draw mobs away from doorways."}, [2]={mob="Dalaran Wizard", note="Moderate density of normal ranged mobs outside Ambermill, near the Dalaran quest area. Pull singles and watch for guards."}, [3]={mob="Sickly Refugee", note="Dense normal mobs by the Greymane Wall. Pull singles from the roadside. Grind to level 20 before leaving."}}, supply={[1]={npc="Karos Razok"}, [2]={npc="Innkeeper Bates"}, [3]={npc="Sebastian Meloche"}, [4]={npc="Innkeeper Bates"}, [5]={npc="Edwin Harly"}, [6]={npc="Patrice Dwyer"}, [7]={npc="Innkeeper Renee"}, [8]={npc="Innkeeper Renee"}, [9]={npc="Michael Garrett"}, [10]={npc="Thomas Mordan"}, [11]={npc="Ezekiel Graves"}}, steps={[1]={text="At the Durotar zeppelin tower, confirm the Tirisfal Glades route with Frezza (50.82, 13.54). Get off south of Brill and follow the road to Undercity. Keep your hearth at the Crossroads."}, [2]={text="Learn Undercity's flight path from Michael Garrett (63.25, 48.56). Fly to the Sepulcher if unlocked. Otherwise leave the city and take Tirisfal's southwest road into Silverpine Forest."}, [3]={text="Pick up at the Sepulcher → northern farms"}, [4]={text="Learn the Sepulcher flight path from Karos Razok (45.62, 42.60). Keep your current hearth."}, [5]={hint="Speak with Mura Runetotem in the Sepulcher."}, [6]={npc="Mura Runetotem", tgt="Mura Runetotem"}, [7]={hint="Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.", tag="Optional"}, [8]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", tag="Optional"}, [9]={hint="Place Clarice's Pendant on Yuriv's Tomb in Silverpine.", tag="Optional"}, [10]={npc="Yuriv's Tombstone", npcObj=true, tag="Optional"}, [11]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [12]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [13]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [14]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [15]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [16]={hint="Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps."}, [17]={hint="Kill rot hide gnolls at the Dead Fields."}, [18]={hint="Find the Deathstalkers Quinn and Rane Yorick."}, [19]={npc="Rane Yorick", tgt="Rane Yorick"}, [20]={npc="Rane Yorick", tgt="Rane Yorick"}, [21]={hint="Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher."}, [22]={npc="Deathstalker Erland", tgt="Deathstalker Erland", tag="Optional"}, [23]={hint="Escort Erland through the wolves, to Rane Yorick.", tag="Optional"}, [24]={npc="Rane Yorick", tgt="Rane Yorick", tag="Optional"}, [25]={npc="Rane Yorick", tgt="Rane Yorick", tag="Requires quest Escorting Erland, Optional"}, [26]={hint="Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity."}, [27]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [28]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [29]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [30]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [31]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [32]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [33]={hint="Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.", tag="Requires quest Escorting Erland, Optional"}, [34]={npc="High Executor Hadrec", tgt="High Executor Hadrec", tag="Requires quest Escorting Erland, Optional"}, [35]={npc="High Executor Hadrec", tgt="High Executor Hadrec", tag="Requires quest The Deathstalkers' Report, Optional"}, [36]={hint="Speak with Apothecary Renferrel at the Sepulcher.", tag="Requires quest The Deathstalkers' Report, Optional"}, [37]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", tag="Requires quest The Deathstalkers' Report, Optional"}, [38]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", tag="Requires quest Speak with Renferrel, Optional"}, [39]={text="Northern farms → lakeside crossing → crates on the south road"}, [40]={hint="Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher."}, [41]={hint="Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher."}, [42]={npc="Quinn Yorick", tgt="Quinn Yorick"}, [43]={npc="Quinn Yorick", tgt="Quinn Yorick"}, [44]={hint="Gather 3 murloc eyes and bring them to Apothecary Renferrel at the Sepulcher."}, [45]={hint="Go to the Decrepit Ferry."}, [46]={npc="Corpse Laden Boat", npcObj=true}, [47]={npc="Corpse Laden Boat", npcObj=true}, [48]={hint="Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south."}, [49]={npc="Dalaran Crate", npcObj=true}, [50]={npc="Dalaran Crate", npcObj=true}, [51]={hint="Bring the strange pendant to Shadow Priest Allister at the Sepulcher."}, [52]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [53]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [54]={hint="Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher."}, [55]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [56]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [57]={hint="Speak with Shadow Priest Allister at the Sepulcher."}, [58]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [59]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [60]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [61]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [62]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [63]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [64]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [65]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [66]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [67]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [68]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [69]={text="Worgen cave and Ambermill → Fenris ferry → Brill and Undercity"}, [70]={hint="Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher."}, [71]={hint="Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher."}, [72]={hint="Slay 8 Dalaran Wizards and 8 Dalaran Watchers for Shadow Priest Allister in the Sepulcher."}, [73]={hint="Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher."}, [74]={hint="Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher."}, [75]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [76]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [77]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [78]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [79]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [80]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [81]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [82]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [83]={hint="Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher."}, [84]={hint="Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher."}, [85]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [86]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [87]={npc="Shadow Priest Allister", tgt="Shadow Priest Allister"}, [88]={hint="Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher."}, [89]={npc="Quinn Yorick", tgt="Quinn Yorick"}, [90]={npc="Rane Yorick", tgt="Rane Yorick"}, [91]={hint="Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch."}, [92]={npc="Rane Yorick", tgt="Rane Yorick"}, [93]={hint="Bring Deliah's Ring to Magistrate Sevren in Brill."}, [94]={npc="Magistrate Sevren", tgt="Magistrate Sevren"}, [95]={npc="Magistrate Sevren", tgt="Magistrate Sevren"}, [96]={text="After Brill, run to Undercity for the city turn-ins. Learn the flight path from Michael Garrett (63.25, 48.56) if needed."}, [97]={hint="Bring Deliah's Ring to Raleigh."}, [98]={npc="Raleigh Andrean", tgt="Raleigh Andrean"}, [99]={npc="Raleigh Andrean", tgt="Raleigh Andrean"}, [100]={hint="Bring the Sample Ichor to Bethor Iceshard in the Undercity."}, [101]={npc="Bethor Iceshard", tgt="Bethor Iceshard"}, [102]={npc="Bethor Iceshard", tgt="Bethor Iceshard"}, [103]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [104]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [105]={hint="Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.", tag="Optional"}, [106]={npc="Apothecary Zinge", tgt="Apothecary Zinge", tag="Optional"}, [107]={npc="Keeper Bel'dugur", tgt="Keeper Bel'dugur", tag="Only for a Shadowfang Keep run, Optional"}, [108]={text="Return to the Sepulcher → Pyrewood Village → Greymane Wall"}, [109]={text="Fly from Undercity to the Sepulcher, then take the west road south to Pyrewood Village."}, [110]={hint="Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher."}, [111]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [112]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [113]={hint="Report to High Executor Hadrec at the Sepulcher."}, [114]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [115]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [116]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver", tag="Lv 18+. Accept only for Shadowfang Keep., Optional"}, [117]={npc="High Executor Hadrec", tgt="High Executor Hadrec", tag="Lv 18+. Accept only for Shadowfang Keep., Optional"}, [118]={hint="Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher."}, [119]={hint="Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher."}, [120]={npc="Deathstalker Faerleia", tgt="Deathstalker Faerleia", tag="Group, Optional"}, [121]={hint="Help Deathstalker Faerleia kill the Pyrewood Council.", tag="Group, Optional"}, [122]={npc="Deathstalker Faerleia", tgt="Deathstalker Faerleia", tag="Group, Optional"}, [123]={hint="Find the Deathstalker Adamant and Deathstalker Vincent.", tag="Dungeon, Optional", desc="In Shadowfang Keep, find both Deathstalkers. Vincent is at 56.50, 58.50 on floor 1."}, [124]={npc="Deathstalker Vincent", tgt="Deathstalker Vincent", tag="Dungeon, Optional, Unverified", desc="SFK entrance: 44.80, 67.80. Turn in to Vincent on floor 1 at 56.50, 58.50."}, [125]={hint="Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", tag="Dungeon, Optional", desc="The pin marks the Shadowfang Keep entrance. Interior coordinates are unknown."}, [126]={hint="Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", tag="Dungeon, Optional", desc="The pin marks the Shadowfang Keep entrance. Interior coordinates are unknown."}, [127]={hint="Kill Valdred Moray."}, [128]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [129]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [130]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel"}, [131]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver", tag="Dungeon, Optional"}, [132]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [133]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [134]={hint="Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher."}, [135]={hint="Slay 5 Sickly Refugees and 5 Haggard Refugees for Dalar Dawnweaver in The Sepulcher."}, [136]={text="Fenris Isle and shore → Sepulcher turn-ins → Undercity"}, [137]={hint="Bring Thule's Head to High Executor Hadrec at the Sepulcher."}, [138]={hint="Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."}, [139]={npc="A Talking Head", npcObj=true, tag="Drop starts it, Optional"}, [140]={hint="Bring Alaric's Head to his grave.", tag="Drop starts it, Optional"}, [141]={npc="Shallow Grave", npcObj=true, tag="Drop starts it, Optional"}, [142]={npc="Shallow Grave", npcObj=true, tag="Optional"}, [143]={hint="Take Alaric to the hidden alcove.", tag="Optional"}, [144]={npc="Dusty Shelf", npcObj=true, tag="Optional"}, [145]={npc="Dusty Shelf", npcObj=true, tag="Optional"}, [146]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [147]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [148]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [149]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", tag="Lv 19+. Save for Tarren Mill."}, [150]={text="Fly to Undercity if you have turn-ins there. Otherwise hearth straight from the Sepulcher at the next step."}, [151]={npc="Raleigh Andrean", tgt="Raleigh Andrean"}, [152]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [153]={npc="Keeper Bel'dugur", tgt="Keeper Bel'dugur", tag="Dungeon, Optional"}, [154]={hint="Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", tag="Optional"}, [155]={npc="Bethor Iceshard", tgt="Bethor Iceshard", tag="Optional"}, [156]={npc="Danitha Morr", tgt="Danitha Morr", desc="At level 18, return from the Sepulcher to Tirisfal. Visit the fort after the farms."}, [157]={hint="Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers.", desc="At level 18, return from the Sepulcher to Tirisfal. Visit the fort after the farms."}, [158]={npc="Trevan Rol", tgt="Trevan Rol", desc="At level 18, return from the Sepulcher to Tirisfal. Visit the fort after the farms."}, [159]={npc="Trevan Rol", tgt="Trevan Rol"}, [160]={hint="Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."}, [161]={npc="Deathguard Baldren", tgt="Deathguard Baldren"}, [162]={npc="Deathguard Baldren", tgt="Deathguard Baldren", desc="Do this alongside the Sepulcher's Fenris Isle quests."}, [163]={hint="Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party.", desc="Do this alongside the Sepulcher's Fenris Isle quests."}, [164]={npc="Charred Remains", npcObj=true, desc="Do this alongside the Sepulcher's Fenris Isle quests."}, [165]={npc="Charred Remains", npcObj=true}, [166]={hint="Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."}, [167]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [168]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [169]={hint="Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."}, [170]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [171]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [172]={hint="Accompany Lumina Windsinger and help her escape Fenris Keep."}, [173]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [174]={npc="Lumina Windsinger", tgt="Lumina Windsinger", desc="Reach level 20 to unlock the follow-up, A Moon-Kissed Blade."}, [175]={hint="Speak with Lumina Windsinger in the Sepulcher.", desc="Reach level 20 to unlock the follow-up, A Moon-Kissed Blade."}, [176]={npc="Lumina Windsinger", tgt="Lumina Windsinger", desc="Reach level 20 to unlock the follow-up, A Moon-Kissed Blade."}, [177]={npc="Lumina Windsinger", tgt="Lumina Windsinger", tag="Optional", desc="Turn in The Debt. At 20, see Lumina and keep Trevan's notes. Return with all 3 materials."}, [178]={npc="Mennet Carkad", tgt="Mennet Carkad", tag="Optional", desc="Do this on your Silverpine loop. Turn in back in Undercity."}, [179]={hint="Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.", tag="Optional", desc="Do this on your Silverpine loop. Turn in back in Undercity."}, [180]={npc="Mennet Carkad", tgt="Mennet Carkad", tag="Optional", desc="Do this on your Silverpine loop. Turn in back in Undercity."}, [181]={npc="Mennet Carkad", tgt="Mennet Carkad", tag="Optional", desc="Stealth past the Dalaran Mage before entering the room."}, [182]={hint="Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.", tag="Optional", desc="Stealth past the Dalaran Mage before entering the room."}, [183]={npc="Mennet Carkad", tgt="Mennet Carkad", tag="Optional", desc="Stealth past the Dalaran Mage before entering the room."}, [184]={npc="Mennet Carkad", tgt="Mennet Carkad", desc="Undead start in Undercity. Continue lockpicking around Ratchet and Camp Taurajo."}, [185]={hint="Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.", desc="Undead start in Undercity. Continue lockpicking around Ratchet and Camp Taurajo."}, [186]={npc="Shenthul", tgt="Shenthul", desc="Undead start in Undercity. Continue lockpicking around Ratchet and Camp Taurajo."}, [187]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [188]={hint="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."}, [189]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [190]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="First two pins: possible spawns. Swim straight to the Shrine of Remulos to use it."}, [191]={hint="Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.", desc="First two pins: possible spawns. Swim straight to the Shrine of Remulos to use it."}, [192]={npc="Tajarri", tgt="Tajarri", desc="First two pins: possible spawns. Swim straight to the Shrine of Remulos to use it."}, [193]={npc="Tajarri", tgt="Tajarri"}, [194]={hint="Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located."}, [195]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [196]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [197]={hint="Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion."}, [198]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [199]={npc="Cain Firesong", tgt="Cain Firesong", tag="Optional", desc="Take the Brill lead-in if passing. In Undercity, pick up Investigate the Alchemist Shop directly."}, [200]={hint="Speak with Anastasia Hartwell.", tag="Optional", desc="Take the Brill lead-in if passing. In Undercity, pick up Investigate the Alchemist Shop directly."}, [201]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell", tag="Optional", desc="Take the Brill lead-in if passing. In Undercity, pick up Investigate the Alchemist Shop directly."}, [202]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell", desc="Reveal it with the scroll. Fight until it stops, use the coffer, then loot it."}, [203]={hint="Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell. Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.", desc="Reveal it with the scroll. Fight until it stops, use the coffer, then loot it."}, [204]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell", desc="Reveal it with the scroll. Fight until it stops, use the coffer, then loot it."}, [205]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell"}, [206]={hint="Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian."}, [207]={npc="Josef Gregorian", tgt="Josef Gregorian"}, [208]={npc="Josef Gregorian", tgt="Josef Gregorian", star={"Lesser Spellfire Robes", {"MAGE"}}}, [209]={hint="Complete the quest objectives."}, [210]={npc="Josef Gregorian", tgt="Josef Gregorian", star={"Lesser Spellfire Robes", {"MAGE"}}}, [211]={text="Hearth to the Crossroads. If your hearth is unavailable, board the Orgrimmar zeppelin at Zapetta's west platform south of Brill (60.74, 58.87), then fly to the Crossroads."}}},
    ["05-d3"] = {name="Ruins of Lordaeron", entrance="Undercity 72.41, 11.37", pickup="Check Rear Guard Patrol with Linnea in Brill. Linnea also offers Rear Guard Patrol to Orcs and Undead. Visit Linnea and Kristof after getting off the zeppelin. In the Sepulcher, take A Frightened Request from Tabitha and finish A Recipe For Death → A Recipe For Death → A Recipe For Death. See the Apothecarium for Grave and Morbin. Save all six sets of turn-ins for the dungeon leg.", pickupS={{"Check Rear Guard Patrol with Linnea in Brill"}, {"Linnea also offers Rear Guard Patrol to Orcs and Undead", {race={"Orc", "Scourge"}}}, {"Visit Linnea and Kristof after getting off the zeppelin"}, {"In the Sepulcher, take A Frightened Request from Tabitha and finish A Recipe For Death → A Recipe For Death → A Recipe For Death"}, {"See the Apothecarium for Grave and Morbin"}, {"Save all six sets of turn-ins for the dungeon leg"}}, tips={{k="動線", text="Entrance → Witherfang in King's Alley → clear undead → kill the Baron and loot the crest → Rath'mael in the cemetery and Edward to the west. The Forsaken in the market and Victor by the southwest chimney are optional."}, {k="取捨", text="Horde can prioritize a run at levels 16-20. If you haven't done the Silverpine recipe chain, do the Sepulcher quests first so Witherfang counts toward the chain."}, {k="說明", text="The portal is in the Ruins of Lordaeron above Undercity. Use the Undercity map coordinates. Enter the ruins and climb the stone stairs on the left instead of taking the elevator down.", s={{"The portal is in the Ruins of Lordaeron above Undercity"}, {"Use the Undercity map coordinates"}, {"Enter the ruins and climb the stone stairs on the left instead of taking the elevator down"}}}}, steps={[1]={npc="Deathguard Linnea", tgt="Deathguard Linnea", desc="Skip if you finished this in Brill."}, [2]={hint="Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.", desc="Skip if you finished this in Brill."}, [3]={npc="Deathguard Linnea", tgt="Deathguard Linnea", desc="Skip if you finished this in Brill."}, [4]={npc="Deathguard Linnea", tgt="Deathguard Linnea", preText="Rear Guard Patrol"}, [5]={hint="Bring Riptear's Heart to Deathguard Linnea."}, [6]={npc="Deathguard Linnea", tgt="Deathguard Linnea"}, [7]={npc="Deathguard Kristof", tgt="Deathguard Kristof", desc="Quest Rear Guard Patrol has race restrictions. Check whether Kristof offers it to you.", preText="Rear Guard Patrol"}, [8]={npc="Tabitha Heartweaver", tgt="Tabitha Heartweaver"}, [9]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", desc="If you've started this at the Sepulcher, continue from your current progress."}, [10]={hint="Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", desc="If you've started this at the Sepulcher, continue from your current progress."}, [11]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="If you've started this at the Sepulcher, continue from your current progress."}, [12]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Find Bernard's diary in the Pyrewood Village inn.", preText="A Recipe For Death"}, [13]={hint="Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", desc="Find Bernard's diary in the Pyrewood Village inn."}, [14]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", desc="Find Bernard's diary in the Pyrewood Village inn."}, [15]={npc="Apothecary Renferrel", tgt="Apothecary Renferrel", preText="A Recipe For Death"}, [16]={hint="Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."}, [17]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [18]={npc="Theodore Griffs", tgt="Theodore Griffs", preText="A Recipe For Death"}, [19]={npc="Morbin Lightbane", tgt="Morbin Lightbane"}, [20]={text="Ruins of Lordaeron entrance"}, [21]={hint="Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity.", desc="DungeonsForever map 1: Witherfang (70.20, 37.30). Location: Pass the nerubians and look for Witherfang patrolling King's Alley."}, [22]={hint="Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.", desc="Location: Loot undead along the main route through King's Alley, the overlook and cemetery."}, [23]={npc="Abominable Head", npcObj=true, tag="Unverified", desc="Loot and use the Baron's head. Horde can pick this up at 15 after the Nov 6 hotfix. DungeonsForever map 1: The Baron drops the starter (58.80, 69.80)."}, [24]={npc="Crest of Lordaeron", npcObj=true, tag="Unverified", desc="Check the spider courtyard, towers and locked rooms for the Crest of Lordaeron."}, [25]={hint="Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.", desc="Location: Find Edward by the ghouls on the west side of Rath'mael's cemetery. Order: Do step 25 before approaching the body."}, [26]={hint="Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.", desc="DungeonsForever map 1: Rath'mael (43.90, 60.70). Location: Clear space around Rath'mael in the Lordaeron cemetery before pulling."}, [27]={npc="Theodore Griffs", tgt="Theodore Griffs"}, [28]={npc="Morbin Lightbane", tgt="Morbin Lightbane"}, [29]={hint="Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.", desc="Check the spider courtyard, towers and locked rooms for the Crest of Lordaeron."}, [30]={npc="Oran Snakewrithe", tgt="Oran Snakewrithe"}, [31]={hint="Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.", desc="Loot and use the Baron's head. Horde can pick this up at 15 after the Nov 6 hotfix."}, [32]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [33]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", preText="Unending Torment"}, [34]={hint="Bring the Head of the Baron to the body of Othmar in the Undercity."}, [35]={npc="Unfinished Abomination", tgt="Unfinished Abomination"}, [36]={npc="Unfinished Abomination", tgt="Unfinished Abomination", preText="Unending Torment"}, [37]={hint="Report your findings to Master Apothecary Faranell in Undercity."}, [38]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [39]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Find the first reagent in Trade, the herb by the trainer and poison in Rogues' Quarter.", preText="Unending Torment"}, [40]={hint="Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.", desc="Find the first reagent in Trade, the herb by the trainer and poison in Rogues' Quarter."}, [41]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Find the first reagent in Trade, the herb by the trainer and poison in Rogues' Quarter."}, [42]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Inject the serum into the device above the remains.", preText="Unending Torment"}, [43]={hint="Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.", desc="Inject the serum into the device above the remains."}, [44]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Inject the serum into the device above the remains."}, [45]={npc="Deathguard Kristof", tgt="Deathguard Kristof"}, [46]={npc="Tabitha Heartweaver", tgt="Tabitha Heartweaver"}}},
    ["02-10"] = {name="The Barrens: Ratchet & Camp Taurajo", short="Barrens: Ratchet +", tips={{k="交通", text="Finish the northern loop, then hearth to the Crossroads and turn in before flying to Ratchet. Unlock the Camp Taurajo flight path on your first visit."}, {k="取捨", text="Do Tribes at War, Her Name Is Olgra, and Consumed by Hatred together. Keep any tusks you get toward the 60 needed for Consumed by Hatred. Skip farming the rest if you've reached the target level."}, {k="取捨", text="Turn in Letter to Jin'Zil and Ziz Fizziks at the next stop in Stonetalon Mountains. Collect the eggs for Deepmoss Spider Eggs now and turn it in the next time you pass through Ratchet. Save The Ashenvale Hunt and optional The Warsong Reports for Ashenvale."}, {k="取捨", text="Group for the level 20 elite in WANTED: Bruuz, the centaur event in Counterattack!, and border quest Wrongly Blamed, Justly Corrected. Skip the Northwatch Hold escort if you want to avoid extra pulls."}, {k="取捨", text="The miner's loot has a low drop rate. Move on if it won't drop. The four rare quests only start if you find the rare and loot its item."}, {k="提醒", text="Below level 23? Grind lizards and stalkers at the Field to Clear spot (47.11, 77.38), or head south for Gann's Reclamation. Run Wailing Caverns around levels 18-23 (entrance 47.70, 35.00). Bring Leaders of the Fang and Serpentbloom from the Crossroads, Trouble at the Docks and Smart Drinks from Ratchet, and Deviate Hides and Deviate Eradication from the ledge outside the cave.", s={{"Below level 23?"}, {"Grind lizards and stalkers at the Field to Clear spot (47.11, 77.38), or head south for Gann's Reclamation"}, {"Run Wailing Caverns around levels 18-23 (entrance 47.70, 35.00)"}, {"Bring Leaders of the Fang and Serpentbloom from the Crossroads, Trouble at the Docks and Smart Drinks from Ratchet, and Deviate Hides and Deviate Eradication from the ledge outside the cave"}}}}, danger={[1]="An elite pillager at Field to Clear patrols among the normal mobs. Grind lizards on the outside and avoid crossing the battlefield.", [2]="Alliance soldiers cluster at the Dustwallow Marsh border. Skip Wrongly Blamed, Justly Corrected if you don't have a group."}, grind={[1]={mob="Stormhide", note="Dense normal mobs in the Field to Clear. Loop through the grass and stay out of the fighting. Watch for the elite Outraged Pillager."}, [2]={mob="Hecklefang Stalker", note="Dense normal mobs in the same field as the Stormhides. If other players are farming, switch targets along the edge without moving camps."}}, supply={[1]={npc="Devrak"}, [2]={npc="Bragok"}, [3]={npc="Innkeeper Wiley"}, [4]={npc="Grazlix"}, [5]={npc="Innkeeper Wiley"}, [6]={npc="Jazzik"}, [7]={npc="Omusa Thunderhorn"}, [8]={npc="Innkeeper Byula"}, [9]={npc="Sanuye Runetotem"}}, steps={[1]={text="Pick up quests if you're already back at the Crossroads. Joining from the Eastern Kingdoms? Hearth there, or take the Orgrimmar zeppelin south of Brill and fly to the Crossroads. Save your hearth for the end of the northern loop."}, [2]={npc="Mankrik", tgt="Mankrik"}, [3]={npc="Mankrik", tgt="Mankrik"}, [4]={npc="Korran", tgt="Korran"}, [5]={npc="Thork", tgt="Thork"}, [6]={hint="Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads."}, [7]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn", desc="Skip if you already turned it in at the Crossroads."}, [8]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [9]={hint="Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.", desc="Do this only if you didn't finish it at the Crossroads."}, [10]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger", desc="Skip if you already turned it in at the Crossroads."}, [11]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger"}, [12]={text="Fly from the Crossroads to Ratchet if both flight paths are open. Otherwise take the east road and learn Ratchet from Bragok (63.08, 37.16). Keep quest Samophlange if you picked it up at the Crossroads."}, [13]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [14]={npc="Captain Thalo'thas Brightsun", tgt="Captain Thalo'thas Brightsun"}, [15]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [16]={npc="Sputtervalve", tgt="Sputtervalve"}, [17]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig", tag="Optional", desc="Accept only if you're heading to the mine up north."}, [18]={npc="WANTED", npcObj=true, tag="Optional", desc="Level 20 elite. Accept only if you plan to group up."}, [19]={npc="Crane Operator Bigglefuzz", tgt="Crane Operator Bigglefuzz", tag="Optional", desc="Accept only if you're planning a Wailing Caverns run."}, [20]={text="Take Ratchet's north exit to the Sludge Fen and clear the northern flats. If you missed Samophlange, pick it up from Sputtervalve first."}, [21]={hint="Access the control console at the Venture Company research site."}, [22]={npc="Control Console", npcObj=true}, [23]={npc="Control Console", npcObj=true}, [24]={hint="Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again."}, [25]={npc="Control Console", npcObj=true}, [26]={npc="Control Console", npcObj=true}, [27]={hint="Get the Console Key from Tinkerer Sniggles to use on the control console."}, [28]={npc="Control Console", npcObj=true}, [29]={npc="Control Console", npcObj=true}, [30]={hint="Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.", tag="Optional", desc="Cats Eye Emerald has a low drop rate. Try on the way, but don't camp it."}, [31]={npc="Wizzlecrank's Shredder", tgt="Wizzlecrank's Shredder", desc="Kill the foreman for the Ignition Key and bring it to Wizzlecrank."}, [32]={hint="Get the Ignition Key and bring it to Wizzlecrank.", desc="Kill the foreman for the Ignition Key and bring it to Wizzlecrank."}, [33]={npc="Wizzlecrank's Shredder", tgt="Wizzlecrank's Shredder", desc="Kill the foreman for the Ignition Key and bring it to Wizzlecrank."}, [34]={npc="Wizzlecrank's Shredder", tgt="Wizzlecrank's Shredder", desc="Heal up and clear nearby mobs before accepting. The escort starts immediately."}, [35]={hint="Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.", desc="Escort out of the Sludge Fen. Wait for the dialogue and quest credit."}, [36]={hint="Report to Kadrak at the watch tower in northern Barrens."}, [37]={npc="Kadrak", tgt="Kadrak"}, [38]={npc="Kadrak", tgt="Kadrak", tag="Optional", desc="At Splintertree Post, open the Bundle of Reports, then keep all three replies."}, [39]={npc="Vrang Wildgore", tgt="Vrang Wildgore"}, [40]={npc="Vrang Wildgore", tgt="Vrang Wildgore"}, [41]={hint="Collect 6 Savannah Lion Hides from the Savannah Matriarchs and Savannah Patriarchs in the Barrens."}, [42]={hint="Collect 8 Trapped Game from traps found in Sprung Traps in the Barrens."}, [43]={npc="Vrang Wildgore", tgt="Vrang Wildgore"}, [44]={npc="Vrang Wildgore", tgt="Vrang Wildgore"}, [45]={npc="Vrang Wildgore", tgt="Vrang Wildgore"}, [46]={hint="Bring the Bundle of Hides to the hermit on the ridge overlooking the Dry Hills in the Barrens."}, [47]={npc="Terry Longdrink", tgt="Walton"}, [48]={npc="Terry Longdrink", tgt="Walton"}, [49]={hint="Travel to the wrecked caravan and learn more about why the Kul Tirans are here."}, [50]={npc="Terry Longdrink", tgt="Walton"}, [51]={npc="Terry Longdrink", tgt="Walton", tag="Optional", desc="Pull lone sailors off the guard. Wait until Terry Longdrink dies before turning in."}, [52]={hint="Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines.", tag="Optional", desc="Pull lone sailors off the guard. Wait until Terry Longdrink dies before turning in."}, [53]={npc="Terry Longdrink", tgt="Walton", tag="Optional", desc="Pull lone sailors off the guard. Wait until Terry Longdrink dies before turning in."}, [54]={hint="Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads."}, [55]={text="Hearth to the Crossroads after clearing the north, or take the main road south. Turn in to Serena and pick up Jin'Zil's Letter, then fly to Ratchet."}, [56]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger"}, [57]={npc="Darsok Swiftdagger", tgt="Darsok Swiftdagger", desc="On the Sun Rock Retreat leg, find Jin'Zil in the cave at the Stonetalon entrance."}, [58]={text="Finish the Crossroads turn-ins, then fly to Ratchet to turn in Samophlange and the northern quests."}, [59]={hint="Return the Samophlange to Sputtervalve in Ratchet."}, [60]={npc="Sputtervalve", tgt="Sputtervalve"}, [61]={npc="Sputtervalve", tgt="Sputtervalve"}, [62]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig", tag="Optional"}, [63]={hint="Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet.", tag="Optional", desc="Group up or pull to guards. Deal enough damage to get loot credit."}, [64]={npc="Gazlowe", tgt="Gazlowe", tag="Optional"}, [65]={text="Southeast coast and quilboar pickups at Camp Taurajo"}, [66]={hint="Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.", desc="Do this on the Northwatch Hold trip. Open a chest at each Southsea camp first."}, [67]={hint="Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe."}, [68]={npc="Gilthares Firebough", tgt="Gilthares Firebough", tag="Optional", desc="Finish the tower cannons and badges before starting the escort."}, [69]={hint="Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.", tag="Optional", desc="Escort Gilthares from Northwatch Hold to Ratchet. Stay until you get credit."}, [70]={npc="Gazlowe", tgt="Gazlowe"}, [71]={npc="Captain Thalo'thas Brightsun", tgt="Captain Thalo'thas Brightsun"}, [72]={npc="Captain Thalo'thas Brightsun", tgt="Captain Thalo'thas Brightsun", tag="Optional"}, [73]={text="Head southwest from Ratchet through the Stagnant Oasis and the raptor nests, then continue to Camp Taurajo."}, [74]={hint="Bring Verog's Head to Regthar Deathgate, west of the Crossroads.", desc="Group up to clear faster. When you see the yell, head to the tent at 53.06, 41.74."}, [75]={hint="Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads."}, [76]={hint="Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet."}, [77]={hint="Bring the Stolen Silver to Gazrog in the Crossroads."}, [78]={hint="Find Mankrik's wife and then return to him in the Crossroads."}, [79]={text="At Camp Taurajo, learn Omusa Thunderhorn's flight path (44.45, 59.15) if needed. Keep your Crossroads hearth through Sun Rock Retreat."}, [80]={npc="Mangletooth", tgt="Mangletooth"}, [81]={npc="Tatternack Steelforge", tgt="Tatternack Steelforge", tag="Optional", desc="Accept only if you're heading south to kill quilboar."}, [82]={npc="Grunt Logmar", tgt="Grunt Logmar", tag="Optional", desc="WoW Forever group chain. Skip if you can't form a group."}, [83]={text="Fly to the Crossroads for The Angry Scytheclaws, Lost in Battle and other turn-ins. After getting Jorn's lead-in, head southwest for centaurs or fly back to Camp Taurajo."}, [84]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [85]={npc="Gazrog", tgt="Gazrog"}, [86]={npc="Mankrik", tgt="Mankrik"}, [87]={npc="Mankrik", tgt="Mankrik", desc="Turn in Lost in Battle before accepting."}, [88]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [89]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [90]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [91]={hint="Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads."}, [92]={npc="Regthar Deathgate", tgt="Regthar Deathgate"}, [93]={npc="Regthar Deathgate", tgt="Regthar Deathgate", tag="Optional", desc="Group up before accepting. Centaur reinforcements come in waves."}, [94]={hint="Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.", tag="Optional", desc="Defend your allies, kill Warlord Krom'zar and loot a Piece of Krom'zar's Banner."}, [95]={npc="Regthar Deathgate", tgt="Regthar Deathgate", tag="Optional"}, [96]={hint="Speak with Jorn Skyseer at Camp Taurajo."}, [97]={npc="Jorn Skyseer", tgt="Jorn Skyseer"}, [98]={npc="Jorn Skyseer", tgt="Jorn Skyseer"}, [99]={text="South of Camp Taurajo: quilboar and thunder lizards"}, [100]={hint="Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens."}, [101]={hint="Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads."}, [102]={hint="Slay quilboars and collect 4 of Olgra's Adornments for Mankrik's memorial."}, [103]={hint="Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads."}, [104]={hint="Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.", tag="Optional", desc="Pull soldiers separately, then kill the Outraged Pillager."}, [105]={npc="Hoof of Lakota'mani", npcObj=true, tag="Optional", desc="Do this if you find rare Lakota'mani and loot his hoof."}, [106]={hint="Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.", tag="Optional", desc="Do this if you find rare Lakota'mani and loot his hoof."}, [107]={npc="Jorn Skyseer", tgt="Jorn Skyseer", tag="Optional", desc="Do this if you find rare Lakota'mani and loot his hoof."}, [108]={npc="Owatanka's Tailspike", npcObj=true, tag="Optional", desc="Do this if you find rare Owatanka and loot his tailspike."}, [109]={hint="Bring Owatanka's Tailspike to Jorn at Camp Taurajo.", tag="Optional", desc="Do this if you find rare Owatanka and loot his tailspike."}, [110]={npc="Jorn Skyseer", tgt="Jorn Skyseer", tag="Optional", desc="Do this if you find rare Owatanka and loot his tailspike."}, [111]={npc="Harvester's Head", npcObj=true, tag="Optional", desc="Do this if you find the rare Harvester and loot its head."}, [112]={hint="Bring the Harvester's Head to Jorn Skyseer.", tag="Optional", desc="Do this if you find the rare Harvester and loot its head."}, [113]={npc="Jorn Skyseer", tgt="Jorn Skyseer", tag="Optional", desc="Do this if you find the rare Harvester and loot its head."}, [114]={npc="Washte Pawne's Feather", npcObj=true, tag="Optional", desc="Do this if you find rare Washte Pawne and loot his feather."}, [115]={hint="Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.", tag="Optional", desc="Do this if you find rare Washte Pawne and loot his feather."}, [116]={npc="Jorn Skyseer", tgt="Jorn Skyseer", tag="Optional", desc="Do this if you find rare Washte Pawne and loot his feather."}, [117]={npc="Mangletooth", tgt="Mangletooth"}, [118]={npc="Mangletooth", tgt="Mangletooth", desc="Turn in a Blood Shard if you have one. Otherwise kill outside camp for another."}, [119]={hint="Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.", desc="Turn in a Blood Shard if you have one. Otherwise kill outside camp for another."}, [120]={npc="Mangletooth", tgt="Mangletooth", desc="Turn in a Blood Shard if you have one. Otherwise kill outside camp for another."}, [121]={npc="Mangletooth", tgt="Mangletooth", tag="Optional", desc="Accept only if you're heading south to kill all three bosses."}, [122]={npc="Grunt Logmar", tgt="Grunt Logmar", tag="Optional"}, [123]={text="Add the far south if you need XP, then finish your turn-ins"}, [124]={hint="Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.", tag="Optional"}, [125]={hint="Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.", tag="Optional", desc="The three named mobs are in separate settlements. Follow the pins."}, [126]={npc="Gann Stonespire", tgt="Gann Stonespire", tag="Optional", desc="Below 23 and already south? Kill both dwarf types and loot the foreman's journal."}, [127]={hint="Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.", tag="Optional", desc="Below 23 and already south? Kill both dwarf types and loot the foreman's journal."}, [128]={npc="Gann Stonespire", tgt="Gann Stonespire", tag="Optional", desc="Below 23 and already south? Kill both dwarf types and loot the foreman's journal."}, [129]={npc="Sulhasa", tgt="Sulhasa", desc="Find Sulhasa in a tree on the Dustwallow Marsh border."}, [130]={hint="Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely."}, [131]={npc="Sulhasa", tgt="Sulhasa"}, [132]={npc="Mangletooth", tgt="Mangletooth", tag="Optional"}, [133]={npc="Mangletooth", tgt="Mangletooth", tag="Optional", desc="Turn in when you return to the Crossroads."}, [134]={npc="Tatternack Steelforge", tgt="Tatternack Steelforge", tag="Optional"}, [135]={text="Finish Jorn's chain and the two lead-ins for later stops"}, [136]={text="North of Camp Taurajo, look for Swiftmane and Ishamuhale west of Ratchet. Once you loot a Fresh Zhevra Carcass, use it to summon Ishamuhale."}, [137]={hint="Bring Ishamuhale's Fang to Jorn at Camp Taurajo.", desc="Zhevra carcasses decay after 30 minutes."}, [138]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [139]={hint="Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.", tag="Optional", desc="Loot lion fangs, bird kidneys and lizard horns en route. Skip if short."}, [140]={npc="Brewmaster Drohn", tgt="Brewmaster Drohn", tag="Optional"}, [141]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix", tag="Optional", desc="Turn in Raptor Horns first. Accept only if you're planning a Wailing Caverns run."}, [142]={text="Fly from Ratchet to Camp Taurajo and see Jorn. At level 23, skip the Ashenvale hunting lead-in if desired and head west from the Crossroads to Stonetalon."}, [143]={npc="Jorn Skyseer", tgt="Jorn Skyseer"}, [144]={npc="Jorn Skyseer", tgt="Jorn Skyseer", desc="Save the turn-in for Splintertree Post in Ashenvale."}, [145]={npc="Jorn Skyseer", tgt="Jorn Skyseer", desc="Do this with the thunder lizards outside camp. Have three bottles ready."}, [146]={hint="Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.", desc="Do this with the thunder lizards outside camp. Have three bottles ready."}, [147]={npc="Jorn Skyseer", tgt="Jorn Skyseer", desc="Do this with the thunder lizards outside camp. Have three bottles ready."}, [148]={npc="Jorn Skyseer", tgt="Jorn Skyseer"}, [149]={hint="Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo."}, [150]={npc="Jorn Skyseer", tgt="Jorn Skyseer"}, [151]={text="Fly back to the Crossroads for remaining turn-ins, then head west past Honor's Stand (35.26, 27.88) to Stonetalon."}, [152]={npc="Mankrik", tgt="Mankrik"}, [153]={npc="Mankrik", tgt="Mankrik"}, [154]={npc="Korran", tgt="Korran"}, [155]={hint="Bring Lok's Skull to Thork at the Crossroads in the Barrens.", tag="Optional"}, [156]={npc="Thork", tgt="Thork", tag="Optional"}, [157]={npc="Sorek", tgt="Sorek", tag="Optional", desc="Other pickups: Torm Ragetotem in Thunder Bluff or Baltus Fowler in Undercity."}, [158]={hint="Speak with Ruga Ragetotem.", tag="Optional", desc="Accept from a trainer in Orgrimmar, Thunder Bluff or Undercity."}, [159]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional", desc="Accept from a trainer in Orgrimmar, Thunder Bluff or Undercity."}, [160]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional", desc="Do this alongside the Camp Taurajo quests."}, [161]={hint="Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo", tag="Optional", desc="Do this alongside the Camp Taurajo quests."}, [162]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional", desc="Do this alongside the Camp Taurajo quests."}, [163]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional"}, [164]={hint="Speak with Thun'grim Firegaze in the Barrens.", tag="Optional"}, [165]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [166]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Get Iron Bars from goblins, Azurite from farmers and Phlogiston in Razorfen Kraul."}, [167]={npc="Shenthul", tgt="Shenthul", desc="Use the Razor Hill lead-in (To Orgrimmar!) or pick up directly from Shenthul."}, [168]={hint="Speak with Zando'zan at the Cleft of Shadow.", desc="Use the Razor Hill lead-in (To Orgrimmar!) or pick up directly from Shenthul."}, [169]={npc="Zando'zan", tgt="Zando'zan", desc="Use the Razor Hill lead-in (To Orgrimmar!) or pick up directly from Shenthul."}, [170]={npc="Zando'zan", tgt="Zando'zan"}, [171]={hint="Travel to Ratchet and speak with Wrenix the Wretched."}, [172]={npc="Wrenix the Wretched", tgt="Wrenix the Wretched"}, [173]={npc="Wrenix the Wretched", tgt="Wrenix the Wretched", desc="Use E.C.A.C. On the parrot first. Practice Lockpicking on shipboard chests."}, [174]={hint="Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.", desc="Use E.C.A.C. On the parrot first. Practice Lockpicking on shipboard chests."}, [175]={npc="Wrenix the Wretched", tgt="Wrenix the Wretched", desc="Use E.C.A.C. On the parrot first. Practice Lockpicking on shipboard chests."}, [176]={npc="Shenthul", tgt="Shenthul", desc="Watch Shenthul's demonstration, then target him and /salute."}, [177]={hint="Perform the Shattered Salute on Shenthul.", desc="Watch Shenthul's demonstration, then target him and /salute."}, [178]={npc="Shenthul", tgt="Shenthul", desc="Watch Shenthul's demonstration, then target him and /salute."}, [179]={npc="Shenthul", tgt="Shenthul", desc="Fire two flares, approach, then /salute. The wrong order makes him attack."}, [180]={hint="Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.", desc="Fire two flares, approach, then /salute. The wrong order makes him attack."}, [181]={npc="Taskmaster Fizzule", tgt="Taskmaster Fizzule", desc="Fire two flares, approach, then /salute. The wrong order makes him attack."}, [182]={npc="Taskmaster Fizzule", tgt="Taskmaster Fizzule", desc="Pickpocket the key and pick the lock. After the poison, take Hinott's Assistance."}, [183]={hint="Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.", desc="Pickpocket the key and pick the lock. After the poison, take Hinott's Assistance."}, [184]={npc="Shenthul", tgt="Shenthul", desc="Pickpocket the key and pick the lock. After the poison, take Hinott's Assistance."}, [185]={npc="Shenthul", tgt="Shenthul", desc="Turn in at Tarren Mill."}, [186]={npc="Searn Firewarder", tgt="Searn Firewarder", desc="Use any listed Call of Water lead-in or go straight to Islen Waterseer."}, [187]={hint="Find Islen Waterseer in the Barrens.", desc="Use any listed Call of Water lead-in or go straight to Islen Waterseer."}, [188]={npc="Islen Waterseer", tgt="Islen Waterseer", desc="Use any listed Call of Water lead-in or go straight to Islen Waterseer."}, [189]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [190]={hint="Find Brine in Southern Barrens."}, [191]={npc="Brine", tgt="Brine"}, [192]={npc="Brine", tgt="Brine"}, [193]={hint="Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens."}, [194]={npc="Brine", tgt="Brine"}, [195]={npc="Brine", tgt="Brine", desc="Get water at Tarren Mill. Turn it in back in the Barrens after Freewind Post."}, [196]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [197]={hint="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."}, [198]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [199]={text="Tauren"}, [200]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [201]={hint="Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat."}, [202]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [203]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [204]={hint="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit."}, [205]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [206]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [207]={hint="Speak to Dendrite."}, [208]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [209]={text="Windshaper Skyborne"}, [210]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [211]={hint="Seek out the Avatar of Saeyleenan in the southern part Moonglade and learn what it has to share with you about the nature of the windborne cat."}, [212]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [213]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [214]={hint="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan."}, [215]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [216]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [217]={hint="Speak to Dendrite."}, [218]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [219]={text="Finish both racial routes here"}, [220]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Turn in to Turak Runetotem to learn Cat Form and its starter abilities."}, [221]={hint="Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.", desc="Turn in to Turak Runetotem to learn Cat Form and its starter abilities."}, [222]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Turn in to Turak Runetotem to learn Cat Form and its starter abilities."}, [223]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="After accepting, choose a Succubus or Incubus with Cazul."}, [224]={hint="Speak with Cazul in the Cleft of Shadow.", desc="After accepting, choose a Succubus or Incubus with Cazul."}, [225]={npc="Cazul", tgt="Cazul", desc="After accepting, choose a Succubus or Incubus with Cazul."}, [226]={text="Western route: Succubus"}, [227]={npc="Cazul", tgt="Cazul"}, [228]={hint="Speak with Zankaja in Orgrimmar."}, [229]={npc="Zankaja", tgt="Zankaja"}, [230]={npc="Zankaja", tgt="Zankaja"}, [231]={hint="Speak with Gazrog at the Crossroads."}, [232]={npc="Gazrog", tgt="Gazrog"}, [233]={npc="Gazrog", tgt="Gazrog"}, [234]={hint="Speak with Ken'zigla at the Malaka'jin."}, [235]={npc="Ken'zigla", tgt="Ken'zigla"}, [236]={npc="Ken'zigla", tgt="Ken'zigla"}, [237]={hint="Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo."}, [238]={npc="Grunt Logmar", tgt="Grunt Logmar"}, [239]={npc="Grunt Logmar", tgt="Grunt Logmar"}, [240]={hint="Bring Ken'zigla's Draught to Dogran in the Barrens."}, [241]={npc="Grunt Dogran", tgt="Grunt Dogran"}, [242]={npc="Grunt Dogran", tgt="Grunt Dogran"}, [243]={hint="Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar."}, [244]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye"}, [245]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Use Dogran's Pendant at the summoning circle in Orgrimmar. Defeat the succubus."}, [246]={hint="Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.", desc="Use Dogran's Pendant at the summoning circle in Orgrimmar. Defeat the succubus."}, [247]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Use Dogran's Pendant at the summoning circle in Orgrimmar. Defeat the succubus."}, [248]={text="Western route: Incubus"}, [249]={npc="Cazul", tgt="Cazul", tag="Optional"}, [250]={hint="Speak with Magar in Orgrimmar.", tag="Optional"}, [251]={npc="Magar", tgt="Magar", tag="Optional"}, [252]={npc="Magar", tgt="Magar", tag="Optional", desc="Kill Shadethicket Stone Movers near Fallen Sky Lake for a Shriveled Scarf."}, [253]={hint="Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", tag="Optional", desc="Kill Shadethicket Stone Movers near Fallen Sky Lake for a Shriveled Scarf."}, [254]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Kill Shadethicket Stone Movers near Fallen Sky Lake for a Shriveled Scarf."}, [255]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Use the scarf to summon the Incubus in Orgrimmar. Defeat it and see Gan'rul."}, [256]={hint="Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", tag="Optional", desc="Use the scarf to summon the Incubus in Orgrimmar. Defeat it and see Gan'rul."}, [257]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Use the scarf to summon the Incubus in Orgrimmar. Defeat it and see Gan'rul."}, [258]={text="Eastern route: shared start"}, [259]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="For the eastern route, see Godrick in Undercity. Pick up once you're level 20."}, [260]={hint="Speak with Godrick Farsan in the Temple of the Damned.", tag="Optional", desc="For the eastern route, see Godrick in Undercity. Pick up once you're level 20."}, [261]={npc="Godrick Farsan", tgt="Godrick Farsan", tag="Optional", desc="For the eastern route, see Godrick in Undercity. Pick up once you're level 20."}, [262]={text="Eastern route: Succubus"}, [263]={npc="Godrick Farsan", tgt="Godrick Farsan", tag="Optional", desc="Loot Dalin's heart in south Silverpine and Comar's near Menethil Harbor."}, [264]={hint="Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.", tag="Optional", desc="Loot Dalin's heart in south Silverpine and Comar's near Menethil Harbor."}, [265]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Loot Dalin's heart in south Silverpine and Comar's near Menethil Harbor."}, [266]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Succubus."}, [267]={hint="Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Succubus."}, [268]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Succubus."}, [269]={text="Eastern route: Incubus"}, [270]={npc="Godrick Farsan", tgt="Godrick Farsan", tag="Optional", desc="Kill Avelina in Silverpine and Isaac Pearson in the Barrens. Loot both hearts."}, [271]={hint="Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", tag="Optional", desc="Kill Avelina in Silverpine and Isaac Pearson in the Barrens. Loot both hearts."}, [272]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Kill Avelina in Silverpine and Isaac Pearson in the Barrens. Loot both hearts."}, [273]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Incubus."}, [274]={hint="Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Incubus."}, [275]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Use the heart at Undercity's summoning circle, then defeat the Incubus."}, [276]={text="Optional class gear"}, [277]={npc="Doan Karhan", tgt="Doan Karhan", tag="Optional", desc="Loot 3 small fragments from BFD acolytes and 1 large fragment from SFK Darksouls.", star={"Orb of Soran'ruk", {"WARLOCK"}}}, [278]={hint="Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", tag="Optional", desc="Loot 3 small fragments from BFD acolytes and 1 large fragment from SFK Darksouls. Pins mark BFD and SFK entrances. Interior mob positions are unconfirmed."}, [279]={npc="Doan Karhan", tgt="Doan Karhan", tag="Optional", desc="Loot 3 small fragments from BFD acolytes and 1 large fragment from SFK Darksouls.", star={"Orb of Soran'ruk", {"WARLOCK"}}}}},
    ["05-d5"] = {name="The Deadmines", entrance="Westfall 38.20, 77.50", pickup="On the way to Silverpine, take Diplomatic Incident from Danitha Morr at Bandarion Keep in Tirisfal and finish the Silverpine and Fenris Isle prerequisites. At level 20, take A Moon-Kissed Blade from Lumina in the Sepulcher and get the notes from Trevan. These quests are for Undead Paladins. Take the Ratchet boat to Booty Bay, then ride north through Stranglethorn into Duskwood and west to Moonbrook.", pickupS={{"On the way to Silverpine, take Diplomatic Incident from Danitha Morr at Bandarion Keep in Tirisfal and finish the Silverpine and Fenris Isle prerequisites"}, {"At level 20, take A Moon-Kissed Blade from Lumina in the Sepulcher and get the notes from Trevan"}, {"These quests are for Undead Paladins"}, {"Take the Ratchet boat to Booty Bay, then ride north through Stranglethorn into Duskwood and west to Moonbrook"}}, tips={{k="動線", text="Mine tunnel → Rhahk'Zor → Sneed and the lumber → Gilnid's forge → blast the door to the docks → Mr. Smite → Captain Greenskin → Edwin VanCleef. Cookie is on the lower deck. Leave after Sneed if you only need the lumber."}, {k="取捨", text="Skip this trip if you're just leveling. For A Moon-Kissed Blade, reach Sneed's room and collect the lumber (Undead Paladins only). Keep going if the group wants loot from the final boss.", s={{"Skip this trip if you're just leveling"}, {"For A Moon-Kissed Blade, reach Sneed's room and collect the lumber (Undead Paladins only)", {race={"Scourge"}, class={"PALADIN"}}}, {"Keep going if the group wants loot from the final boss"}}}, {k="說明", text="Enter the mine building at Moonbrook (42.40, 70.40), go downstairs, and follow the tunnel to the portal at 38.20, 77.50. The Alliance Defias quests are unavailable to Horde.", s={{"Enter the mine building at Moonbrook (42.40, 70.40), go downstairs, and follow the tunnel to the portal at 38.20, 77.50"}, {"The Alliance Defias quests are unavailable to Horde"}}}}, steps={[1]={npc="Danitha Morr", tgt="Danitha Morr"}, [2]={hint="Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."}, [3]={npc="Trevan Rol", tgt="Trevan Rol"}, [4]={npc="Trevan Rol", tgt="Trevan Rol", preText="Diplomatic Incident"}, [5]={hint="Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."}, [6]={npc="Deathguard Baldren", tgt="Deathguard Baldren"}, [7]={npc="Deathguard Baldren", tgt="Deathguard Baldren", preText="A Curious Pair"}, [8]={hint="Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party."}, [9]={npc="Charred Remains", npcObj=true}, [10]={npc="Charred Remains", npcObj=true, preText="A Grim Fate"}, [11]={hint="Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."}, [12]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [13]={npc="Lumina Windsinger", tgt="Lumina Windsinger", preText="Into Fenris Keep"}, [14]={hint="Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."}, [15]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [16]={npc="Lumina Windsinger", tgt="Lumina Windsinger", desc="Skyborne: follow the class steps for the Sepulcher in Silverpine Forest.", preText="Lumina Windsinger"}, [17]={hint="Accompany Lumina Windsinger and help her escape Fenris Keep.", desc="Skyborne: follow the class steps for the Sepulcher in Silverpine Forest."}, [18]={npc="Lumina Windsinger", tgt="Lumina Windsinger", desc="Skyborne: follow the class steps for the Sepulcher in Silverpine Forest."}, [19]={npc="Lumina Windsinger", tgt="Lumina Windsinger", preText="The Windshaper's Wrath"}, [20]={hint="Speak with Lumina Windsinger in the Sepulcher."}, [21]={npc="Lumina Windsinger", tgt="Lumina Windsinger"}, [22]={npc="Lumina Windsinger", tgt="Lumina Windsinger", desc="Talk to Trevan Rol after accepting. Get one weapon note and keep the quest in your log.", preText="The Debt"}, [23]={text="The Deadmines entrance"}, [24]={hint="Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", desc="Drop rate: Whitestone Oak Lumber from Goblin Woodcarvers only. Location: Pass Rhahk'Zor. Kill the carpenters by Sneed in the lumber room."}, [25]={npc="Trevan Rol", tgt="Trevan Rol", desc="Bring the notes, Whitestone Oak, Enchanted Silver Bar and Purified Kor Gem."}}},
    ["05-d4"] = {name="Wailing Caverns", entrance="The Barrens 46.00, 36.30", pickup="Finish The Forgotten Pools → The Stagnant Oasis → Altered Beings with Tonga at the Crossroads, then visit Hamuul, Nara, and Zama in Thunder Bluff. Turn in Raptor Horns before taking Smart Drinks and Trouble at the Docks in Ratchet. Find Nalpak and Ebru on the ledge above the cave entrance.", pickupS={{"Finish The Forgotten Pools → The Stagnant Oasis → Altered Beings with Tonga at the Crossroads, then visit Hamuul, Nara, and Zama in Thunder Bluff"}, {"Turn in Raptor Horns before taking Smart Drinks and Trouble at the Docks in Ratchet"}, {"Find Nalpak and Ebru on the ledge above the cave entrance"}}, tips={{k="動線", text="Anacondra in the entrance shallows → Cobrahn west of the river → Pythas, Skum, Serpentis and Verdan to the east → return to the entrance after all four Fanglords, escort the Disciple and kill Mutanus. Gather Serpentbloom, Deviate Hides and Wailing Essence while clearing deviates in both wings."}, {k="取捨", text="Turn in Raptor Horns to unlock Smart Drinks. If you miss one quest, don't keep the group waiting at the door. If the Crossroads oasis chain is done, continue from Hamuul Runetotem."}, {k="說明", text="Enter the outer cave at the Lushwater Oasis (47.70, 35.00) and follow the tunnel to the portal. Pick up quests from Nalpak and Ebru in the alcove above the outer entrance first.", s={{"Enter the outer cave at the Lushwater Oasis (47.70, 35.00) and follow the tunnel to the portal"}, {"Pick up quests from Nalpak and Ebru in the alcove above the outer entrance first"}}}}, steps={[1]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [2]={hint="Report back to Tonga Runetotem with your findings."}, [3]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [4]={npc="Tonga Runetotem", tgt="Tonga Runetotem", preText="The Forgotten Pools"}, [5]={hint="Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."}, [6]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [7]={npc="Tonga Runetotem", tgt="Tonga Runetotem", preText="The Stagnant Oasis"}, [8]={hint="Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", tag="Target: Oasis Snapjaw / Oasis Snapjaw Hatchling"}, [9]={npc="Tonga Runetotem", tgt="Tonga Runetotem"}, [10]={npc="Tonga Runetotem", tgt="Tonga Runetotem", preText="Altered Beings"}, [11]={hint="Speak with Hamuul Runetotem."}, [12]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem"}, [13]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem", preText="Hamuul Runetotem"}, [14]={hint="Speak with Nara Wildmane."}, [15]={npc="Nara Wildmane", tgt="Nara Wildmane"}, [16]={npc="Nara Wildmane", tgt="Nara Wildmane", preText="Nara Wildmane"}, [17]={npc="Apothecary Zamah", tgt="Apothecary Zamah"}, [18]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [19]={hint="Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet."}, [20]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [21]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix", preText="Raptor Horns"}, [22]={npc="Crane Operator Bigglefuzz", tgt="Crane Operator Bigglefuzz"}, [23]={npc="Nalpak", tgt="Nalpak"}, [24]={npc="Ebru", tgt="Ebru"}, [25]={hint="Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns."}, [26]={text="Wailing Caverns entrance"}, [27]={hint="Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.", desc="The pins mark Serpentbloom outside the instance portal. Location: Follow the shallow stream and gather Serpentbloom along both banks."}, [28]={hint="Nalpak in the Wailing Caverns wants 20 Deviate Hides.", desc="Pins mark Deviate Slayers in the cave outside the portal. Location: Kill deviates at the shallow fork and in both wings. Loot hides as you go."}, [29]={hint="Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", desc="Location: Clear the shallow fork, then finish all four mobs in the west and east wings."}, [30]={hint="Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.", desc="Pins mark Devouring Ectoplasms outside. Oozes inside count too. Drop rate: Devouring Ectoplasms outside the dungeon portal. Location: Find oozes along the stream if you're short on Wailing Essence."}, [31]={hint="Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", desc="Map 1: Anacondra 30.5,43.2; Cobrahn 15.6,58.5; Pythas 85.6,28.4; Serpentis 61.6,53.8. Location: Find Anacondra in the shallows, Cobrahn west and the other two bosses east."}, [32]={npc="Glowing Shard", npcObj=true, tag="Unverified", desc="Return to the Disciple after the four Druids. Escort him and kill Mutanus for the shard. DungeonsForever map 1: Mutanus the Devourer drops the shard (34.40, 13.60)."}, [33]={npc="Nalpak", tgt="Nalpak"}, [34]={npc="Ebru", tgt="Ebru"}, [35]={npc="Crane Operator Bigglefuzz", tgt="Crane Operator Bigglefuzz"}, [36]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [37]={hint="Travel to Ratchet to find someone that can tell you more about the glowing shard."}, [38]={npc="Falla Sagewind", tgt="Falla Sagewind"}, [39]={npc="Falla Sagewind", tgt="Falla Sagewind", preText="The Glowing Shard"}, [40]={hint="Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise."}, [41]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem"}, [42]={npc="Nara Wildmane", tgt="Nara Wildmane"}, [43]={npc="Apothecary Zamah", tgt="Apothecary Zamah"}}},
    ["02-11"] = {name="Stonetalon Mountains", tips={{k="交通", text="Unlock the flight path and set your Hearthstone on your first visit to Sun Rock Retreat. After the turn-in by the southern pass, hearth back to Sun Rock Retreat and fly to Ratchet."}, {k="取捨", text="Pick up the Gaea Seeds at Mirkfallon Lake and do Cenarius' Legacy at Stonetalon Peak. Turn in the seeds, then do all four Charred Vale objectives on one loop. Turn in Calling in the Reserves at the Great Lift on the way to Freewind Post."}, {k="取捨", text="Kill Ordanus for Ordanus on the Splintertree Post leg. Continue Further Instructions-Gerenzo Wrenchwhistle only if you plan to revisit Windshear Crag. That saves a round trip to Ratchet."}, {k="取捨", text="Besseleth and Earthen Arise involve elites. Quest Jin'Zil's Forest Magic sends you after several kinds of beasts and turns in at the south end. Turn it in only if you already have the materials."}, {k="提醒", text="Below level 25? Grind Bloodfury harpies or fire elementals on the edge of the Charred Vale (around 32, 64). Pull singles first.", s={{"Below level 25?"}, {"Grind Bloodfury harpies or fire elementals on the edge of the Charred Vale (around 32, 64)"}, {"Pull singles first"}}}}, danger={[1]="Besseleth is an elite spider near Webwinder Path. Clear the small spiders first. Skip it if you don't have a group.", [2]="The cave in Boulderslide Ravine is narrow. Clear a path from the entrance to the barrel before opening it to summon Goggeroc."}, grind={[1]={mob="Bloodfury Harpy", note="Moderate density of normal mobs at the Charred Vale's east entrance. Pick off singles outside, watch for patrols, and grind from 23."}, [2]={mob="Bloodfury Windcaller", note="Dense normal casters in eastern Charred Vale. Use the cliff for line-of-sight pulls to avoid whole nests. Pair with the Charred Vale quests."}}, supply={[1]={npc="Tharm"}, [2]={npc="Innkeeper Jayka"}, [3]={npc="Borand"}, [4]={npc="Innkeeper Jayka"}, [5]={npc="Grawnal"}, [6]={npc="Jeeda"}}, steps={[1]={text="Take the northwest road from the Crossroads toward Stonetalon. Stop for Seereth Stonebreak in the Barrens (35.26, 27.88)."}, [2]={hint="Speak with Seereth Stonebreak in the Stonetalon Mountains.", tag="If accepted at the Crossroads, Optional"}, [3]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak", tag="If accepted at the Crossroads, Optional"}, [4]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak"}, [5]={text="Go through southern Stonetalon to Malaka'jin, then uphill past the spiders to Windshear Crag."}, [6]={hint="Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [7]={npc="Witch Doctor Jin'Zil", tgt="Witch Doctor Jin'Zil", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [8]={npc="Xen'Zilla", tgt="Xen'Zilla"}, [9]={npc="Witch Doctor Jin'Zil", tgt="Witch Doctor Jin'Zil", tag="Optional"}, [10]={npc="Wanted Poster: Besseleth", npcObj=true, tag="Optional"}, [11]={hint="Speak with Ziz Fizziks in Windshear Crag.", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [12]={npc="Ziz Fizziks", tgt="Ziz Fizziks", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [13]={npc="Ziz Fizziks", tgt="Ziz Fizziks"}, [14]={hint="Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters."}, [15]={hint="Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [16]={hint="Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens."}, [17]={hint="Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", desc="Drop rate: Venture Co. Operators, per QuestieDB."}, [18]={npc="Ziz Fizziks", tgt="Ziz Fizziks"}, [19]={npc="Ziz Fizziks", tgt="Ziz Fizziks"}, [20]={hint="Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.", tag="Optional", desc="Besseleth is elite. Skip if you can't beat her."}, [21]={text="Follow the road up to Sun Rock Retreat. Learn the flight path from Tharm (45.12, 59.84) and set your hearth with Innkeeper Jayka (47.47, 62.13). Save it until the southern pass turn-ins are done."}, [22]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder", tag="Optional"}, [23]={npc="Tammra Windfield", tgt="Tammra Windfield"}, [24]={npc="Braelyn Firehand", tgt="Braelyn Firehand"}, [25]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder"}, [26]={npc="Tsunaman", tgt="Tsunaman"}, [27]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder"}, [28]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder"}, [29]={npc="Mor'rogal", tgt="Mor'rogal", tag="Optional"}, [30]={text="Loop north around Mirkfallon Lake and Stonetalon Peak. Come back down the same way and turn in the seeds at Sun Rock Retreat before heading west."}, [31]={hint="Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds."}, [32]={hint="Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat."}, [33]={hint="Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.", tag="Optional", desc="Loot the eyes on the Cenarius' Legacy run. Don't farm the rest separately."}, [34]={npc="Tammra Windfield", tgt="Tammra Windfield"}, [35]={npc="Tammra Windfield", tgt="Tammra Windfield"}, [36]={npc="Braelyn Firehand", tgt="Braelyn Firehand"}, [37]={npc="Braelyn Firehand", tgt="Braelyn Firehand", tag="Optional"}, [38]={text="Head west from Sun Rock Retreat into the Charred Vale. Kill harpies and fire elementals, collect Glittering Sunstones, and check the mounds on one loop."}, [39]={hint="Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers."}, [40]={hint="Bring 15 Glittering Sunstones to Mor'rogal."}, [41]={hint="Bring 10 Incendrites to Tsunaman at Sun Rock Retreat."}, [42]={hint="Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.", desc="Use the quest seed on a raised Gaea Dirt Mound."}, [43]={text="Return east to Sun Rock Retreat for turn-ins. Save your hearth for the Malaka'jin and mountain pass return."}, [44]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder"}, [45]={npc="Mor'rogal", tgt="Mor'rogal"}, [46]={npc="Tsunaman", tgt="Tsunaman"}, [47]={npc="Tammra Windfield", tgt="Tammra Windfield"}, [48]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder", tag="Elite, Optional"}, [49]={hint="Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.", tag="Elite, Optional", desc="Bloodfury Ripper is a level 26 elite. Bring a group."}, [50]={npc="Maggran Earthbinder", tgt="Maggran Earthbinder", tag="Elite, Optional"}, [51]={text="After the Charred Vale turn-ins, take the southeast road. Do the optional Boulderslide Ravine quests or go straight to Malaka'jin and the Barrens pass. Save your hearth for after the pass turn-ins."}, [52]={hint="Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.", tag="Optional"}, [53]={npc="Mor'rogal", tgt="Mor'rogal", tag="Optional"}, [54]={npc="Mor'rogal", tgt="Mor'rogal", tag="Optional"}, [55]={hint="Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.", tag="Optional", desc="This summons a level 20 elite. Skip if you're solo."}, [56]={npc="Mor'rogal", tgt="Mor'rogal", tag="Optional"}, [57]={npc="Xen'Zilla", tgt="Xen'Zilla"}, [58]={npc="Witch Doctor Jin'Zil", tgt="Witch Doctor Jin'Zil", tag="Optional"}, [59]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak"}, [60]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak", tag="Skip the return trip if you have enough XP, Optional"}, [61]={hint="Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", tag="Skip the return trip if you have enough XP, Optional, Target: XT:4/XT:9"}, [62]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak", tag="Skip the return trip if you have enough XP, Optional"}, [63]={npc="Seereth Stonebreak", tgt="Seereth Stonebreak", tag="Thunder Bluff prereq, Optional"}, [64]={text="After turning in to Seereth at the pass, hearth to Sun Rock Retreat. Fly from Tharm to Ratchet for the egg and letter. If your hearth is down, run to the Crossroads and fly from there."}, [65]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [66]={hint="Deliver the Sealed Envelope to Sputtervalve in the Barrens."}, [67]={npc="Sputtervalve", tgt="Sputtervalve"}, [68]={npc="Sputtervalve", tgt="Sputtervalve", tag="Later, on the way, Optional"}, [69]={text="If doing the optional Innocent Blood lead-in and holding The Elder Crone, fly from Ratchet to Thunder Bluff. Skip the detour and fly to Orgrimmar if you won't unlock Thunder Bluff along the way."}, [70]={hint="Speak with Magatha in Thunder Bluff.", tag="Thunder Bluff prereq, Optional"}, [71]={npc="Magatha Grimtotem", tgt="Magatha Grimtotem", tag="Thunder Bluff prereq, Optional"}, [72]={npc="Magatha Grimtotem", tgt="Magatha Grimtotem", tag="Thunder Bluff prereq, Optional"}, [73]={hint="Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", tag="Thunder Bluff prereq, Optional"}, [74]={npc="Apothecary Zamah", tgt="Apothecary Zamah", tag="Thunder Bluff prereq, Optional"}, [75]={npc="Apothecary Zamah", tgt="Apothecary Zamah", tag="Thunder Bluff prereq, Optional"}, [76]={npc="Veenix", tgt="Veenix", tag="Optional", desc="Finish this first, then do The Horn of Xelthos in Silverpine for another way into the dungeon."}, [77]={hint="Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village.", tag="Optional", desc="Finish this first, then do The Horn of Xelthos in Silverpine for another way into the dungeon."}, [78]={npc="Veenix", tgt="Veenix", tag="Optional", desc="Finish this first, then do The Horn of Xelthos in Silverpine for another way into the dungeon."}, [79]={npc="Ur'kyo", tgt="Ur'kyo"}, [80]={hint="Complete the quest objectives."}, [81]={npc="Ur'kyo", tgt="Ur'kyo"}, [82]={text="After the optional Thunder Bluff quests, fly to Orgrimmar. Board the Tirisfal zeppelin at Frezza's platform (50.82, 13.54). Get off south of Brill, head to Undercity, then continue to Tarren Mill."}}},
    ["02-12"] = {name="Hillsbrad Foothills", tips={{k="交通", text="Walk from the Sepulcher to Tarren Mill on your first visit. Unlock the flight path with Zarise and set your Hearthstone with Shay. To leave, walk from Undercity to the south tower outside Brill and take the Orgrimmar zeppelin."}, {k="取捨", text="Collect Elixir of Suffering and Elixir of Pain on the west-side loop alongside Battle of Hillsbrad. Turn in Battle of Hillsbrad to unlock Souvenirs of Death, then loot skulls as you kill humans."}, {k="取捨", text="Do Scout Support and Elixir of Agony together around Deathstalker Masoj. If you have Blood of Innocents, continue to the outskirts of Durnholde Keep. Start collecting skulls with Battle of Hillsbrad instead of waiting until after the loop as Forever XP does."}, {k="取捨", text="Skip Dangerous! if the target is missing and you'd need to backtrack. Dun Garok is crowded for Battle of Hillsbrad, so solo it later. Skip the Valuable Vantages chain if you're in a hurry. Higher-level mountain lions patrol its western ridge."}, {k="取捨", text="If you accepted Journey to Tarren Mill at Sun Rock Retreat, finish Blood of Innocents at Durnholde Keep. Turn in Return to Thunder Bluff when you pass through Thunder Bluff on the way to Freewind Post."}, {k="取捨", text="Finish Elixir of Agony → Elixir of Agony, then pick up Elixir of Agony in Undercity on the Tarren Mill leg and do it on the Hillsbrad coast."}, {k="取捨", text="Do The Rescue at Durnholde Keep alongside WANTED: Syndicate Personnel. See the Alterac Mountains section for both quests. The Rescue unlocks Infiltration at level 29."}, {k="提醒", text="At level 27, stop briefly at Freewind Post before Ashenvale. Below 27, grind farmers at Hillsbrad Fields (around 33, 42) or normal Syndicate mobs outside Durnholde Keep (around 77, 43). With a group, you can do Dun Garok.", s={{"At level 27, stop briefly at Freewind Post before Ashenvale"}, {"Below 27, grind farmers at Hillsbrad Fields (around 33, 42) or normal Syndicate mobs outside Durnholde Keep (around 77, 43)"}, {"With a group, you can do Dun Garok"}}}}, danger={[1]="Dun Garok riflemen, priests, and mountaineers assist each other at the stairs. Clear the outside with your group before going in for the captain.", [2]="Take the path above the yeti cave to place the vial at the western peak. If you see higher-level mountain lions, go around along the slope instead of climbing straight up."}, grind={[1]={mob="Hillsbrad Farmer", note="Moderate density of normal mobs on the east side of Hillsbrad Fields. Avoid packs by the farmhouse. Collect Hillsbrad Human Skulls as you go."}, [2]={mob="Hillsbrad Footman", note="Moderate density of normal mobs in the middle of the farm. Look for footman patrols along the fields. Avoid houses with both a councilman and a farmer."}, [3]={mob="Elder Gray Bear", note="Sparse normal mobs in the woods north of Durnholde Keep. Avoid the keep's packs. Pick up a few kills on your way back along the eastern route."}}, supply={[1]={npc="Zarise"}, [2]={npc="Innkeeper Shay"}, [3]={npc="Innkeeper Shay"}, [4]={npc="Kayren Soothallow"}, [5]={npc="Gordon Wendham"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezekiel Graves"}}, steps={[1]={text="Start from Undercity if you arrived from Sun Rock Retreat. Fly to Tarren Mill if unlocked. Otherwise fly to the Sepulcher, follow the south road east into Hillsbrad, then take the north fork. Walk from Undercity if needed. If still in Kalimdor, board the zeppelin outside Orgrimmar first."}, [2]={text="On arrival, learn Zarise's flight path (60.14, 18.62) and set your hearth with Innkeeper Shay (62.78, 19.03)."}, [3]={hint="Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills."}, [4]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [5]={hint="Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", tag="Optional"}, [6]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [7]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Requires quest Journey to Tarren Mill, Optional"}, [8]={text="Pick up at Tarren Mill → bears, spiders, lions and farms to the west"}, [9]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [10]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [11]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [12]={npc="Dangerous!", npcObj=true, tag="Optional"}, [13]={hint="Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor."}, [14]={hint="Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill."}, [15]={hint="Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill."}, [16]={text="After the first western loop, hearth to Tarren Mill or take the main road back."}, [17]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [18]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [19]={npc="Deathguard Samsa", tgt="Deathguard Samsa"}, [20]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [21]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [22]={hint="Give Umpi the Elixir of Suffering."}, [23]={npc="Umpi", tgt="Umpi"}, [24]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [25]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [26]={text="Second farm loop → Durnholde and Mudsnout Blossoms → western smithy"}, [27]={hint="Feed the Elixir of Pain to Stanley."}, [28]={npc="Stanley", tgt="Stanley"}, [29]={hint="Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill."}, [30]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [31]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [32]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [33]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [34]={hint="Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", tag="Optional"}, [35]={hint="High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok."}, [36]={npc="Deathstalker Masoj", tgt="Deathstalker Masoj"}, [37]={npc="Deathstalker Masoj", tgt="Deathstalker Masoj", tag="Finish quest Scout Support, Optional"}, [38]={hint="Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill."}, [39]={hint="Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths."}, [40]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [41]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [42]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [43]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Complete Blood of Innocents first. Turn in at Freewind Post., Optional"}, [44]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [45]={npc="Apothecary Lydon", tgt="Apothecary Lydon"}, [46]={text="Town hall → mine → turn in at Tarren Mill"}, [47]={hint="Kill Magistrate Burnside and 5 Hillsbrad Councilmen. Destroy the Hillsbrad Proclamation. Steal the Hillsbrad Town Registry. Report back to Darthalia in Tarren Mill afterwards."}, [48]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [49]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [50]={hint="Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill."}, [51]={hint="High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.", tag="Optional"}, [52]={hint="Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls."}, [53]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [54]={npc="Deathguard Samsa", tgt="Deathguard Samsa"}, [55]={npc="High Executor Darthalia", tgt="High Executor Darthalia", tag="Optional"}, [56]={npc="High Executor Darthalia", tgt="High Executor Darthalia", tag="Group, Optional"}, [57]={hint="Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", tag="Group, Optional"}, [58]={hint="Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him.", tag="High-level mobs. Wowhead player-reported coords., Optional"}, [59]={npc="Deathstalker Masoj", tgt="Deathstalker Masoj", tag="Optional"}, [60]={npc="High Executor Darthalia", tgt="High Executor Darthalia", tag="Group, Optional"}, [61]={npc="High Executor Darthalia", tgt="High Executor Darthalia", tag="Requires quest Battle of Hillsbrad, Optional"}, [62]={text="Fly from Tarren Mill to Undercity to turn in Elixir of Agony and Darthalia's Sealed Commendation if you have it. Keep your hearth set to Tarren Mill."}, [63]={hint="Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity."}, [64]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell"}, [65]={hint="Take Darthalia's Sealed Commendation to Varimathras in the Undercity.", tag="Optional"}, [66]={npc="Varimathras", tgt="Varimathras", tag="Optional"}, [67]={hint="Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott."}, [68]={npc="Serge Hinott", tgt="Serge Hinott"}, [69]={npc="Serge Hinott", tgt="Serge Hinott", desc="Continue the chain to cure Touch of Zanzil."}, [70]={hint="Wait for Serge Hinott to complete the cure.", desc="Continue the chain to cure Touch of Zanzil."}, [71]={npc="Serge Hinott", tgt="Serge Hinott", desc="Continue the chain to cure Touch of Zanzil."}, [72]={npc="Elegant Letter", npcObj=true, tag="Optional", desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [73]={hint="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.", tag="Optional", desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [74]={npc="Fahrad", tgt="Fahrad", tag="Optional", desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [75]={npc="Ravenholdt Guard", tgt="Ravenholdt Guard", tag="Optional", desc="Repeatable reputation quest. Skip if you're leveling."}, [76]={hint="Loot from: Syndicate Assassin, Syndicate Conjuror, Syndicate Footpad", tag="Optional", desc="Repeatable reputation quest. Skip if you're leveling."}, [77]={npc="Ravenholdt Guard", tgt="Ravenholdt Guard", tag="Optional", desc="Repeatable reputation quest. Skip if you're leveling."}, [78]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Do this alongside the Durnholde quest."}, [79]={hint="Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform.", tag="Optional", desc="Do this alongside the Durnholde quest."}, [80]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Do this alongside the Durnholde quest."}, [81]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Dead Drop outside the village. Min. Level 1; 23+ advised. Use Veenix's Explosives solo."}, [82]={hint="Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", tag="Optional", desc="Dead Drop outside the village. Min. Level 1; 23+ advised. Use Veenix's Explosives solo."}, [83]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Dead Drop outside the village. Min. Level 1; 23+ advised. Use Veenix's Explosives solo."}, [84]={hint="Log", tag="Optional", desc="Wait for the follow-up in your mailbox, then return to the Dead Drop."}, [85]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Wait for the follow-up in your mailbox, then return to the Dead Drop."}, [86]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Level 25+. Learn Vanish and Distract first. Return to Silverpine with the invite."}, [87]={hint="Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", tag="Optional", desc="Level 25+. Learn Vanish and Distract first. Return to Silverpine with the invite."}, [88]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Level 25+. Learn Vanish and Distract first. Return to Silverpine with the invite."}, [89]={hint="Log", tag="Optional", desc="Return only after you receive the follow-up letter."}, [90]={npc="Dead Drop", npcObj=true, tag="Optional", desc="Return only after you receive the follow-up letter."}, [91]={hint="Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.", desc="Keep the full waterskin for Freewind Post in Thousand Needles."}, [92]={npc="Aelthalyste", tgt="Aelthalyste"}, [93]={hint="Complete the quest objectives."}, [94]={npc="Aelthalyste", tgt="Aelthalyste"}, [95]={npc="Anastasia Hartwell", tgt="Anastasia Hartwell", tag="Optional"}, [96]={hint="Speak with Deino.", tag="Optional"}, [97]={npc="Deino", tgt="Deino", tag="Optional"}, [98]={text="Board the Orgrimmar zeppelin south of Brill at Zapetta's west platform (60.74, 58.87) for Freewind Post. At level 29 with Freewind Post finished, go straight from Orgrimmar to Splintertree Post."}}},
    ["05-d7"] = {name="Excavation Site: Wetlands", entrance="Wetlands (Vahlarriel's Search), 47.79, 56.16.", pickup="At level 24, fly from Stonetalon to Orgrimmar and take Changing Tastes from Borstan in the Cleft of Shadow. After Tarren Mill, pick up Dragonmaw Rumors from Zaruk at Hammerfall. Cross the Thandol Span and pass Dun Modr, then follow the mountain road near Thelgen Rock to the Deathstalker Agent. Accept Open the Maw before entering.", pickupS={{"At level 24, fly from Stonetalon to Orgrimmar and take Changing Tastes from Borstan in the Cleft of Shadow"}, {"After Tarren Mill, pick up Dragonmaw Rumors from Zaruk at Hammerfall"}, {"Cross the Thandol Span and pass Dun Modr, then follow the mountain road near Thelgen Rock to the Deathstalker Agent"}, {"Accept Open the Maw before entering"}}, tips={{k="動線", text="From the east entrance, head west through the marsh to Saltspine → take the brushy trail for Thicket Raptors and Shadetooth → clear Dragonmaw in the southwest camp → activate the panel at the dig site and loot the relic from the Relic Guardian."}, {k="取捨", text="A full run covers the meat, the Dragonmaw dispatch, and the relic from the final boss. Save the last Kalimdor turn-in for the next Orgrimmar or Thunder Bluff visit."}, {k="說明", text="The blue portal is up the slope southeast of Whelgar's Excavation Site. The Meeting Stone, Deathstalker Agent, and portal are at separate locations.", s={{"The blue portal is up the slope southeast of Whelgar's Excavation Site"}, {"The Meeting Stone, Deathstalker Agent, and portal are at separate locations"}}}}, steps={[1]={npc="Borstan", tgt="Borstan"}, [2]={npc="Zaruk", tgt="Zaruk"}, [3]={hint="Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp."}, [4]={npc="Deathstalker Agent", tgt="Deathstalker Agent"}, [5]={npc="Deathstalker Agent", tgt="Deathstalker Agent", preText="Dragonmaw Rumors"}, [6]={text="Excavation Site: Wetlands entrance"}, [7]={hint="Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat.", desc="Location: Past Saltspine's lake, take the brushy trail before Shadetooth and kill raptors."}, [8]={hint="Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover.", desc="DungeonsForever map 1: Dragonmaw troops (28.20, 67.20). Location: Pass Shadetooth and clear Dragonmaw troops at the excavation camp."}, [9]={npc="Titan Relic", npcObj=true, tag="Unverified", desc="Loot the Titan Relic from the Relic Guardian and right-click it to start the quest. DungeonsForever map 1: Relic Guardian drops the starter (46.60, 74.10)."}, [10]={npc="Deathstalker Agent", tgt="Deathstalker Agent"}, [11]={npc="Borstan", tgt="Borstan"}, [12]={hint="Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it.", desc="Loot the Titan Relic from the Relic Guardian and right-click it to start the quest."}, [13]={npc="Bashana Runetotem", tgt="Bashana Runetotem"}, [14]={npc="Bashana Runetotem", tgt="Bashana Runetotem", desc="After Elder Knowledge, check whether Bashana gives you the relic again.", preText="Elder Knowledge"}, [15]={hint="Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore.", desc="After Elder Knowledge, check whether Bashana gives you the relic again."}, [16]={npc="Alaana Stormwalker", tgt="Muln Earthfury", desc="After Elder Knowledge, check whether Bashana gives you the relic again."}}},
    ["05-d6"] = {name="Shadowfang Keep", entrance="Silverpine Forest 44.70, 67.80", pickup="Before Silverpine, pick up The Book of Ur in the Apothecarium, then take Deathstalkers in Shadowfang and Arugal Must Die from Hadrec and Dalar at the Sepulcher. Warlocks can pick up The Orb of Soran'ruk east of Camp Taurajo. Undead Paladins should follow the Deadmines chain from Diplomatic Incident to A Moon-Kissed Blade and keep A Moon-Kissed Blade active. On the way to Hillsbrad, fly to the Sepulcher after returning to the Eastern Kingdoms, then go south.", pickupS={{"Before Silverpine, pick up The Book of Ur in the Apothecarium, then take Deathstalkers in Shadowfang and Arugal Must Die from Hadrec and Dalar at the Sepulcher"}, {"Warlocks can pick up The Orb of Soran'ruk east of Camp Taurajo", {class={"WARLOCK"}}}, {"Undead Paladins should follow the Deadmines chain from Diplomatic Incident to A Moon-Kissed Blade and keep A Moon-Kissed Blade active", {race={"Scourge"}, class={"PALADIN"}}}, {"On the way to Hillsbrad, fly to the Sepulcher after returning to the Eastern Kingdoms, then go south"}}, tips={{k="動線", text="Kill Rethilgore and free Adamant → find Vincent on the right side of the courtyard → banquet hall and ramparts → Fenrus's room for the book → clear the tower to Wolf Master Nandos → kill Arugal upstairs and check his table."}, {k="取捨", text="Turn in The Book of Ur and Arugal Must Die outside the dungeon. Turn in Deathstalkers in Shadowfang to Vincent inside. If your group is struggling before level 22, try the Ruins of Lordaeron or Wailing Caverns first."}, {k="說明", text="Head south from the Sepulcher. Take the ramp north of Pyrewood Village into the keep, then go through the outer gate to the dungeon portal by the courtyard. For the City of Dalaran's hidden boss, take the Black Tome from Arugal's table. Use Ambermill's Leyline Device to make the Tome of Dalaran.", s={{"Head south from the Sepulcher"}, {"Take the ramp north of Pyrewood Village into the keep, then go through the outer gate to the dungeon portal by the courtyard"}, {"For the City of Dalaran's hidden boss, take the Black Tome from Arugal's table"}, {"Use Ambermill's Leyline Device to make the Tome of Dalaran"}}}}, steps={[1]={npc="Keeper Bel'dugur", tgt="Keeper Bel'dugur"}, [2]={npc="High Executor Hadrec", tgt="High Executor Hadrec"}, [3]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [4]={npc="Doan Karhan", tgt="Doan Karhan", tag="Optional", desc="Loot the other 3 fragments in Blackfathom Deeps before turning in."}, [5]={text="Shadowfang Keep entrance"}, [6]={hint="Find the Deathstalker Adamant and Deathstalker Vincent.", desc="Location: After Rethilgore, open the cell and follow the Deathstalker up the right stairs."}, [7]={npc="Deathstalker Vincent", tgt="Deathstalker Vincent", tag="Unverified", desc="DungeonsForever map 1: Deathstalker Vincent (56.50, 58.50)."}, [8]={hint="Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", desc="DungeonsForever map 4: The Book of Ur in Fenrus's room (46.10, 62.60). Location: Climb the tower. Check the bottom of the left bookcase in Fenrus's room."}, [9]={hint="Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", tag="Optional", desc="Location: Kill Shadowfang Darksouls on the tower path. Loot only if on the Warlock quest."}, [10]={hint="Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", desc="DungeonsForever map 6: Archmage Arugal (63.90, 20.00). Location: Go upstairs after Wolf Master Nandos and kill Arugal in his room."}, [11]={hint="Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", tag="Optional", desc="Location: Look on the table in Arugal's room. Loot only if on A Moon-Kissed Blade."}, [12]={npc="Dalar Dawnweaver", tgt="Dalar Dawnweaver"}, [13]={npc="Keeper Bel'dugur", tgt="Keeper Bel'dugur"}, [14]={npc="Doan Karhan", tgt="Doan Karhan", tag="Optional", desc="Loot all 3 small fragments in Blackfathom Deeps, then turn in in the Barrens."}}},
    ["02-13"] = {name="Thousand Needles", tips={{k="交通", text="Fly from Orgrimmar to Camp Taurajo, then take the Great Lift at the south end of the Barrens. Unlock Freewind Post on your first visit. Detour to Thunder Bluff only if you have Sacred Fire."}, {k="取捨", text="Turn in the letter from Sun Rock Retreat to the guard at the Great Lift. Do the crate, three harpy types, and Test of Endurance together west of Freewind Post."}, {k="取捨", text="The video introduces Ashenvale before mentioning the Thousand Needles detour. Stop at Freewind Post before the Ashenvale chain. Save the full Shimmering Flats loop for the later Thousand Needles visit."}, {k="取捨", text="Skip the Lakota Windsong escort, the panther cage, and the western patrol follow-up unless you have help or are already passing the targets."}, {k="提醒", text="The Razorfen Kraul entrance is at the south end of the Barrens before the Great Lift. If you're behind on XP, grind the Screeching harpies west of Freewind Post (around 27, 51).", s={{"The Razorfen Kraul entrance is at the south end of the Barrens before the Great Lift"}, {"If you're behind on XP, grind the Screeching harpies west of Freewind Post (around 27, 51)"}}}}, danger={[1]="The elevator drop is fatal. Wait for the platform before crossing the Freewind Post bridge or using the northern lift.", [2]="Opening the crate in the harpy cave spawns enemies. Clear nearby mobs and make sure you have a way out first."}, grind={[1]={mob="Pesterhide Hyena", note="Moderate density of normal mobs in the valley west of Freewind Post. Pull singles on the valley floor and skip the harpy camp detour."}, [2]={mob="Screeching Harpy", note="Moderate density of normal mobs on the western harpy slopes. Pick off lone harpies along the edge while doing the harpy quest."}}, supply={[1]={npc="Nyse"}, [2]={npc="Innkeeper Abeqwa"}, [3]={npc="Starn"}, [4]={npc="Innkeeper Abeqwa"}, [5]={npc="Starn"}, [6]={npc="Montarr"}, [7]={npc="Omusa Thunderhorn"}}, steps={[1]={text="Confirm the Orgrimmar zeppelin at Zapetta's west platform south of Brill (60.74, 58.87). Enter Orgrimmar after landing. Fly through Thunder Bluff if turning in Return to Thunder Bluff. Otherwise fly directly to Camp Taurajo. If still in Tarren Mill, fly to Undercity first."}, [2]={hint="Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", tag="If accepted at Tarren Mill, Optional"}, [3]={npc="Apothecary Zamah", tgt="Apothecary Zamah", tag="If accepted at Tarren Mill, Optional"}, [4]={text="Take the southern Barrens road to the Great Lift and speak to the guard on the north side."}, [5]={hint="Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.", tag="If accepted at Sun Rock Retreat"}, [6]={npc="Grish Longrunner", tgt="Grish Longrunner", tag="If accepted at Sun Rock Retreat"}, [7]={npc="Brave Moonhorn", tgt="Brave Moonhorn"}, [8]={hint="Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post."}, [9]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [10]={text="Take the Great Lift down. Follow the valley east and ride the Freewind Post lift up. Learn Nyse's flight path (45.14, 49.11). Keep your hearth."}, [11]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [12]={npc="Hagar Lightninghoof", tgt="Hagar Lightninghoof"}, [13]={npc="Jandia", tgt="Jandia"}, [14]={npc="Jandia", tgt="Jandia", desc="Rau Cliffrunner also offers this quest (46.14, 51.71)."}, [15]={npc="Elu", tgt="Elu"}, [16]={npc="Wanted Poster - Arnak Grimtotem", npcObj=true}, [17]={text="Clear the centaur camps north of Freewind Post, then head to Dorn and the wind serpent nests."}, [18]={hint="Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post."}, [19]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker"}, [20]={hint="If you have faith, leap from the planks overlooking Thousand Needles.", desc="Jump from the plank directly in front of Dorn. A successful jump teleports you back."}, [21]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker"}, [22]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker"}, [23]={hint="Return the Alien Egg to Hagar Lightninghoof in Freewind Post."}, [24]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [25]={npc="Hagar Lightninghoof", tgt="Hagar Lightninghoof"}, [26]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [27]={npc="Hagar Lightninghoof", tgt="Hagar Lightninghoof"}, [28]={text="Clear the screeching harpies and supply crates to the west. Follow the valley through Highperch to Whitereach Post."}, [29]={hint="Bring 8 Stolen Freewind Supplies to Jandia in Freewind Post.", desc="Head west from Freewind Post, up the harpy slope to the crate in Stop the Screeching's cave. Three in-game spawn points for object 670338."}, [30]={hint="Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies."}, [31]={hint="Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", desc="Clear the cave first. Break the crate at the back to spawn Grenka Bloodscreech."}, [32]={hint="Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post."}, [33]={npc="Pao'ka Swiftmountain", tgt="Pao'ka Swiftmountain", tag="Escort, Optional"}, [34]={hint="Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.", tag="Escort, Optional", desc="At Highperch, loot eggs and clear manticores near the exit before escorting Pao'ka."}, [35]={npc="Motega Firemane", tgt="Motega Firemane", tag="Escort, Optional"}, [36]={hint="Report your findings to Motega Firemane."}, [37]={npc="Motega Firemane", tgt="Motega Firemane"}, [38]={npc="Motega Firemane", tgt="Motega Firemane", tag="Accept if flying to Thunder Bluff, Optional"}, [39]={npc="Wizlo Bearingshiner", tgt="Wizlo Bearingshiner", tag="Elite, Optional"}, [40]={hint="Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.", tag="Elite, Optional", desc="Group up. The elite attacks as soon as you open the cage."}, [41]={npc="Wizlo Bearingshiner", tgt="Wizlo Bearingshiner", tag="Elite, Optional"}, [42]={npc="Assassination Note", npcObj=true, tag="Drop starts it, Optional", desc="The Galak Messenger patrols between camps. Loot and use the Assassination Note."}, [43]={hint="Warn Kanati Greycloud at Whitereach Post of the plot to kill him.", tag="Drop starts it, Optional", desc="The Galak Messenger patrols between camps. Loot and use the Assassination Note."}, [44]={npc="Kanati Greycloud", tgt="Kanati Greycloud", tag="Drop starts it, Optional"}, [45]={npc="Kanati Greycloud", tgt="Kanati Greycloud", tag="Drop starts it, Optional"}, [46]={hint="Protect Kanati Greycloud from the centaur attack.", tag="Drop starts it, Optional", desc="Heal and drink before accepting. The assault starts immediately."}, [47]={npc="Kanati Greycloud", tgt="Kanati Greycloud", tag="Drop starts it, Optional"}, [48]={text="Take the western ramp up Darkcloud Pinnacle for the note, then cross the bridges north."}, [49]={hint="Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.", desc="Take the ramp at 31.5, 36.7 onto the bridge. Search all three camps for the notes."}, [50]={hint="Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."}, [51]={npc="Lakota Windsong", tgt="Lakota Windsong", tag="If time allows, Optional"}, [52]={hint="Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.", tag="If time allows, Optional", desc="Clear the cage area and bridge first, then escort Lakota down the mountain."}, [53]={hint="Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.", tag="If time allows, Optional"}, [54]={text="Return to Freewind Post for turn-ins. Turn in Test of Endurance to Dorn northeast of the post."}, [55]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [56]={npc="Jandia", tgt="Jandia"}, [57]={npc="Jandia", tgt="Jandia"}, [58]={npc="Elu", tgt="Elu"}, [59]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker"}, [60]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [61]={npc="Thalia Amberhide", tgt="Thalia Amberhide", tag="Optional"}, [62]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="If you see it, Optional"}, [63]={hint="Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", tag="If you see it, Optional", desc="Look for Rok'Alim the Pounder in the west valley and near Highperch."}, [64]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="If you see it, Optional"}, [65]={text="If you have Sacred Fire ready and Thunder Bluff unlocked, fly there from Freewind Post. Otherwise skip the next turn-in and continue."}, [66]={npc="Magatha Grimtotem", tgt="Magatha Grimtotem", tag="Turn in at Thunder Bluff, Optional"}, [67]={npc="Brine", tgt="Brine"}, [68]={npc="Brine", tgt="Brine", desc="Get water at Splintertree Post. Turn in back in the Barrens."}, [69]={text="Fly from Freewind Post or Thunder Bluff. If Splintertree Post is locked, fly to the Crossroads and run north past Mor'shan Rampart into Ashenvale, then follow the east road to Splintertree."}}},
    ["02-14"] = {name="Ashenvale", tips={{k="交通", text="Unlock Splintertree Post, then Zoram'gar Outpost. Fly to Splintertree, Sun Rock Retreat, or the Crossroads for outstanding turn-ins, or go straight to Orgrimmar from Zoram'gar. Keep your Hearthstone set to Tarren Mill."}, {k="取捨", text="Do three loops from Splintertree Post: outrunners to the south, lake elementals to the southwest, and satyrs to the north. Do the furbolgs and cave charms together at Zoram'gar."}, {k="取捨", text="The three beasts patrol. Kill them only if you come across them. Trade for missing pages later instead of farming them."}, {k="取捨", text="At level 29, take The Swarm Grows if you're already headed to the Crossroads and Orgrimmar. Turn it in at Orgrimmar for The Swarm Grows, then turn in The Swarm Grows at the Shimmering Flats to unlock The Swarm Grows. Skip the chain if it's out of the way."}, {k="提醒", text="Below level 30? Grind satyrs (around 67, 57) or Thistlefur furbolgs (around 32, 38). Run Blackfathom Deeps on the Zoram Strand if your group is ready. Otherwise, keep questing.", s={{"Below level 30?"}, {"Grind satyrs (around 67, 57) or Thistlefur furbolgs (around 32, 38)"}, {"Run Blackfathom Deeps on the Zoram Strand if your group is ready"}, {"Otherwise, keep questing"}}}}, danger={[1]="Astranaar is an Alliance town with level 40 sentinels by the road. Go around it on the way to Zoram'gar.", [2]="Furbolgs can block the narrow passages in Thistlefur Hold. Clear an escape route before opening the chest or starting Ruul's escort."}, grind={[1]={mob="Felmusk Shadowstalker", note="Moderate density of normal mobs outside the satyr camp. Clear along the edge, watch for patrols and nearby satyrs, and collect Satyr Horns."}, [2]={mob="Ghostpaw Alpha", note="Moderate density of normal mobs in the woods north of Splintertree Post. Pull singles in the open near the flight path if skipping the satyr camp."}, [3]={mob="Xavian Rogue", note="Moderate density of normal mobs at Xavian. Watch for stealthed mobs and patrols. Clear outside first and finish level 29 while collecting Satyr Horns."}}, supply={[1]={npc="Vhulgra"}, [2]={npc="Innkeeper Kaylisk"}, [3]={npc="Burkrum"}, [4]={npc="Innkeeper Kaylisk"}, [5]={npc="Burkrum"}, [6]={npc="Andruk"}, [7]={npc="Wik'Tar"}}, steps={[1]={text="Learn the flight path from Vhulgra at Splintertree Post (73.18, 61.59). Keep your Tarren Mill hearth for the return. If you want to bind in Ashenvale, see Innkeeper Kaylisk (73.99, 60.65)."}, [2]={hint="Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [3]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="If accepted on the Ratchet/Camp Taurajo leg"}, [4]={npc="Senani Thunderheart", tgt="Senani Thunderheart"}, [5]={hint="Complete the quest objectives.", desc="Turn in The Ashenvale Hunt, then do The Ashenvale Hunt before starting the three hunt quests from drops."}, [6]={npc="Senani Thunderheart", tgt="Senani Thunderheart"}, [7]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss"}, [8]={npc="Pixel", tgt="Pixel"}, [9]={npc="Kuray'bin", tgt="Kuray'bin"}, [10]={npc="Gurda Ragescar", tgt="Gurda Ragescar", tag="Check if you already have missing pages, Optional"}, [11]={text="Kill Ashenvale Outrunners south of Splintertree Post, then head southwest to the lake."}, [12]={npc="Sharptalon's Claw", npcObj=true, tag="If you see it, Optional", desc="Kill Sharptalon and right-click the claw in your bags to start the quest."}, [13]={hint="Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.", tag="If you see it, Optional", desc="Kill Sharptalon and right-click the claw in your bags to start the quest."}, [14]={hint="Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost."}, [15]={npc="Warsong Scout", tgt="Warsong Scout", tag="Requires the Warsong Report, Optional", desc="Open the Bundle of Reports, then trade the Warsong Report with the scout."}, [16]={hint="Complete the quest objectives.", tag="Requires the Warsong Report, Optional"}, [17]={npc="Warsong Scout", tgt="Warsong Scout", tag="Requires the Warsong Report, Optional"}, [18]={npc="Torek", tgt="Torek", tag="Escort, Optional"}, [19]={hint="Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", tag="Escort, Optional", desc="Wait by Torek for your group. Combat starts when you accept the escort."}, [20]={hint="Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post."}, [21]={npc="Befouled Water Globe", npcObj=true, tag="If it drops, Optional", desc="Find Tideress by the lake. Right-click the Befouled Water Globe to start."}, [22]={hint="Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.", tag="If it drops, Optional", desc="Find Tideress by the lake. Right-click the Befouled Water Globe to start."}, [23]={npc="Ursangous's Paw", npcObj=true, tag="If it drops, Optional", desc="Kill Ursangous and right-click his paw in your bags to start the quest."}, [24]={hint="Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.", tag="If it drops, Optional", desc="Kill Ursangous and right-click his paw in your bags to start the quest."}, [25]={npc="Shadumbra's Head", npcObj=true, tag="If it drops, Optional", desc="Kill Shadumbra and right-click her head in your bags to start the quest."}, [26]={hint="Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.", tag="If it drops, Optional", desc="Kill Shadumbra and right-click her head in your bags to start the quest."}, [27]={text="Follow the lake northeast toward Splintertree Post. Kill Ordanus and clear the satyr camp on the way back."}, [28]={hint="Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.", tag="If accepted at Sun Rock Retreat, Optional"}, [29]={hint="Collect 16 Satyr Horns for Pixel in Splintertree Post."}, [30]={npc="Warsong Outrider", tgt="Warsong Outrider", tag="Requires the Warsong Report, Optional"}, [31]={hint="Complete the quest objectives.", tag="Requires the Warsong Report, Optional"}, [32]={npc="Warsong Outrider", tgt="Warsong Outrider", tag="Requires the Warsong Report, Optional"}, [33]={npc="Kuray'bin", tgt="Kuray'bin"}, [34]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss"}, [35]={npc="Pixel", tgt="Pixel"}, [36]={npc="Ertog Ragetusk", tgt="Ertog Ragetusk", tag="Turn in after the escort, Optional"}, [37]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="Turn in once you have the catch, Optional"}, [38]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="Turn in once you have the catch, Optional"}, [39]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="Turn in once you have the catch, Optional"}, [40]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="Turn in once you have the catch, Optional"}, [41]={hint="Complete the quest objectives.", tag="Turn in once you have the catch, Optional"}, [42]={npc="Senani Thunderheart", tgt="Senani Thunderheart", tag="Turn in once you have the catch, Optional"}, [43]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss", tag="Accept if you loot the Water Globe, Optional"}, [44]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss", tag="Accept if you loot the Water Globe, Optional"}, [45]={hint="Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.", tag="Requires all pages, Optional", desc="Don't farm missing pages. Use the pages in your bags to assemble the chapters. Pins are for pages 6 and 11. Loot or trade for the other pages along the way."}, [46]={npc="Gurda Ragescar", tgt="Gurda Ragescar", tag="Requires all pages, Optional"}, [47]={text="Fly to Zoram'gar Outpost if unlocked. On a first visit, take Ashenvale's road west, avoid the Alliance guards in Astranaar and continue to the coast. Learn the flight path from Andruk (12.24, 33.80)."}, [48]={hint="Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", tag="If you have the Water Globe breadcrumb, Optional"}, [49]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="If you have the Water Globe breadcrumb, Optional"}, [50]={npc="Warsong Runner", tgt="Warsong Runner", tag="Requires the Warsong Report, Optional"}, [51]={hint="Complete the quest objectives.", tag="Requires the Warsong Report, Optional"}, [52]={npc="Warsong Runner", tgt="Warsong Runner", tag="Requires the Warsong Report, Optional"}, [53]={npc="Karang Amakkar", tgt="Karang Amakkar"}, [54]={npc="Mitsuwa", tgt="Mitsuwa"}, [55]={npc="Marukai", tgt="Marukai", tag="Fills an XP gap, Optional"}, [56]={hint="Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.", tag="Fills an XP gap, Optional"}, [57]={npc="Marukai", tgt="Marukai", tag="Fills an XP gap, Optional"}, [58]={text="Follow the east road to Thistlefur Village. Kill furbolgs and loot the charms in the cave north of the village."}, [59]={hint="Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village. Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale."}, [60]={hint="Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost."}, [61]={npc="Ruul Snowhoof", tgt="Ruul Snowhoof", tag="Escort, Optional"}, [62]={hint="Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.", tag="Escort, Optional", desc="Mobs can spawn at the entrance and inside. Clear the passage before accepting."}, [63]={npc="Karang Amakkar", tgt="Karang Amakkar"}, [64]={npc="Mitsuwa", tgt="Mitsuwa"}, [65]={npc="Karang Amakkar", tgt="Karang Amakkar", tag="Return to the eastern camp, Optional"}, [66]={hint="Place Karang's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.", tag="Return to the eastern camp, Optional", desc="Clear the area before planting the flag. Be ready to control the waves."}, [67]={npc="Karang Amakkar", tgt="Karang Amakkar", tag="Return to the eastern camp, Optional"}, [68]={npc="Muglash", tgt="Muglash", tag="Group escort, Optional"}, [69]={hint="Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.", tag="Group escort, Optional"}, [70]={npc="Warsong Runner", tgt="Warsong Runner", tag="Group escort, Optional"}, [71]={text="Fly from Zoram'gar Outpost to Splintertree Post if you need to turn in Freedom to Ruul or have other quests there. Hearth instead if bound there and ready. If you skipped the escort and have no turn-ins, fly straight to your next stop from Zoram'gar."}, [72]={npc="Yama Snowhoof", tgt="Yama Snowhoof", tag="If escort is complete, Optional"}, [73]={text="If Ordanus is done or you plan to continue with Further Instructions, fly to Sun Rock Retreat (45.12, 59.84) from Zoram'gar or Splintertree. Skip the trip if Stonetalon is clear."}, [74]={npc="Braelyn Firehand", tgt="Braelyn Firehand", tag="If accepted at Sun Rock Retreat, Optional"}, [75]={hint="Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", tag="If accepted and returning to Windshear Crag, Optional"}, [76]={npc="Ziz Fizziks", tgt="Ziz Fizziks", tag="If accepted and returning to Windshear Crag, Optional"}, [77]={npc="Ziz Fizziks", tgt="Ziz Fizziks", tag="If accepted and returning to Windshear Crag, Optional"}, [78]={hint="Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", tag="If accepted and returning to Windshear Crag, Optional", desc="Take the ramp north of Windshear Crag to the platform. Don't look in the lake. The pin marks Gerenzo Wrenchwhistle on the platform."}, [79]={npc="Ziz Fizziks", tgt="Ziz Fizziks", tag="If accepted and returning to Windshear Crag, Optional"}, [80]={npc="Braelyn Firehand", tgt="Braelyn Firehand", tag="Later or with a group, Optional"}, [81]={hint="Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.", tag="Later or with a group, Optional", desc="The guards and cave mobs are packed together. Go in with a group if you're nearby. The first three pins mark caches. The last marks the Talon Den Hoard."}, [82]={npc="Talon Den Hoard", npcObj=true, tag="Later or with a group, Optional"}, [83]={text="With all three Warsong Reports, go to the Crossroads and take the north road to Kadrak by Mor'shan Rampart (48.12, 5.42). If you've unlocked an Ashenvale flight path, you can also take the east road south."}, [84]={hint="Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.", tag="Turn in with all three updated reports, Optional", desc="Turn in the three updated reports here. Open and trade the reports earlier."}, [85]={npc="Kadrak", tgt="Kadrak", tag="Turn in with all three updated reports, Optional"}, [86]={npc="Ulric Frostveil", tgt="Ulric Frostveil", tag="Optional", desc="Accept A Moon-Kissed Blade first, then pick this up at the Zoram Strand in Ashenvale."}, [87]={hint="Bring a Kor Gem to Ulric Frostveil in Ashenvale.", tag="Optional", desc="Accept A Moon-Kissed Blade first, then pick this up at the Zoram Strand in Ashenvale."}, [88]={npc="Ulric Frostveil", tgt="Ulric Frostveil", tag="Optional", desc="Accept A Moon-Kissed Blade first, then pick this up at the Zoram Strand in Ashenvale."}, [89]={hint="Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", tag="Optional", desc="Get all three materials. Horde can reach Deadmines via Stranglethorn and Duskwood. Drop rate: Whitestone Oak Lumber from Goblin Woodcarvers only."}, [90]={npc="Trevan Rol", tgt="Trevan Rol", tag="Optional", desc="With all 3 items, fly to Orgrimmar, zeppelin to Tirisfal, then fly to the Sepulcher."}, [91]={npc="Trevan Rol", tgt="Trevan Rol", tag="Optional", desc="Do it on the Tarren Mill leg, or fly there from the Sepulcher if you're past it."}, [92]={hint="Speak with Ott and ask him to forge your blade.", tag="Optional", desc="Do it on the Tarren Mill leg, or fly there from the Sepulcher if you're past it."}, [93]={npc="Ott", tgt="Ott", tag="Optional", desc="Do it on the Tarren Mill leg, or fly there from the Sepulcher if you're past it."}, [94]={npc="Ott", tgt="Ott", tag="Optional"}, [95]={hint="Watch as Ott forges your blade.", tag="Optional"}, [96]={npc="Ott", tgt="Ott", tag="Optional"}, [97]={npc="Ott", tgt="Ott", tag="Optional", desc="Turn in to get the Moonsilver Blade.", star={"Moonsilver Blade", {"PALADIN"}}}, [98]={hint="Bring Ott's Masterwork to Trevan Rol in Silverpine Forest.", tag="Optional", desc="Turn in to get the Moonsilver Blade."}, [99]={npc="Trevan Rol", tgt="Trevan Rol", tag="Optional", desc="Turn in to get the Moonsilver Blade.", star={"Moonsilver Blade", {"PALADIN"}}}, [100]={npc="Lumina Windsinger", tgt="Lumina Windsinger", tag="Optional", desc="Group for the level 25 elite. Train 2H Swords with Archibald before using Wolfsbane.", star={"Wolfsbane", {"PALADIN"}}}, [101]={hint="Use the Moonsilver Blade to destroy Old Fire-Eye in Silverpine Forest.", tag="Optional", desc="Group for the level 25 elite. Train 2H Swords with Archibald before using Wolfsbane."}, [102]={npc="Lumina Windsinger", tgt="Lumina Windsinger", tag="Optional", desc="Group for the level 25 elite. Train 2H Swords with Archibald before using Wolfsbane.", star={"Wolfsbane", {"PALADIN"}}}, [103]={hint="Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.", tag="Optional", desc="Skip the gear quest for now if you're missing Phlogiston or mining materials."}, [104]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Skip the gear quest for now if you're missing Phlogiston or mining materials."}, [105]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", star={"Brutal Hauberk", {"WARRIOR"}}}, [106]={hint="Complete the quest objectives.", tag="Optional"}, [107]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", star={"Brutal Hauberk", {"WARRIOR"}}}, [108]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [109]={hint="Speak with Ula'elek in Durotar.", tag="Optional"}, [110]={npc="Ula'elek", tgt="Ula'elek", tag="Optional"}, [111]={npc="Ula'elek", tgt="Ula'elek", tag="Optional", desc="Do this with Satyr Horns after finishing Brutal Hauberk."}, [112]={hint="Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar.", tag="Optional", desc="Do this with Satyr Horns after finishing Brutal Hauberk."}, [113]={npc="Ula'elek", tgt="Ula'elek", tag="Optional", desc="Do this with Satyr Horns after finishing Brutal Hauberk."}, [114]={npc="Ula'elek", tgt="Ula'elek", tag="Optional"}, [115]={hint="Complete the quest objectives.", tag="Optional"}, [116]={npc="Ula'elek", tgt="Ula'elek", tag="Optional"}, [117]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [118]={hint="Speak with Orm Stonehoof in Thunder Bluff.", tag="Optional"}, [119]={npc="Orm Stonehoof", tgt="Orm Stonehoof", tag="Optional"}, [120]={npc="Orm Stonehoof", tgt="Orm Stonehoof", tag="Optional", desc="Backtrack for the gear only if you have a group or are high enough level."}, [121]={hint="Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.", tag="Optional", desc="Backtrack for the gear only if you have a group or are high enough level."}, [122]={npc="Orm Stonehoof", tgt="Orm Stonehoof", tag="Optional", desc="Backtrack for the gear only if you have a group or are high enough level."}, [123]={npc="Orm Stonehoof", tgt="Orm Stonehoof", tag="Optional"}, [124]={hint="Complete the quest objectives.", tag="Optional"}, [125]={npc="Orm Stonehoof", tgt="Orm Stonehoof", tag="Optional"}, [126]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [127]={hint="Speak with Velora Nitely in the Undercity.", tag="Optional"}, [128]={npc="Velora Nitely", tgt="Velora Nitely", tag="Optional"}, [129]={npc="Velora Nitely", tgt="Velora Nitely", tag="Optional", desc="Requires a detour to the Wetlands. Skip if you're only leveling."}, [130]={hint="Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.", tag="Optional", desc="Requires a detour to the Wetlands. Skip if you're only leveling."}, [131]={npc="Velora Nitely", tgt="Velora Nitely", tag="Optional", desc="Requires a detour to the Wetlands. Skip if you're only leveling."}, [132]={npc="Velora Nitely", tgt="Velora Nitely", tag="Optional"}, [133]={hint="Complete the quest objectives.", tag="Optional"}, [134]={npc="Velora Nitely", tgt="Velora Nitely", tag="Optional"}, [135]={hint="Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.", desc="Head southwest from Ashenvale to turn in in the Barrens."}, [136]={npc="Brine", tgt="Brine", desc="Head southwest from Ashenvale to turn in in the Barrens."}, [137]={npc="Brine", tgt="Brine"}, [138]={hint="Bring the Vial of Purest Water to Islen Waterseer in the Barrens."}, [139]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [140]={npc="Islen Waterseer", tgt="Islen Waterseer", desc="Purify it in Silverpine when passing through on the Tarren Mill leg."}, [141]={npc="Deino", tgt="Deino", tag="Optional", desc="Stand inside the waterfall and use the quest bottle."}, [142]={hint="Bring the Xavian Water Sample to Deino in Orgrimmar.", tag="Optional", desc="Stand inside the waterfall and use the quest bottle."}, [143]={npc="Deino", tgt="Deino", tag="Optional", desc="Stand inside the waterfall and use the quest bottle."}, [144]={npc="Deino", tgt="Deino", tag="Optional"}, [145]={hint="Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.", tag="Optional"}, [146]={npc="Kil'hala", tgt="Kil'hala", tag="Optional"}, [147]={npc="Kil'hala", tgt="Kil'hala", tag="Optional"}, [148]={hint="Complete the quest objectives.", tag="Optional"}, [149]={npc="Kil'hala", tgt="Kil'hala", tag="Optional"}, [150]={text="After turning in the Warsong Reports, return to the Crossroads and fly to Orgrimmar. Otherwise fly from Splintertree Post, Zoram'gar Outpost or Sun Rock Retreat. Train level 30 skills, then take the Tirisfal zeppelin from Frezza's platform (50.82, 13.54). Get off at Brill and head to Undercity. Hearth to Tarren Mill only if you have no Undercity quests or training."}}},
    ["05-d8"] = {name="Blackfathom Deeps", entrance="Ashenvale 16.50, 11.00", pickup="Accept Trouble in the Deeps from Tsunaman at Sun Rock Retreat and save it for Je'neu Sancrea at Zoram'gar. Warlocks can take The Orb of Soran'ruk on the Barrens leg. Undead Paladins should keep A Moon-Kissed Blade from the Sepulcher in their log. Pick up The Essence of Aku'Mai and Amongst the Ruins on the Zoram Strand. If you loot the note in the outer cave, turn it in at the outpost before entering. Undead Paladins can then take Seeking the Kor Gem.", pickupS={{"Accept Trouble in the Deeps from Tsunaman at Sun Rock Retreat and save it for Je'neu Sancrea at Zoram'gar"}, {"Warlocks can take The Orb of Soran'ruk on the Barrens leg"}, {"Undead Paladins should keep A Moon-Kissed Blade from the Sepulcher in their log"}, {"Pick up The Essence of Aku'Mai and Amongst the Ruins on the Zoram Strand"}, {"If you loot the note in the outer cave, turn it in at the outpost before entering"}, {"Undead Paladins can then take Seeking the Kor Gem"}}, tips={{k="動線", text="Follow the flooded cave to Ghamoo-ra's pool and find Thaelrid in the underwater side cave → past Lady Sarevess and Gelihast to Lorgus Jett in the Twilight camp. Warlocks loot shards there. Use the stone under the bridge for Aquanis and his globe → Kelris → get the group ready before lighting all four braziers for Aku'mai."}, {k="取捨", text="Do The Essence of Aku'Mai and look for the note in the outer cave on one trip. If the note doesn't drop, do the other quests anyway. Undead Paladins with Seeking the Kor Gem can finish it on the same run.", s={{"Do The Essence of Aku'Mai and look for the note in the outer cave on one trip"}, {"If the note doesn't drop, do the other quests anyway"}, {"Undead Paladins with Seeking the Kor Gem can finish it on the same run", {race={"Scourge"}, class={"PALADIN"}}}}}, {k="說明", text="Swim in from the ruins at the northwest end of the Zoram Strand. Follow the submerged passage through the cave to the dungeon portal. The braziers around Kelris each trigger a wave. Light them one at a time.", s={{"Swim in from the ruins at the northwest end of the Zoram Strand"}, {"Follow the submerged passage through the cave to the dungeon portal"}, {"The braziers around Kelris each trigger a wave"}, {"Light them one at a time"}}}}, steps={[1]={npc="Tsunaman", tgt="Tsunaman"}, [2]={hint="Speak to Je'neu Sancrea in Ashenvale."}, [3]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [4]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", desc="Pick up at Zoram'gar Outpost first."}, [5]={hint="Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", desc="Pick up at Zoram'gar Outpost first."}, [6]={npc="Damp Note", npcObj=true, tag="Optional", desc="Keep The Essence of Aku'Mai in your log after Trouble in the Deeps. Don't make the group wait for the note to drop.", preText="Trouble in the Deeps"}, [7]={hint="Bring the Damp Note to Je'neu Sancrea in Ashenvale.", tag="Optional", desc="Keep The Essence of Aku'Mai in your log after Trouble in the Deeps. Don't make the group wait for the note to drop."}, [8]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Optional", desc="Keep The Essence of Aku'Mai in your log after Trouble in the Deeps. Don't make the group wait for the note to drop."}, [9]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Optional", desc="Turn in Damp Note (Allegiance to the Old Gods), then accept from the same NPC.", preText="Allegiance to the Old Gods"}, [10]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [11]={npc="Ulric Frostveil", tgt="Ulric Frostveil", tag="Optional", desc="Take A Moon-Kissed Blade. Get the Purified Kor Gem here before turning it in."}, [12]={hint="Bring a Kor Gem to Ulric Frostveil in Ashenvale.", tag="Optional"}, [13]={npc="Ulric Frostveil", tgt="Ulric Frostveil", tag="Optional"}, [14]={text="Blackfathom Deeps entrance"}, [15]={npc="Argent Guard Thaelrid", tgt="Argent Guard Thaelrid", tag="Unverified", desc="Find Thaelrid in the flooded passage by the turtle pool before the Twilight altar. DungeonsForever map 1: Argent Guard Thaelrid pickup (20.90, 73.70)."}, [16]={hint="Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", tag="Optional", desc="DungeonsForever map 2: Lorgus Jett (38.80, 20.00). Alternate pin: 44.1, 23.4. Location: Past Gelihast's flooded cave, find Lorgus Jett in the Twilight camp."}, [17]={hint="Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", tag="Optional", desc="Location: Kill acolytes from the Twilight camp to the sanctum and loot three shards."}, [18]={hint="Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", desc="DungeonsForever map 2: Twilight Lord Kelris (51.90, 81.60). Location: Go ashore into the moon sanctum. Kill Kelris at the Twilight altar. Order: For steps 18-19, go underwater first, then enter the sanctuary."}, [19]={hint="Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", desc="DungeonsForever map 2: Fathom Core underwater below the altar (42.50, 74.60). Location: Dive under the bridge at the ruined altar. Use the Fathom Stone for the core. Order: Group up before clicking the stone to summon Baron Aquanis for step 19."}, [20]={npc="Strange Water Globe", npcObj=true, tag="Unverified", desc="Kill Baron Aquanis, loot the globe, and right-click it to start the quest. DungeonsForever map 2: Baron Aquanis drops the starter (44.20, 72.70)."}, [21]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [22]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [23]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Optional"}, [24]={hint="Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."}, [25]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [26]={npc="Bashana Runetotem", tgt="Bashana Runetotem"}}},
    ["03-15"] = {name="Hillsbrad Foothills", tips={{k="取捨", text="Below level 31? Grind yetis in the Hillsbrad cave."}, {k="取捨", text="Turn in the previous round to unlock the Dalaran patrol and Bracers of Binding quests. Do them on the west-side loop. Pick up the city key quest if passing, and skip City of Dalaran if you prefer."}, {k="取捨", text="Finish The Rescue to unlock Infiltration. Save it for Alterac Mountains. Skip the coastal Elixir of Agony branch if you haven't done the earlier quests."}, {k="提醒", text="Helcular's grave is near the Alliance town of Southshore. Approach from outside town.", s={{"Helcular's grave is near the Alliance town of Southshore"}, {"Approach from outside town"}}}, {k="提醒", text="Combine the level 30-32 leg with Hammerfall in Arathi Highlands. Need XP? Grind normal yetis in the west Hillsbrad foothills (around 45, 29), or catch up at Hammerfall.", s={{"Combine the level 30-32 leg with Hammerfall in Arathi Highlands"}, {"Need XP?"}, {"Grind normal yetis in the west Hillsbrad foothills (around 45, 29), or catch up at Hammerfall"}}}}, danger={[1]="Level 55 Alliance guards patrol Southshore. Go around town to reach the grave for Helcular's Revenge.", [2]="Respawns are dense at the yeti cave entrance. Clear the outside while looking for Helcular's Rod. Keep an escape route before going in."}, grind={[1]={mob="Cave Yeti", note="Dense normal mobs on the slope outside the western yeti cave. Pull singles away from the entrance. Start at level 30."}, [2]={mob="Ferocious Yeti", note="Dense normal mobs mixed with Cave Yetis at the cave entrance. Clear the outer edge first for level 31-32 XP."}}, supply={[1]={npc="Zarise"}, [2]={npc="Innkeeper Shay"}, [3]={npc="Innkeeper Shay"}, [4]={npc="Kayren Soothallow"}, [5]={npc="Gordon Wendham"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezekiel Graves"}}, steps={[1]={text="If you took the zeppelin after Splintertree Post, head from Brill's south tower to Undercity. If joining the route in Kalimdor, fly to Orgrimmar, train, then take the zeppelin. Unlock Undercity's flight path with Michael Garrett (63.25, 48.56) if needed."}, [2]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Requires the Undercity prereq, Optional"}, [3]={text="Fly from Undercity to Tarren Mill."}, [4]={text="Learn the Tarren Mill flight path (60.14, 18.62) and set your hearth."}, [5]={npc="Novice Thaivand", tgt="Novice Thaivand"}, [6]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [7]={npc="Keeper Bel'varil", tgt="Keeper Bel'varil"}, [8]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [9]={npc="Tallow", tgt="Tallow"}, [10]={text="Foothill Caverns → Dalaran camp"}, [11]={hint="Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.", desc="Find the tombstone outside Southshore. Avoid Alliance guards."}, [12]={npc="Novice Thaivand", tgt="Novice Thaivand"}, [13]={npc="Novice Thaivand", tgt="Novice Thaivand"}, [14]={hint="Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."}, [15]={hint="Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill."}, [16]={hint="Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill."}, [17]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [18]={npc="Keeper Bel'varil", tgt="Keeper Bel'varil"}, [19]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [20]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [21]={npc="Keeper Bel'varil", tgt="Keeper Bel'varil"}, [22]={hint="Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."}, [23]={hint="Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.", desc="Kill Enslaved Elementals near Dalaran for the bracers."}, [24]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [25]={npc="Keeper Bel'varil", tgt="Keeper Bel'varil"}, [26]={text="Azurelode Mine and the coast near Southshore"}, [27]={hint="Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", tag="Optional"}, [28]={hint="Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel."}, [29]={npc="Helcular's Grave", npcObj=true}, [30]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [31]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [32]={hint="Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", tag="Optional"}, [33]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [34]={npc="Apothecary Lydon", tgt="Apothecary Lydon", tag="Optional"}, [35]={hint="Place the Tainted Keg on the rug for the captured farmers.", tag="Optional"}, [36]={npc="Dusty Rug", npcObj=true, tag="Optional"}, [37]={npc="Sorek", tgt="Sorek", desc="Start Berserker Stance before crossing to Eastern Kingdoms. Ask a city Warrior trainer."}, [38]={hint="Speak with Klannoc Macleod.", desc="Start Berserker Stance before crossing to Eastern Kingdoms. Ask a city Warrior trainer."}, [39]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Start Berserker Stance before crossing to Eastern Kingdoms. Ask a city Warrior trainer."}, [40]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Stock up before stepping onto the grate. Finish to learn Berserker Stance."}, [41]={hint="Kill Big Will, then speak to Klannoc Macleod on Fray Island.", desc="Stock up before stepping onto the grate. Finish to learn Berserker Stance."}, [42]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Stock up before stepping onto the grate. Finish to learn Berserker Stance."}, [43]={npc="Klannoc Macleod", tgt="Klannoc Macleod", tag="Optional", desc="Start the Whirlwind weapon chain separately from Berserker Stance."}, [44]={hint="Speak with Bath'rah the Windwatcher.", tag="Optional", desc="Start the Whirlwind weapon chain separately from Berserker Stance."}, [45]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Start the Whirlwind weapon chain separately from Berserker Stance."}, [46]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Get Bloodscalp Tusks in Stranglethorn and charms near Hammerfall. Return to Bath'rah."}, [47]={hint="Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", desc="Do the water delivery at Splintertree Post first. See Tiev if your Sapta expires."}, [48]={npc="Brazier of Everfount", npcObj=true, tag="Unverified", desc="Do the water delivery at Splintertree Post first. See Tiev if your Sapta expires."}, [49]={npc="Brazier of Everfount", npcObj=true, tag="Unverified"}, [50]={hint="Speak to the Minor Manifestation of Water in Silverpine Forest."}, [51]={npc="Minor Manifestation of Water", tgt="Minor Manifestation of Water"}, [52]={npc="Minor Manifestation of Water", tgt="Minor Manifestation of Water", desc="Turn in at the Shimmering Flats when you return to Kalimdor."}, [53]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [54]={hint="Speak to Strahad Farsan in Ratchet.", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [55]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [56]={npc="Carendin Halgar", tgt="Carendin Halgar", tag="Optional", desc="Undercity breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [57]={hint="Find Strahad Farsan in Ratchet.", tag="Optional", desc="Undercity breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [58]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Optional", desc="Undercity breadcrumb. Take this or Seeking Strahad, or go straight to Ratchet."}, [59]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [60]={hint="Speak with Jorah Annison in the Undercity."}, [61]={npc="Jorah Annison", tgt="Jorah Annison"}, [62]={npc="Jorah Annison", tgt="Jorah Annison", desc="Loot the book on the SW Hillsbrad coast and the manuscript in south Thousand Needles."}, [63]={hint="Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.", desc="Loot the book on the SW Hillsbrad coast and the manuscript in south Thousand Needles."}, [64]={npc="Jorah Annison", tgt="Jorah Annison", desc="Loot the book on the SW Hillsbrad coast and the manuscript in south Thousand Needles."}, [65]={npc="Jorah Annison", tgt="Jorah Annison", desc="Loot 3 rods from Dragonmaw Bonewarders or Shadowwarders. Bring the book/rods to Ratchet."}, [66]={hint="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", desc="Loot 3 rods from Dragonmaw Bonewarders or Shadowwarders. Bring the book/rods to Ratchet."}, [67]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Loot 3 rods from Dragonmaw Bonewarders or Shadowwarders. Bring the book/rods to Ratchet."}, [68]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Use Tome of the Cabal at the circle by Ratchet's tower. Kill the felhunter."}, [69]={hint="Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", desc="Use Tome of the Cabal at the circle by Ratchet's tower. Kill the felhunter."}, [70]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Use Tome of the Cabal at the circle by Ratchet's tower. Kill the felhunter."}, [71]={text="Head east from Tarren Mill through Thoradin's Wall into Arathi Highlands."}}},
    ["05-d10"] = {name="City of Dalaran", entrance="Alterac Mountains 8.46, 59.21", pickup="Take The Grave Knight from Melisara in Tarren Mill and Source of Power from Doctor Martin Felben in Undercity. At level 30, take Prison Break In and Key to the City from Wordeen. Go southeast along Lordamere Lake to the internment camp for both the bloodstone and the key. Turn in at Tarren Mill, then do Dalaran Patrols and take Blood in the Streets. Follow the lakeshore to Modera's image, take Heart of Disruption, and keep the sewer key.", pickupS={{"Take The Grave Knight from Melisara in Tarren Mill and Source of Power from Doctor Martin Felben in Undercity"}, {"At level 30, take Prison Break In and Key to the City from Wordeen"}, {"Go southeast along Lordamere Lake to the internment camp for both the bloodstone and the key"}, {"Turn in at Tarren Mill, then do Dalaran Patrols and take Blood in the Streets"}, {"Follow the lakeshore to Modera's image, take Heart of Disruption, and keep the sewer key"}}, tips={{k="動線", text="Pick up the goblin quests at the sewer entrance → kill Atrexis, then optionally enter the rune chamber for Lynn → take the right path to the street and loot construct cores → get the book upstairs left of the Citadel → portal to the Violet Parlor for the Archmage's Shade. Turn the book in to Rexxie by the entrance."}, {k="取捨", text="Horde prerequisites start at level 30. Finish the access quest before forming a group. Check who has the key, and get your own for later runs. Bring the Tome of Dalaran from Shadowfang Keep if your group wants Lyn the Ignored."}, {k="說明", text="Modera's image and the dungeon portal are at separate spots. Approach from the Lordamere Lake sewer side. Faction restrictions apply to the outdoor city gates and NPC access.", s={{"Modera's image and the dungeon portal are at separate spots"}, {"Approach from the Lordamere Lake sewer side"}, {"Faction restrictions apply to the outdoor city gates and NPC access"}}}}, steps={[1]={npc="Doctor Martin Felben", tgt="Doctor Martin Felben"}, [2]={npc="Melisara", tgt="Melisara"}, [3]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [4]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [5]={hint="Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."}, [6]={hint="Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill.", desc="Approximate coordinates for the refuge footlocker from an in-game run."}, [7]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [8]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [9]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare", preText="Prison Break In, Key to the City"}, [10]={hint="Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."}, [11]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [12]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare", preText="Dalaran Patrols, Key to the City"}, [13]={hint="Find a way into Dalaran along the Lordamere Lake.", desc="Approximate player position at turn-in."}, [14]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera", desc="Approximate player position at pickup and turn-in."}, [15]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera", desc="Accept to get the Dalaran Sewer Key (277507). The Filthy Key is a prerequisite. Approximate player position at pickup and turn-in.", preText="Blood in the Streets"}, [16]={text="City of Dalaran entrance"}, [17]={npc="Rexxie Copperclutch", tag="Unverified", desc="Look for the goblin behind the grate on the right side of the sewer."}, [18]={hint="Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.", desc="DungeonsForever map 2: Atrexis the Grave Knight (48.90, 45.60). Location: Follow the main sewer tunnel to the open area and kill Atrexis."}, [19]={hint="Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.", desc="DungeonsForever map 1: Shattered Sentinel corpses (48.90, 43.30). Location: After the Grave Knight, go up to the street on the right. Kill Shattered Sentinels."}, [20]={hint="Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.", desc="Location: Go upstairs in the building left of the Citadel steps. Check behind the statue."}, [21]={npc="Rexxie Copperclutch", tag="Unverified"}, [22]={hint="Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", desc="DungeonsForever map 1: the Archmage's Shade (45.70, 22.20). Location: Use the Violet Citadel portal to the Violet Parlor. Kill the Archmage's Shade."}, [23]={npc="Melisara", tgt="Melisara"}, [24]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare"}, [25]={npc="Doctor Martin Felben", tgt="Doctor Martin Felben"}, [26]={npc="Magus Wordeen Voidglare", tgt="Magus Wordeen Voidglare", desc="Horde: turn in to the image by the lake outside. Follow your quest marker.", preText="Heart of Disruption"}, [27]={hint="Speak with the Image of Archmage Modera near Dalaran.", desc="Horde: turn in to the image by the lake outside. Follow your quest marker. Approximate player position at pickup and turn-in."}, [28]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera", desc="Horde: turn in to the image by the lake outside. Follow your quest marker. Approximate player position at pickup and turn-in."}}},
    ["05-d9"] = {name="Scarlet Monastery: Graveyard", entrance="Tirisfal Glades 85.20, 32.10", pickup="Unlock Tarren Mill on the way, then follow the north road through Tirisfal from Undercity to the monastery. Finish Razorfen Kraul quest Going, Going, Guano! first. If you run RFK after Thousand Needles, save Hearts of Zeal for the Alterac Mountains leg and do Vorrel in the Graveyard now. See Faranell in the Apothecarium. After the Graveyard, head to the Alterac lakeshore and Tarren Mill.", pickupS={{"Unlock Tarren Mill on the way, then follow the north road through Tirisfal from Undercity to the monastery"}, {"Finish Razorfen Kraul quest Going, Going, Guano! first"}, {"If you run RFK after Thousand Needles, save Hearts of Zeal for the Alterac Mountains leg and do Vorrel in the Graveyard now"}, {"See Faranell in the Apothecarium"}, {"After the Graveyard, head to the Alterac lakeshore and Tarren Mill"}}, tips={{k="動線", text="Clear Crusaders and loot hearts in the entry hall → kill Vishas and find Vorrel on the rack → cross the open cemetery and descend to Bloodmage Thalnos."}, {k="取捨", text="The Graveyard is easy to group for early. Do Vorrel even if you haven't finished Going, Going, Guano!."}, {k="說明", text="Take the far-left entrance. The Graveyard doesn't require the Scarlet Key.", s={{"Take the far-left entrance"}, {"The Graveyard doesn't require the Scarlet Key"}}}}, steps={[1]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Optional", desc="Pick up only if doing Razorfen Kraul first. Fits the Shimmering Flats leg."}, [2]={hint="Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", tag="Optional", desc="This step is in Razorfen Kraul."}, [3]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Optional"}, [4]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Optional", desc="See Razorfen Kraul for Going, Going, Guano!. Hearts drop in all four wings, so pick up before the run.", preText="Going, Going, Guano!"}, [5]={text="Scarlet Monastery: Graveyard entrance"}, [6]={npc="Vorrel Sengutz", tgt="Vorrel Sengutz", tag="Unverified", desc="Find Vorrel on the rack in the first interrogation room. DungeonsForever map 1: Vorrel Sengutz (73.60, 57.20)."}, [7]={hint="Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", tag="Optional", desc="Location: Clear living Scarlet Crusaders from the entrance hall to the interrogation room."}, [8]={hint="Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", desc="Another elite may be in the room. Wait for her to patrol to the dock."}, [9]={npc="Monika Sengutz", tgt="Monika Sengutz"}, [10]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Optional", desc="Collect all 20 before turning in at Undercity."}}},
    ["03-16"] = {name="Arathi Highlands: Hammerfall", short="Hammerfall", tips={{k="取捨", text="Clear the raptors and Syndicate mobs near Hammerfall and the Witherbark mobs to the southeast. If you're already level 32, save the later Call to Arms and Guile of the Raptor quests for the return visit."}, {k="取捨", text="Ward Restocking and Silky Sutures are new in Forever. Turn in Silky Sutures to unlock Ward Restocking. Save them for the next visit if you're already level 32."}, {k="提醒", text="Below level 32? Grind normal Witherbark trolls outside the village (around 68, 69) before leaving for Thousand Needles. Stay out of the crowded camp.", s={{"Below level 32?"}, {"Grind normal Witherbark trolls outside the village (around 68, 69) before leaving for Thousand Needles"}, {"Stay out of the crowded camp"}}}}, danger={[1]="Witherbark Witch Doctors heal inside the huts, and higher-level Headhunters stand outside. Clear from the edge of the fields and save an interrupt."}, grind={[1]={mob="Witherbark Axe Thrower", note="Dense normal ranged mobs outside Witherbark Village. Pull singles from the slope near the quest area. Grind to 32."}, [2]={mob="Witherbark Witch Doctor", note="Dense normal casters in eastern Witherbark Village. Interrupt heals and clear around the buildings. Watch for higher-level Witherbark Headhunters."}}, supply={[1]={npc="Urda"}, [2]={npc="Innkeeper Adegwa"}, [3]={npc="Mu'uta"}, [4]={npc="Innkeeper Adegwa"}, [5]={npc="Graud"}}, steps={[1]={hint="Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands."}, [2]={text="Learn Urda's flight path on arrival in Hammerfall (73.02, 32.70)."}, [3]={npc="Drum Fel", tgt="Drum Fel"}, [4]={npc="Gor'mul", tgt="Gor'mul"}, [5]={hint="Speak with Tor'gan in Hammerfall."}, [6]={npc="Tor'gan", tgt="Tor'gan"}, [7]={npc="Tor'gan", tgt="Tor'gan"}, [8]={npc="Tor'gan", tgt="Tor'gan"}, [9]={npc="Drum Fel", tgt="Drum Fel"}, [10]={npc="Doctor Gregory Victor", tgt="Doctor Gregory Victor"}, [11]={hint="Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall."}, [12]={hint="Get 10 Bloodstone Amulets for Tor'gan in Hammerfall."}, [13]={npc="Tor'gan", tgt="Tor'gan"}, [14]={npc="Tor'gan", tgt="Tor'gan"}, [15]={npc="Tor'gan", tgt="Tor'gan"}, [16]={hint="Give the Raptor Talon Amulet to Gor'mul."}, [17]={npc="Gor'mul", tgt="Gor'mul"}, [18]={npc="Gor'mul", tgt="Gor'mul"}, [19]={hint="Speak with Tor'gan."}, [20]={npc="Tor'gan", tgt="Tor'gan"}, [21]={hint="Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost."}, [22]={hint="Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands."}, [23]={npc="Drum Fel", tgt="Drum Fel"}, [24]={npc="Doctor Gregory Victor", tgt="Doctor Gregory Victor"}, [25]={npc="Doctor Gregory Victor", tgt="Doctor Gregory Victor", desc="Turn in Silky Sutures to the same doctor to unlock the supply quest."}, [26]={hint="Pick up a case of Packaged Tonics at Jorell's lab in Go'shek Farm and return to Doctor Gregory Victor in Hammerfall."}, [27]={npc="Doctor Gregory Victor", tgt="Doctor Gregory Victor"}, [28]={text="Fly to Undercity to train and clear your bags. Take the zeppelin south of Brill to Orgrimmar. Fly to Freewind Post if unlocked. Otherwise fly to Camp Taurajo, take the Great Lift down and ride the Freewind Post lift up."}}},
    ["05-d13"] = {name="Scarlet Monastery: Cathedral", entrance="Tirisfal Glades 85.20, 32.10", pickup="Fly from Hammerfall to Undercity. At level 35, run the Cathedral with the Library and Armory. On the Hillsbrad leg, check Varimathras in the Royal Quarter for Into The Scarlet Monastery at level 33. Below 35? Save the run for the Alterac Mountains return. Bring the Scarlet Key and finish the Library and Armory kills.", pickupS={{"Fly from Hammerfall to Undercity"}, {"At level 35, run the Cathedral with the Library and Armory"}, {"On the Hillsbrad leg, check Varimathras in the Royal Quarter for Into The Scarlet Monastery at level 33"}, {"Below 35?"}, {"Save the run for the Alterac Mountains return"}, {"Bring the Scarlet Key and finish the Library and Armory kills"}}, tips={{k="動線", text="Cross the fountain courtyard and go up the steps → kill Mograine in the Cathedral → wait for Whitemane to resurrect him → kill both."}, {k="取捨", text="Still need Loksey or Herod? Return to the corresponding wing before heading back to town."}, {k="說明", text="Bring the Scarlet Key, or have a Rogue with Look To The Stars Lockpicking open the door.", s={{"Bring the Scarlet Key, or have a Rogue with Look To The Stars Lockpicking open the door"}}}}, steps={[1]={text="Prerequisite: Into The Scarlet Monastery"}, [2]={text="Scarlet Monastery: Cathedral entrance"}, [3]={hint="Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.", desc="Clear around the room first. Whitemane resurrects Mograine. Map 1: Whitemane (49.10, 16.00). Mograine: 49.0, 27.5. Location: Cross the fountain courtyard and go up the steps. Kill both Cathedral bosses. Order: Kill Mograine → Whitemane resurrects him → fight both."}, [4]={npc="Varimathras", tgt="Varimathras", desc="Turn in at Undercity's Royal Quarter after all four bosses count."}}},
    ["05-d12"] = {name="Scarlet Monastery: Armory", entrance="Tirisfal Glades 85.20, 32.10", pickup="Fly from Hammerfall to Undercity and pair the Armory with the Library. At level 33, pick up Into The Scarlet Monastery from Varimathras in the Royal Quarter. If you already have it, keep it active and bring the Scarlet Key. Follow the north road through Tirisfal to the monastery.", pickupS={{"Fly from Hammerfall to Undercity and pair the Armory with the Library"}, {"At level 33, pick up Into The Scarlet Monastery from Varimathras in the Royal Quarter"}, {"If you already have it, keep it active and bring the Scarlet Key"}, {"Follow the north road through Tirisfal to the monastery"}}, tips={{k="動線", text="Open the Armory door → follow the barracks and hall to Herod → clear the Scarlet Trainees after he dies."}, {k="取捨", text="If someone has the Scarlet Key, head straight to the Armory."}, {k="說明", text="Bring the Scarlet Key, or have a Rogue with Look To The Stars Lockpicking open the door.", s={{"Bring the Scarlet Key, or have a Rogue with Look To The Stars Lockpicking open the door"}}}}, steps={[1]={text="Prerequisite: Into The Scarlet Monastery"}, [2]={text="Scarlet Monastery: Armory entrance"}, [3]={text="Kill Herod for Into The Scarlet Monastery. Melee should back out during Whirlwind."}, [4]={text="Keep Into The Scarlet Monastery for Cathedral. Turn it in at Undercity after all four bosses.", desc="Keep the quest after Armory and continue to Cathedral."}}},
    ["05-d11"] = {name="Scarlet Monastery: Library", entrance="Tirisfal Glades 85.20, 32.10", pickup="Fly from Hammerfall to Undercity for the Library. Do Dorn's Test of Faith → Test of Endurance → Test of Strength chain at Freewind Post first. If you've done Sun Rock Retreat, use the south Ashenvale tunnel to Braug, then see Parqual in Undercity. Orcs, Tauren, and Trolls can take Compendium of the Fallen in Thunder Bluff. Mages can do Tabetha's and Tirth's prerequisites at Shimmering Flats and Brackenwall Village, then get the book on the next Eastern Kingdoms visit.", pickupS={{"Fly from Hammerfall to Undercity for the Library"}, {"Do Dorn's Test of Faith → Test of Endurance → Test of Strength chain at Freewind Post first"}, {"If you've done Sun Rock Retreat, use the south Ashenvale tunnel to Braug, then see Parqual in Undercity"}, {"Orcs, Tauren, and Trolls can take Compendium of the Fallen in Thunder Bluff", {race={"Orc", "Tauren", "Troll"}}}, {"Mages can do Tabetha's and Tirth's prerequisites at Shimmering Flats and Brackenwall Village, then get the book on the next Eastern Kingdoms visit", {class={"MAGE"}}}}, tips={{k="動線", text="Take the book from the small left room past the gallery → kill Houndmaster Loksey → collect the books from the last corridor and the shelf before Doan → kill Arcanist Doan and loot the Scarlet Key from the strongbox behind him."}, {k="取捨", text="Get the Scarlet Key to open the Armory and Cathedral. Pick up the quest books on the same run."}, {k="說明", text="Quest Into The Scarlet Monastery spans three wings. See the Cathedral section for the full clear and turn-in.", s={{"Quest Into The Scarlet Monastery spans three wings"}, {"See the Cathedral section for the full clear and turn-in"}}}}, steps={[1]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional", desc="Skip if you did this at Freewind Post."}, [2]={hint="If you have faith, leap from the planks overlooking Thousand Needles.", tag="Optional", desc="Skip if you did this at Freewind Post."}, [3]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional", desc="Skip if you did this at Freewind Post."}, [4]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional", preText="Test of Faith"}, [5]={hint="Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", tag="Optional"}, [6]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional"}, [7]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional", preText="Test of Endurance"}, [8]={hint="Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", tag="Optional"}, [9]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional"}, [10]={npc="Dorn Plainstalker", tgt="Dorn Plainstalker", tag="Optional", preText="Test of Strength"}, [11]={hint="Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", tag="Optional"}, [12]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional"}, [13]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional", desc="Find the book in the cave, then return to Braug.", preText="Test of Lore"}, [14]={hint="Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", tag="Optional", desc="Find the book in the cave, then return to Braug."}, [15]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional", desc="Find the book in the cave, then return to Braug."}, [16]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional", preText="Test of Lore"}, [17]={hint="Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", tag="Optional"}, [18]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional"}, [19]={npc="Braug Dimspirit", tgt="Braug Dimspirit", tag="Optional", preText="Test of Lore"}, [20]={hint="Find Parqual Fintallas in Undercity.", tag="Optional"}, [21]={npc="Parqual Fintallas", tgt="Parqual Fintallas", tag="Optional"}, [22]={npc="Parqual Fintallas", tgt="Parqual Fintallas", tag="Optional", preText="Test of Lore"}, [23]={npc="Sage Truthseeker", tgt="Sage Truthseeker", desc="QuestieDB omits Undead and Skyborne from the allowed races."}, [24]={npc="Varimathras", tgt="Varimathras", desc="Level 33+. If you're too low this time, pick it up later and kill Loksey again."}, [25]={npc="Deino", tgt="Deino", tag="Optional", desc="Via Orgrimmar. Alts: Ursyn Ghull 25.70,14.19; Anastasia Hartwell 85.14,10.03."}, [26]={hint="Speak with Tabetha.", tag="Optional"}, [27]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [28]={npc="Tabetha", tgt="Tabetha", tag="Optional", preText="Journey to the Marsh"}, [29]={hint="Speak with Magus Tirth in the Shimmering Flats.", tag="Optional"}, [30]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional"}, [31]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional", preText="Hidden Secrets"}, [32]={hint="Find the phrase to Tirth's strongbox, then return to Tirth.", tag="Optional"}, [33]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional"}, [34]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional", preText="Get the Scoop"}, [35]={text="Scarlet Monastery: Library entrance"}, [36]={hint="Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", tag="Optional", desc="DungeonsForever map 1: Beginnings of the Undead Threat (45.50, 29.60). Location: Check the table in the small left room near the start of the gallery."}, [37]={hint="Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.", desc="DungeonsForever map 1: Compendium of the Fallen (83.40, 13.50). Location: Pass Loksey. Check the bookcase at the start of Doan's hall after the last turn."}, [38]={hint="Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", tag="Optional", desc="Location: Check the book sticking out of the left shelf at the start of the final hall."}, [39]={text="Kill Houndmaster Loksey for Into The Scarlet Monastery."}, [40]={text="Kill Arcanist Doan and loot the Scarlet Key from the strongbox behind him."}, [41]={npc="Parqual Fintallas", tgt="Parqual Fintallas", tag="Optional"}, [42]={npc="Sage Truthseeker", tgt="Sage Truthseeker"}, [43]={npc="Tabetha", tgt="Tabetha", tag="Optional"}}},
    ["03-17"] = {name="Thousand Needles: Freewind Post & Shimmering Flats", short="Freewind Post +", tips={{k="取捨", text="Pick up all six Shimmering Flats quests before making a loop. Do the Wharfmaster Dizzywig delivery on your next Ratchet visit. Then take Parts for Kravel from Wharfmaster Dizzywig and turn it in at the racetrack on your next Shimmering Flats visit."}, {k="取捨", text="Save Martek the Exiled for Kargath, Brother (Family Tree) for Shadowprey Village, and Nesingwary (Hemet Nesingwary) for the Grom'gol and Booty Bay leg."}, {k="提醒", text="Skip The Swarm Grows if you haven't turned in The Swarm Grows. The video warns about higher-level mobs deep in the hive. Kill near the entrance, then leave. If you finish Parts of the Swarm, turn it in at the Crossroads on the way to Brackenwall Village.", s={{"Skip The Swarm Grows if you haven't turned in The Swarm Grows"}, {"The video warns about higher-level mobs deep in the hive"}, {"Kill near the entrance, then leave"}, {"If you finish Parts of the Swarm, turn it in at the Crossroads on the way to Brackenwall Village"}}}, {k="提醒", text="Combine this level 32-34 leg with Shadowprey Village. Below level 33? Grind turtles, vultures, and scorpids south of the racetrack (around 76, 85), then head to Desolace.", s={{"Combine this level 32-34 leg with Shadowprey Village"}, {"Below level 33?"}, {"Grind turtles, vultures, and scorpids south of the racetrack (around 76, 85), then head to Desolace"}}}}, danger={[1]="Higher-level silithid pack the back of the Shimmering Flats hive. After The Swarm Grows, retrace your steps to the entrance."}, grind={[1]={mob="Saltstone Crystalhide", note="Dense normal mobs south of the Shimmering Flats racetrack. Pick off singles across the open salt flats at level 32."}, [2]={mob="Sparkleshell Borer", note="Moderate density of normal mobs farther east on the salt flats. Alternate with lizards and collect Hardened Tortoise Shells."}, [3]={mob="Scorpid Terror", note="Moderate density of normal mobs southeast of the racetrack. Circle aboveground and watch for other beasts. Collect Salty Scorpid Venom if needed."}}, supply={[1]={npc="Nyse"}, [2]={npc="Innkeeper Abeqwa"}, [3]={npc="Starn"}, [4]={npc="Innkeeper Abeqwa"}, [5]={npc="Starn"}, [6]={npc="Montarr"}, [7]={npc="Synge"}, [8]={npc="Riznek"}, [9]={npc="Synge"}}, steps={[1]={text="Learn Nyse's Freewind Post flight path (45.14, 49.11), then follow the road southeast into the Shimmering Flats."}, [2]={npc="Cliffwatcher Longhorn", tgt="Cliffwatcher Longhorn"}, [3]={npc="Moktar Krin", tgt="Moktar Krin", tag="Optional"}, [4]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [5]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [6]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [7]={npc="Trackmaster Zherin", tgt="Trackmaster Zherin"}, [8]={npc="Pozzik", tgt="Pozzik"}, [9]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [10]={hint="Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats."}, [11]={hint="Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats."}, [12]={hint="Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats."}, [13]={hint="Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats."}, [14]={hint="Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats."}, [15]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [16]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [17]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [18]={npc="Trackmaster Zherin", tgt="Trackmaster Zherin"}, [19]={npc="Pozzik", tgt="Pozzik"}, [20]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [21]={npc="Pozzik", tgt="Pozzik", tag="If passing through Ratchet, Optional"}, [22]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard", tag="If passing through Ratchet, Optional"}, [23]={text="Detour to Ratchet if you've picked up Wharfmaster Dizzywig."}, [24]={hint="Speak to Gazlowe in Ratchet.", tag="If passing through Ratchet, Optional"}, [25]={hint="Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.", tag="If passing through Ratchet, Optional"}, [26]={npc="Gazlowe", tgt="Gazlowe", tag="If passing through Ratchet, Optional"}, [27]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig", tag="If passing through Ratchet, Optional"}, [28]={npc="Gazlowe", tgt="Gazlowe", tag="Optional"}, [29]={npc="Cracked Silithid Carapace", npcObj=true, tag="Accept if it drops during The Swarm Grows, Optional", desc="Loot the Cracked Silithid Carapace during The Swarm Grows. Right-click it to start the quest."}, [30]={hint="Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", tag="Do alongside The Swarm Grows, Optional"}, [31]={hint="Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.", tag="Optional"}, [32]={npc="Moktar Krin", tgt="Moktar Krin", tag="Optional"}, [33]={hint="Bring the Shard of Water to Islen Waterseer in the Barrens.", desc="Finish the quest to get your Water Totem."}, [34]={npc="Islen Waterseer", tgt="Islen Waterseer", desc="Finish the quest to get your Water Totem."}, [35]={npc="Searn Firewarder", tgt="Searn Firewarder", desc="Start Call of Air in Orgrimmar or take the Call of Air breadcrumb in Thunder Bluff."}, [36]={hint="Find Prate Cloudseer in Thousand Needles.", desc="Start Call of Air in Orgrimmar or take the Call of Air breadcrumb in Thunder Bluff."}, [37]={npc="Prate Cloudseer", tgt="Prate Cloudseer", desc="Start Call of Air in Orgrimmar or take the Call of Air breadcrumb in Thunder Bluff."}, [38]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Optional", desc="Save the final boss's note for Alterac. Rau Cliffrunner also offers it (46.14, 51.71)."}, [39]={hint="Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", tag="Optional", desc="Keep the note from Razorfen Kraul's final boss for the Alterac turn-in. The pin marks Razorfen Kraul's entrance. Interior target coordinates are unknown."}, [40]={text="After the Shimmering Flats, retrace your route and take the lift up to Freewind Post. Fly to Sun Rock Retreat, then go southwest through the Charred Vale into Desolace."}}},
    ["05-d14"] = {name="Razorfen Kraul", entrance="The Barrens (1413), near the portal in the thorn tunnel, about 42.30, 89.90.", pickup="Run Razorfen Kraul on the way to Thousand Needles. In Ratchet, pick up Blueleaf Tubers and the gopher tools. Pick up Going, Going, Guano! from Faranell in Undercity on the way to Hillsbrad. If passing through Thunder Bluff before the run, get A Vengeful Fate from Auld. From Freewind Post, take the Great Lift back into the Barrens, then follow the west thorn path to the portal.", pickupS={{"Run Razorfen Kraul on the way to Thousand Needles"}, {"In Ratchet, pick up Blueleaf Tubers and the gopher tools"}, {"Pick up Going, Going, Guano! from Faranell in Undercity on the way to Hillsbrad"}, {"If passing through Thunder Bluff before the run, get A Vengeful Fate from Auld"}, {"From Freewind Post, take the Great Lift back into the Barrens, then follow the west thorn path to the portal"}}, tips={{k="動線", text="Use the gopher for Blueleaf Tubers along the bramble path → Roogug on the side path → Jargba → Ramtusk → bat guano in the cave → Charlga's hut for her heart and quest loot → return to Willix's tent and escort him to the entrance."}, {k="取捨", text="Kill the final boss and the bats in the front hall to unlock Hearts of Zeal and the Razorfen Downs follow-up. If short on time, do the gophers or escort along the route first."}, {k="說明", text="Razorfen Kraul is west of the Great Lift. Razorfen Downs is east. The Forever client marks the entrance at 42.30, 89.90. Follow the west thorn tunnel from the main road to the dungeon portal.", s={{"Razorfen Kraul is west of the Great Lift"}, {"Razorfen Downs is east"}, {"The Forever client marks the entrance at 42.30, 89.90"}, {"Follow the west thorn tunnel from the main road to the dungeon portal"}}}}, steps={[1]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix", desc="Get the crate, command stick and manual by the Ratchet NPC before entering."}, [2]={npc="Auld Stonespire", tgt="Auld Stonespire"}, [3]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Turn in to unlock Scarlet Monastery quest Hearts of Zeal."}, [4]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional"}, [5]={hint="Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo", tag="Optional"}, [6]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional"}, [7]={npc="Ruga Ragetotem", tgt="Ruga Ragetotem", tag="Optional", preText="Trial at the Field of Giants"}, [8]={hint="Speak with Thun'grim Firegaze in the Barrens.", tag="Optional"}, [9]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [10]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional", desc="Bring 15 Smoky Iron Ingots, 10 Powdered Azurite and 10 Iron Bars. Last mat: RFK.", preText="Trial at the Field of Giants, Speak with Thun'grim"}, [11]={npc="Searn Firewarder", tgt="Searn Firewarder", tag="Dungeon prereq"}, [12]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Dungeon prereq"}, [13]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Optional", desc="Level 30 Totem chain. Alternate pickup: Rau Cliffrunner (46.14, 51.71)."}, [14]={text="Razorfen Kraul entrance"}, [15]={hint="Grab a Crate with Holes.", desc="Location: Dig up tubers along the bramble path or while escorting Willix back."}, [16]={hint="Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.", tag="Optional", desc="DungeonsForever map 1: Roogug drops Phlogiston (64.80, 42.10). Location: Take the early side path to Roogug. Clear his adds first."}, [17]={npc="Willix the Importer", tgt="Willix the Importer", tag="Unverified", desc="Start the escort from the NPC inside the dungeon. DungeonsForever map 1: Willix the Importer escort start (37.00, 31.90)."}, [18]={hint="Escort Willix the Importer out of Razorfen Kraul.", desc="Start the escort from the NPC inside the dungeon. Location: Find Willix in a tent by the last boss and escort him back to the entrance. Order: Finish steps 17-20 before starting the escort."}, [19]={npc="Willix the Importer", tgt="Willix the Importer", tag="Unverified", desc="Start the escort from the NPC inside the dungeon."}, [20]={hint="Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", desc="Location: Kill bats in the cave before the final boss."}, [21]={hint="Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", desc="DungeonsForever map 1: Charlga Razorflank (25.80, 32.40). Location: Leave the bat cave, climb the platform and kill Charlga in the last hut."}, [22]={hint="Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", tag="Optional", desc="DungeonsForever map 1: Charlga Razorflank drops the quest item (25.80, 32.40). Location: Kill Charlga in the final hut while doing step 18. Order: Loot this with step 18."}, [23]={npc="Small Scroll", npcObj=true, tag="Optional, Unverified", desc="Loot and use the Small Scroll from Charlga Razorflank. Save for Undercity. DungeonsForever map 1: Charlga Razorflank drops the quest item (25.80, 32.40)."}, [24]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [25]={npc="Auld Stonespire", tgt="Auld Stonespire"}, [26]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", desc="Turn in at Undercity, then accept Hearts of Zeal."}, [27]={hint="Take the Small Scroll to Varimathras in the Undercity.", tag="Optional"}, [28]={npc="Varimathras", tgt="Varimathras", tag="Optional"}, [29]={npc="Thun'grim Firegaze", tgt="Thun'grim Firegaze", tag="Optional"}, [30]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Turn in in Alterac. If your log says Freewind Post, see Rau (46.14, 51.71)."}}},
    ["03-18"] = {name="Desolace: Shadowprey Village", short="Shadowprey Village", tips={{k="取捨", text="Do Highway Robbery and Bone Collector together. Click the campfire on the way to Bibbly's hut. All three quests are level 40 and require level 30. Save the On the Lam turn-in for Booty Bay."}, {k="取捨", text="Do Gelkis quests Gelkis Alliance and Stealing Supplies on the south road. Skip both and the Shadowprey Village Gelkis follow-ups if you chose the Magram or have the wrong reputation."}, {k="取捨", text="On the Shadowprey Village coast loop, do both water quests and the ancient book together. At Thunder Axe Fortress, do the Sceptre of Light and Hand of Iruxos first. If short on XP, turn in on your second visit."}, {k="取捨", text="Move on if the caravan isn't there. Don't wait for the escort. Save Hunting in Stranglethorn for the next stop in Stranglethorn Vale."}, {k="提醒", text="Below level 34? Grind normal centaurs around the Kodo Graveyard (around 56, 60-68) or Slitherblade naga on the west coast (35.91, 28.84) before leaving for Stranglethorn Vale.", s={{"Below level 34?"}, {"Grind normal centaurs around the Kodo Graveyard (around 56, 60-68) or Slitherblade naga on the west coast (35.91, 28.84) before leaving for Stranglethorn Vale"}}}}, danger={[1]="The west-coast naga are near underwater makrura. Pull casters onto the beach to avoid aggroing both packs underwater."}, grind={[1]={mob="Dread Swoop", note="Sparse normal mobs east of the Kodo Graveyard. Watch for other carrion birds. Pick up a little XP on the graveyard quest loop."}, [2]={mob="Slitherblade Naga", note="Dense normal mobs by the west coast. Pick off singles and watch for nearby sorceresses. Pair with the other coastal quests."}, [3]={mob="Slitherblade Sorceress", note="Moderate density of normal casters at the south end of the west-coast naga area. Pull them onto shore to avoid makrura adds."}}, supply={[1]={npc="Thalon"}, [2]={npc="Innkeeper Sikewa"}, [3]={npc="Hae'Wilani"}, [4]={npc="Innkeeper Sikewa"}, [5]={npc="Tukk"}}, steps={[1]={npc="Felgur Twocuts", tgt="Felgur Twocuts"}, [2]={npc="Gurda Wildmane", tgt="Gurda Wildmane"}, [3]={npc="Gurda Wildmane", tgt="Gurda Wildmane"}, [4]={npc="Nataka Longhorn", tgt="Nataka Longhorn"}, [5]={hint="Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace."}, [6]={npc="Nataka Longhorn", tgt="Nataka Longhorn"}, [7]={npc="Smeed Scrabblescrew", tgt="Smeed Scrabblescrew"}, [8]={hint="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp."}, [9]={npc="Smeed Scrabblescrew", tgt="Smeed Scrabblescrew"}, [10]={text="Follow the south road past the Gelkis village. Learn Thalon's flight path (21.60, 74.13) and set your hearth in Shadowprey Village."}, [11]={npc="Roon Wildmane", tgt="Roon Wildmane"}, [12]={npc="Taiga Wisemane", tgt="Taiga Wisemane"}, [13]={npc="Mai'Lahii", tgt="Mai'Lahii"}, [14]={npc="Drulzegar Skraghook", tgt="Drulzegar Skraghook"}, [15]={npc="Aka'rai", tgt="Aka'rai"}, [16]={text="Coast → Thunder Axe Fortress → satyrs to the east"}, [17]={npc="Rackmore's Log", npcObj=true}, [18]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [19]={npc="Flayed Demon Skin", npcObj=true, tag="If it drops, Optional", desc="Right-click the Flayed Demon Skin to start the chain. Move on if it doesn't drop."}, [20]={hint="Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.", tag="If it drops, Optional"}, [21]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="If it drops, Optional"}, [22]={hint="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor."}, [23]={hint="Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.", desc="Use the pick on the red crystal in Thunder Axe Fortress. Kill the spirit for the box."}, [24]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [25]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [26]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="Optional"}, [27]={hint="Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village."}, [28]={hint="Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.", tag="Optional"}, [29]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="Optional"}, [30]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="Optional"}, [31]={hint="Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace."}, [32]={npc="Felgur Twocuts", tgt="Felgur Twocuts"}, [33]={npc="Felgur Twocuts", tgt="Felgur Twocuts"}, [34]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle"}, [35]={hint="Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise."}, [36]={npc="Uthek the Wise", tgt="Uthek the Wise"}, [37]={npc="Uthek the Wise", tgt="Uthek the Wise"}, [38]={hint="Bring 15 Centaur Ears to Felgur Twocuts in Desolace."}, [39]={hint="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post."}, [40]={hint="Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village."}, [41]={npc="Felgur Twocuts", tgt="Felgur Twocuts"}, [42]={npc="Gurda Wildmane", tgt="Gurda Wildmane"}, [43]={npc="Uthek the Wise", tgt="Uthek the Wise"}, [44]={npc="Extinguished Campfire", npcObj=true, desc="Click the Extinguished Campfire northwest of the Kodo Graveyard. Requires level 30."}, [45]={hint="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut."}, [46]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle"}, [47]={hint="Find someone in Desolace who knows about the pillaged campsite."}, [48]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle"}, [49]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle", desc="Pick up here after Highway Robbery. Turn it in at the Booty Bay inn."}, [50]={text="West coast naga and islands, then return to Shadowprey Village"}, [51]={hint="Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.", desc="Talk to Jinar'Zillen in Shadowprey Village for two fish. Pair with west coast quests."}, [52]={hint="Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village."}, [53]={hint="Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace."}, [54]={hint="Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor."}, [55]={hint="Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.", tag="Optional"}, [56]={hint="Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest.", desc="Loot silver and gold keys from makrura and naga, then swim to the island chest."}, [57]={npc="Rackmore's Chest", npcObj=true}, [58]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [59]={npc="Nataka Longhorn", tgt="Nataka Longhorn"}, [60]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="Optional"}, [61]={npc="Maurin Bonesplitter", tgt="Maurin Bonesplitter", tag="Optional"}, [62]={hint="Speak to Takata Steelblade in Desolace.", tag="Optional"}, [63]={npc="Takata Steelblade", tgt="Takata Steelblade", tag="Optional"}, [64]={text="Hearth to Shadowprey Village."}, [65]={npc="Mai'Lahii", tgt="Mai'Lahii"}, [66]={npc="Drulzegar Skraghook", tgt="Drulzegar Skraghook"}, [67]={npc="Taiga Wisemane", tgt="Taiga Wisemane"}, [68]={npc="Aka'rai", tgt="Aka'rai"}, [69]={npc="Zevrost", tgt="Zevrost", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [70]={hint="Speak to Menara Voidrender in the Barrens.", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [71]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Orgrimmar breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [72]={npc="Kaal Soulreaper", tgt="Kaal Soulreaper", tag="Optional", desc="Undercity breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [73]={hint="Speak to Menara Voidrender in the Barrens.", tag="Optional", desc="Undercity breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [74]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Undercity breadcrumb. Take this or Knowledge of the Orb of Orahil, or go straight to Ratchet."}, [75]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="After accepting, choose one of the two attendants in the tower for your reward path."}, [76]={npc="Acolyte Wytula", tgt="Acolyte Wytula", tag="Optional", desc="Choose one branch. Capture a Mana Eater or Mage Hunter soul with the ruby. See Menara."}, [77]={hint="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", tag="Optional", desc="Choose one branch. Capture a Mana Eater or Mage Hunter soul with the ruby. See Menara."}, [78]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Choose one branch. Capture a Mana Eater or Mage Hunter soul with the ruby. See Menara."}, [79]={npc="Acolyte Magaz", tgt="Acolyte Magaz", tag="Optional", desc="Choose one branch. Capture a Lesser Infernal's soul with the emerald. See Menara."}, [80]={hint="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.", tag="Optional", desc="Choose one branch. Capture a Lesser Infernal's soul with the emerald. See Menara."}, [81]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Choose one branch. Capture a Lesser Infernal's soul with the emerald. See Menara."}, [82]={hint="Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.", tag="Optional"}, [83]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [84]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [85]={hint="Kill the Demon of the Orb, then speak with Tabetha.", tag="Optional"}, [86]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [87]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [88]={hint="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.", tag="Optional"}, [89]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional"}, [90]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [91]={hint="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [92]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [93]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [94]={hint="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [95]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do your branch's finale. If The Completed Orb of Dar'Orahil or The Completed Orb of Noh'Orahil isn't shown, check Menara after Returning the Cleansed Orb."}, [96]={text="Fly from Shadowprey Village to Orgrimmar. At the Durotar zeppelin tower (50.80, 13.60), board for Grom'gol in Stranglethorn Vale."}}},
    ["03-19"] = {name="Stranglethorn Vale", tips={{k="取捨", text="Turn in On the Lam on your first Booty Bay visit. Buy the wine for Cherry for Your Thoughts? Take the follow-up when you visit the island off southeastern Arathi Highlands."}, {k="取捨", text="Do the keys and escort only if you find Gimix at Zul'Kunda. The keys and Stolen Shipment are in the same area. If another player is escorting him, keep questing. [zhTW quest record](https://wowamobi.com/quests/Where's the Key?)"}, {k="取捨", text="On your first Booty Bay visit, unlock the flight path and pick up quests. At around level 35, turn in only Bloodscalp Ears, Investigate the Camp, Supply and Demand, Singing Blue Shards, and Hostile Takeover, plus Anything of Value and Zimmix's Great Escape if done. Turn in Supply and Demand and Singing Blue Shards to unlock Some Assembly Required and Venture Company Mining."}, {k="取捨", text="Save Venture Company Mining and Excelsior for the Booty Bay return after the southern loop. Turn in Some Assembly Required first on that visit to unlock Excelsior."}, {k="取捨", text="Save Bloodsail The Bloodsail Buccaneers → The Bloodsail Buccaneers → The Bloodsail Buccaneers → The Bloodsail Buccaneers → The Bloodsail Buccaneers for the level 42 return. Pair with Keep An Eye Out, Up to Snuff, Zanzil's Secret, and Scaring Shaky → Return to MacKinley → Voodoo Dues. Save Stranglethorn Fever/Stranglethorn Fever, Message in a Bottle → Message in a Bottle, The Captain's Chest, Whiskey Slim's Lost Grog, and An OOX of Your Own for the level 45+ Booty Bay list. Follow the video's staggered turn-ins and use these quest IDs to plan them."}, {k="取捨", text="Advance Raptor Mastery to Raptor Mastery, then kill lashtail raptors for it and The Defense of Grom'gol together. Kill the northern Crystal Spine Basilisks for Singing Blue Shards. Skip the southern detour on this visit."}, {k="取捨", text="Starting fresh at 34? Do the first two rounds of all three hunting chains, plus the Grom'gol and Bloodscalp quests. Shadowmaw Panthers count for Panther Mastery and Mok'thardin's Enchantment. Kill Sin'Dall for Tiger Mastery on the same loop. Save the three trophies for Speaking with Nezzliok and the Split Bone Necklace for Booty Bay. Turn in The Green Hills of Stranglethorn (-Chapter IV) if you have the pages."}, {k="提醒", text="Run The Drowned City at level 35 with a group (recommended 35-40). Check your quests first. Enter underwater west of Grom'gol.", s={{"Run The Drowned City at level 35 with a group (recommended 35-40)"}, {"Check your quests first"}, {"Enter underwater west of Grom'gol"}}}, {k="提醒", text="At around 34-35, grind Bloodscalp trolls in northern Stranglethorn (29.76, 21.62). From 36, switch to the ogre camp southeast of Grom'gol (35.55, 30.92). Grind to 37 as needed and turn in any finished quests at the camp before boarding the zeppelin.", s={{"At around 34-35, grind Bloodscalp trolls in northern Stranglethorn (29.76, 21.62)"}, {"From 36, switch to the ogre camp southeast of Grom'gol (35.55, 30.92)"}, {"Grind to 37 as needed and turn in any finished quests at the camp before boarding the zeppelin"}}}}, danger={[1]="Elite Saltscale murlocs guard the ruins. Dive from the surface and follow the outer wall to the tablet. Leave enough air for the return swim.", [2]="Gimix's escort through the Ruins of Zul'Kunda crosses a patrol route. Clear the outside of the camp before starting."}, grind={[1]={mob="Bloodscalp Warrior", note="Moderate density of normal mobs at the northern Bloodscalp ruins. Pull singles along the outer walls and watch for shamans. Grind at 34. Warriors can collect Bloodscalp Tusks for their Whirlwind weapon."}, [2]={mob="Lashtail Raptor", note="Dense normal mobs in the woods north of Grom'gol. Pick off singles along the road and avoid elite Saltscale mobs in the water. Pair with raptor hunting."}, [3]={mob="Mosh'Ogg Brute", note="Moderate density of normal mobs outside the ogre camp southeast of Grom'gol. Avoid witch doctors and rare Roloch. Grind from level 36 to 37."}}, supply={[1]={npc="Thysta"}, [2]={npc="Innkeeper Thulbek"}, [3]={npc="Krakk"}, [4]={npc="Nargatt"}, [5]={npc="Uthok"}, [6]={npc="Gringer"}, [7]={npc="Innkeeper Skindle"}, [8]={npc="Jutak"}, [9]={npc="Nixxrax Fillamug"}, [10]={npc="Haren Kanmae"}}, steps={[1]={text="Take the Grom'gol zeppelin from outside Orgrimmar. Learn Thysta's flight path (32.54, 29.35). If you're already in Stranglethorn Vale, head straight to camp."}, [2]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [3]={npc="Nimboya", tgt="Nimboya", tag="Crowded, Optional"}, [4]={npc="Kin'weelay", tgt="Kin'weelay", tag="Crowded, Optional"}, [5]={npc="Far Seer Mok'thardin", tgt="Far Seer Mok'thardin"}, [6]={npc="Nimboya", tgt="Nimboya"}, [7]={npc="Kin'weelay", tgt="Kin'weelay"}, [8]={npc="Carnivorous Weed", tgt="Gemmil", desc="Crank Fizzlebub also offers this quest (27.12, 77.21)."}, [9]={hint="Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", desc="Swim to the slab on the outer wall of the sunken ruins. Avoid elite murloc patrols."}, [10]={npc="Kin'weelay", tgt="Kin'weelay"}, [11]={npc="Kin'weelay", tgt="Kin'weelay", desc="Turn this in to unlock Enemies in the Water."}, [12]={text="Fly from Grom'gol to Booty Bay if unlocked. Otherwise follow the road south and learn Gringer's flight path (26.87, 77.10). Pick up the first batch before flying back."}, [13]={npc="Kebok", tgt="Kebok", tag="Crowded, Optional"}, [14]={npc="Krazek", tgt="Krazek"}, [15]={npc="Krazek", tgt="Krazek"}, [16]={npc="Krazek", tgt="Krazek"}, [17]={npc="Drizzlik", tgt="Drizzlik"}, [18]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [19]={hint="Find one of the Desolace marauders."}, [20]={npc="Tokal", tgt="Tokal"}, [21]={npc="Tokal", tgt="Tokal"}, [22]={hint="Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story.", desc="Buy it and turn it in. Don't drink it."}, [23]={npc="Tokal", tgt="Tokal", desc="Pick up No Honor Among Thieves after turning in. Save it for the southeast Arathi Highlands coast."}, [24]={npc="Kebok", tgt="Kebok"}, [25]={hint="Speak with Wharfmaster Lozgil in Booty Bay.", tag="Optional"}, [26]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", tag="Optional"}, [27]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", tag="Optional"}, [28]={hint="Speak with Baron Revilgaz in Booty Bay.", tag="Optional"}, [29]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [30]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [31]={text="Northern expedition → river, troll ruins and wildlife"}, [32]={hint="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."}, [33]={hint="Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn."}, [34]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [35]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [36]={npc="Barnil Stonepot", tgt="Barnil Stonepot"}, [37]={hint="Speak with Hemet Nesingwary"}, [38]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [39]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [40]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [41]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [42]={hint="Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay."}, [43]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers."}, [44]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers."}, [45]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [46]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [47]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [48]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [49]={hint="Find the hunters' camp and report its location to Krazek in Booty Bay."}, [50]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers."}, [51]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers."}, [52]={hint="Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors."}, [53]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [54]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [55]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [56]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [57]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [58]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [59]={npc="Thoroughly Scavenged Supplies", npcObj=true, tag="Crowded, Optional"}, [60]={text="Clear Zuul'Kunda and the Bloodscalps before returning to Grom'gol"}, [61]={hint="Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.", tag="Crowded, Optional"}, [62]={hint="Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", tag="Crowded, Optional"}, [63]={hint="Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.", tag="Crowded, Optional"}, [64]={npc="Nimboya", tgt="Nimboya", tag="Crowded, Optional"}, [65]={npc="Kin'weelay", tgt="Kin'weelay", tag="Crowded, Optional"}, [66]={npc="Nimboya", tgt="Nimboya", tag="Crowded, Optional"}, [67]={hint="Bring 10 Singing Crystal Shards to Crank Fizzlebub."}, [68]={hint="Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay."}, [69]={hint="Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", tag="Do alongside Hostile Takeover, Optional"}, [70]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark", tag="Optional", desc="Accept at the cage west of Zul'Kunda. Check the NPC if the step is hidden."}, [71]={hint="Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay.", tag="Crowded, Optional"}, [72]={hint="Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."}, [73]={hint="Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark.", tag="Optional"}, [74]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark", tag="Optional"}, [75]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark", tag="If you see it, Optional", desc="Gimix is west of the ruins. Wait for the current escort to finish or skip it."}, [76]={hint="Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue.", tag="If you see it, Optional"}, [77]={hint="Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", tag="Crowded, Optional"}, [78]={npc="Nimboya", tgt="Nimboya", tag="Crowded, Optional"}, [79]={hint="Hemet Nesingwary wants you to kill 10 Lashtail Raptors."}, [80]={hint="Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors."}, [81]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [82]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [83]={npc="Nimboya", tgt="Nimboya", tag="Crowded, Optional"}, [84]={npc="Kin'weelay", tgt="Kin'weelay"}, [85]={npc="Kin'weelay", tgt="Kin'weelay"}, [86]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [87]={hint="Gather 10 Brinescale Tridents from Brinescale Skirmishers.", tag="Target: Brinescale Skirmisher"}, [88]={hint="Explore the Vile Reef and find the cavern entrance."}, [89]={npc="Kin'weelay", tgt="Kin'weelay"}, [90]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [91]={npc="Kin'weelay", tgt="Kin'weelay"}, [92]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [93]={hint="Slay 6 Carnivorous Weeds south of Grom'gol and then inform Gemmil's mother."}, [94]={npc="Nerrist", tgt="Nerrist"}, [95]={text="Around level 35, fly to Booty Bay once you have a batch of low-level turn-ins."}, [96]={npc="Kebok", tgt="Kebok", tag="Crowded, Optional"}, [97]={npc="Krazek", tgt="Krazek"}, [98]={npc="Drizzlik", tgt="Drizzlik"}, [99]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [100]={npc="Kebok", tgt="Kebok"}, [101]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", tag="Crowded, Optional"}, [102]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", tag="Optional"}, [103]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [104]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Turn in on the next Shimmering Flats visit, Optional"}, [105]={npc="Drizzlik", tgt="Drizzlik"}, [106]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [107]={text="After the first round of turn-ins, fly back to Grom'gol."}, [108]={text="Central coast: trolls, ogres and nearby hunts"}, [109]={hint="Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", tag="Crowded, Optional"}, [110]={hint="Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors."}, [111]={npc="Bubbling Cauldron", npcObj=true, tag="Crowded, Optional"}, [112]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [113]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers."}, [114]={hint="Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang."}, [115]={npc="Far Seer Mok'thardin", tgt="Far Seer Mok'thardin"}, [116]={npc="Far Seer Mok'thardin", tgt="Far Seer Mok'thardin"}, [117]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers."}, [118]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [119]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [120]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [121]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [122]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin", tag="Optional"}, [123]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw."}, [124]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.", tag="Optional"}, [125]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [126]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin", tag="Optional"}, [127]={hint="Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay."}, [128]={text="If Some Assembly Required is ready, save it for your next stop in Booty Bay."}, [129]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [130]={hint="Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.", tag="Optional", desc="Do this with Stranglethorn quests. Get Essence of the Exile near Hammerfall."}, [131]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Optional"}, [132]={hint="Get a Crimson Trophy Quill from Gharrik in the Badlands. Then, return to Hemet Nesingwary in Stranglethorn Vale.", tag="Optional, Target: Garrick"}, [133]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Optional"}, [134]={npc="Zevrost", tgt="Zevrost", tag="Optional", desc="Orgrimmar breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [135]={hint="Speak to Menara Voidrender in the Barrens.", tag="Optional", desc="Orgrimmar breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [136]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Orgrimmar breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [137]={npc="Kaal Soulreaper", tgt="Kaal Soulreaper", tag="Optional", desc="Undercity breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [138]={hint="Speak to Menara Voidrender in the Barrens.", tag="Optional", desc="Undercity breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [139]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Undercity breadcrumb. Take this or In Search of Menara Voidrender, or go straight to Ratchet."}, [140]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional"}, [141]={hint="Bring Robes of the Arcana to Menara Voidrender in the Barrens.", tag="Optional"}, [142]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional"}, [143]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Bring a Gold Bar to Xizk Goodstitch in Booty Bay."}, [144]={hint="Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.", tag="Optional", desc="Bring a Gold Bar to Xizk Goodstitch in Booty Bay."}, [145]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", tag="Optional", desc="Bring a Gold Bar to Xizk Goodstitch in Booty Bay."}, [146]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", tag="Optional"}, [147]={hint="Return to Menara Voidrender in the Barrens.", tag="Optional"}, [148]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional"}, [149]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Loot 10 satyr blood in north Desolace and 1 Lesser Infernal Stone in the south."}, [150]={hint="Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.", tag="Optional", desc="Loot 10 satyr blood in north Desolace and 1 Lesser Infernal Stone in the south."}, [151]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Loot 10 satyr blood in north Desolace and 1 Lesser Infernal Stone in the south."}, [152]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", tag="Optional"}, [153]={hint="Complete the quest objectives.", tag="Optional"}, [154]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", tag="Optional"}, [155]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Bring Fine Gold Thread, 2 Smoldering Coal and a Soul Shard to Menara."}, [156]={hint="Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", tag="Optional", desc="Bring Fine Gold Thread, 2 Smoldering Coal and a Soul Shard to Menara."}, [157]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Bring Fine Gold Thread, 2 Smoldering Coal and a Soul Shard to Menara."}, [158]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", star={"Enchanted Gold Bloodrobe", {"WARLOCK"}}}, [159]={hint="Wait for Menara Voidrender to complete your robe and then speak to her again.", tag="Optional"}, [160]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", star={"Enchanted Gold Bloodrobe", {"WARLOCK"}}}, [161]={text="Take the zeppelin from Grom'gol to Orgrimmar, then fly to the Crossroads or Camp Taurajo."}}},
    ["05-d16"] = {name="The Drowned City", entrance="Stranglethorn Vale 21.50, 27.70", pickup="Follow the first Stranglethorn visit: take The Vile Reef at Grom'gol and do the reef objectives, then turn it in for The Gurubashi Legends of Old. Take Shady Saltseers and The Saltseer Captain from Krazek at Booty Bay. Take the rubbings for The Gurubashi Legends of Old at Zul'Kunda. Back at Grom'gol, pick up Locating the Lost City and Enemies in the Water, do both on the west coast, then take The Drowned City and The Only Good Brinescale.... If you've unlocked Thunder Bluff, fly there before the run and follow the Mulgore road to Mazu'kon at Skywatcher Plateau. Return to Grom'gol and swim to the underwater portal from the west coast.", pickupS={{"Follow the first Stranglethorn visit: take The Vile Reef at Grom'gol and do the reef objectives, then turn it in for The Gurubashi Legends of Old"}, {"Take Shady Saltseers and The Saltseer Captain from Krazek at Booty Bay"}, {"Take the rubbings for The Gurubashi Legends of Old at Zul'Kunda"}, {"Back at Grom'gol, pick up Locating the Lost City and Enemies in the Water, do both on the west coast, then take The Drowned City and The Only Good Brinescale..."}, {"If you've unlocked Thunder Bluff, fly there before the run and follow the Mulgore road to Mazu'kon at Skywatcher Plateau"}, {"Return to Grom'gol and swim to the underwater portal from the west coast"}}, tips={{k="動線", text="Zul'Alai → Var'Taka → Captain Dreadrise → Deathless Marrow → Min'loth the Serpent. Make rubbings left of the entrance pool, left of Var'Taka, in the skull by the ships and behind Min'loth. Loot artifacts from the pirates. Primeval Elemental and Gill are optional."}, {k="取捨", text="Finish both Grom'gol prerequisites before swimming out, so you can do more than the ship section. Skip the single Mulgore turn-in if it's out of the way."}, {k="說明", text="The portal is in an underwater cave west of Grom'gol. The DungeonsForever pin (21.50, 27.70) matches the field guide (around 21.4, 27.9). Quest Locating the Lost City uses a separate exploration point (22.40, 27.18). Bring an underwater breathing potion or ask a party member for the spell.", s={{"The portal is in an underwater cave west of Grom'gol"}, {"The DungeonsForever pin (21.50, 27.70) matches the field guide (around 21.4, 27.9)"}, {"Quest Locating the Lost City uses a separate exploration point (22.40, 27.18)"}, {"Bring an underwater breathing potion or ask a party member for the spell"}}}}, steps={[1]={npc="Kin'weelay", tgt="Kin'weelay", desc="Skip if you did this on the Grom'gol and Booty Bay leg."}, [2]={hint="Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", desc="Skip if you did this on the Grom'gol and Booty Bay leg."}, [3]={npc="Kin'weelay", tgt="Kin'weelay", desc="Skip if you did this on the Grom'gol and Booty Bay leg."}, [4]={npc="Kin'weelay", tgt="Kin'weelay", preText="The Vile Reef"}, [5]={hint="Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."}, [6]={npc="Kin'weelay", tgt="Kin'weelay"}, [7]={npc="Kin'weelay", tgt="Kin'weelay", preText="The Gurubashi Legends of Old"}, [8]={hint="Explore the Vile Reef and find the cavern entrance."}, [9]={npc="Kin'weelay", tgt="Kin'weelay"}, [10]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh", desc="After The Vile Reef, check with the commander while visiting Kin'weelay.", preText="The Vile Reef, The Gurubashi Legends of Old"}, [11]={hint="Gather 10 Brinescale Tridents from Brinescale Skirmishers.", tag="Target: Brinescale Skirmisher", desc="After The Vile Reef, check with the commander while visiting Kin'weelay."}, [12]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh", desc="After The Vile Reef, check with the commander while visiting Kin'weelay."}, [13]={npc="Kin'weelay", tgt="Kin'weelay", preText="Locating the Lost City"}, [14]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh", preText="Enemies in the Water, Locating the Lost City"}, [15]={npc="Krazek", tgt="Krazek"}, [16]={npc="Krazek", tgt="Krazek"}, [17]={npc="Mazu'kon", tgt="Mazu'kon", tag="Optional", desc="Mazu'kon is at Skywatcher Plateau in Mulgore. Go if you have transport unlocked."}, [18]={text="The Drowned City entrance"}, [19]={hint="Use the hide and charcoal to create rubbings of the tablets found in the Drowned City.", desc="Wowhead Forever player report. Exact instance coordinates are unknown. Location: Left of pool, left of Var'Taka, skull by Captain Dreadrise, behind last boss. Order: Take rubbings at the four landmarks along the way."}, [20]={hint="Slay Var'Taka in the Drowned City.", desc="Kill the priest next to the boss first. Watch your breath underwater. DungeonsForever map 1: Var'Taka (47.80, 71.70). Location: Past Zul'Alai, find the boss next to two priestesses in the flooded archive."}, [21]={hint="Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City.", desc="Keep clearing pirates around the ships if you still need drops. Location: Clear Saltseer pirates by the ships and loot the artifacts. Order: Clear this area with step 21."}, [22]={hint="Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City.", desc="DungeonsForever map 1: Captain Dreadrise (51.00, 26.30). Location: Clear coroners along the passages near the captain in the ship area. Order: Click the glowing pearl after killing the captain."}, [23]={hint="Recover an Ancient Gurubashi Idol from the Drowned City.", tag="Optional", desc="DungeonsForever map 1: Deathless Marrow drops the item (27.30, 49.80). Location: Pass the captain and pearl barrier, then kill Deathless Marrow."}, [24]={npc="Kin'weelay", tgt="Kin'weelay"}, [25]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh"}, [26]={npc="Krazek", tgt="Krazek"}, [27]={npc="Krazek", tgt="Krazek"}, [28]={npc="Mazu'kon", tgt="Mazu'kon", tag="Optional"}, [29]={npc="Kin'weelay", tgt="Kin'weelay", tag="Optional", desc="Turn in if you're already flying to Orgrimmar. This can wait until after the run.", preText="The Drowned City"}, [30]={hint="Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar.", tag="Optional", desc="Turn in if you're already flying to Orgrimmar. This can wait until after the run."}, [31]={npc="Master Gadrin", tgt="Master Gadrin", tag="Optional", desc="Turn in if you're already flying to Orgrimmar. This can wait until after the run."}}},
    ["05-d15"] = {name="Gnomeregan", entrance="Stranglethorn Vale 27.60, 77.48", pickup="Before Booty Bay, visit Sovik and Nogg in the Valley of Honor. Take the boat from Ratchet or fly from Grom'gol to Booty Bay. Finish Chief Engineer Scooty → Gnomer-gooooone! with Scooty and keep the Goblin Transponder to enter.", pickupS={{"Before Booty Bay, visit Sovik and Nogg in the Valley of Honor"}, {"Take the boat from Ratchet or fly from Grom'gol to Booty Bay"}, {"Finish Chief Engineer Scooty → Gnomer-gooooone! with Scooty and keep the Goblin Transponder to enter"}}, tips={{k="動線", text="Go left and downhill to the Clean Zone → escort Kernobee from the quarters on the right → Electrocutioner 6000 → Crowd Pummeler 9-60 → Thermaplugg, then use his code on the safe. Use the Sparklematic in the Clean Zone if you loot a Grime-Encrusted Ring."}, {k="取捨", text="Run if the gear or quest XP is worth it. Pair the turn-ins with your Booty Bay quests to save travel."}, {k="說明", text="Use the teleporter to the facility in Dun Morogh and follow the underground corridor to the dungeon portal. Skip Ironforge. Finish Scooty's chain first if the teleporter is locked.", s={{"Use the teleporter to the facility in Dun Morogh and follow the underground corridor to the dungeon portal"}, {"Skip Ironforge"}, {"Finish Scooty's chain first if the teleporter is locked"}}}}, steps={[1]={npc="Nogg", tgt="Nogg"}, [2]={npc="Sovik", tgt="Sovik", preText="Rig Wars"}, [3]={hint="Speak with Scooty in Booty Bay."}, [4]={npc="Scooty", tgt="Scooty"}, [5]={npc="Scooty", tgt="Scooty", preText="Chief Engineer Scooty"}, [6]={hint="Wait for Scooty to calibrate the Goblin Transponder."}, [7]={npc="Scooty", tgt="Scooty"}, [8]={text="Gnomeregan entrance"}, [9]={hint="Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", desc="Have someone press the button by the shelter during the fight to control the bombs. DungeonsForever map 4: Mekgineer Thermaplugg (31.30, 30.00). The safe is separate. Location: Follow the workshop tunnel to the round room. Kill the last boss and open the safe."}, [10]={npc="Kernobee", tgt="Kernobee", tag="Unverified", desc="Find Kernobee near the clean area. Clear the escort route first. DungeonsForever map 2: Kernobee escort start (82.00, 79.10). Alt pin: 82.8, 81.0."}, [11]={hint="Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", desc="Location: Pick up Kernobee by the Clean Zone quarters. Escort him to the front entrance. Order: Do steps 9-10 before heading deeper to the final boss."}, [12]={npc="Grime-Encrusted Ring", npcObj=true, tag="Optional, Unverified", desc="Bring 3 silver and follow the machine's dialogue."}, [13]={hint="Figure out a way to remove the grime from the Grime-Encrusted Ring.", tag="Optional", desc="Bring 3 silver and follow the machine's dialogue. Location: Turn left and go down to the Clean Zone. Find the Sparklematic by the wall. Order: Loot the ring from the Dark Iron Agent first."}, [14]={npc="The Sparklematic 5200", npcObj=true, tag="Optional, Unverified", desc="Bring 3 silver and follow the machine's dialogue."}, [15]={npc="The Sparklematic 5200", npcObj=true, tag="Optional, Unverified", preText="Grime-Encrusted Ring"}, [16]={npc="Scooty", tgt="Scooty"}, [17]={npc="Nogg", tgt="Nogg"}, [18]={hint="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", tag="Optional"}, [19]={npc="Nogg", tgt="Nogg", tag="Optional"}}},
    ["03-20"] = {name="Dustwallow Marsh: Brackenwall Village", short="Brackenwall Village", tips={{k="取捨", text="Pick up The Black Shield, Suspicious Hoofprints, and Lieutenant Paval Reethe at the same burned inn before entering the village."}, {k="取捨", text="Bring 3 Soothing Spices before leaving town. Turn in the Moonsteel Broadsword if you have one. Buying or crafting it adds a detour. Turn in Stinky's Escape at Ratchet if passing, or save or skip it."}, {k="提醒", text="Brackenwall Village and the Shadowprey Village return together cover levels 37-38. If you've already turned in the Desolace quests, grind normal spiders and raptors in northern Dustwallow Marsh until 38.", s={{"Brackenwall Village and the Shadowprey Village return together cover levels 37-38"}, {"If you've already turned in the Desolace quests, grind normal spiders and raptors in northern Dustwallow Marsh until 38"}}}}, danger={[1]="Poisonous spiders and raptor patrols overlap in the northern marsh. Pull singles from the edge and avoid the spots where patrols meet in the brush."}, grind={[1]={mob="Withervine Mire Beast", note="Dense normal mobs in the northern swamp among the other Withervine mobs. Pull singles from dry ground to reach the next stop's level."}, [2]={mob="Darkfang Venomspitter", note="Moderate density of normal mobs in the eastern part of the northern swamp. Watch for poison damage and raptor patrols. Move here if Withervine mobs are being farmed."}, [3]={mob="Bloodfen Screecher", note="Dense normal mobs along the northern swamp's treeline. Pull singles along the shore and watch for crocolisks and other raptors. Leave at 38."}}, supply={[1]={npc="Shardi"}, [2]={npc="Krak"}, [3]={npc="Ogg'marr"}, [4]={npc="Zanara"}, [5]={npc="Balai Lok'Wein"}}, steps={[1]={npc="Korran", tgt="Korran", tag="Optional"}, [2]={text="Head east from Camp Taurajo into Dustwallow Marsh. Stop first at the burned-out inn by the road."}, [3]={npc="Black Shield", npcObj=true}, [4]={npc="Hoofprints", npcObj=true}, [5]={npc="Theramore Guard Badge", npcObj=true}, [6]={node="Brackenwall Village", desc="Unlock the flight path with Shardi."}, [7]={text="Keep your Shadowprey Village hearth for the return on the next leg."}, [8]={hint="Bring the Blackened Iron Shield to Krog in Brackenwall Village."}, [9]={hint="Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village."}, [10]={hint="Bring Reethe's Badge to Krog in Brackenwall Village."}, [11]={npc="Krog", tgt="Krog"}, [12]={npc="Krog", tgt="Krog"}, [13]={npc="Krog", tgt="Krog"}, [14]={npc="Krog", tgt="Krog"}, [15]={hint="Show the Blackened Iron Shield to Do'gol in Brackenwall Village."}, [16]={npc="Do'gol", tgt="Do'gol"}, [17]={npc="Do'gol", tgt="Do'gol"}, [18]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [19]={npc="Mudcrush Durtfeet", tgt="Mudcrush Durtfeet"}, [20]={npc="Ogron", tgt="Ogron"}, [21]={hint="Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village."}, [22]={npc="Krog", tgt="Krog"}, [23]={hint="Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village."}, [24]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [25]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [26]={text="North road escort → Swamplight Manor → coast"}, [27]={npc="\"Stinky\" Ignatz", tgt="Stinky Ignatz", tag="Turn in when passing Ratchet, Optional"}, [28]={hint="Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", tag="Optional"}, [29]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [30]={hint="Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh."}, [31]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [32]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [33]={npc="Loose Dirt", npcObj=true}, [34]={hint="Bring 40 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor."}, [35]={hint="Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village."}, [36]={hint="Acquire 6 Acidic Venom Sacs for Do'gol in Brackenwall Village."}, [37]={hint="Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village."}, [38]={hint="Mudcrush Durtfeet in northern Dustwallow wants 12 Mirefin Heads."}, [39]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [40]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [41]={npc="Do'gol", tgt="Do'gol"}, [42]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [43]={npc="Mudcrush Durtfeet", tgt="Mudcrush Durtfeet"}, [44]={npc="Do'gol", tgt="Do'gol"}, [45]={hint="Talk with Krog in Brackenwall Village."}, [46]={npc="Krog", tgt="Krog"}, [47]={npc="Krog", tgt="Krog", tag="Optional"}, [48]={text="Optional return trip and cross-zone quests"}, [49]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl", tag="Requires Moonsteel Broadsword, Optional"}, [50]={hint="Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.", tag="Requires Moonsteel Broadsword, Optional", desc="Bring a Moonsteel Broadsword to turn in."}, [51]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl", tag="Requires Moonsteel Broadsword, Optional"}, [52]={npc="Loose Dirt", npcObj=true, tag="Optional"}, [53]={hint="Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", tag="Optional"}, [54]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike", tag="Optional"}, [55]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike", tag="Optional"}, [56]={npc="Deino", tgt="Deino", tag="Optional", desc="Via Orgrimmar. Alts: Ursyn Ghull 25.70,14.19; Anastasia Hartwell 85.14,10.03."}, [57]={hint="Speak with Tabetha.", tag="Optional"}, [58]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [59]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Keep 10 Totem Bundles. Combine them at the Circle of Outer Binding."}, [60]={hint="Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.", tag="Optional", desc="Keep 10 Totem Bundles. Combine them at the Circle of Outer Binding."}, [61]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Keep 10 Totem Bundles. Combine them at the Circle of Outer Binding."}, [62]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [63]={hint="Speak with Magus Tirth in the Shimmering Flats.", tag="Optional"}, [64]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional"}, [65]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional", desc="Target the chicken and /beckon. Talk to it after it changes into a human."}, [66]={hint="Find the phrase to Tirth's strongbox, then return to Tirth.", tag="Optional", desc="Target the chicken and /beckon. Talk to it after it changes into a human."}, [67]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional", desc="Target the chicken and /beckon. Talk to it after it changes into a human."}, [68]={npc="Magus Tirth", tgt="Magus Tirth", tag="Optional", desc="Group up for the Library and find the book on the shelves."}, [69]={hint="Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", tag="Optional", desc="Group up for the Library and find the book on the shelves. Take the Library wing at Scarlet Monastery. Pin marks the entrance only."}, [70]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Group up for the Library and find the book on the shelves."}, [71]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Finish both wand material chains before reporting back.", star={"Icefury Wand / Nether Force Wand / Ragefire Wand"}}, [72]={hint="Speak with Tabetha after her ritual.", tag="Optional", desc="Finish both wand material chains before reporting back."}, [73]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Finish both wand material chains before reporting back.", star={"Icefury Wand / Nether Force Wand / Ragefire Wand"}}, [74]={text="Return to Brackenwall Village and fly to Shadowprey Village. If the route is unavailable, change flights at the Crossroads. Save your hearth for the return from Mannoroc Coven."}}},
    ["03-21"] = {name="Desolace: Shadowprey Village", short="Shadowprey Village", tips={{k="取捨", text="The video includes this return trip. If short on XP at level 37, do the southeastern centaur quests and the nearby Burning Legion portal. Turn in Hand of Iruxos to unlock Portals of the Legion. Use the crate to draw out ghosts for Ghost-o-plasm, then kill them one at a time."}, {k="取捨", text="Accept Ongeku now and do it on the Stonard leg. Turn it in at the village to unlock Khan Jehn, which you can save for later."}, {k="提醒", text="Below level 38? Grind normal demons around the edge of Mannoroc Coven (around 50.40, 70.40). If kills are slow, switch to the centaurs southeast of the Kodo Graveyard.", s={{"Below level 38?"}, {"Grind normal demons around the edge of Mannoroc Coven (around 50.40, 70.40)"}, {"If kills are slow, switch to the centaurs southeast of the Kodo Graveyard"}}}}, danger={[1]="Elite lords roam south of Mannoroc Coven. For XP or materials, stick to Mage Hunters on the east side."}, grind={[1]={mob="Lesser Infernal", note="Dense normal mobs north of Mannoroc Coven. Watch for nearby demons. Warlocks can collect a Lesser Infernal Stone for Enchanted Gold Bloodrobe."}, [2]={mob="Nether Maiden", note="Moderate density of normal casters on the same outer edge of Mannoroc Coven. Use terrain to pull them away from packs. Alternate with Lesser Infernals."}, [3]={mob="Mage Hunter", note="Moderate density of normal mobs east of Mannoroc Coven. Pick off singles around the edge and avoid the elite lord to the south. Use this spot if the outer loop is crowded."}}, supply={[1]={npc="Thalon"}, [2]={npc="Innkeeper Sikewa"}, [3]={npc="Hae'Wilani"}, [4]={npc="Innkeeper Sikewa"}, [5]={npc="Tukk"}}, steps={[1]={npc="Taiga Wisemane", tgt="Taiga Wisemane"}, [2]={text="From Shadowprey Village, go to Ghost Walker Post first. Follow the south road to Mannoroc Coven."}, [3]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [4]={npc="Uthek the Wise", tgt="Uthek the Wise", tag="Gelkis chain with a prerequisite, Optional"}, [5]={hint="Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.", desc="Use Taiga's Hand of Iruxos on the portal in the hall to banish six demons."}, [6]={hint="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", desc="Set the crate down in the Valley of Bones. Step back and pull the ghosts one by one."}, [7]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [8]={npc="Taiga Wisemane", tgt="Taiga Wisemane"}, [9]={npc="Deino", tgt="Deino", tag="Optional", desc="Via Orgrimmar. Alts: Ursyn Ghull 25.70,14.19; Anastasia Hartwell 85.14,10.03."}, [10]={hint="Speak with Tabetha.", tag="Optional"}, [11]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [12]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [13]={hint="Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", tag="Optional"}, [14]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [15]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Top up health and mana, then ask Tabetha to begin the exorcism."}, [16]={hint="Kill the Demon of the Orb, then speak with Tabetha.", tag="Optional", desc="Top up health and mana, then ask Tabetha to begin the exorcism."}, [17]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Top up health and mana, then ask Tabetha to begin the exorcism."}, [18]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Confirm your group is using the entrance that leads to Obsidian Sentinel."}, [19]={hint="Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", tag="Optional", desc="Confirm your group is using the entrance that leads to Obsidian Sentinel. Use Uldaman's back door for Obsidian Sentinel. Pin marks the entrance only."}, [20]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Confirm your group is using the entrance that leads to Obsidian Sentinel."}, [21]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Top up your mana before accepting. The timer starts when you accept."}, [22]={hint="Kill 12 Mana Surges in the allowed time limit.", tag="Optional", desc="Top up your mana before accepting. The timer starts when you accept."}, [23]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Top up your mana before accepting. The timer starts when you accept."}, [24]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [25]={hint="Complete the quest objectives.", tag="Optional"}, [26]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [27]={text="Hearth to Shadowprey if bound there. Otherwise run back to the flight master. Fly to Orgrimmar to train."}}},
    ["03-22"] = {name="Alterac Mountains", tips={{k="取捨", text="Check The Rescue and WANTED: Syndicate Personnel in Tarren Mill. Do both prerequisites at Durnholde Keep on one trip. In Alterac, turn in Infiltration to unlock Gol'dir, then look for Gol'dir and Vardus at the Syndicate camps."}, {k="提醒", text="Use this leg and Hammerfall to reach level 40. Check your XP when you arrive. If you're just short, grind normal Syndicate mobs (58.44, 70.00) before heading to Hammerfall.", s={{"Use this leg and Hammerfall to reach level 40"}, {"Check your XP when you arrive"}, {"If you're just short, grind normal Syndicate mobs (58.44, 70.00) before heading to Hammerfall"}}}}, danger={[1]="Elite ogres are inside the Ruins of Alterac. Fight normal Brutes along the outer road until your group arrives."}, grind={[1]={mob="Syndicate Spy", note="Dense normal mobs outside the Syndicate camp. Watch for stealthed mobs and wizards. Pick off singles for a little XP before Hammerfall."}, [2]={mob="Crushridge Brute", note="Dense normal mobs along the mountain road outside the Ruins of Alterac. Stay outside to avoid the elites and keep solo grinding on route."}}, supply={[1]={npc="Zarise"}, [2]={npc="Innkeeper Shay"}, [3]={npc="Innkeeper Shay"}, [4]={npc="Kayren Soothallow"}, [5]={npc="Gordon Wendham"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezekiel Graves"}}, steps={[1]={text="Board the Tirisfal zeppelin outside Orgrimmar. From Brill's south tower, head to Undercity, fly to Tarren Mill and set your hearth."}, [2]={npc="Melisara", tgt="Melisara", tag="Group, Optional"}, [3]={npc="Krusk", tgt="Krusk"}, [4]={npc="WANTED", npcObj=true, desc="The wanted poster also offers this quest (62.57, 20.66)."}, [5]={hint="Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", desc="Loot both keys from Durnholde guards, then free the two prisoners."}, [6]={hint="Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward."}, [7]={npc="Krusk", tgt="Krusk"}, [8]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [9]={npc="Krusk", tgt="Krusk"}, [10]={npc="WANTED", npcObj=true, desc="The wanted poster also offers this quest (62.57, 20.66)."}, [11]={hint="Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill."}, [12]={hint="Kill 10 Crushridge Maulers for Melisara in Tarren Mill.", tag="Group, Optional", desc="Group up for the elite Crushridge Maulers before entering the Ruins of Alterac."}, [13]={npc="Krusk", tgt="Krusk"}, [14]={npc="Melisara", tgt="Melisara", tag="Group, Optional"}, [15]={npc="Melisara", tgt="Melisara", tag="Optional"}, [16]={npc="Krusk", tgt="Krusk"}, [17]={hint="Free Gol'dir then return to Krusk in Tarren Mill."}, [18]={hint="Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.", desc="Check near Gol'dir for Vardus, then search the Syndicate camps farther north."}, [19]={npc="Gol'dir", tgt="Gol'dir"}, [20]={npc="Gol'dir", tgt="Gol'dir"}, [21]={hint="Return the information gathered by Gol'dir to Krusk in Tarren Mill."}, [22]={npc="Krusk", tgt="Krusk"}, [23]={npc="High Executor Darthalia", tgt="High Executor Darthalia"}, [24]={hint="Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", tag="Optional"}, [25]={npc="Melisara", tgt="Melisara", tag="Optional"}, [26]={npc="Melisara", tgt="Melisara", tag="Group, Optional"}, [27]={hint="Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", tag="Group, Optional"}, [28]={npc="Melisara", tgt="Melisara", tag="Group, Optional"}, [29]={npc="Melisara", tgt="Melisara", tag="Group, Optional"}, [30]={hint="Deliver the Crown of Will to Sharlindra in the Undercity.", tag="Group, Optional"}, [31]={npc="Sharlindra", tgt="Sharlindra", tag="Group, Optional"}, [32]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Requires 24; quest level 36. Do it on this trip to Alterac."}, [33]={hint="Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor.", tag="Optional, Target: Barton", desc="Requires 24; quest level 36. Do it on this trip to Alterac."}, [34]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Requires 24; quest level 36. Do it on this trip to Alterac."}, [35]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Loot the uniform from the footlocker. Stay disguised in Stromgarde for the follow-up."}, [36]={hint="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", tag="Optional", desc="Loot the uniform from the footlocker. Stay disguised in Stromgarde for the follow-up."}, [37]={npc="Syndicate Footlocker", npcObj=true, tag="Optional", desc="Loot the uniform from the footlocker. Stay disguised in Stromgarde for the follow-up."}, [38]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Carry the RFK note. Turn it in to Rau (46.14, 51.71) if your log says Freewind Post."}, [39]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="After Elemental Aid, see Bath'rah. If you turned it in at Freewind Post, pick up from Rau."}, [40]={hint="Speak with Prate Cloudseer in Thousand Needles.", tag="Optional", desc="Accept after Elemental Aid."}, [41]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Optional", desc="Accept after Elemental Aid."}, [42]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Optional", desc="Accept from Bath'rah if offered. Get fire/earth at stops 25/27; return for air and water."}, [43]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional, Unverified", desc="Take this side quest if Bath'rah offers it. It can wait until after leveling."}, [44]={hint="Return to Rau Cliffrunner in Thousand Needles at Freewind Post.", tag="Optional, Unverified", desc="Take this side quest if Bath'rah offers it. It can wait until after leveling."}, [45]={npc="Rau Cliffrunner", tgt="Rau Cliffrunner", tag="Optional, Unverified", desc="Take this side quest if Bath'rah offers it. It can wait until after leveling."}, [46]={text="After the Syndicate camp, go east through Thoradin's Wall back into Arathi Highlands."}}},
    ["03-23"] = {name="Arathi Highlands: Hammerfall", short="Hammerfall", tips={{k="取捨", text="Do the later Boulderfist, raptor, and Syndicate quests together on the return visit. Skip follow-ups if you missed the earlier quest of the same name. Click the stones for Stones of Binding on the loop and save Fozruk (Breaking the Keystone) for a group."}, {k="取捨", text="Pick up the salvage, underwater treasure, and captain quests at Faldir's Cove. Finish Sunken Treasure to unlock Sunken Treasure and get the goggles. Do Deep Sea Salvage and Drowned Sorrows underwater on the same trip. Save Sunken Treasure for Booty Bay and turn in Sunken Treasure on a later Faldir's Cove visit."}, {k="取捨", text="The video treats Stromgarde as optional. Do the crystals and the objectives near Hammerfall first. Skip Stromgarde quests Sigil of Arathor-Trol'kalar to save travel time."}, {k="提醒", text="Unlock the flight path when you pass through Stonard. Save the Swamp of Sorrows quests for the Stonard leg.", s={{"Unlock the flight path when you pass through Stonard"}, {"Save the Swamp of Sorrows quests for the Stonard leg"}}}, {k="提醒", text="Below level 40? Grind normal kobolds in Drywhisker Gorge east of Hammerfall (around 84, 31). Once they turn gray, switch to normal Witherbark trolls outside the village (around 68, 69).", s={{"Below level 40?"}, {"Grind normal kobolds in Drywhisker Gorge east of Hammerfall (around 84, 31)"}, {"Once they turn gray, switch to normal Witherbark trolls outside the village (around 68, 69)"}}}}, danger={[1]="Stromgarde guards gather in the gateways. Pull them separately before turning in the sigil chain and avoid aggroing two packs from inside a building.", [2]="Underwater mobs guard the Faldir's Cove wrecks. Equip your Treasure Hunting Goggles and watch your breath before entering."}, grind={[1]={mob="Drywhisker Surveyor", note="Moderate density of normal mobs deep in Drywhisker Gorge, east of Hammerfall. Clear the narrow cave in stages. Watch for rare Geomancer Flintdagger."}, [2]={mob="Drywhisker Digger", note="Dense normal mobs mixed with prospectors in the Drywhisker tunnels. Pair with the crystal quest. Watch for respawns on the way out."}, [3]={mob="Cresting Exile", note="Dense normal water elementals northwest of Hammerfall. They're slightly higher-level than the kobolds and good through 40. Warriors can collect charms for their Whirlwind weapon."}}, supply={[1]={npc="Urda"}, [2]={npc="Innkeeper Adegwa"}, [3]={npc="Mu'uta"}, [4]={npc="Innkeeper Adegwa"}, [5]={npc="Graud"}}, steps={[1]={npc="Shards of Myzrael", npcObj=true}, [2]={npc="Tor'gan", tgt="Tor'gan"}, [3]={npc="Drum Fel", tgt="Drum Fel"}, [4]={npc="Tor'gan", tgt="Tor'gan", tag="Optional"}, [5]={hint="Travel to Hammerfall in the Arathi Highlands and speak with Zengu."}, [6]={npc="Zengu", tgt="Zengu"}, [7]={npc="Zengu", tgt="Zengu", tag="Optional"}, [8]={hint="Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge."}, [9]={npc="Iridescent Shards", npcObj=true}, [10]={npc="Iridescent Shards", npcObj=true}, [11]={hint="Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan."}, [12]={hint="Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost."}, [13]={hint="Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.", tag="Optional"}, [14]={npc="Tor'gan", tgt="Tor'gan"}, [15]={npc="Drum Fel", tgt="Drum Fel"}, [16]={npc="Tor'gan", tgt="Tor'gan", tag="Optional"}, [17]={npc="Tor'gan", tgt="Tor'gan"}, [18]={hint="Give Tor'gan's Orb to Gor'mul."}, [19]={npc="Gor'mul", tgt="Gor'mul"}, [20]={npc="Gor'mul", tgt="Gor'mul"}, [21]={hint="Speak with Tor'gan."}, [22]={npc="Tor'gan", tgt="Tor'gan"}, [23]={npc="Drum Fel", tgt="Drum Fel", tag="Optional"}, [24]={npc="Korin Fel", tgt="Korin Fel", tag="Optional"}, [25]={hint="Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.", tag="Optional"}, [26]={hint="Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.", tag="Optional"}, [27]={npc="Drum Fel", tgt="Drum Fel", tag="Optional"}, [28]={npc="Korin Fel", tgt="Korin Fel", tag="Optional"}, [29]={hint="Get the Sigil of Strom for Zengu in Hammerfall.", tag="Optional"}, [30]={npc="Zengu", tgt="Zengu", tag="Optional"}, [31]={npc="Zengu", tgt="Zengu", tag="Optional"}, [32]={hint="Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", tag="Optional"}, [33]={npc="Tor'gan", tgt="Tor'gan", tag="Optional"}, [34]={npc="Tor'gan", tgt="Tor'gan", tag="Optional"}, [35]={hint="Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", tag="Optional"}, [36]={npc="Zengu", tgt="Zengu", tag="Optional"}, [37]={hint="Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding."}, [38]={npc="Stone of Inner Binding", npcObj=true}, [39]={npc="Stone of Inner Binding", npcObj=true, tag="Group, Optional"}, [40]={hint="Find and kill Fozruk. Bring the Rod of Order to the Keystone in the Arathi Highlands.", tag="Group, Optional"}, [41]={npc="Keystone", npcObj=true, tag="Group, Optional"}, [42]={npc="Keystone", npcObj=true, tag="Group, Optional"}, [43]={hint="Speak with Zaruk in Hammerfall.", tag="Group, Optional"}, [44]={npc="Zaruk", tgt="Zaruk", tag="Group, Optional"}, [45]={npc="Zaruk", tgt="Zaruk", tag="Optional", desc="Turn in Myzrael's Allies at Hammerfall, then pick up from Zaruk. Save for Badlands."}, [46]={text="Faldir's Cove"}, [47]={npc="Lolo the Lookout", tgt="Lolo the Lookout"}, [48]={hint="Talk to Captain O'Breen in Faldir's Cove."}, [49]={npc="Shakes O'Breen", tgt="Shakes O'Breen"}, [50]={npc="Professor Phizzlethorpe", tgt="Professor Phizzlethorpe"}, [51]={hint="Escort Professor Phizzlethorpe to the cave and back.", desc="Clear around the professor. Escort him into the cave, then back to Booty Bay."}, [52]={npc="Doctor Draxlegauge", tgt="Doctor Draxlegauge"}, [53]={npc="First Mate Nilzlix", tgt="First Mate Nilzlix"}, [54]={npc="Captain Steelgut", tgt="Captain Steelgut"}, [55]={npc="Doctor Draxlegauge", tgt="Doctor Draxlegauge"}, [56]={hint="First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine."}, [57]={hint="Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses."}, [58]={hint="Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", desc="Accept Sunken Treasure for the goggles. Wear them for the underwater gems. Pair with Deep Sea Salvage and Drowned Sorrows."}, [59]={npc="First Mate Nilzlix", tgt="First Mate Nilzlix"}, [60]={npc="Captain Steelgut", tgt="Captain Steelgut"}, [61]={npc="Doctor Draxlegauge", tgt="Doctor Draxlegauge"}, [62]={npc="Doctor Draxlegauge", tgt="Doctor Draxlegauge"}, [63]={hint="Take the Elven Gems to Captain O'Breen."}, [64]={npc="Shakes O'Breen", tgt="Shakes O'Breen"}, [65]={npc="Shakes O'Breen", tgt="Shakes O'Breen"}, [66]={npc="Tor'gan", tgt="Tor'gan"}, [67]={npc="Bath'rah's Cauldron", npcObj=true, tag="Optional", desc="Buy charms on the AH if needed. Use the same cauldron to accept and turn in."}, [68]={hint="Loot from: Drywhisker Kobold, Drywhisker Surveyor, Drywhisker Digger", tag="Optional", desc="Buy charms on the AH if needed. Use the same cauldron to accept and turn in."}, [69]={npc="Bath'rah's Cauldron", npcObj=true, tag="Optional", desc="Buy charms on the AH if needed. Use the same cauldron to accept and turn in."}, [70]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional"}, [71]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Level 40 elite quest. Group up before triggering it."}, [72]={hint="Bring the Whirlwind Heart to Bath'rah Windwatcher.", tag="Optional", desc="Level 40 elite quest. Group up before triggering it."}, [73]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Level 40 elite quest. Group up before triggering it."}, [74]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", star={"Whirlwind Axe / Whirlwind Sword / Whirlwind Warhammer"}}, [75]={hint="Complete the quest objectives.", tag="Optional"}, [76]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", star={"Whirlwind Axe / Whirlwind Sword / Whirlwind Warhammer"}}, [77]={npc="Syndicate Footlocker", npcObj=true, tag="Optional", desc="Put on the uniform before entering. Avoid combat to keep your disguise."}, [78]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.", tag="Optional", desc="Put on the uniform before entering. Avoid combat to keep your disguise."}, [79]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Optional", desc="Put on the uniform before entering. Avoid combat to keep your disguise."}, [80]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Optional", desc="QuestieDB has no exact coordinates for the money chest."}, [81]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="Optional", desc="QuestieDB has no exact coordinates for the money chest. Find Anastasia's Stash upstairs in the house by Stromgarde Keep."}, [82]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Optional", desc="QuestieDB has no exact coordinates for the money chest."}, [83]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Optional", desc="Two guards watch the cargo. The pin is a Wowhead player report."}, [84]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="Optional", desc="Two guards watch the cargo. The pin is a Wowhead player report."}, [85]={npc="Myrokos Silentform", tgt="Myrokos Silentform", tag="Optional", desc="Two guards watch the cargo. The pin is a Wowhead player report."}, [86]={text="Return to Hammerfall. If Rog'mar and Stonard are unlocked, fly to Rog'mar. On a first visit, fly to Stonard instead. If Stonard is locked, fly to Grom'gol and run north through Duskwood, skirting Darkshire's guards. Go east through Deadwind Pass into Swamp of Sorrows. If Grom'gol is locked, take its zeppelin from the tower south of Brill.", tag="Flight path locked. Travel there on foot the first time."}}},
    ["05-d17"] = {name="Razorfen Downs", entrance="The Barrens (1413), portal deep in the thorn tunnel, about 49.10, 93.40.", pickup="Fly from Hammerfall to Undercity. On the Shimmering Flats leg, run Razorfen Kraul and loot An Unholy Alliance. On the Alterac-Hammerfall leg, turn in to Varimathras in Undercity, then take Bring the End from Andrew. Take the zeppelin from Tirisfal to Orgrimmar, then fly to Thunder Bluff and see Sutara Plainstalker in northwest Mulgore for The Coldbringer's Eye. Fly to Camp Taurajo and head south to Myriam Moonsinger outside the entrance. From Powderfuse Port, you can also boat to Steamwheedle Port and head north to Thousand Needles.", pickupS={{"Fly from Hammerfall to Undercity"}, {"On the Shimmering Flats leg, run Razorfen Kraul and loot An Unholy Alliance"}, {"On the Alterac-Hammerfall leg, turn in to Varimathras in Undercity, then take Bring the End from Andrew"}, {"Take the zeppelin from Tirisfal to Orgrimmar, then fly to Thunder Bluff and see Sutara Plainstalker in northwest Mulgore for The Coldbringer's Eye"}, {"Fly to Camp Taurajo and head south to Myriam Moonsinger outside the entrance"}, {"From Powderfuse Port, you can also boat to Steamwheedle Port and head north to Thousand Needles"}}, tips={{k="動線", text="Clear to Belnistrasz's cell near Mordresh Fire Eye → turn in the oathstone and escort him to the idol, with Plaguemaw the Rotting if encountered → take the spiral ramp to Amnennar and look for the Coldbringer's Eye nearby."}, {k="取捨", text="Run the full dungeon with a group at level 40+. Kill the final boss for both The Coldbringer's Eye and Bring the End. At 34, pick up the eyeball quest and do A Host of Evil outside if passing."}, {k="說明", text="Five-player dungeon. No key needed. Take the eastern road north of the Great Lift. Razorfen Kraul is to the west. From Riverglades, boat from Powderfuse Port to Steamwheedle Port, then head north.", s={{"Five-player dungeon"}, {"No key needed"}, {"Take the eastern road north of the Great Lift"}, {"Razorfen Kraul is to the west"}, {"From Riverglades, boat from Powderfuse Port to Steamwheedle Port, then head north"}}}, {k="提醒", text="Five-player dungeon. No key needed. Take the eastern road north of the Great Lift. Razorfen Kraul is to the west. From Riverglades, boat from Powderfuse Port to Steamwheedle Port, then head north.", s={{"Five-player dungeon"}, {"No key needed"}, {"Take the eastern road north of the Great Lift"}, {"Razorfen Kraul is to the west"}, {"From Riverglades, boat from Powderfuse Port to Steamwheedle Port, then head north"}}}}, steps={[1]={npc="Small Scroll", npcObj=true, tag="Unverified", desc="Skip if you already looted the Small Scroll from Charlga in Razorfen Kraul."}, [2]={hint="Take the Small Scroll to Varimathras in the Undercity."}, [3]={npc="Varimathras", tgt="Varimathras"}, [4]={npc="Varimathras", tgt="Varimathras", desc="After An Unholy Alliance, pick up here. Targets are in the brambles outside Razorfen Downs.", preText="An Unholy Alliance"}, [5]={npc="Andrew Brownell", tgt="Andrew Brownell", desc="Accept at level 37 in Undercity's Magic Quarter."}, [6]={npc="Sutara Plainstalker", tgt="Sutara Plainstalker", desc="New in Forever. Mulgore (34.56, 23.00). QuestieDB has no sharing flag."}, [7]={npc="Myriam Moonsinger", tgt="Myriam Moonsinger", desc="Accept from Myriam (49.01, 94.94) in the south Barrens. Clear outside before entering."}, [8]={hint="Bring Ambassador Malcin's Head to Varimathras in the Undercity."}, [9]={hint="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."}, [10]={npc="Myriam Moonsinger", tgt="Myriam Moonsinger"}, [11]={text="Razorfen Downs entrance"}, [12]={npc="Belnistrasz", tgt="Belnistrasz", tag="Unverified", desc="Find Belnistrasz in the cells. Everyone should finish the oath before the escort. DungeonsForever map 1: Belnistrasz dialogue objective (80.20, 21.70)."}, [13]={hint="If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", desc="DungeonsForever map 1: Belnistrasz dialogue objective (80.20, 21.70). Location: Find Belnistrasz in the cells near Mordresh Fire Eye. Order: Have everyone turn in the Oathstone before starting the escort."}, [14]={npc="Belnistrasz", tgt="Belnistrasz", tag="Unverified", desc="DungeonsForever map 1: Belnistrasz dialogue objective (80.20, 21.70)."}, [15]={npc="Belnistrasz", tgt="Belnistrasz", tag="Unverified", desc="Wait for the whole group before starting, then stay close to the NPC.", preText="Scourge of the Downs"}, [16]={hint="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.", desc="Location: Escort Belnistrasz from his cell to the idol and protect him."}, [17]={npc="Belnistrasz's Brazier", npcObj=true, tag="Unverified", desc="DungeonsForever map 1: idol ritual (82.20, 19.60). Exact brazier pin unconfirmed."}, [18]={hint="Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", desc="DungeonsForever map 1: Amnennar the Coldbringer (45.00, 59.10). Location: Leave the cells and take the spiral ramp up to Amnennar."}, [19]={hint="Recover The Coldbringer's Eye from Razorfen Downs.", desc="Location: Find the Coldbringer's Eye in Amnennar's lair. Order: Same area as step 17."}, [20]={npc="Sutara Plainstalker", tgt="Sutara Plainstalker"}, [21]={npc="Andrew Brownell", tgt="Andrew Brownell"}, [22]={npc="Varimathras", tgt="Varimathras"}}},
    ["03-24"] = {tips={{k="取捨", text="On the first visit, clear the farm, gnolls, riverbank, and beasts around Rog'mar. Save Chogg'Zac (Twilight No More!) and its follow-up for a group. Pick up the Bolder'ok boar and quarry quests now. Save the level 42+ Twilight and coastal quests for the Bolder'ok and Powderfuse Port return."}, {k="取捨", text="Unlock Rog'mar's flight path to cut travel to Kargath and Stonard. See Toka for supplies."}, {k="提醒", text="Below level 41 after turn-ins? Grind normal boars south of Na'zok's farm (70.62, 33.08) or beasts south of Rog'mar (around 61, 50). Save the later Bolder'ok Twilight quests for the Powderfuse Port return.", s={{"Below level 41 after turn-ins?"}, {"Grind normal boars south of Na'zok's farm (70.62, 33.08) or beasts south of Rog'mar (around 61, 50)"}, {"Save the later Bolder'ok Twilight quests for the Powderfuse Port return"}}}}, danger={[1]="Farholde scouts and priests roam south of Rog'mar. Pull lone scouts to avoid bringing in priests.", [2]="The Twilight ritual cave in Sunnyglade is narrow. Clear the entrance before disrupting the ritual circles. Watch for shadowmancers respawning behind you."}, grind={[1]={mob="Low Plains Buzzard", note="Dense normal mobs south of Rog'mar. Pick off singles along the road, avoid the level 41-42 elite beasts, and collect feathers for Feathers for Fletching."}, [2]={mob="Farholde Scout", note="Dense normal mobs in the Farholde scout area south of Rog'mar. Clear along the river for Show Them How It's Done and avoid pulling priests and scouts together."}, [3]={mob="Farholde Priest", note="Moderate density of normal casters on the western end of the south bank. Interrupt heals and keep scouts out of the pull. Grind here on the west leg of Show Them How It's Done."}}, supply={[1]={npc="Grakna"}, [2]={npc="Innkeeper Toka"}, [3]={npc="Gur'dok"}, [4]={npc="Naluk"}, [5]={npc="Maka"}, [6]={npc="Breyk"}, [7]={npc="Thultazor"}}, steps={[1]={node="Stonard", desc="Unlock the flight path with Breyk if coming overland from the Swamp. Otherwise skip."}, [2]={text="Fly from Stonard if you've unlocked Rog'mar. On your first visit, enter Riverglades from the Swamp of Sorrows, follow the road along the south side past Terral's Watch (about 60, 64), then head north to Rog'mar (video 26:56-27:13). If you flew in from Hammerfall, go straight to the flight master.", tag="Flight path locked. Travel there on foot the first time."}, [3]={node="Rog'mar", desc="Unlock the flight path with Grakna."}, [4]={text="Set your hearth with Innkeeper Toka (57.58, 45.47)."}, [5]={hint="Report to Krom'rosh at the Rog'mar outpost in the Riverglades."}, [6]={hint="Find Tan'jani at Rog'mar in the Riverglades."}, [7]={npc="Krom'rosh", tgt="Krom'rosh"}, [8]={npc="Tan'jani", tgt="Tan'jani"}, [9]={npc="Krom'rosh", tgt="Krom'rosh"}, [10]={npc="Krom'rosh", tgt="Krom'rosh"}, [11]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [12]={npc="Tan'jani", tgt="Tan'jani"}, [13]={text="Southern farms and southwest gnolls"}, [14]={hint="Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success.", tag="Target: Meadowsbrook Farmhand"}, [15]={hint="Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."}, [16]={npc="Krom'rosh", tgt="Krom'rosh"}, [17]={npc="Krom'rosh", tgt="Krom'rosh"}, [18]={npc="Krom'rosh", tgt="Krom'rosh"}, [19]={hint="Deliver the Stolen Feed to Gorg in Rog'mar."}, [20]={npc="Gorg", tgt="Gorg"}, [21]={npc="Gorg", tgt="Gorg"}, [22]={hint="Feed 8 Rog'mar Trainees at the training grounds.", tag="Target: Rog'mar Trainee"}, [23]={npc="Gorg", tgt="Gorg"}, [24]={npc="Krom'rosh", tgt="Krom'rosh"}, [25]={hint="Slay 8 Farholde Priests and 12 Farholde Scouts south of the river.", tag="Target: Farholde Priest / Farholde Scout"}, [26]={npc="Krom'rosh", tgt="Krom'rosh"}, [27]={npc="Tran'gul", tgt="Tran'gul"}, [28]={npc="Tran'gul", tgt="Tran'gul"}, [29]={text="Riverside lumber camps and Sunnyglade"}, [30]={hint="Retrieve 10 Woodworker's Axe from the lumberjacks at Turner's Logging Camp for Kreza Darkthorn in Rog'mar.", tag="Target: Turner's Mill Lumberjack"}, [31]={hint="Collect Wood Bundles from Peasant Woodpiles in Turner's Logging Camp then fletch them into 20 Makeshift Stickin' Spears."}, [32]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [33]={npc="Gur'dok", tgt="Kreza Darkthorn", desc="After Borrowed Blades, accept here. Save the sword for Friz in Powderfuse Port."}, [34]={npc="Tan'jani", tgt="Tan'jani"}, [35]={npc="Tan'jani", tgt="Tan'jani"}, [36]={hint="Impale 10 Freshwater Crocolisks then return to Tran'jani in Rog'mar.", tag="Target: Freshwater Crocolisk"}, [37]={npc="Tan'jani", tgt="Tan'jani"}, [38]={hint="Defeat 8 Twilight Raiders and 8 Twilight Neophytes within Sunnyglade for Tran'gul in Rog'mar.", tag="Target: Twilight Raider/Twilight Shadowmancer/Twilight Neophyte"}, [39]={hint="Retrieve 3 Twilight Missives from Twilight Shadowmancers in Sunnyglade for Tran'gul in Rog'mar.", tag="Target: Twilight Shadowmancer"}, [40]={npc="Tran'gul", tgt="Tran'gul"}, [41]={npc="Tran'gul", tgt="Tran'gul"}, [42]={npc="Tran'gul", tgt="Tran'gul"}, [43]={hint="Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."}, [44]={npc="Clubtoe", tgt="Clubtoe"}, [45]={npc="Clubtoe", tgt="Clubtoe"}, [46]={hint="Find missing ogres in the caves beneath Sunnyglade for Clubtoe."}, [47]={npc="Empowered Brute", tgt="Twilight Brute"}, [48]={npc="Empowered Brute", tgt="Twilight Brute"}, [49]={npc="Clubtoe", tgt="Clubtoe"}, [50]={hint="Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade.", tag="Target: Empowered Brute/Twilight Ritualist"}, [51]={hint="Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade."}, [52]={npc="Clubtoe", tgt="Clubtoe"}, [53]={npc="Clubtoe", tgt="Clubtoe"}, [54]={npc="Clubtoe", tgt="Clubtoe", tag="Group, Optional"}, [55]={hint="Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe.", tag="Group, Optional, Target: Chogg'Zac", desc="Chogg'Zac is a level 41 elite in the Clearwood Caverns."}, [56]={npc="Clubtoe", tgt="Clubtoe", tag="Group, Optional"}, [57]={npc="Clubtoe", tgt="Clubtoe", tag="Group, Optional"}, [58]={hint="Deliver the head of Chogg to Tran'gul in Rog'mar.", tag="Group, Optional"}, [59]={npc="Tran'gul", tgt="Tran'gul", tag="Group, Optional"}, [60]={npc="Tran'gul", tgt="Tran'gul", tag="Group, Optional"}, [61]={text="Hunts around Rog'mar"}, [62]={npc="Picked Carcass", tgt="Picked Carcass", desc="Click the Gnawed Corpse on the ground among beasts to the south."}, [63]={hint="Bring the Gnawed Skull to Neza Bloodsnout at Rog'mar."}, [64]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [65]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [66]={hint="Bring an Intact Tallstrider Beak to Neza Bloodsnout at Rog'mar.", tag="Target: Roving Tallstrider"}, [67]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [68]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [69]={hint="Bring 6 Plains Buzzard Feathers to Neza Bloodsnout at Rog'mar.", tag="Target: Low Plains Buzzard"}, [70]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [71]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [72]={hint="Bring 4 samples of Glade Viper Venom to Neza Bloodsnout at Rog'mar.", tag="Target: Glade Viper"}, [73]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [74]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [75]={hint="Gather 6 Prized Lion Hides for Neza Bloodsnout at Rog'mar.", tag="Target: Wildplains Patriarch/Wildplains Huntress"}, [76]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [77]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout", tag="Optional", star={"Bloodsnout Striker", {"WARRIOR", "PALADIN"}}}, [78]={hint="Locate Snargl in the Bristle Hills, kill him, and retrieve his snout for Neza Bloodsnout.", tag="Optional, Target: Snargl"}, [79]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout", tag="Optional", star={"Bloodsnout Striker", {"WARRIOR", "PALADIN"}}}, [80]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [81]={hint="Gather 40 Stolen Ore from gnolls in the Bristle Hills for Kreza Darkthorn.", tag="Target: Redridge Brute / Redridge Mystic / Redridge Trapper"}, [82]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [83]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [84]={hint="Kill 8 Redridge Mystics, 8 Redridge Trappers, and 6 Redridge Brutes for Neza Bloodsnout at Rog'mar.", tag="Target: Redridge Mystic / Redridge Trapper / Redridge Brute"}, [85]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout"}, [86]={text="Levels 40-41: short northern loop"}, [87]={hint="Deliver Chogg's head to the ogre city to the north.", tag="Group, Optional"}, [88]={npc="Clugfist", tgt="Clugfist", tag="Group, Optional"}, [89]={npc="Na'zok", tgt="Na'zok"}, [90]={npc="Na'zok", tgt="Na'zok"}, [91]={npc="Gorgegut", tgt="Gorgegut", desc="Hamur also offers this quest (67.24, 21.75)."}, [92]={hint="Gather 10 Chunks of Boar Meat for Na'zok near Bolder'ok."}, [93]={hint="Return 10 Young Paletusks to Na'zok's farm near Bolder'ok.", tag="Target: Young Paletusk", desc="Use the quest item on young boars to herd them back to the farm."}, [94]={hint="Gather 10 Good Rocks for Hamur in Bolder'ok."}, [95]={npc="Na'zok", tgt="Na'zok"}, [96]={npc="Na'zok", tgt="Na'zok"}, [97]={npc="Hamur", tgt="Hamur"}, [98]={npc="Hamur", tgt="Hamur"}, [99]={hint="Deliver 10 Heavy Weightstones to Hamur in Bolder'ok.", desc="Bring the materials to Hamur. Craft the Heavy Weightstone or buy it from a player."}, [100]={npc="Hamur", tgt="Hamur"}, [101]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout", tag="Optional"}, [102]={hint="Use the Tallstrider Call to call forth the leader of the lion pride. Slay the beast and retrieve its hide for Neza Bloodsnout at Rog'mar.", tag="Optional, Target: Ombassa", desc="Group up, then use the quest item to summon Ombassa, a level 41 elite."}, [103]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout", tag="Optional"}, [104]={npc="Garen Largo", tgt="Garen Largo", desc="Accept in Undercity at 40, then head to the keep. Alodan also offers it (25.42, 14.71)."}, [105]={hint="Speak with Danitha Morr at Bandarion Keep.", desc="Accept in Undercity at level 40, then head to Bandarion Keep."}, [106]={npc="Danitha Morr", tgt="Danitha Morr", desc="Accept in Undercity at level 40, then head to Bandarion Keep."}, [107]={npc="Danitha Morr", tgt="Danitha Morr", desc="Pick up after Report to Danitha. Finish this chain before buying a mount if you want the Warhorse."}, [108]={hint="Speak with Danitha Morr to learn to summon your Warhorse.", desc="Pick up after Report to Danitha. Finish this chain before buying a mount if you want the Warhorse."}, [109]={npc="Danitha Morr", tgt="Danitha Morr", desc="Pick up after Report to Danitha. Finish this chain before buying a mount if you want the Warhorse."}, [110]={npc="Zevrost", tgt="Zevrost", tag="Optional"}, [111]={hint="Speak to Strahad Farsan in the Barrens.", tag="Optional"}, [112]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Optional"}, [113]={npc="Kaal Soulreaper", tgt="Kaal Soulreaper", tag="Optional"}, [114]={hint="Speak to Strahad Farsan in Ratchet.", tag="Optional"}, [115]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Optional"}, [116]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Turn in the local lead-in, then pick up from Strahad."}, [117]={hint="Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed.", desc="Turn in the local lead-in, then pick up from Strahad."}, [118]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Turn in the local lead-in, then pick up from Strahad."}, [119]={text="Fly from Rog'mar to Kargath if unlocked. On a first visit, use the west pass north of the Twilight camp to enter Badlands, then go northwest to Kargath (video 27:55-28:03). Keep your Rog'mar hearth for the return.", tag="Flight path locked. Travel there on foot the first time."}}},
    ["03-25"] = {name="Badlands: Kargath", tips={{k="取捨", text="The rock elementals overlap with Badlands Reagent Run. Pick up both quests before fighting. Loot 30 coyote jaws as you go and move on once you reach the target level."}, {k="取捨", text="Do Coolant Heads Prevail-Liquid Stone only if you have Frost Oil, a Gyrochronatom, and the potion. Save Broken Alliances for a higher level or a group."}, {k="提醒", text="The video trains riding on this level 40 city trip. If you're level 40 and can afford it, visit your race's riding trainer while passing through. See the class quests and level 40 riding notes below.", s={{"The video trains riding on this level 40 city trip"}, {"If you're level 40 and can afford it, visit your race's riding trainer while passing through"}, {"See the class quests and level 40 riding notes below"}}}, {k="提醒", text="Below level 42? Grind normal Greater Rock Elementals in southwest Badlands (around 6.65, 73.85). If that spot is crowded, switch to coyotes and vultures on the ridge southeast of Kargath.", s={{"Below level 42?"}, {"Grind normal Greater Rock Elementals in southwest Badlands (around 6.65, 73.85)"}, {"If that spot is crowded, switch to coyotes and vultures on the ridge southeast of Kargath"}}}}, danger={[1]="Level 39-40 elite Stonevault Seers and Brawlers roam the east Badlands. Give them a wide berth when skirting Uldaman."}, grind={[1]={mob="Greater Rock Elemental", note="Dense normal mobs along the cliff south of Kargath. Clear outside along the rocks and watch for Firegut Ogres. Switch to the ridge if it's too tough before 42."}, [2]={mob="Ridge Stalker Patriarch", note="Moderate density of normal mobs on the ridge southeast of Kargath. Avoid elite and rare patrols. Solo grind at 41 or switch here if the elementals are crowded."}, [3]={mob="Giant Buzzard", note="Moderate density of normal mobs on the slope southeast of Kargath. Alternate with the ridge mobs. Pick up buzzard wings or gizzards if needed."}}, supply={[1]={npc="Gorrik"}, [2]={npc="Innkeeper Shul'kar"}, [3]={npc="Sranda"}, [4]={npc="Innkeeper Shul'kar"}, [5]={npc="Grawl"}}, steps={[1]={node="Kargath", desc="Unlock the flight path with Gorrik."}, [2]={text="Leave to train skills or learn Riding if needed. Fly back to Kargath afterward."}, [3]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [4]={npc="Neeka Bloodscar", tgt="Neeka Bloodscar"}, [5]={npc="Neeka Bloodscar", tgt="Neeka Bloodscar"}, [6]={npc="Gorn", tgt="Gorn", tag="Optional"}, [7]={text="Rock elementals and central mob loop"}, [8]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [9]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="When you have the items, Optional"}, [10]={hint="Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", tag="When you have the items, Optional", desc="Bring Frost Oil to Lotwil Veriatus. Turn in here. Ask an alchemist to make Frost Oil if you need it."}, [11]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="When you have the items, Optional"}, [12]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="When you have the items, Optional"}, [13]={hint="Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", tag="When you have the items, Optional", desc="Get a Gyrochronatom first. Engineers can craft it. The pin marks the material turn-in."}, [14]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="When you have the items, Optional"}, [15]={npc="Lucien Tosselwrench", tgt="Lucien Tosselwrench", tag="When you have the items, Optional"}, [16]={hint="Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.", tag="When you have the items, Optional"}, [17]={npc="Lucien Tosselwrench", tgt="Lucien Tosselwrench", tag="When you have the items, Optional"}, [18]={hint="Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands."}, [19]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [20]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [21]={hint="Bring Fizzle's Letter to Martek the Exiled in the Badlands."}, [22]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [23]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [24]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [25]={hint="Find Theldurin the Lost.", tag="Optional"}, [26]={npc="Theldurin the Lost", tgt="Theldurin the Lost", tag="Optional"}, [27]={npc="Theldurin the Lost", tgt="Theldurin the Lost", tag="Optional"}, [28]={hint="Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands."}, [29]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [30]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [31]={hint="Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", desc="Farm Stonebound Bracers from normal Greater Rock Elementals in the southwest."}, [32]={hint="Bring 10 Indurium Flakes to Martek the Exiled in the Badlands."}, [33]={hint="Bring 4 Buzzard Wings to Rigglefuzz."}, [34]={hint="Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", tag="Optional"}, [35]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [36]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [37]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [38]={npc="Theldurin the Lost", tgt="Theldurin the Lost", tag="Optional"}, [39]={hint="Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."}, [40]={hint="Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath."}, [41]={hint="Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.", tag="Group, Optional"}, [42]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [43]={npc="Neeka Bloodscar", tgt="Neeka Bloodscar"}, [44]={npc="Gorn", tgt="Gorn", tag="Group, Optional"}, [45]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", tag="Only for an Uldaman run, Optional"}, [46]={text="If you know Riding, fly from Kargath to Grom'gol, then on to Booty Bay. Otherwise visit your racial riding trainer. If you're near Orgrimmar or Undercity, take the Grom'gol zeppelin."}}},
    ["05-d18"] = {name="Uldaman", entrance="Badlands (1418), about 42.60, 10.80. Follow the dig site underground. Back portal coords unknown.", pickup="Approach Uldaman from Kargath. On the Alterac and Hammerfall legs, take Reclaimed Treasures from Patrick in Undercity. Fly from Hammerfall or Grom'gol to Kargath, do Jarkal's Badlands Reagent Run → Uldaman Reagent Run, then visit Rigglefuzz and Theldurin. Mages can do Tabetha's Dustwallow prerequisite from level 35. For the necklace chain, loot the Shattered Necklace on the first run, turn it in to Dran on an Orgrimmar visit, then return through Kargath.", pickupS={{"Approach Uldaman from Kargath"}, {"On the Alterac and Hammerfall legs, take Reclaimed Treasures from Patrick in Undercity"}, {"Fly from Hammerfall or Grom'gol to Kargath, do Jarkal's Badlands Reagent Run → Uldaman Reagent Run, then visit Rigglefuzz and Theldurin"}, {"Mages can do Tabetha's Dustwallow prerequisite from level 35", {class={"MAGE"}}}, {"For the necklace chain, loot the Shattered Necklace on the first run, turn it in to Dran on an Orgrimmar visit, then return through Kargath"}}, tips={{k="動線", text="Main entrance → Revelosh → loot the journal from the remains. Return to Kargath for the translation before the next run. Mages can reach the Obsidian Sentinel from the back door. Second dig site → Galgann → Grimlok → Archaedas → Discs of Norgannon."}, {k="取捨", text="Prioritize Uldaman Reagent Run, Reclaimed Treasures, and Power Stones. At level 40, get the discs and the bag. The necklace takes at least two trips, so skip it if leveling quickly."}, {k="說明", text="Five-player dungeon. At level 34, take Reclaimed Treasures in Undercity and do the outer cave when passing through Badlands. Aim for level 42 for the final boss. Use the front door for a full clear or the necklace, or the back door for the latter half or the Mage quest. If your map only marks the surface cave, follow the main tunnel to the portal.", s={{"Five-player dungeon"}, {"At level 34, take Reclaimed Treasures in Undercity and do the outer cave when passing through Badlands"}, {"Aim for level 42 for the final boss"}, {"Use the front door for a full clear or the necklace, or the back door for the latter half or the Mage quest"}, {"If your map only marks the surface cave, follow the main tunnel to the portal"}}}, {k="提醒", text="Five-player dungeon. At level 34, take Reclaimed Treasures in Undercity and do the outer cave when passing through Badlands. Aim for level 42 for the final boss. Use the front door for a full clear or the necklace, or the back door for the latter half or the Mage quest. If your map only marks the surface cave, follow the main tunnel to the portal.", s={{"Five-player dungeon"}, {"At level 34, take Reclaimed Treasures in Undercity and do the outer cave when passing through Badlands"}, {"Aim for level 42 for the final boss"}, {"Use the front door for a full clear or the necklace, or the back door for the latter half or the Mage quest"}, {"If your map only marks the surface cave, follow the main tunnel to the portal"}}}}, steps={[1]={npc="Patrick Garrett", tgt="Patrick Garrett", desc="Pick up in Undercity at level 33. The chest is outside the portal."}, [2]={npc="Rigglefuzz", tgt="Rigglefuzz", desc="Loot Power Stones from Shadowforge dwarves outside on the same trip."}, [3]={npc="Theldurin the Lost", tgt="Theldurin the Lost", desc="Theldurin is in southern Badlands. Accept if you're passing through."}, [4]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", desc="If you turned in this quest at Kargath, pick up Uldaman Reagent Run directly."}, [5]={hint="Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."}, [6]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [7]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", desc="Pick up from Jarkal in Kargath after turning in Badlands Reagent Run.", preText="Badlands Reagent Run"}, [8]={npc="Deino", tgt="Deino", desc="At 35, do this between Brackenwall and Shadowprey. Skip if turned in."}, [9]={hint="Speak with Tabetha."}, [10]={npc="Tabetha", tgt="Tabetha"}, [11]={npc="Tabetha", tgt="Tabetha"}, [12]={hint="Bring an Infernal Orb to Tabetha in Dustwallow Marsh."}, [13]={npc="Tabetha", tgt="Tabetha"}, [14]={npc="Tabetha", tgt="Tabetha", preText="The Infernal Orb"}, [15]={hint="Kill the Demon of the Orb, then speak with Tabetha."}, [16]={npc="Tabetha", tgt="Tabetha"}, [17]={npc="Tabetha", tgt="Tabetha", desc="Pick up after Tabetha's exorcism. Ask the group to clear the back-entrance sentinel.", preText="The Exorcism"}, [18]={hint="Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."}, [19]={hint="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."}, [20]={hint="Bring the Tablet of Ryun'eh to Theldurin the Lost."}, [21]={npc="Dran Droffers", tgt="Dran Droffers", desc="Optional chain. Loot a Shattered Necklace from dig site or dungeon dwarves."}, [22]={hint="Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."}, [23]={npc="Dran Droffers", tgt="Dran Droffers"}, [24]={npc="Dran Droffers", tgt="Dran Droffers", desc="Skip this chain if running Uldaman once. Pick up from Dran after turning in Necklace Recovery.", preText="Necklace Recovery"}, [25]={text="Uldaman entrance"}, [26]={hint="Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", desc="The pin marks Magenta Cap Clusters outside the portal. Location: Gather mushrooms outside the main door, then finish along the excavation tunnels."}, [27]={hint="Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", desc="DungeonsForever map 1: Obsidian Sentinel (28.80, 61.80). Location: Take the back entrance. The Obsidian Sentinel is nearby."}, [28]={hint="Find a clue as to the gems' whereabouts in the depths of Uldaman.", desc="Map 1: Remains of a Paladin (54.20, 63.20), also the Translating the Journal pickup. Location: Take the main entrance. Find the body in the room past Revelosh. Order: Leave the dungeon for steps 30 and 33."}, [29]={npc="Remains of a Paladin", tgt="Remains of a Paladin", tag="Unverified", desc="Map 1: Remains of a Paladin (54.20, 63.20), also the Translating the Journal pickup."}, [30]={npc="Remains of a Paladin", tgt="Remains of a Paladin", tag="Unverified", desc="Pick up the diary at the corpse and return to Kargath to unlock the next trip. DungeonsForever map 1: Remains of a Paladin (54.20, 63.20).", preText="Necklace Recovery, Take 2"}, [31]={hint="Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."}, [32]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [33]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", preText="Translating the Journal"}, [34]={hint="Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."}, [35]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [36]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", desc="Accept after getting the translation in Kargath. Full clear on the second run.", preText="Translating the Journal"}, [37]={hint="Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.", desc="Location: Check the second dig site's urn, then Galgann, Grimlok and the final boss. Order: Take the topaz first, then the ruby and sapphire, then the power source."}, [38]={npc="The Discs of Norgannon", npcObj=true, tag="Unverified", desc="At level 40+, kill Archaedas and click the Discs of Norgannon in the final room. DungeonsForever map 1: Discs of Norgannon (38.60, 5.50)."}, [39]={hint="Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon.", desc="DungeonsForever map 1: Discs of Norgannon (38.60, 5.50). Location: Kill Archaedas and use the Discs of Norgannon in the vault behind him. Order: Listen to the Stone Keeper, then click the discs."}, [40]={npc="The Discs of Norgannon", npcObj=true, tag="Unverified", desc="DungeonsForever map 1: Discs of Norgannon (38.60, 5.50)."}, [41]={npc="The Discs of Norgannon", npcObj=true, tag="Unverified", desc="Use the same discs to accept the Horde delivery. Return to Thunder Bluff. DungeonsForever map 1: Discs of Norgannon (38.60, 5.50), also used in The Platinum Discs.", preText="The Platinum Discs"}, [42]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [43]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [44]={npc="Theldurin the Lost", tgt="Theldurin the Lost"}, [45]={npc="Patrick Garrett", tgt="Patrick Garrett"}, [46]={npc="Tabetha", tgt="Tabetha"}, [47]={hint="Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."}, [48]={npc="Sage Truthseeker", tgt="Sage Truthseeker"}, [49]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}, [50]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld", preText="Find the Gems and Power Source"}, [51]={hint="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."}, [52]={npc="Dran Droffers", tgt="Dran Droffers"}, [53]={npc="Dran Droffers", tgt="Dran Droffers", preText="Deliver the Gems"}, [54]={hint="Visit Jarkal Mossmeld in Kargath to see if he was successful."}, [55]={npc="Jarkal Mossmeld", tgt="Jarkal Mossmeld"}}},
    ["03-26"] = {name="Stranglethorn Vale", tips={{k="取捨", text="On the second Booty Bay visit, turn in completed quests such as Sunken Treasure, Venture Company Mining, and Excelsior. Do Bloodsail The Bloodsail Buccaneers → The Bloodsail Buccaneers → The Bloodsail Buccaneers near shore, then pair The Bloodsail Buccaneers with Keep An Eye Out and Up to Snuff. Turn in The Bloodsail Buccaneers to unlock The Bloodsail Buccaneers for the three captains. Turn in Scaring Shaky → Return to MacKinley to unlock Voodoo Dues. Return to town for those unlocks."}, {k="取捨", text="Pick up Cortello's Riddle on the Bloodsail ships and do the first leg when passing Stonard. Finish Excelsior and Venture Company Mining along the way if needed to avoid another flight. Do Voodoo Dues ashore before boarding."}, {k="提醒", text="The Booty Bay and Bolder'ok/Powderfuse Port legs together take you to level 45. If you're just short here, grind normal Bloodsail pirates on the shore after the three ships (around 32, 79).", s={{"The Booty Bay and Bolder'ok/Powderfuse Port legs together take you to level 45"}, {"If you're just short here, grind normal Bloodsail pirates on the shore after the three ships (around 32, 79)"}}}}, danger={[1]="Mosh'Ogg Ogre Mound has several ogre types, including elites. For the Grom'gol plan, pull from the foot of the hill and stay out of the camp.", [2]="The Bloodsail ships have narrow stairs and few exits. Clear the shore before boarding, then clear each deck before leaving."}, grind={[1]={mob="Bloodsail Swashbuckler", note="Dense normal mobs on the beaches outside Booty Bay. Clear ashore first and watch for players doing Bloodsail quests. Grind here after the ship quests."}, [2]={mob="Bloodsail Warlock", note="Dense normal casters on the southern Bloodsail shore. Clear nearby melee mobs first, then pull the warlocks. Loop ashore to save boarding time."}}, supply={[1]={npc="Gringer"}, [2]={npc="Innkeeper Skindle"}, [3]={npc="Jutak"}, [4]={npc="Nixxrax Fillamug"}, [5]={npc="Haren Kanmae"}, [6]={npc="Thysta"}, [7]={npc="Innkeeper Thulbek"}, [8]={npc="Krakk"}, [9]={npc="Nargatt"}}, steps={[1]={text="On arrival at Grom'gol, fly to Booty Bay for the next quest batch. Pick up camp quests first if you started nearby."}, [2]={hint="Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay."}, [3]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [4]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn", tag="Later, on the way, Optional"}, [5]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [6]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [7]={npc="Privateer Bloads", tgt="Privateer Bloads"}, [8]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [9]={npc="Kebok", tgt="Kebok"}, [10]={npc="Drizzlik", tgt="Drizzlik"}, [11]={npc="Drizzlik", tgt="Drizzlik"}, [12]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", tag="Requires the Zul'Kunda escort, Optional"}, [13]={npc="Krazek", tgt="Krazek", tag="Do at Stonard in Swamp of Sorrows, Optional", desc="Do Parts for Kravel in Ratchet and Delivery to the Gnomes at the Shimmering Flats, then turn in The Rumormonger in Booty Bay."}, [14]={text="Scout the north beach, then unlock the Bloodsail quests in Booty Bay"}, [15]={hint="First Mate Crazz wants you to check the cove north of Booty Bay."}, [16]={npc="Bloodsail Correspondence", npcObj=true}, [17]={npc="Bloodsail Correspondence", npcObj=true}, [18]={hint="Report your findings to First Mate Crazz in Booty Bay."}, [19]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [20]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [21]={hint="Report the planned Bloodsail attack to Fleet Master Seahorn."}, [22]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [23]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [24]={npc="Dizzy One-Eye", tgt="Dizzy One-Eye"}, [25]={npc="Deeg", tgt="Deeg"}, [26]={text="For the extra camp quests, fly from Booty Bay to Grom'gol and clear south toward the port."}, [27]={hint="Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", tag="Optional"}, [28]={npc="Kin'weelay", tgt="Kin'weelay", tag="Optional"}, [29]={npc="Bubbling Cauldron", npcObj=true, tag="Turn in on your Dustwallow return, Optional"}, [30]={npc="Kin'weelay", tgt="Kin'weelay", tag="Requires Bloody Bone Necklaces and The Vile Reef"}, [31]={npc="Bubbling Cauldron", npcObj=true}, [32]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [33]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh", tag="Optional"}, [34]={hint="Hemet Nesingwary wants you to kill 10 Jungle Stalkers."}, [35]={hint="Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.", tag="Do alongside Raptor Mastery"}, [36]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [37]={npc="Far Seer Mok'thardin", tgt="Far Seer Mok'thardin", tag="Do alongside Raptor Mastery"}, [38]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group or solo, Optional"}, [39]={hint="Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.", tag="Group or solo, Optional"}, [40]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group or solo, Optional"}, [41]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group or solo, Optional", star={"Master Hunter's Bow / Master Hunter's Rifle"}}, [42]={hint="Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.", tag="Group or solo, Optional"}, [43]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group or solo, Optional", star={"Master Hunter's Bow / Master Hunter's Rifle"}}, [44]={hint="Commander Aggro'gosh of the Grom'gol base camp wants you to kill ogres at the Mosh'Ogg Ogre Mount.", tag="Optional", desc="Group up for the four elite targets at the Mosh'Ogg Ogre Mound."}, [45]={hint="Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp."}, [46]={hint="Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp."}, [47]={npc="Commander Aggro'gosh", tgt="Commander Aggro'gosh", tag="Optional"}, [48]={npc="Kin'weelay", tgt="Kin'weelay"}, [49]={npc="Bubbling Cauldron", npcObj=true}, [50]={text="Pickups in central and southern Stranglethorn → Bloodsail Compound"}, [51]={hint="Acquire 18 Skullsplitter Tusks and return them to Kebok."}, [52]={hint="Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay."}, [53]={hint="Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay."}, [54]={hint="Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.", tag="Target: Naga Explorer / Brinescale Skirmisher"}, [55]={hint="Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."}, [56]={hint="Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay."}, [57]={hint="Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders."}, [58]={hint="Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers."}, [59]={hint="Deeg in Booty Bay wants you to bring him 15 shares of Snuff."}, [60]={npc="Kebok", tgt="Kebok"}, [61]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [62]={npc="Drizzlik", tgt="Drizzlik"}, [63]={npc="Privateer Bloads", tgt="Privateer Bloads"}, [64]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [65]={npc="\"Shaky\" Phillipe", tgt="Shaky Phillipe"}, [66]={npc="\"Shaky\" Phillipe", tgt="Shaky Phillipe"}, [67]={hint="Bring Shaky's Payment to \"Sea Wolf\" MacKinley."}, [68]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [69]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [70]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [71]={npc="Dizzy One-Eye", tgt="Dizzy One-Eye"}, [72]={npc="Deeg", tgt="Deeg"}, [73]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [74]={text="Final loop: board the ships and collect debts"}, [75]={hint="Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay."}, [76]={hint="Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon."}, [77]={npc="Cortello's Riddle", npcObj=true, desc="Start on the Bloodsail ship. Turn in under the bridge in Swamp of Sorrows."}, [78]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [79]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [80]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley", tag="Optional"}, [81]={hint="Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.", tag="Optional"}, [82]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley", tag="Optional"}, [83]={text="After the Bloodsail and debt quests, fly to Stonard from Booty Bay or Grom'gol. If locked, fly to Grom'gol and take the road through eastern Duskwood and Deadwind Pass."}}},
    ["03-27"] = {name="Swamp of Sorrows: Stonard", short="Stonard", tips={{k="取捨", text="Clear the path for Galen's Escape before opening the cage. Turn it in at the strongbox at the end of the escort."}, {k="取捨", text="Save Lack of Surplus ( → Lack of Surplus), Threat From the Sea ( → Threat From the Sea → 1427 → Continued Threat), and Fresh Meat for the southeast coast return at level 47+. The video goes there around 30:50."}, {k="提醒", text="Turn in Cortello's scroll on the west side, then go to Fallow Sanctuary. Do the crystal quest and both Lost Ones chains together. Need a little XP? Grind normal mobs around the Pool of Tears (around 60, 55), or catch up at Eastwind Shore.", s={{"Turn in Cortello's scroll on the west side, then go to Fallow Sanctuary"}, {"Do the crystal quest and both Lost Ones chains together"}, {"Need a little XP?"}, {"Grind normal mobs around the Pool of Tears (around 60, 55), or catch up at Eastwind Shore"}}}}, danger={[1]="Clear the cage area and camp exit before talking to Galen. Pulling after opening the cage makes it harder to keep both of you alive."}, grind={[1]={mob="Wyrmkin Dreamwalker", note="Moderate density of normal mobs north of the Pool of Tears. Pull from dry land to avoid green dragonkin. Use this on-route spot for a little XP."}, [2]={mob="Marsh Inkspewer", note="Moderate density of normal murlocs southeast of Stonard. Pull singles from outside the camp without chasing into packs. Good at 42-43."}, [3]={mob="Marsh Flesheater", note="Moderate density of normal mobs at the south edge of the same murloc camp. Watch for higher-level Oracles and alternate with Inkspitters before 44."}}, supply={[1]={npc="Breyk"}, [2]={npc="Innkeeper Karakul"}, [3]={npc="Gharash"}, [4]={npc="Thultash"}, [5]={npc="Thultazor"}}, steps={[1]={text="Check that Breyk's Stonard flight path is unlocked (46.07, 54.83)."}, [2]={hint="Bring Neeka's Report to Helgrum the Swift in Stonard."}, [3]={npc="Helgrum the Swift", tgt="Helgrum the Swift"}, [4]={npc="Fel'zerul", tgt="Fel'zerul"}, [5]={text="Under the west bridge and at the Harborage"}, [6]={hint="Solve the riddle!"}, [7]={npc="A Soggy Scroll", npcObj=true}, [8]={npc="A Soggy Scroll", npcObj=true, tag="Later, on the way"}, [9]={npc="Magtoor", tgt="Magtoor"}, [10]={npc="Karana", tgt="Karana"}, [11]={npc="Pelluk", tgt="Pelluk"}, [12]={hint="Bring 10 Specks of Dream Dust to Krazek in Booty Bay. Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", tag="Optional"}, [13]={hint="Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.", tag="Optional"}, [14]={hint="Slay 10 Lost Ones in the Fallow Sanctuary."}, [15]={hint="Find the Lost One Fisherman who stole Pelluk's lure, and take it back."}, [16]={hint="Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows."}, [17]={npc="Noboru's Cudgel", npcObj=true, tag="If it drops, Optional", desc="Kill the patrolling Noboru the Cudgel and right-click his cudgel to start."}, [18]={hint="Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.", tag="If it drops, Optional"}, [19]={npc="Magtoor", tgt="Magtoor", tag="If it drops, Optional"}, [20]={text="Northeast escort and Pool of Tears"}, [21]={npc="Galen Goodward", tgt="Galen Goodward"}, [22]={hint="Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", desc="Clear the cage and exit. Escort Galen and turn in at his strongbox at the end."}, [23]={npc="Galen's Strongbox", npcObj=true}, [24]={npc="Magtoor", tgt="Magtoor"}, [25]={npc="Karana", tgt="Karana"}, [26]={npc="Pelluk", tgt="Pelluk"}, [27]={hint="Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts."}, [28]={npc="Fel'zerul", tgt="Fel'zerul"}, [29]={npc="Fel'zerul", tgt="Fel'zerul", tag="Do with Sunken Temple, Optional"}, [30]={npc="Owen Thadd", tgt="Owen Thadd", tag="Optional", desc="Return to the Library once you have all the outdoor and dungeon materials."}, [31]={hint="Track down and collect the spellbook materials requested by the librarian.", tag="Optional", desc="Return to the Library once you have all the outdoor and dungeon materials."}, [32]={npc="Owen Thadd", tgt="Owen Thadd", tag="Optional", desc="Return to the Library once you have all the outdoor and dungeon materials."}, [33]={text="Fly from Stonard to Rog'mar in Riverglades. Joining midway without the flight path? Run there by road and unlock it on arrival."}}},
    ["03-28"] = {tips={{k="取捨", text="The north loop and Twilight's Shroud chain are optional. If you've done Twilight No More!, return to Bolder'ok. Turn in Clugfist's Decree, then pick up The Wayward Warrior at Rog'mar. Loot the smuggled goods on the first Powderfuse Port pirate loop. On the second, collect the kegs, kill the Bombardiers, and deliver the smuggler's package before sabotaging the ships. The sea monster is a cave detour. Do it only if short on XP and the NPC offers it."}, {k="提醒", text="Below level 45? Grind Eastsea Buccaneers and Musketeers along Eastwind Shore (around 84, 35-43). Restock by the port. At 40-45, run Krol'dok Stronghold with a group after taking Eye of Mugg and Tome of Twilight in Rog'mar.", s={{"Below level 45?"}, {"Grind Eastsea Buccaneers and Musketeers along Eastwind Shore (around 84, 35-43)"}, {"Restock by the port"}, {"At 40-45, run Krol'dok Stronghold with a group after taking Eye of Mugg and Tome of Twilight in Rog'mar"}}}, {k="交通", text="At level 45, take the neutral boat from Powderfuse Port (80.60, 54.60) to Steamwheedle Port (68.60, 23.00), then head to Gadgetzan. To stay in the Eastern Kingdoms, return to the Rog'mar flight path. If arriving from Tanaris, go overland to unlock it."}}, danger={[1]="Scoutmaster Vargas is elite. Wait for your group before approaching, and pull the nearby patrols separately.", [2]="Eastsea Musketeers can join from range. Pull pirates along the beach and clear the boarding path before sabotaging the ships."}, grind={[1]={mob="Eastsea Buccaneer", note="Dense normal mobs at Eastwind Shore north of Powderfuse Port. Pull singles along the beach among the musketeers. Pair with Unfriendly Competition."}, [2]={mob="Eastsea Musketeer", note="Dense normal ranged mobs in central Eastwind Shore among the pirates. Melee can use terrain to draw them ashore. Grind to 45."}}, supply={[1]={npc="Grakna"}, [2]={npc="Innkeeper Zizplink"}, [3]={npc="Mika Darby"}, [4]={npc="Innkeeper Zizplink"}, [5]={npc="Grizzek"}, [6]={npc="Krikshank"}}, steps={[1]={text="Take the north loop to Clugfist only after turning in Twilight No More! and taking Land of Giants. Return to Rog'mar with Clugfist's Decree before heading west to Twilight's Shroud. If skipping the chain, go east from Rog'mar to Powderfuse Port.", tag="Optional"}, [2]={npc="Clugfist", tgt="Clugfist", tag="Requires the northern prereq, Optional"}, [3]={npc="Clugfist", tgt="Clugfist", tag="Requires the northern prereq, Optional"}, [4]={hint="Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok.", tag="Requires the northern prereq, Optional, Target: Twilight Mauler/Twilight Firecaller"}, [5]={hint="Collect Skullthumper from Klunk for Clugfist in Bolder'ok.", tag="Requires the northern prereq, Optional, Target: Klunk"}, [6]={npc="Jom-jom", tgt="Jom-jom", tag="If passing by, Optional"}, [7]={hint="Escort Jom-jom to Clugfist at Bolder'ok.", tag="If passing by, Optional"}, [8]={npc="Clugfist", tgt="Clugfist", tag="If passing by, Optional"}, [9]={npc="Clugfist", tgt="Clugfist", tag="Requires the northern prereq, Optional"}, [10]={npc="Clugfist", tgt="Clugfist", tag="Requires the northern prereq, Optional"}, [11]={npc="Clugfist", tgt="Clugfist", tag="Requires the northern prereq, Optional"}, [12]={hint="Report to Krom'rosh in Rog'mar.", tag="Requires the northern prereq, Optional"}, [13]={npc="Krom'rosh", tgt="Krom'rosh", tag="Requires the northern prereq, Optional"}, [14]={text="Twilight camp west of Rog'mar"}, [15]={npc="Krom'rosh", tgt="Krom'rosh", tag="Optional"}, [16]={hint="Find Da'grosh in the hills west of Rog'mar.", tag="Optional"}, [17]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [18]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [19]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [20]={hint="Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Da'grosh.", tag="Target: Twilight Fanatic/Twilight Corrupter/Twilight Champion, Optional"}, [21]={hint="Rescue 5 Rog'mar Scouts within the Twilight's Shroud for Da'grosh.", tag="Target: Rog'mar Scout, Optional", desc="Loot five keys from Twilight cultists. Free five Rog'mar Scouts from their cages."}, [22]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [23]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [24]={npc="Da'grosh", tgt="Da'grosh", tag="Hard, Optional"}, [25]={hint="Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Da'grosh.", tag="Hard, Optional, Target: Overlord Kilgar"}, [26]={npc="Da'grosh", tgt="Da'grosh", tag="Hard, Optional"}, [27]={npc="Da'grosh", tgt="Da'grosh", tag="Optional"}, [28]={hint="Deliver the missive to Krom'rosh at Rog'mar.", tag="Optional"}, [29]={npc="Krom'rosh", tgt="Krom'rosh", tag="Optional"}, [30]={text="Optional group quest: Scoutmaster Vargas"}, [31]={npc="Wanted", npcObj=true, tag="Group, Optional, Unverified"}, [32]={hint="Bring the Scoutmaster's Eye to Neza Bloodsnout in Rog'mar.", tag="Group, Optional, Target: Scoutmaster Vargas / Scout Reynolds", desc="Group up for the elite scoutmaster. Bring the evidence back to Rog'mar."}, [33]={npc="Neza Bloodsnout", tgt="Neza Bloodsnout", tag="Group, Optional"}, [34]={text="South of Powderfuse Port → port pickups → Eastwind Shore"}, [35]={npc="Painted Hide", npcObj=true, tag="Optional", desc="Optional detour to the sea monster's cave near the keep. Accept if time allows."}, [36]={hint="Find someone at Powderfuse Port who can identify the monster from the painted hide.", tag="Optional"}, [37]={npc="Trapclaw", tgt="Argo Brinewhistle", tag="Optional"}, [38]={npc="Trapclaw", tgt="Argo Brinewhistle", tag="Optional", desc="Optional detour to the sea monster's cave near the keep. Accept if time allows."}, [39]={hint="Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades.", tag="Optional"}, [40]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz", tag="Optional"}, [41]={hint="Deliver the blade to Kreza Darkthorn's acquaintance at the docks east of Rog'mar."}, [42]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [43]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark", desc="Horde: take the Rog'mar sword chain. If Friz has no quest, start at the docks."}, [44]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [45]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [46]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [47]={npc="WANTED!", npcObj=true, tag="Unverified"}, [48]={hint="Kill 8 Murloc Oracles and 8 Murloc Warriors along the Eastwind Shore.", tag="Target: Murloc Warrior / Murloc Oracle"}, [49]={hint="Gather 12 Murloc Eyes and 6 pieces of Sand Crawler Meat for Fimbo Greasemitz.", tag="Target: Murloc Oracle / Murloc Tideskimmer / Murloc Raider / Sand Crawler / Shore Crawler"}, [50]={hint="Bring Trapclaw's Pincer to Fimbo Greasemitz.", tag="Target: Trapclaw"}, [51]={hint="Kill 10 Eastsea Buccaneers and 10 Eastsea Musketeers along the Eastwind Shore, north of Powderfuse Port.", tag="Target: Eastsea Buccaneer / Eastsea Musketeer"}, [52]={hint="Collect 8 Smuggled Goods for Friz Frazzlespark at Powderfuse Port."}, [53]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [54]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [55]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [56]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [57]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [58]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [59]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [60]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [61]={hint="Steal 5 Eastsea Powder Kegs for Wharfmaster Whizzbuzz."}, [62]={hint="Kill 8 Eastsea Raiders and 8 Eastsea Bombardiers for Wharfmaster Whizzbuzz."}, [63]={hint="Collect 15 Beast Entrails and 8 Rotflesh Mushrooms for Argo Brinewhistle.", tag="Optional", desc="First pin: adult boars. Second: cave entrance. Ogres inside."}, [64]={hint="Deliver The Friz Special to Captain Bentcoin in Eastwind Shore."}, [65]={npc="Captain Haynes", tgt="Captain Bentcoin"}, [66]={npc="Trapclaw", tgt="Argo Brinewhistle", tag="Optional"}, [67]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [68]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [69]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz", desc="Turn in the powder keg and Unchecked Expansion together, then take the ship quest."}, [70]={hint="Plant a remote explosive charge on each of the Eastsea's three boats.", desc="Bring the quest explosives and plant one charge on each of the three pirate ships. Pins mark shore mobs. Look by the second-deck cannons; exact charge spots unknown."}, [71]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [72]={npc="Trapclaw", tgt="Argo Brinewhistle", tag="Optional"}, [73]={hint="Use the Big Ball o' Bait to lure out the sea monster. Then, bring its head to Argo Brinewhistle.", tag="Target: Monstrous Threshadon, Optional", desc="Use the bait by the sunken wreck at Murloc Island. Kill the summon and loot its head."}, [74]={npc="Trapclaw", tgt="Argo Brinewhistle", tag="Optional"}, [75]={text="Optional dungeon: Krol'dok Stronghold"}, [76]={npc="Krom'rosh", tgt="Krom'rosh", tag="Group only, Optional"}, [77]={npc="Tran'gul", tgt="Tran'gul", tag="Group only, Optional"}, [78]={hint="Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise.", tag="Group only, Optional", desc="Krol'dok Stronghold entrance only. Overlord's coordinates inside are unknown."}, [79]={hint="Recover the Tome of Twilight from Krol'dok Stronghold.", tag="Group only, Optional", desc="Entrance pin only. Nar'gurk drops the book; his coordinates inside are unknown."}, [80]={npc="Krom'rosh", tgt="Krom'rosh", tag="Group only, Optional"}, [81]={npc="Tran'gul", tgt="Tran'gul", tag="Group only, Optional"}, [82]={npc="Fahrad", tgt="Fahrad", tag="Optional, Unverified", desc="Level 45 solo dungeon chain. Pick it up if you're passing through the manor."}, [83]={hint="Speak to Fahrad when you're ready to hear his plan.", tag="Optional, Unverified", desc="Level 45 solo dungeon chain. Pick it up if you're passing through the manor."}, [84]={npc="Fahrad", tgt="Fahrad", tag="Optional, Unverified", desc="Level 45 solo dungeon chain. Pick it up if you're passing through the manor."}, [85]={npc="Fahrad", tgt="Fahrad", tag="Optional, Unverified", desc="Requires 45; quest level 50. Run the dungeon after reaching Tanaris."}, [86]={hint="Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone.", tag="Optional, Unverified", desc="Requires 45; quest level 50. Run the dungeon after reaching Tanaris. The pin marks Zul'Farrak's entrance. Interior target coordinates are unknown."}, [87]={npc="Fahrad", tgt="Fahrad", tag="Optional, Unverified", desc="Requires 45; quest level 50. Run the dungeon after reaching Tanaris."}, [88]={hint="Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Prate Cloudseer in Thousand Needles.", tag="Optional", desc="Fire Badlands / Earth Swamp / Air Desolace / Water Dustwallow. Turn in: Thousand Needles."}, [89]={npc="Prate Cloudseer", tgt="Prate Cloudseer", tag="Optional", desc="Fire: Badlands. Earth: Swamp. Air: Desolace. Water: Dustwallow. Check log for turn-in."}, [90]={npc="Rau Cliffrunner", tgt="Rau Cliffrunner", tag="Optional", desc="Finish all four Twisted Totems. Watch for quilboar after triggering the steam pools."}, [91]={hint="Use the Twisted Totems to put an end to the quilboar ritual.", tag="Optional, Target: Ravaging Tempest", desc="Finish all four Twisted Totems. Watch for quilboar after triggering the steam pools."}, [92]={npc="Rau Cliffrunner", tgt="Rau Cliffrunner", tag="Optional", desc="Finish all four Twisted Totems. Watch for quilboar after triggering the steam pools."}, [93]={npc="Rau Cliffrunner", tgt="Rau Cliffrunner", tag="Optional, Unverified", desc="Finish Heed My Call at Freewind Post first.", star={"Rage of the Storm / Lightning's Grasp / Tidebringer's Claw"}}, [94]={hint="Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", tag="Optional, Unverified", desc="Finish Heed My Call at Freewind Post first."}, [95]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional, Unverified", desc="Finish Heed My Call at Freewind Post first.", star={"Rage of the Storm / Lightning's Grasp / Tidebringer's Claw"}}}},
    ["05-d19"] = {name="Krol'dok Stronghold", entrance="Riverglades 48.60, 26.30", pickup="At Rog'mar, do Tran'gul's Sunnyglade and Clubtoe quests, then the Bolder'ok prerequisites. Go west from Rog'mar to the Twilight camp and find Da'grosh and Crag'rog. Turn in the letter at Rog'mar to unlock the eye and tome quests. Fly to Rog'mar or walk from Kargath, then find the portal on the heights north of Sunnyglade. Bring 4 Thick Leather and 12 Iron Bars for the mold follow-up.", pickupS={{"At Rog'mar, do Tran'gul's Sunnyglade and Clubtoe quests, then the Bolder'ok prerequisites"}, {"Go west from Rog'mar to the Twilight camp and find Da'grosh and Crag'rog"}, {"Turn in the letter at Rog'mar to unlock the eye and tome quests"}, {"Fly to Rog'mar or walk from Kargath, then find the portal on the heights north of Sunnyglade"}, {"Bring 4 Thick Leather and 12 Iron Bars for the mold follow-up"}}, tips={{k="動線", text="Mine: Slavecrusher Grox → Twilight Commander Zarmok → mold in Ashka's smithy → Nar'gurk for Tome of Twilight → Bossman Toof at the bridge → Overlord Mugg for Eye of Mugg. Loot cultist ears along the way."}, {k="取捨", text="Finish the Rog'mar, Bolder'ok, and Powderfuse Port prerequisites before grouping so you can do all three on one run. Bring the mold materials and turn them in if the mold drops."}, {k="說明", text="The entrance is north of Sunnyglade, with another portal by the stronghold gate. Use the DungeonsForever entrance pin. The early Wowhead Riverglades overview marks a different spot. Alliance quests such as the 94800 chain are outside this route.", s={{"The entrance is north of Sunnyglade, with another portal by the stronghold gate"}, {"Use the DungeonsForever entrance pin"}, {"The early Wowhead Riverglades overview marks a different spot"}, {"Alliance quests such as the 94800 chain are outside this route"}}}}, steps={[1]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [2]={hint="Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success.", tag="Dungeon prereq"}, [3]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [4]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [5]={hint="Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh.", tag="Dungeon prereq"}, [6]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [7]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [8]={hint="Slay 8 Farholde Priests and 12 Farholde Scouts south of the river.", tag="Dungeon prereq"}, [9]={npc="Krom'rosh", tgt="Krom'rosh", tag="Dungeon prereq"}, [10]={npc="Tran'gul", tgt="Tran'gul"}, [11]={npc="Tran'gul", tgt="Tran'gul"}, [12]={hint="Defeat 8 Twilight Raiders and 8 Twilight Neophytes within Sunnyglade for Tran'gul in Rog'mar.", tag="Target: Twilight Raider/Twilight Shadowmancer/Twilight Neophyte"}, [13]={hint="Retrieve 3 Twilight Missives from Twilight Shadowmancers in Sunnyglade for Tran'gul in Rog'mar.", tag="Target: Twilight Shadowmancer"}, [14]={npc="Tran'gul", tgt="Tran'gul"}, [15]={npc="Tran'gul", tgt="Tran'gul"}, [16]={npc="Tran'gul", tgt="Tran'gul", preText="Encroaching Twilight, Twilight Missives"}, [17]={hint="Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."}, [18]={npc="Clubtoe", tgt="Clubtoe"}, [19]={npc="Clubtoe", tgt="Clubtoe", preText="Digging for Answers"}, [20]={hint="Find missing ogres in the caves beneath Sunnyglade for Clubtoe."}, [21]={npc="Empowered Brute", tgt="Twilight Brute"}, [22]={npc="Empowered Brute", tgt="Twilight Brute", preText="The Purple Ones"}, [23]={npc="Clubtoe", tgt="Clubtoe", preText="The Purple Ones"}, [24]={hint="Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade.", tag="Target: Empowered Brute/Twilight Ritualist"}, [25]={hint="Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade.", desc="QuestieDB has no separate pin for the ritual circle. Check along the cave."}, [26]={npc="Clubtoe", tgt="Clubtoe"}, [27]={npc="Clubtoe", tgt="Clubtoe"}, [28]={npc="Clubtoe", tgt="Clubtoe", desc="Elite. Ask your group to help.", preText="The Purple Ones, Sickening Lights"}, [29]={hint="Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe.", tag="Target: Chogg'Zac", desc="Elite. Ask your group to help."}, [30]={npc="Clubtoe", tgt="Clubtoe", desc="Elite. Ask your group to help."}, [31]={npc="Clubtoe", tgt="Clubtoe", preText="Twilight No More!"}, [32]={hint="Deliver the head of Chogg to Tran'gul in Rog'mar."}, [33]={npc="Tran'gul", tgt="Tran'gul"}, [34]={npc="Tran'gul", tgt="Tran'gul", preText="Spread the Word"}, [35]={hint="Deliver Chogg's head to the ogre city to the north."}, [36]={npc="Clugfist", tgt="Clugfist"}, [37]={npc="Clugfist", tgt="Clugfist", preText="Land of Giants"}, [38]={hint="Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok.", tag="Target: Twilight Mauler/Twilight Firecaller"}, [39]={npc="Clugfist", tgt="Clugfist"}, [40]={npc="Clugfist", tgt="Clugfist", preText="Land of Giants"}, [41]={hint="Collect Skullthumper from Klunk for Clugfist in Bolder'ok.", tag="Target: Klunk"}, [42]={npc="Clugfist", tgt="Clugfist"}, [43]={npc="Clugfist", tgt="Clugfist", preText="Unworthy Champion"}, [44]={hint="Report to Krom'rosh in Rog'mar."}, [45]={npc="Krom'rosh", tgt="Krom'rosh"}, [46]={npc="Krom'rosh", tgt="Krom'rosh", preText="Clugfist's Decree"}, [47]={hint="Find Da'grosh in the hills west of Rog'mar."}, [48]={npc="Da'grosh", tgt="Da'grosh"}, [49]={npc="Da'grosh", tgt="Da'grosh", preText="The Wayward Warrior"}, [50]={npc="Da'grosh", tgt="Da'grosh", preText="The Wayward Warrior"}, [51]={npc="Da'grosh", tgt="Da'grosh", tag="Optional", preText="The Wayward Warrior"}, [52]={hint="Look for the Bolder'ok ogre in the nearby cave.", tag="Optional"}, [53]={npc="Ogre Miner", tgt="Crag'rog", tag="Optional"}, [54]={npc="Ogre Miner", tgt="Crag'rog", tag="Optional", desc="Accept from Crag'rog in Twilight's Shroud.", preText="Rumblings of Discontent"}, [55]={hint="Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Da'grosh.", tag="Target: Twilight Fanatic/Twilight Corrupter/Twilight Champion"}, [56]={hint="Rescue 5 Rog'mar Scouts within the Twilight's Shroud for Da'grosh.", tag="Target: Rog'mar Scout"}, [57]={hint="Recruit 5 Ogre Miners.", tag="Optional", desc="The three miner pins are verified. Other locations are unknown."}, [58]={npc="Ogre Miner", tgt="Crag'rog", tag="Optional"}, [59]={npc="Da'grosh", tgt="Da'grosh"}, [60]={npc="Da'grosh", tgt="Da'grosh"}, [61]={npc="Da'grosh", tgt="Da'grosh", desc="If still unavailable after Carving a Path and Break Their Chains, do Klarg's lead.", preText="Carving a Path, Break Their Chains"}, [62]={hint="Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Da'grosh.", tag="Target: Overlord Kilgar"}, [63]={npc="Da'grosh", tgt="Da'grosh"}, [64]={npc="Da'grosh", tgt="Da'grosh", desc="Turn in Overlord Kilgar's head to unlock this from Da'grosh.", preText="Bring Me His Head"}, [65]={npc="Da'grosh", tgt="Da'grosh", preText="Bring Me His Head"}, [66]={hint="Deliver the missive to Krom'rosh at Rog'mar."}, [67]={npc="Krom'rosh", tgt="Krom'rosh"}, [68]={npc="Krom'rosh", tgt="Krom'rosh", preText="It Is Time, Brother..."}, [69]={npc="Tran'gul", tgt="Tran'gul", preText="It Is Time, Brother..."}, [70]={text="Krol'dok Stronghold entrance"}, [71]={hint="Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold.", desc="Clear cultists near Zarmok first, then check your count. Dungeon map: Zarmok (39.10, 69.40) is one source of the ears. Location: Clear around Zarmok after the mine. Loot more ears in the stronghold passages."}, [72]={npc="Krol'dok Moulding", npcObj=true, tag="Optional, Unverified", desc="Loot the mold from Tunk and right-click it to start the quest. Find Tunk in the smithy by War Handler Ashka. Loot and right-click the mold."}, [73]={hint="Recover the Tome of Twilight from Krol'dok Stronghold.", desc="Dungeon map: Nar'gurk (34.70, 50.30). Location: Pass Ashka and look for Nar'gurk in the Twilight caster area."}, [74]={hint="Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise.", desc="Dungeon map: Mugg (71.00, 14.30). Location: Cross Bossman Toof's bridge. Kill Overlord Mugg in the last room."}, [75]={npc="Krom'rosh", tgt="Krom'rosh"}, [76]={npc="Tran'gul", tgt="Tran'gul"}, [77]={hint="Find someone in Rog'mar who may know about the mould.", tag="Optional"}, [78]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Optional"}, [79]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Optional", desc="Buy the materials ahead of time at the Auction House.", preText="Krol'dok Moulding"}, [80]={hint="Bring 4 Thick Leather and 12 Iron Bar to Kreza Darkthorn.", tag="Optional", desc="Buy the materials ahead of time at the Auction House."}, [81]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Optional", desc="Buy the materials ahead of time at the Auction House."}, [82]={npc="Da'grosh", tgt="Da'grosh", desc="From Rog'mar, head west back to Da'grosh."}}},
    ["04-29"] = {name="Tanaris: Steamwheedle Port & Gadgetzan", short="Steamwheedle Port +", tips={{k="取捨", text="Do the pirate hats, kills, bounty, and crates together on the first Steamwheedle Port visit. TUGs does Feralas first and returns for the pirates. Take the boat from Powderfuse Port and clear the coast now to keep the video's stop order."}, {k="取捨", text="Save Screecher Spirits for Camp Mojache, Dunemaul Dues for the Dunemaul Compound, and Deliver to MacKinley for the Booty Bay turn-in on the way to Swamp of Sorrows."}, {k="提醒", text="Need XP for the next stop? Grind normal mobs at the Wastewander camp (59.40, 24.71) or Lost Rigger Cove entrance (70.90, 42.48). Bring Scarab Shells, Divino-matic Rod, and Troll Temper if you have a Zul'Farrak group, then turn in on the Gadgetzan and Dunemaul leg.", s={{"Need XP for the next stop?"}, {"Grind normal mobs at the Wastewander camp (59.40, 24.71) or Lost Rigger Cove entrance (70.90, 42.48)"}, {"Bring Scarab Shells, Divino-matic Rod, and Troll Temper if you have a Zul'Farrak group, then turn in on the Gadgetzan and Dunemaul leg"}}}}, danger={[1]="Caliph patrols and may have guards. Clear the nearby Wastewander Bandits and pull him when he reaches open ground."}, grind={[1]={mob="Southsea Pirate", note="Dense normal mobs at the Lost Rigger Cove entrance. Other players may be doing pirate quests. Clear toward the beach along the edge and collect their drops."}, [2]={mob="Southsea Swashbuckler", note="Normal mobs outside the docks. Switch here if the pirate entrance is busy. Pull from the edge to avoid the dock guards."}}, supply={[1]={npc="Bulkrek Ragefist"}, [2]={npc="Innkeeper Fizzgrimble"}, [3]={npc="Wrinkle Goodsteel"}, [4]={npc="Innkeeper Fizzgrimble"}, [5]={npc="Blizrik Buckshot"}, [6]={npc="Gikkix"}}, steps={[1]={text="Board the boat at Powderfuse Port in Riverglades (80.60, 54.60) and get off at Steamwheedle Port in Tanaris (68.60, 23.00). Fly from Orgrimmar if Gadgetzan is unlocked. On your first visit, you can also run from Freewind Post through the Shimmering Flats and down the south ramp to Gadgetzan."}, [2]={text="Pick up at the port, then resupply in town"}, [3]={npc="Haughty Modiste", tgt="Haughty Modiste"}, [4]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [5]={npc="Wanted Poster", npcObj=true}, [6]={npc="Wanted Poster", npcObj=true}, [7]={npc="Stoley", tgt="Stoley"}, [8]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Do in Feralas. Turn in at Steamwheedle Port during the Tanaris visit."}, [9]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle", tag="Optional", desc="Do at Dunemaul Compound. Turn in at Steamwheedle Port."}, [10]={text="Follow the road west to Gadgetzan. Learn the Horde flight path from Bulkrek Ragefist (51.60, 25.44) and set your hearth with Innkeeper Fizzgrimble (52.51, 27.91). Rebind in Camp Mojache later."}, [11]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [12]={npc="Spigot Operator Luglunket", tgt="Spigot Operator Luglunket"}, [13]={npc="Tran'rek", tgt="Tran'rek", tag="Optional", desc="Pick up only if running Zul'Farrak."}, [14]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle", tag="Optional", desc="Loot this during the stair event in Zul'Farrak.", star={"Masons Fraternity Ring", {"ROGUE", "HUNTER", "DRUID"}}}, [15]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer", tag="Optional", desc="Pick up only if running Zul'Farrak."}, [16]={text="Wastewander camps and Lost Rigger Cove"}, [17]={hint="Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle."}, [18]={hint="Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan."}, [19]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [20]={npc="Spigot Operator Luglunket", tgt="Spigot Operator Luglunket"}, [21]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [22]={hint="Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.", desc="Enter the Wastewander camp southeast of Gadgetzan."}, [23]={hint="Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", desc="He may have an escort. Wait until he reaches the edge of camp before pulling."}, [24]={hint="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers."}, [25]={hint="Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", desc="Loot every kill while doing Southsea Shakedown."}, [26]={hint="Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port."}, [27]={hint="Bring Stoley's Shipment to Stoley in Steamwheedle Port."}, [28]={npc="Ship Schedule", npcObj=true, tag="Optional", desc="Loot a pirate's footlocker, then right-click the schedule inside to start the quest."}, [29]={hint="Report the Ship Schedules to an authority in Steamwheedle Port.", tag="Optional"}, [30]={text="Follow the coast north to Steamwheedle Port and turn in the pirate and cargo quests together."}, [31]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [32]={npc="Haughty Modiste", tgt="Haughty Modiste"}, [33]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [34]={npc="Stoley", tgt="Stoley"}, [35]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle", tag="Optional"}, [36]={npc="Stoley", tgt="Stoley", desc="Save for the Stonard/Eastwind Shore leg. Turn in at Booty Bay."}, [37]={text="Return to Gadgetzan for the second Wastewander batch and the wanted quests. Hearth if bound there."}, [38]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [39]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}}},
    ["04-30"] = {name="Feralas: Camp Mojache", tips={{k="取捨", text="Follow the Woodpaw gnoll chain through The Battle Plans to unlock the two overlapping Zukk'ash quests southeast of Camp Mojache."}, {k="取捨", text="Keep the OOX-22/FE Distress Beacon if it drops. Save the escort, coastal giants, and water elementals for your Camp Mojache return."}, {k="提醒", text="Below level 47? Grind yetis in Feral Scar Vale (55.29, 53.76) or Gordunni ogres north of Camp Mojache (75.13, 34.86), then return to camp to turn in.", s={{"Below level 47?"}, {"Grind yetis in Feral Scar Vale (55.29, 53.76) or Gordunni ogres north of Camp Mojache (75.13, 34.86), then return to camp to turn in"}}}}, danger={[1]="The Gordunni camp north of Camp Mojache has both casters and brutes. Clear your exit before digging for cobalt and stay out of the back of the camp."}, grind={[1]={mob="Feral Scar Yeti", note="Normal yetis cluster on the outer slopes of Feral Scar Vale. Loop the slope for yeti hides if questers are at the cave entrance."}, [2]={mob="Hulking Feral Scar", note="Slightly higher-level normal yetis southwest of Feral Scar Vale. Pull melee mobs from outside and avoid the crowded cave mouth."}}, supply={[1]={npc="Shyn"}, [2]={npc="Innkeeper Greul"}, [3]={npc="Cawind Trueaim"}, [4]={npc="Innkeeper Greul"}, [5]={npc="Cawind Trueaim"}, [6]={npc="Tarhus"}}, steps={[1]={text="Fly from Gadgetzan to Camp Mojache if unlocked. On a first visit, head north into the Shimmering Flats and take the west road through Thousand Needles into Feralas.", tag="Flight path locked. Travel there on foot the first time."}, [2]={node="Camp Mojache", desc="Unlock the flight path with Shyn."}, [3]={text="Set your hearth with Innkeeper Greul (74.80, 45.18)."}, [4]={npc="Krueg Skullsplitter", tgt="Krueg Skullsplitter"}, [5]={npc="Orwin Gizzmick", tgt="Orwin Gizzmick"}, [6]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [7]={npc="Jangdor Swiftstrider", tgt="Jangdor Swiftstrider"}, [8]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [9]={npc="Rok Orhan", tgt="Rok Orhan"}, [10]={text="Around camp and first Gordunni quests to the north"}, [11]={hint="Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache."}, [12]={hint="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes."}, [13]={hint="Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", desc="Use the quest shovel next to the blue mound at Gordunni Camp."}, [14]={npc="Gordunni Scroll", npcObj=true, desc="Click the Gordunni Scroll on the ground at the north end."}, [15]={hint="Bring the Gordunni Scroll to Rok Orhan in Camp Mojache."}, [16]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [17]={npc="Rok Orhan", tgt="Rok Orhan"}, [18]={npc="Orwin Gizzmick", tgt="Orwin Gizzmick"}, [19]={npc="Rok Orhan", tgt="Rok Orhan"}, [20]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [21]={npc="Rok Orhan", tgt="Rok Orhan"}, [22]={npc="Rok Orhan", tgt="Rok Orhan"}, [23]={hint="Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", desc="One-hour timer. Kill five in Woodpaw Hills to the south, then return immediately."}, [24]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [25]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [26]={hint="Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache."}, [27]={npc="Woodpaw Battle Map", npcObj=true}, [28]={npc="Woodpaw Battle Map", npcObj=true}, [29]={hint="Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache."}, [30]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [31]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [32]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [33]={text="Faerie dragons in the middle, then west to Feral Scar Vale"}, [34]={hint="Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache."}, [35]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", desc="Turn in at Steamwheedle Port after the Gadgetzan/Dunemaul Compound leg."}, [36]={hint="Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", desc="Kill Rage Scar Yetis in and around the cave for Thick Yeti Hide."}, [37]={text="After Feral Scar Vale, hearth to Camp Mojache and turn in together."}, [38]={npc="Krueg Skullsplitter", tgt="Krueg Skullsplitter"}, [39]={npc="Jangdor Swiftstrider", tgt="Jangdor Swiftstrider"}, [40]={npc="Krueg Skullsplitter", tgt="Krueg Skullsplitter"}, [41]={npc="Jangdor Swiftstrider", tgt="Jangdor Swiftstrider"}, [42]={hint="Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", desc="Get the horns at the Grimtotem camp northwest of Camp Mojache, then return."}, [43]={npc="Krueg Skullsplitter", tgt="Krueg Skullsplitter"}, [44]={npc="Krueg Skullsplitter", tgt="Krueg Skullsplitter"}, [45]={text="Stop in Orgrimmar for the Feralas follow-up en route to Swamp of Sorrows"}, [46]={text="Fly from Camp Mojache to Orgrimmar, usually via Camp Taurajo or other unlocked stops. Keep your Camp Mojache hearth for after the eastern Swamp of Sorrows loop."}, [47]={hint="Take the Shrunken Head to Neeru Fireblade in Orgrimmar."}, [48]={hint="Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar."}, [49]={npc="Neeru Fireblade", tgt="Neeru Fireblade"}, [50]={npc="Belgrom Rockmaul", tgt="Belgrom Rockmaul"}, [51]={npc="Neeru Fireblade", tgt="Neeru Fireblade", desc="Save for the Rage Scar Hold leg. Turn in at Camp Mojache."}}},
    ["04-31"] = {name="Swamp of Sorrows: Stonard", short="Stonard", tips={{k="取捨", text="The northern Lost Ones and escort are already done. This time, stick to the coast. Turn in Lack of Surplus and Lack of Surplus to unlock the murloc chain. Collect crab legs on the way out and turn them in on the way back."}, {k="提醒", text="Running Sunken Temple? Start with The Atal'ai Exile from Stonard. It turns in in the Hinterlands, so save it for the Revantusk Village and Jintha'Alor leg. Below level 47, grind normal giant crabs near Eastwind Shore (91.00, 70.80). Near level 49, grind the higher-level Rage Scar Yetis at the next stop.", s={{"Running Sunken Temple?"}, {"Start with The Atal'ai Exile from Stonard"}, {"It turns in in the Hinterlands, so save it for the Revantusk Village and Jintha'Alor leg"}, {"Below level 47, grind normal giant crabs near Eastwind Shore (91.00, 70.80)"}, {"Near level 49, grind the higher-level Rage Scar Yetis at the next stop"}}}}, danger={[1]="Murlocs stand close together on Eastwind Shore, and Ink Sprayers and Oracles can add from behind. Pull singles from shore and don't chase into the water."}, grind={[1]={mob="Monstrous Crawler", note="Dense normal crabs along the eastern Swamp of Sorrows coast. Skin them as you go. Best on arrival or for a small XP top-up alongside coastal quests."}, [2]={mob="Elder Rage Scar", note="If you're near 49, wait until Feralas. Normal yetis at Rage Scar Hold are a better level. Pull singles on the outer slopes and avoid the busy cave entrance."}}, supply={[1]={npc="Breyk"}, [2]={npc="Innkeeper Karakul"}, [3]={npc="Gharash"}, [4]={npc="Thultash"}, [5]={npc="Thultazor"}}, steps={[1]={text="Fly from Orgrimmar to Ratchet and take the boat to Booty Bay. Keep your Camp Mojache hearth."}, [2]={text="Booty Bay turn-ins along the way"}, [3]={hint="Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay."}, [4]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [5]={npc="Krazek", tgt="Krazek", tag="Optional", desc="Turn in at Stonard only once you have all the Dream Dust."}, [6]={npc="Whiskey Slim", tgt="Whiskey Slim", desc="Pick up the grog on the Hinterlands coast. Turn in when you revisit Booty Bay."}, [7]={text="Stonard to the southeast coast"}, [8]={text="Fly from Booty Bay to Stonard. If locked, run north through Stranglethorn Vale, then along eastern Duskwood and through Deadwind Pass. Learn the flight path from Breyk (46.07, 54.83)."}, [9]={npc="Dar", tgt="Dar"}, [10]={npc="Dar", tgt="Dar"}, [11]={hint="Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.", desc="Kill Saltjaw Crocolisks southwest of the Pool of Tears. Check the shore for more."}, [12]={hint="Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.", desc="Kill crabs along the northern coast. Collect ten legs before heading south."}, [13]={npc="Tok'Kar", tgt="Tok'Kar"}, [14]={npc="Tok'Kar", tgt="Tok'Kar"}, [15]={hint="Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows."}, [16]={npc="Tok'Kar", tgt="Tok'Kar"}, [17]={npc="Tok'Kar", tgt="Tok'Kar"}, [18]={hint="Speak to Katar in the Swamp of Sorrows."}, [19]={npc="Katar", tgt="Katar"}, [20]={npc="Katar", tgt="Katar", desc="Kill ten of each of the three murloc types on the southeast beach. Return to Katar."}, [21]={hint="Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.", desc="Kill ten of each of the three murloc types on the southeast beach. Return to Katar."}, [22]={npc="Katar", tgt="Katar", desc="Kill ten of each of the three murloc types on the southeast beach. Return to Katar."}, [23]={npc="Katar", tgt="Katar"}, [24]={hint="Speak with Tok'Kar in the Swamp of Sorrows."}, [25]={npc="Tok'Kar", tgt="Tok'Kar"}, [26]={npc="Katar", tgt="Katar", desc="After 1427, see Katar. Find Oracles farther north. Check all three kill counts."}, [27]={hint="Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.", desc="After 1427, see Katar. Find Oracles farther north. Check all three kill counts."}, [28]={npc="Katar", tgt="Katar", desc="After 1427, see Katar. Find Oracles farther north. Check all three kill counts."}, [29]={text="Retrace your route west to Stonard and turn the crab legs in to Dar."}, [30]={npc="Dar", tgt="Dar"}, [31]={text="Hearth to Camp Mojache after the turn-in. Otherwise fly to Booty Bay, take the Ratchet boat and fly to Camp Mojache."}}},
    ["04-32"] = {name="Feralas: Camp Mojache & Dire Maul", short="Feralas: Camp Mojache +", tips={{k="取捨", text="Rage Scar Yetis and the Feral Scar Vale yetis are separate objectives. Turn in The Mark of Quality at Camp Mojache, then do Improved Quality. Turn in Perfect Yeti Hide only if the item drops."}, {k="取捨", text="Hearth back after the murloc chain to save a crossing. Collect the owlbeast essence for Testing the Vessel on the Hinterlands leg. Save Hippogryph Muisek-Weapons of Spirit for Camp Mojache."}, {k="提醒", text="The video returns to Feralas near level 49. If short on XP, grind Rage Scar Yetis on the outer loop from 55.73, 33.05 to 54.39, 33.10. Pull singles.", s={{"The video returns to Feralas near level 49"}, {"If short on XP, grind Rage Scar Yetis on the outer loop from 55.73, 33.05 to 54.39, 33.10"}, {"Pull singles"}}}}, danger={[1]="The yeti cave entrance is narrow. Elder Rage Scar Yetis can pull with the mobs at the mouth. Clear outside before entering."}, grind={[1]={mob="Rage Scar Yeti", note="Normal yetis on the outer slopes of Rage Scar Hold. Loop the slope for yeti hides if the cave is busy."}, [2]={mob="Elder Rage Scar", note="Higher-level normal yetis in the same camp. Mix them in to reach 49. Clear by the entrance first to avoid double pulls in the narrow cave."}}, supply={[1]={npc="Shyn"}, [2]={npc="Innkeeper Greul"}, [3]={npc="Cawind Trueaim"}, [4]={npc="Innkeeper Greul"}, [5]={npc="Cawind Trueaim"}, [6]={npc="Tarhus"}}, steps={[1]={hint="Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas."}, [2]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [3]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", desc="Use the container on Hinterlands owlbeast corpses. Turn in at Camp Mojache."}, [4]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", tag="Optional", desc="Save Natural Materials as you go. Finish collecting and turn in at Camp Mojache."}, [5]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", desc="Turn in to Marvon at the Broken Pillar in Tanaris."}, [6]={npc="Talo Thornhoof", tgt="Talo Thornhoof", desc="Save for Felwood's bears and maulers. Turn in at Camp Mojache on the next visit."}, [7]={hint="Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas."}, [8]={hint="Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas."}, [9]={hint="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers."}, [10]={hint="Rok Orhan in Camp Mojache wants you to find a Gordunni Orb."}, [11]={text="Follow the road back to Camp Mojache for The Ogres of Feralas and The Zukk'ash Infestation. Save the northern yetis for the next loop."}, [12]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [13]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider"}, [14]={npc="Rok Orhan", tgt="Rok Orhan"}, [15]={npc="Rok Orhan", tgt="Rok Orhan"}, [16]={npc="Hadoken Swiftstrider", tgt="Hadoken Swiftstrider", desc="Turn in with the other quests when you pass Orgrimmar on the Tanaris leg."}, [17]={npc="Rok Orhan", tgt="Rok Orhan", desc="Save for the Orgrimmar turn-in on the Tanaris leg."}, [18]={text="Rage Scar yetis and the return trip"}, [19]={hint="Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.", desc="Follow the road west to Rage Scar Hold (55.73, 33.05). Collect ten pelts."}, [20]={npc="Perfect Yeti Hide", npcObj=true, tag="Optional", desc="Accept only if a Rage Scar Yeti drops the Pristine Yeti Hide."}, [21]={hint="Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas.", tag="Optional"}, [22]={text="Hearth to Camp Mojache when the yetis are done, or take the main road back. Turn in and fly to Gadgetzan."}, [23]={npc="Jangdor Swiftstrider", tgt="Jangdor Swiftstrider"}, [24]={npc="Jangdor Swiftstrider", tgt="Jangdor Swiftstrider", tag="Optional"}}},
    ["05-d20"] = {name="Maraudon", entrance="Desolace 29.10, 62.50", pickup="At level 39, take Shadowshard Fragments from Uthel'nay in Orgrimmar before Shadowprey Village. From Camp Mojache, head to Shadowprey Village and see Warug and Selendra, then visit Willow and the Centaur Pariah. For the Forever water-vial chain, do the crystal-tower and Magister lead-ins in southeast Shen'dralas, then take Word of the Woods → Rot and Regret at the Forgotten Gardens. Wowhead lists level 35 for the Shen'dralas quests. Pick up from Cavindra before the orange portal.", pickupS={{"At level 39, take Shadowshard Fragments from Uthel'nay in Orgrimmar before Shadowprey Village"}, {"From Camp Mojache, head to Shadowprey Village and see Warug and Selendra, then visit Willow and the Centaur Pariah"}, {"For the Forever water-vial chain, do the crystal-tower and Magister lead-ins in southeast Shen'dralas, then take Word of the Woods → Rot and Regret at the Forgotten Gardens"}, {"Wowhead lists level 35 for the Shen'dralas quests"}, {"Pick up from Cavindra before the orange portal"}}, tips={{k="動線", text="Orange: Noxxion and Razorlash. Purple: Lord Vyletongue. Collect statues, khan gems and other quest loot → Celebras at the junction, then follow his scepter ritual → Earth Song Falls → the Princess → Rotgrip's pool if needed."}, {k="取捨", text="Do both orange and purple wings to get the scepter on your first run. If you only want the princess and crocodile, use a party member's scepter to enter the inner wing. Skip the shortcut if you need the shadow mobs outside or objectives in another wing."}, {k="說明", text="The outer cave is at 29.10, 62.50. Follow the orange or purple tunnel to its portal. Exact world coordinates for the separate portals are unverified. Both routes meet by the poison waterfall.", s={{"The outer cave is at 29.10, 62.50"}, {"Follow the orange or purple tunnel to its portal"}, {"Exact world coordinates for the separate portals are unverified"}, {"Both routes meet by the poison waterfall"}}}}, steps={[1]={npc="Uthel'nay", tgt="Uthel'nay"}, [2]={npc="Vark Battlescar", tgt="Vark Battlescar"}, [3]={npc="Selendra", tgt="Selendra"}, [4]={npc="Willow", tgt="Willow"}, [5]={npc="Centaur Pariah", tgt="Centaur Pariah", desc="Centaur Pariah patrols southern Desolace. The pin marks one spot on his route."}, [6]={npc="Shen'dralar Pylon", npcObj=true, tag="Optional", desc="Pin marks the Temple Crystal Tower. Other tower coordinates are unknown."}, [7]={hint="Explore Shen'dralas in an effort to find other pylons like the one you found.", tag="Optional", desc="Pin marks the Temple Crystal Tower. Other tower coordinates are unknown."}, [8]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Pin marks the Temple Crystal Tower. Other tower coordinates are unknown."}, [9]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Strange Pylons"}, [10]={hint="Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade.", tag="Optional", desc="Pins mark the two items in the Magram and Gelkis centaur villages, in that order."}, [11]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [12]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Check the quest log for the amount of mana you need.", preText="Fragments of the Pylons"}, [13]={hint="Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals. Once you have acquired enough mana, empower the pylons and return to Mordent Evenshade.", tag="Optional, Unverified", desc="Check the quest log for the amount of mana you need. Get the sieve up top. Loot 4 mana per tower (8 total). Both work in Stealth."}, [14]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Check the quest log for the amount of mana you need."}, [15]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional, Unverified", preText="Powering the Pylons"}, [16]={hint="Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired.", tag="Optional, Unverified"}, [17]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional, Unverified"}, [18]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional, Unverified", preText="A Brief History Lesson"}, [19]={hint="Locate Magister Kirandis inside the temple of Shen'dralas.", tag="Optional, Unverified"}, [20]={npc="Magister Kirandis", tgt="Magister Kirandis", tag="Optional, Unverified"}, [21]={npc="Mithera", tgt="Mithera", tag="Dungeon prereq"}, [22]={npc="Mithera", tgt="Mithera", tag="Dungeon prereq"}, [23]={npc="Mithera", tgt="Mithera", tag="Optional, Unverified", preText="Meeting the Magister"}, [24]={hint="Find Woodwyrd in the Forlorn Gardens at Shen'dralas in the Desolace.", tag="Optional, Unverified"}, [25]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional, Unverified"}, [26]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional, Unverified", desc="Turn in Word of the Woods first. Bring this into inner Maraudon.", preText="Word of the Woods"}, [27]={npc="Cavindra", tgt="Cavindra", desc="Cavindra is outside the orange portal. Loot one item from each side's boss."}, [28]={hint="Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."}, [29]={text="Maraudon entrance"}, [30]={text="Orange side: Foulspore Cavern (45-53). Look for orange crystals and the pool deep in the cave. Fill the vial before entering the portal."}, [31]={hint="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.", desc="Location: Fill the vial at the pool outside the orange portal. Find vines inside."}, [32]={text="Purple side: Wicked Grotto (45-53). Take the purple crystal passage at the three-way fork. Loot the diamond from Lord Vyletongue."}, [33]={hint="Collect 15 Theradric Crystal Carvings for Willow in Desolace.", desc="QuestieDB says 15; older guides may list 25. Follow your quest log. Location: Kill centaurs outside both portals and loot statues as you go."}, [34]={hint="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", desc="Three khans patrol by the fork and outer tunnels. One is inside each portal. Location: Find three khans at the fork and outer caves, then one inside each portal."}, [35]={hint="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.", desc="Map: Noxxion 34.80,10.70; Vyletongue 37.70,69.40; Celebras 24.50,14.40. Location: Get the rod on orange and the diamond on purple. Kill Celebras where they meet. Order: Take both orange and purple paths. Turn in once you have all the materials."}, [36]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", tag="Unverified", desc="Talk to Celebras the Redeemed after defeating the boss. After killing Celebras (24.50, 14.40), turn in to the Redeemed in the same room."}, [37]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", tag="Unverified", desc="Celebras's room (24.50, 14.40): follow the Redeemed through the ritual.", preText="Legends of Maraudon"}, [38]={hint="Assist Celebras the Redeemed while he creates the Scepter of Celebras.", desc="Celebras's room (24.50, 14.40): follow the Redeemed through the ritual. Location: Follow Celebras the Redeemed through the ritual in his boss room."}, [39]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", tag="Unverified", desc="Celebras's room (24.50, 14.40): follow the Redeemed through the ritual."}, [40]={text="Inner route: Earth Song Falls (48-57). Descend from the orange/purple junction or have a player with the scepter open the shortcut."}, [41]={hint="Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace.", tag="Optional, Unverified", desc="Rotgrip patrols the pool (41.20, 81.50). Look for the small spring at the surface. Location: Drop into Rotgrip's pool below the Princess. Find the spring at the surface. Order: Do step 39 before diving."}, [42]={hint="Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", desc="DungeonsForever map: Princess in Zaetar's Grave (26.00, 78.30). Location: Follow Earth Song Falls into Zaetar's cavern and reach the Princess's platform."}, [43]={npc="Zaetar's Spirit", tgt="Zaetar's Spirit", tag="Unverified", desc="Zaetar's Spirit appears after the Princess dies. Pick up now and turn in outside. DungeonsForever map: the spirit for quest Seed of Life (23.70, 78.00)."}, [44]={npc="Selendra", tgt="Selendra"}, [45]={npc="Vark Battlescar", tgt="Vark Battlescar"}, [46]={npc="Willow", tgt="Willow"}, [47]={npc="Centaur Pariah", tgt="Centaur Pariah"}, [48]={npc="Uthel'nay", tgt="Uthel'nay"}, [49]={hint="Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace.", tag="Optional, Unverified", desc="The pin marks Woodwyrd."}, [50]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional, Unverified"}, [51]={hint="Seek out Remulos in Moonglade and give him the Seed of Life.", desc="Save for when you pass through Moonglade."}, [52]={npc="Keeper Remulos", tgt="Keeper Remulos", desc="Save for Moonglade."}}},
    ["04-33"] = {name="Tanaris: Gadgetzan & Sandfury camp", short="Tanaris: Gadgetzan +", tips={{k="取捨", text="Turn in at the northern pool to unlock 82. Turn in 82 to unlock 10, then do the Dunemaul, Thistleshrub Valley, and southern hive objectives in one loop."}, {k="取捨", text="Run Zul'Farrak if you have a group and do all four dungeon quests together. Otherwise, skip them and The Ancient Egg."}, {k="取捨", text="Turn in 32 and Zukk'ash Report first. Quest March of the Silithid requires level 50. Check the Cleft of Shadow once eligible and save the full follow-up for the Gadgetzan and Broken Pillar leg."}, {k="提醒", text="Below level 50? Grind clustered normal ogres for cloth at Dunemaul Compound (40.75, 50.67). If you want to ding in Searing Gorge, leave yourself a small XP gap.", s={{"Below level 50?"}, {"Grind clustered normal ogres for cloth at Dunemaul Compound (40.75, 50.67)"}, {"If you want to ding in Searing Gorge, leave yourself a small XP gap"}}}}, danger={[1]="The Centipaar hive entrance is easy to overpull. Fight on open ground outside the hive and don't chase mobs into the narrow tunnel."}, grind={[1]={mob="Dunemaul Brute", note="Dense normal melee mobs outside Dunemaul Compound. Collect cloth and do the ogre quests. Keep moving along the edge if the camp is busy."}, [2]={mob="Centipaar Swarmer", note="Dense, higher-level normal mobs outside the western silithid hive. Pull singles near the entrance. Avoid packs in the narrow tunnels."}}, supply={[1]={npc="Bulkrek Ragefist"}, [2]={npc="Innkeeper Fizzgrimble"}, [3]={npc="Wrinkle Goodsteel"}, [4]={npc="Innkeeper Fizzgrimble"}, [5]={npc="Blizrik Buckshot"}}, steps={[1]={text="Fly from Camp Mojache to Gadgetzan and set your hearth there for now."}, [2]={text="Pick up at Gadgetzan, then go west for the water sample and Noxious Lair"}, [3]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [4]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [5]={npc="Andi Lynn", tgt="Andi Lynn"}, [6]={npc="Tran'rek", tgt="Tran'rek"}, [7]={npc="Quinn", tgt="Quinn", tag="Optional", desc="Loot desert scraps if you pass them."}, [8]={hint="Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", desc="Use the Untapped Dowsing Widget at the Sandsorrow Watch pool. Return with the sample."}, [9]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [10]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [11]={hint="Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan."}, [12]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [13]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [14]={text="South to Sandfury and Thistleshrub Valley, then follow the foothills to the hive"}, [15]={hint="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager."}, [16]={hint="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound.", tag="Optional", desc="Do this only if you picked it up on the Steamwheedle Port and Gadgetzan leg."}, [17]={hint="Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", desc="Kill Dew Collectors in Thistleshrub Valley. Loot one Laden Dew Gland."}, [18]={hint="Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers."}, [19]={hint="Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", desc="Go underground in the southern rift to find Scrimshank's Surveying Gear."}, [20]={hint="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan.", tag="Optional", desc="Pin marks a confirmed spawn. Alliance quests can drop scraps. Check outside Gadgetzan."}, [21]={text="Return to Gadgetzan for turn-ins. Hearth if ready, and pick up In Good Taste and Insect Part Analysis while you're there."}, [22]={npc="Andi Lynn", tgt="Andi Lynn"}, [23]={npc="Tran'rek", tgt="Tran'rek"}, [24]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [25]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [26]={npc="Quinn", tgt="Quinn", tag="Optional"}, [27]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [28]={hint="Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan."}, [29]={npc="Sprinkle", tgt="Sprinkle"}, [30]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [31]={hint="Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts."}, [32]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [33]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [34]={hint="Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested."}, [35]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [36]={npc="Sprinkle", tgt="Sprinkle", desc="Gather Violet Tragan at Valorwind Lake in the Hinterlands. Turn in at Gadgetzan."}, [37]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser", desc="Turn in at the Cleft of Shadow in Orgrimmar. Do the prerequisites with Zukk'ash Report."}, [38]={text="Optional Steamwheedle Port and Zul'Farrak"}, [39]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Requires the three Screecher Spirits from the Camp Mojache leg."}, [40]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle", tag="Optional"}, [41]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional", desc="Turn in Screecher Spirits first. Pick this up once you have a Zul'Farrak group."}, [42]={hint="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", tag="Optional"}, [43]={hint="Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", tag="Optional", desc="Clear the scarabs in the Zul'Farrak graveyard."}, [44]={hint="Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", tag="Optional", desc="Finish the stair event. Get the rod from Sergeant Bly."}, [45]={hint="Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", tag="Optional"}, [46]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional"}, [47]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional", desc="After The Prophecy of Mosh'aru, get the Ancient Egg in the Hinterlands. Turn in at Steamwheedle Port."}, [48]={npc="Tran'rek", tgt="Tran'rek", tag="Optional"}, [49]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle", tag="Optional", star={"Masons Fraternity Ring", {"ROGUE", "HUNTER", "DRUID"}}}, [50]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer", tag="Optional"}, [51]={text="Fly from Gadgetzan to Orgrimmar. See Zilzibin Drumlore in the Drag, then turn in The Gordunni Orb at Darkbriar Lodge."}, [52]={hint="Take the report to Zilzibin Drumlore in Orgrimmar."}, [53]={hint="Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar."}, [54]={hint="Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar."}, [55]={npc="Zilzibin Drumlore", tgt="Zilzibin Drumlore"}, [56]={npc="Zilzibin Drumlore", tgt="Zilzibin Drumlore"}, [57]={npc="Uthel'nay", tgt="Uthel'nay"}}},
    ["05-d21"] = {name="Zul'Farrak", entrance="Tanaris 38.70, 20.00", pickup="Take the three local quests in Gadgetzan, then take Screecher Spirits from Yeh'kinya at Steamwheedle Port. Collect the spirits in Feralas. Return to Steamwheedle Port to turn in Screecher Spirits and pick up The Prophecy of Mosh'aru before meeting your group at Gadgetzan. Pick up Gahz'rilla when passing the Shimmering Flats. Mages can do Tabetha's Dustwallow quest before Swamp of Sorrows.", pickupS={{"Take the three local quests in Gadgetzan, then take Screecher Spirits from Yeh'kinya at Steamwheedle Port"}, {"Collect the spirits in Feralas"}, {"Return to Steamwheedle Port to turn in Screecher Spirits and pick up The Prophecy of Mosh'aru before meeting your group at Gadgetzan"}, {"Pick up Gahz'rilla when passing the Shimmering Flats"}, {"Mages can do Tabetha's Dustwallow quest before Swamp of Sorrows"}}, tips={{k="動線", text="Antu'sul's side path → Theka for the first Mosh'aru Tablet → Zum'rah's graveyard → pyramid stairs event for the Divino-matic Rod → Velratha for the second tablet → optional Gahz'rilla at the pool → Chief Ukorz. Loot scarab shells and Troll Temper throughout."}, {k="取捨", text="Prioritize the three Gadgetzan quests and the Tablets of Mosh'aru. Fight Gahz'rilla if you have the mallet. Save Tabetha for a Dustwallow visit."}, {k="說明", text="Run once on the Steamwheedle Port and Gadgetzan leg. If doing Yeh'kinya's full chain, wait until the Gadgetzan and Dunemaul visit. The Tablets of Mosh'aru are also a prerequisite for the Hakkar chain.", s={{"Run once on the Steamwheedle Port and Gadgetzan leg"}, {"If doing Yeh'kinya's full chain, wait until the Gadgetzan and Dunemaul visit"}, {"The Tablets of Mosh'aru are also a prerequisite for the Hakkar chain"}}}}, steps={[1]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [2]={npc="Tran'rek", tgt="Tran'rek"}, [3]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer"}, [4]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Pick up in Steamwheedle Port, then do Feralas. Take The Prophecy of Mosh'aru after turning this in."}, [5]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port."}, [6]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [7]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="Screecher Spirits"}, [8]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional", desc="Bring a Mallet of Zul'Farrak. Get the Sacred Mallet at Zul's altar, use at Jintha'Alor."}, [9]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Pick up directly from Tabetha. The level-40 Undercity breadcrumb (Tabetha's Task) is optional."}, [10]={text="Zul'Farrak entrance"}, [11]={hint="Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", desc="Location: Kill scarabs around Theka the Martyr's room. Order: Take the first tablet for step 15 here."}, [12]={hint="Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", desc="Agree on loot before the run. One clear may not drop enough. Location: Clear Sandfury trolls along the main route from the entrance."}, [13]={hint="Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", tag="Optional", desc="DungeonsForever map: Hydromancer Velratha (34.50, 35.80). Location: Pass the pyramid and find Velratha by the pool. Order: Take the second tablet for step 15 here."}, [14]={hint="Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", tag="Optional", desc="DungeonsForever map: gong (28.90, 44.60), Gahz'rilla (29.60, 39.40). Location: Ring the gong by Velratha's pool to summon Gahz'rilla. Order: Kill Hydromancer Velratha before ringing the gong."}, [15]={hint="Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", desc="Open the cages for the stair event. Clear the waves below before turning hostile. DungeonsForever map: Sergeant Bly (23.90, 20.60). Location: Open the cages atop the pyramid. Go down the steps and hold off the waves. Order: Defend against the waves, then challenge Sergeant Bly."}, [16]={hint="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", desc="Zul'Farrak map: Theka (56.70, 31.50), Velratha (34.50, 35.80). Location: Loot Theka in the scarab room and Velratha by the pool. Order: Do step 10 in the beetle room and steps 12-13 at the pool."}, [17]={npc="Tran'rek", tgt="Tran'rek"}, [18]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer"}, [19]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Pick up now. Loot the egg in Jintha'Alor before the Temple of Atal'Hakkar.", preText="The Prophecy of Mosh'aru"}, [22]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional"}, [23]={npc="Tabetha", tgt="Tabetha", tag="Optional"}}},
    ["04-34"] = {name="Searing Gorge: Thorium Point", short="Thorium Point", tips={{k="交通", text="Unlock the Horde flight path at Thorium Point. Fly to Undercity or Hammerfall before continuing to the Hinterlands."}, {k="取捨", text="Clear the four kill objectives on one loop. If you're short on drops for STOLEN: Smithing Tuyere and Lookout's Spyglass, turn in the others first. Do WANTED: Overseer Maltorius and What the Flux? in the same cave if you have a group."}, {k="取捨", text="Leave Thorium Point once turn-ins get you to level 50. The later torch quests and the southeastern Wooden Outhouse both require backtracking. Do them only if you need XP."}, {k="提醒", text="Need a little XP? Grind Heavy War Golems east of the Cauldron (44.76, 38.72) or normal Dark Iron Taskmasters on the northern slope (41.21, 23.33).", s={{"Need a little XP?"}, {"Grind Heavy War Golems east of the Cauldron (44.76, 38.72) or normal Dark Iron Taskmasters on the northern slope (41.21, 23.33)"}}}}, danger={[1]="Overseer Maltorius is deep in the Dark Iron mine by the Slag Pit. Clear the tunnels with your group. Skip the bounty if solo."}, grind={[1]={mob="Heavy War Golem", note="Normal golems on the east rim of the Cauldron. Stay high along the rim and count kills for the quest. Avoid the floor if other players are there."}, [2]={mob="Dark Iron Taskmaster", note="Normal Dark Iron mobs south of Thorium Point. Pick up kills and quest drops before returning to the flight path. Watch for adds inside the camp."}}, supply={[1]={npc="Grisha"}, [2]={npc="Master Smith Burninate"}, [3]={npc="Master Smith Burninate"}, [4]={npc="Master Smith Burninate"}}, steps={[1]={text="Fly from Orgrimmar to Ratchet. Pick up the Un'Goro lead-in at the docks before taking the boat to Booty Bay. Fly to Kargath."}, [2]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix", desc="Requires 49. Do at Fire Plume Ridge in Un'Goro. Turn in at Ratchet."}, [3]={text="Take the southwest road out of Kargath into Searing Gorge, then follow the northern road to Thorium Point."}, [4]={node="Thorium Point", desc="Unlock the Horde flight path with Grisha."}, [5]={text="Pick up at Thorium Point, then loop through the Cauldron and Slag Pit"}, [6]={npc="Wanted/Missing/Lost & Found", npcObj=true}, [7]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [8]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [9]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [10]={npc="Wanted/Missing/Lost & Found", npcObj=true, tag="Optional", desc="Loot both drops as you clear the mobs."}, [11]={npc="Wanted/Missing/Lost & Found", npcObj=true, tag="Optional", desc="Martorius is elite. Accept only with a group."}, [12]={npc="Master Smith Burninate", tgt="Master Smith Burninate", tag="Optional", desc="Pick this up on the Martorius group run."}, [13]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [14]={hint="Listen as Kalaran Windblade tells his story."}, [15]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [16]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [17]={hint="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge."}, [18]={hint="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task."}, [19]={hint="Hansel Heavyhands wants you to kill 20 Heavy War Golems."}, [20]={hint="Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", desc="Kill the golems and fire elementals around the Cauldron."}, [21]={hint="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.", tag="Optional"}, [22]={hint="Hansel Heavyhands wants you to kill 20 Incendosaurs.", desc="Kill Incendosaurs in the Slag Pit alongside the Dark Iron mobs."}, [23]={hint="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", tag="Optional", desc="Look for the plans near Martorius deep in the Slag Pit. Loot when safe."}, [24]={hint="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.", tag="Optional"}, [25]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [26]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional", desc="Accept if you need XP and are willing to make another trip to the Cauldron."}, [27]={hint="Bring 8 Thorium Plated Daggers to Kalaran Windblade.", tag="Optional", desc="Drops from Dark Iron Taskmasters and Slavers in the Slag Pit."}, [28]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [29]={text="Return to Thorium Point and turn in all the Cauldron quests together."}, [30]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [31]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange"}, [32]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [33]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [34]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange", tag="Optional"}, [35]={npc="Master Smith Burninate", tgt="Master Smith Burninate", tag="Optional"}, [36]={npc="Lookout Captain Lolo Longstriker", tgt="Lookout Captain Lolo Longstriker", tag="Optional"}, [37]={text="Extra XP or the torch if you still need it"}, [38]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional", desc="Complete Forging the Shaft. Kill Twilight mobs in the west cave for the Symbol of Ragnaros."}, [39]={hint="Find and return a Symbol of Ragnaros to Kalaran Windblade.", tag="Optional", desc="Complete Forging the Shaft. Kill Twilight mobs in the west cave for the Symbol of Ragnaros."}, [40]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional", desc="Complete Forging the Shaft. Kill Twilight mobs in the west cave for the Symbol of Ragnaros."}, [41]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [42]={hint="Wait for Kalaran Windblade to complete the Torch of Retribution.", tag="Optional"}, [43]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [44]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [45]={hint="Take the Torch of Retribution.", tag="Optional"}, [46]={npc="Torch of Retribution", npcObj=true, tag="Optional"}, [47]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [48]={hint="Speak with Squire Maltrake.", tag="Optional"}, [49]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Optional"}, [50]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Optional", desc="Pull the guards away before lighting all four towers."}, [51]={hint="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", tag="Optional", desc="Pull the guards away before lighting all four towers."}, [52]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Optional", desc="Pull the guards away before lighting all four towers."}, [53]={npc="Hoard of the Black Dragonflight", npcObj=true, tag="Optional"}, [54]={hint="Open the chest.", tag="Optional"}, [55]={npc="Hoard of the Black Dragonflight", npcObj=true, tag="Optional"}, [56]={npc="Wooden Outhouse", npcObj=true, tag="Optional", desc="Detour to the Wooden Outhouse if heading southeast or short on XP. Bring 15 Silk Cloth."}, [57]={hint="Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.", tag="Optional", desc="Detour to the Wooden Outhouse if heading southeast or short on XP. Bring 15 Silk Cloth."}, [58]={npc="Wooden Outhouse", npcObj=true, tag="Optional", desc="Detour to the Wooden Outhouse if heading southeast or short on XP. Bring 15 Silk Cloth."}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Dustwallow Marsh 75.30, 14.10", pickup="Below level 48? Unlock Brackenwall Village on the way to Swamp of Sorrows. Before Searing Gorge, take The Missing Kor'kron from Eitrigg in Thrall's chamber in the Valley of Wisdom (34.28, 39.35). Fly to Brackenwall Village and see Nazeer Bloodpike. Swim from the northeast coast to Alcaz Island. Turn in The Elite of the Elite and Right Place, Wrong Time to the sergeant by the island, then take No Orc Left Behind before going under the tower. Save Thrall Needs to Know for Orgrimmar.", pickupS={{"Below level 48?"}, {"Unlock Brackenwall Village on the way to Swamp of Sorrows"}, {"Before Searing Gorge, take The Missing Kor'kron from Eitrigg in Thrall's chamber in the Valley of Wisdom (34.28, 39.35)"}, {"Fly to Brackenwall Village and see Nazeer Bloodpike"}, {"Swim from the northeast coast to Alcaz Island"}, {"Turn in The Elite of the Elite and Right Place, Wrong Time to the sergeant by the island, then take No Orc Left Behind before going under the tower"}, {"Save Thrall Needs to Know for Orgrimmar"}}, tips={{k="動線", text="Find Commander Folkar in the upper cells → kill Overseer Wrex for the key → clear The Questioner and Tidemistress Ca'zass, looting bandanas → open the lower cells for Katerina the Cleaner and Blazeroar → read the note in the hidden room and return to Folkar upstairs."}, {k="取捨", text="Prioritize the Kor'kron rescue chain from The Missing Kor'kron to Thrall Needs to Know. If you're short on bandanas after one run, save that turn-in."}, {k="說明", text="Avoid Theramore. Go from Brackenwall Village to the northeast coast and swim across. The sergeant is by the island, and the dungeon portal is in the corridor under the tower.", s={{"Avoid Theramore"}, {"Go from Brackenwall Village to the northeast coast and swim across"}, {"The sergeant is by the island, and the dungeon portal is in the corridor under the tower"}}}}, steps={[1]={npc="Eitrigg", tgt="Eitrigg", desc="At 48, find Eitrigg in Thrall's hall in the Valley of Wisdom."}, [2]={hint="Speak with Nazeer Bloodspike in Brackenwall Village."}, [3]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike"}, [4]={npc="Nazeer Bloodpike", tgt="Nazeer Bloodpike", preText="The Missing Kor'kron"}, [5]={hint="Find the missing Kor'kron Elites."}, [6]={npc="Sergeant Ulka", tgt="Sergeant Ulka"}, [7]={npc="Sergeant Ulka", tgt="Sergeant Ulka", preText="The Elite of the Elite"}, [8]={hint="Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."}, [9]={npc="Sergeant Ulka", tgt="Sergeant Ulka"}, [10]={npc="Sergeant Ulka", tgt="Sergeant Ulka", preText="Right Place, Wrong Time"}, [11]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Optional", desc="Do The Missing Kor'kron-Right Place, Wrong Time from Orgrimmar to the island, then check the sergeant's quests."}, [12]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Optional", desc="The sergeant offers this in game. Unlock unconfirmed; do The Missing Kor'kron-Right Place, Wrong Time first."}, [13]={text="Alcaz Prison entrance"}, [14]={hint="Enter the Alcaz Prison and find Commander Folkar.", desc="Location: Take the upper hall and find Commander Folkar in a cell."}, [15]={npc="Commander Folkar", tag="Unverified"}, [16]={npc="Commander Folkar", tag="Unverified", preText="No Orc Left Behind"}, [17]={hint="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka.", tag="Optional", desc="Location: Find Tidemistress Ca'zass by the upper cells. Clear naga along the hall."}, [18]={hint="Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there.", tag="Optional", desc="You may need another run. Check your count before leaving the dungeon. Location: Kill human guards along the upper prison hall until you have all the drops."}, [19]={hint="Look for King Varian Wrynn in Alcaz Prison.", desc="Location: Open the lower door and kill the last boss. Find the note in the hidden room. Order: Get the key from the warden first."}, [20]={npc="Quest object", npcObj=true, tag="Unverified"}, [21]={npc="Quest object", npcObj=true, tag="Unverified", preText="The Honor of the Kor'kron"}, [22]={hint="Report back to Commander Folkar.", desc="Location: Return from the last boss's hidden room to the commander in his upper cell. Order: Read the note in step 18 first."}, [23]={npc="Commander Folkar", tag="Unverified"}, [24]={npc="Commander Folkar", tag="Unverified", preText="Bad News for Folkar"}, [25]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Optional"}, [26]={hint="Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."}, [27]={npc="Thrall", tgt="Thrall"}, [28]={npc="Eitrigg", tgt="Eitrigg", tag="Optional"}}},
    ["04-35"] = {name="The Hinterlands: Revantusk & Jintha'Alor", short="Hinterlands: Revantusk +", tips={{k="取捨", text="Do Whiskey Slim's Lost Grog on the same beach as the turtle quests. Kill owlbeasts for Hunt the Savages and Testing the Vessel together."}, {k="取捨", text="Quest Job Opening: Guard Captain of Revantusk Village requires 80 elite kills. Skip it without a group. If Jintha'Alor is too hard to solo, do the coast and inland quests first."}, {k="取捨", text="Turn in Whiskey Slim's Lost Grog at Booty Bay and Testing the Vessel at Camp Mojache. Save Sprinkle's Secret Ingredient and The Ancient Egg for the Gadgetzan and Broken Pillar leg."}, {k="提醒", text="Below level 52? Grind turtles or owlbeasts in the Hinterlands, or clear Jintha'Alor with a group.", s={{"Below level 52?"}, {"Grind turtles or owlbeasts in the Hinterlands, or clear Jintha'Alor with a group"}}}}, danger={[1]="Elite Vilebranch trolls and healers pack upper Jintha'Alor. Clear one tier at a time with a group. Stick to the coast if solo.", [2]="Gammerita is an elite turtle that patrols the coast. Watch for her while grinding normal turtles, and give her room if you're solo."}, grind={[1]={mob="Saltwater Snapjaw", note="Normal turtles on the beach north of Revantusk Village. Follow the shore, skin them, and share the beach with turtle meat questers. Skip the Jintha'Alor elites."}}, supply={[1]={npc="Gorkas"}, [2]={npc="Lard"}, [3]={npc="Smith Slagtree"}, [4]={npc="Lard"}, [5]={npc="Renn'az"}, [6]={npc="Mystic Yayo'jin"}}, steps={[1]={text="Fly from Searing Gorge to Revantusk Village. If locked, fly to Tarren Mill and use the pass north of Durnholde Keep. Follow the Hinterlands road east, then go south along the coast.", tag="Flight path locked. Travel there on foot the first time."}, [2]={node="Revantusk Village", desc="Unlock the flight path with Gorkas."}, [3]={text="You can set your hearth at Revantusk Village for this leg."}, [4]={text="Pick up at Revantusk Village → coast"}, [5]={npc="Katoom the Angler", tgt="Katoom the Angler"}, [6]={npc="Katoom the Angler", tgt="Katoom the Angler"}, [7]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [8]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [9]={npc="Lard", tgt="Lard"}, [10]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [11]={npc="Primal Torntusk", tgt="Primal Torntusk"}, [12]={npc="Primal Torntusk", tgt="Primal Torntusk"}, [13]={npc="Huntsman Markhor", tgt="Huntsman Markhor", tag="Optional", desc="Do it only if you spot a rare Razorbeak gryphon."}, [14]={npc="Smith Slagtree", tgt="Smith Slagtree", tag="Optional", desc="Detour to the temple to the northeast."}, [15]={npc="Call to Arms!", npcObj=true, tag="Optional", desc="Group up for the elites on the upper terraces of Jintha'Alor."}, [16]={npc="Call to Arms!", npcObj=true, tag="Optional", desc="Pick up only if you plan to kill 80 elites in Jintha'Alor.", star={"Rune of the Guard Captain", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task."}, [18]={hint="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.", desc="Do with Snapjaws, Mon! and Whiskey Slim's Lost Grog. Kill the target if you spot it."}, [19]={hint="Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.", desc="Accept at the Stonard/Eastwind Shore stop. Head north up the beach for the bottle."}, [20]={hint="Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete."}, [21]={hint="Solve the riddle!", tag="Optional", desc="Requires Cortello's Riddle turned in and Cortello's Riddle active. Turn in Cortello's Riddle at the scroll under the bridge."}, [22]={npc="Cortello's Treasure", npcObj=true, tag="Optional", desc="Skip if you don't have Cortello's Riddle in your quest log."}, [23]={text="Inland wildkin and Silvermanes → Jintha'Alor altar"}, [24]={hint="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete."}, [25]={hint="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete."}, [26]={hint="Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.", desc="Pick up on the Camp Mojache/Rage Scar Hold leg. Turn in in Feralas later."}, [27]={hint="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.", tag="Optional", desc="Kill it if you see it."}, [28]={hint="Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.", tag="Optional"}, [29]={hint="Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", desc="Accept on the first Gadgetzan/Dunemaul visit. Turn in at Gadgetzan."}, [30]={hint="Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", desc="Do alongside Elder Torntusk's quest. Watch for patrols on the stairs."}, [31]={hint="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.", desc="Loot both items. They are in separate spots."}, [32]={hint="Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor."}, [33]={npc="Elder Torntusk", tgt="Elder Torntusk"}, [34]={npc="Elder Torntusk", tgt="Elder Torntusk"}, [35]={hint="Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key."}, [36]={npc="Elder Torntusk", tgt="Elder Torntusk"}, [37]={npc="Elder Torntusk", tgt="Elder Torntusk"}, [38]={hint="Bring the Ancient Egg to Yeh'kinya in Tanaris.", tag="Optional", desc="Do if accepted during the Dunemaul stop. Turn in at Steamwheedle Port."}, [39]={hint="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.", tag="Optional"}, [40]={hint="You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.", tag="Optional"}, [41]={text="Hearth to Revantusk Village for all turn-ins if bound there."}, [42]={hint="Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue."}, [43]={npc="Primal Torntusk", tgt="Primal Torntusk"}, [44]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [45]={npc="Primal Torntusk", tgt="Primal Torntusk"}, [46]={npc="Katoom the Angler", tgt="Katoom the Angler"}, [47]={npc="Katoom the Angler", tgt="Katoom the Angler"}, [48]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [49]={npc="Huntsman Markhor", tgt="Huntsman Markhor"}, [50]={npc="Lard", tgt="Lard"}, [51]={npc="Huntsman Markhor", tgt="Huntsman Markhor", tag="Optional"}, [52]={npc="Smith Slagtree", tgt="Smith Slagtree", tag="Optional"}, [53]={npc="Primal Torntusk", tgt="Primal Torntusk", tag="Optional"}, [54]={npc="Primal Torntusk", tgt="Primal Torntusk", tag="Optional", star={"Rune of the Guard Captain", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [55]={npc="Christoph Walker", tgt="Christoph Walker", tag="Optional", desc="Accept from Christoph Walker in Undercity before Hinterlands. Turn in in Blasted Lands."}, [56]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Buy four materials on the AH. Head north from Tarren Mill to Bath'rah for Elemental Mastery."}, [57]={hint="Bring the elements earth, air, fire and water to Bath'rah the Windwatcher.", tag="Optional", desc="Buy four materials on the AH. Head north from Tarren Mill to Bath'rah for Elemental Mastery."}, [58]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Buy four materials on the AH. Head north from Tarren Mill to Bath'rah for Elemental Mastery."}, [59]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Do either Elemental Mastery or Mastering the Elements. Gather the materials in Western Plaguelands."}, [60]={npc="Miles Dexter", tgt="Miles Dexter", tag="Optional", desc="Accept in Undercity's Rogues' Quarter on your first trip to the Hinterlands."}, [61]={hint="Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.", tag="Optional", desc="Accept in Undercity's Rogues' Quarter on your first trip to the Hinterlands."}, [62]={npc="Lord Jorach Ravenholdt", tgt="Lord Jorach Ravenholdt", tag="Optional", desc="Accept in Undercity's Rogues' Quarter on your first trip to the Hinterlands."}, [63]={npc="Lord Jorach Ravenholdt", tgt="Lord Jorach Ravenholdt", tag="Optional", desc="Accept at Ravenholdt Manor. Save it for Azshara."}}},
    ["04-36"] = {name="Blasted Lands", tips={{k="取捨", text="Do all five collection quests together. Bring 5 jowls, 6 boar lungs, 6 pincers, 11 basilisk brains, and 14 vulture gizzards. Each turn-in consumes its materials."}, {k="取捨", text="Turn in the quests with faster drops first. If vultures or basilisks are contested, save unfinished The Basilisk's Bite or Vulture's Vigor and head to Booty Bay."}, {k="提醒", text="Need XP? Grind beasts on the northern slopes (46-53, 15-27). Higher-level mobs are farther south.", s={{"Need XP?"}, {"Grind beasts on the northern slopes (46-53, 15-27)"}, {"Higher-level mobs are farther south"}}}}, danger={[1]="The mobs south of the Bloodmage camp are higher level than those on the northern slopes. Stick to the outer slopes for the northern collection quests."}, grind={[1]={mob="Scorpok Stinger", note="Normal scorpids east of the Bloodmage camp. Collect pincers and skin them. Pull away from the road when crowded and watch for elite patrols."}}, supply={[1]={npc="Breyk"}, [2]={npc="Innkeeper Karakul"}, [3]={npc="Gharash"}, [4]={npc="Thultash"}, [5]={npc="Thultazor"}}, steps={[1]={text="Fly from Revantusk Village to Stonard, then follow the road south into the Blasted Lands. Visit the two Bloodmages in the north (50.55, 14.20 and 50.64, 14.30)."}, [2]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [3]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [4]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [5]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [6]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [7]={hint="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial."}, [8]={hint="Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial."}, [9]={hint="Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial."}, [10]={hint="Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore."}, [11]={hint="Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore."}, [12]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [13]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [14]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [15]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [16]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [17]={npc="Kum'isha the Collector", tgt="Kum'isha the Collector", tag="Optional", desc="Skip it if the item doesn't drop."}, [18]={hint="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.", tag="Optional", desc="Skip it if the item doesn't drop."}, [19]={npc="Kum'isha the Collector", tgt="Kum'isha the Collector", tag="Optional", desc="Skip it if the item doesn't drop."}, [20]={npc="Kum'isha the Collector", tgt="Kum'isha the Collector", tag="Optional", desc="Skip it if the item doesn't drop."}, [21]={hint="Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.", tag="Optional", desc="Skip it if the item doesn't drop."}, [22]={npc="Kum'isha the Collector", tgt="Kum'isha the Collector", tag="Optional", desc="Skip it if the item doesn't drop."}, [23]={hint="Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands.", tag="Optional"}, [24]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [25]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Pair with the Blood Mage's boar lung quest. Kill both sets of targets in the north."}, [26]={hint="Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", tag="Optional", desc="Pair with the Blood Mage's boar lung quest. Kill both sets of targets in the north."}, [27]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Pair with the Blood Mage's boar lung quest. Kill both sets of targets in the north."}, [28]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Pull mobs one at a time from the edge of the camp."}, [29]={hint="Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.", tag="Optional", desc="Pull mobs one at a time from the edge of the camp."}, [30]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Pull mobs one at a time from the edge of the camp."}, [31]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Do now with a group or save for the Eastern Kingdoms trip to Light's Hope Chapel.", star={"Diamond Flask", {"WARRIOR"}}}, [32]={text="Retrace your route to Stonard and fly to Booty Bay."}}},
    ["04-37"] = {name="Stranglethorn Vale: Booty Bay (return)", short="Booty Bay", tips={{k="取捨", text="Turn in the level 50 quest Whiskey Slim's Lost Grog first. The lower-level Stranglethorn quests were split between earlier visits. Turn in any still in your log if complete."}, {k="取捨", text="No Hinterlands grog or completed quests? Just take the boat. The Captain's Chest and Stranglethorn Fever require a round trip outside town. Save them for extra XP or a group."}, {k="提醒", text="Booty Bay is a neutral port. Board the passenger boat to Ratchet and make sure you're on the right ferry.", s={{"Booty Bay is a neutral port"}, {"Board the passenger boat to Ratchet and make sure you're on the right ferry"}}}}, grind={[1]={mob="Blood Elf Reclaimer", note="Use Booty Bay for turn-ins and the boat. If below 53, grind normal blood elves in Azshara instead. Pull along the camp edge if questers are there."}}, supply={[1]={npc="Gringer"}, [2]={npc="Innkeeper Skindle"}, [3]={npc="Jutak"}, [4]={npc="Nixxrax Fillamug"}, [5]={npc="Haren Kanmae"}}, steps={[1]={npc="Whiskey Slim", tgt="Whiskey Slim", desc="Accept on the Stonard/Eastwind Shore stop. Collect grog in the Hinterlands."}, [2]={npc="Captain Hecklebury Smotts", tgt="Captain Hecklebury Smotts", tag="Optional", desc="Optional level-47 quest. Accept if you need XP and haven't done it."}, [3]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional", desc="Group up first. Several waves of gorillas attack."}, [4]={hint="Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", tag="Optional"}, [5]={npc="Witch Doctor Unbagwa", tgt="Witch Doctor Unbagwa", tag="Optional", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [6]={hint="Loot from: Mistvale Gorilla, Jungle Thunderer, Enraged Silverback Gorilla", tag="Optional", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [7]={npc="Witch Doctor Unbagwa", tgt="Witch Doctor Unbagwa", tag="Optional", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [8]={hint="Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", tag="Optional", desc="Spawns during the tusk turn-in event for Stranglethorn Fever."}, [9]={npc="Captain Hecklebury Smotts", tgt="Captain Hecklebury Smotts", tag="Optional"}, [10]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional"}, [11]={text="Take the boat to Ratchet and fly to Orgrimmar. You can pick up Betrayed from Belgrom before heading to Valormok in Azshara."}}},
    ["04-38"] = {name="Azshara: Valormok & Temple of Arkkoroc", short="Azshara: Valormok +", tips={{k="取捨", text="Do the Thalassian Base Camp, three marks, and Rimtori on one loop. Collect all four tablets and the naga runes in the Ruins of Eldarath."}, {k="取捨", text="The video skips two group quests. Forever lists Ley of the Land and Deadliest Catch as elite candidates. Skip both on this visit."}, {k="取捨", text="Turn in Delivery to Andron Gant to Andron Gant in Undercity (54.81, 76.33) during the Light's Hope Chapel transfer. Skip the follow-up that sends you back to Azshara."}, {k="提醒", text="Below level 53? Grind naga at the Ruins of Eldarath or blood elves at the Thalassian Base Camp while looking for quest drops.", s={{"Below level 53?"}, {"Grind naga at the Ruins of Eldarath or blood elves at the Thalassian Base Camp while looking for quest drops"}}}}, danger={[1]="Naga casters pack the inner Ruins of Eldarath. Hug the outer wall while collecting tablets. Interrupt casters and pull them out of the rooms."}, grind={[1]={mob="Blood Elf Reclaimer", note="Normal blood elves at Thalassian Base Camp are a good level for XP and quest drops. Pull along the edge to avoid linking casters inside."}, [2]={mob="Spitelash Myrmidon", note="Normal naga at the Ruins of Eldarath. Pair with the naga quests. Pull singles along the outer wall and avoid dense caster packs inside."}}, supply={[1]={npc="Kroum"}, [2]={npc="Gruul Darkblade"}, [3]={npc="Kurll"}, [4]={npc="Innkeeper Gryshka"}, [5]={npc="Kaja"}, [6]={npc="Horthus"}}, steps={[1]={npc="Belgrom Rockmaul", tgt="Belgrom Rockmaul", desc="Accept in Orgrimmar's Valley of Honor. Starts the updated Betrayed chain."}, [2]={npc="Jes'rimon", tgt="Jes'rimon", tag="Optional", desc="Optional. Pick up now, then kill Ravasaurs in Un'Goro."}, [3]={text="Fly from Orgrimmar to Valormok if you've unlocked the Azshara flight path. On your first visit, run east from Splintertree Post, stop at Loh'atu, then continue to Valormok.", tag="Flight path locked. Travel there on foot the first time."}, [4]={text="Loh'atu in the west → pickups at Valormok"}, [5]={npc="Loh'atu", tgt="Loh'atu"}, [6]={npc="Loh'atu", tgt="Loh'atu"}, [7]={hint="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara."}, [8]={hint="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale."}, [9]={npc="Loh'atu", tgt="Loh'atu"}, [10]={npc="Loh'atu", tgt="Loh'atu"}, [11]={node="Valormok", desc="Unlock the flight path with Kroum."}, [12]={hint="Deliver the Sealed Letter to Ag'tor Bloodfist in Azshara."}, [13]={npc="Ag'tor Bloodfist", tgt="Ag'tor Bloodfist"}, [14]={npc="Ag'tor Bloodfist", tgt="Ag'tor Bloodfist"}, [15]={npc="Jediga", tgt="Jediga"}, [16]={text="Thalassian Base Camp → temple and Ruins of Eldarath → Valormok"}, [17]={npc="Kim'jael", tgt="Kim'jael"}, [18]={hint="Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara."}, [19]={npc="Kim'jael", tgt="Kim'jael"}, [20]={npc="Kim'jael", tgt="Kim'jael"}, [21]={hint="Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight.", desc="Wowhead Forever lists 6 of each. QuestieDB lists 10. Check your quest log."}, [22]={npc="Kaldorei Tome of Summoning", npcObj=true, tag="Unverified"}, [23]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="Unverified", desc="Forever's Betrayed chain. Complete Betrayed first, then collect one of each seal."}, [24]={hint="Bring the Seal of the Warden, Seal of the Warrior, and Seal of the Ranger to the Sin'dorei Tome of Summoning.", tag="Target: Lieutenant Suncrest / Magister Hawkhelm / Ranger Lydrea / Skyborne Test, Unverified", desc="Forever's Betrayed chain. Complete Betrayed first, then collect one of each seal."}, [25]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="Unverified", desc="Forever's Betrayed chain. Complete Betrayed first, then collect one of each seal."}, [26]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="Unverified"}, [27]={hint="Break the Seals of the Sin'dorei, then bring Magus Rimtori's head to Ag'tor Bloodfist in Valormok.", tag="Unverified"}, [28]={hint="Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara."}, [29]={hint="Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara."}, [30]={npc="Kim'jael", tgt="Kim'jael"}, [31]={npc="Jediga", tgt="Jediga"}, [32]={npc="Ag'tor Bloodfist", tgt="Ag'tor Bloodfist", tag="Unverified"}, [33]={npc="Ag'tor Bloodfist", tgt="Ag'tor Bloodfist", tag="Unverified"}, [34]={npc="Jediga", tgt="Jediga", tag="Optional", desc="Turn in if you pass through Thunder Bluff before the next stop."}, [35]={npc="Jediga", tgt="Jediga", tag="Optional", desc="Turn in on this visit to Orgrimmar."}, [36]={npc="Jediga", tgt="Jediga", tag="Optional", desc="Save the turn-in until you next pass through Undercity."}, [37]={text="Fly from Valormok to Orgrimmar for the head and tablet turn-ins. The Thunder Bluff tablet turn-in takes another flight."}, [38]={hint="Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar.", tag="Unverified"}, [39]={npc="Belgrom Rockmaul", tgt="Belgrom Rockmaul", tag="Unverified"}, [40]={hint="Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.", tag="Optional"}, [41]={npc="Jes'rimon", tgt="Jes'rimon", tag="Optional"}, [42]={npc="Zilzibin Drumlore", tgt="Zilzibin Drumlore", tag="Optional", desc="Pick up from Zilzibin in Orgrimmar before Feralas. Requires 32 or Zukk'ash Report. Save for Tanaris."}, [43]={hint="Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", tag="Optional"}, [44]={npc="Magatha Grimtotem", tgt="Magatha Grimtotem", tag="Optional"}, [45]={npc="Ormak Grimshot", tgt="Ormak Grimshot", tag="Optional", desc="Visit a Hunter trainer in Orgrimmar. Enter Azshara from its west flight path."}, [46]={hint="Speak to Ogtinc in Azshara.", tag="Optional", desc="Visit a Hunter trainer in Orgrimmar. Enter Azshara from its west flight path."}, [47]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Visit a Hunter trainer in Orgrimmar. Enter Azshara from its west flight path."}, [48]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [49]={hint="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", tag="Optional"}, [50]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [51]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [52]={hint="Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Optional"}, [53]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [54]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Run Sunken Temple during the Eastern Kingdoms trip.", star={"Devilsaur Eye", {"HUNTER"}}}, [55]={npc="Uthel'nay", tgt="Uthel'nay", tag="Optional", desc="See the trainer in Orgrimmar's Valley of Spirits first."}, [56]={hint="Seek out Sanath Lim-yo and gain passage to see Archmage Xylem.", tag="Optional", desc="See the trainer in Orgrimmar's Valley of Spirits first."}, [57]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Optional", desc="See the trainer in Orgrimmar's Valley of Spirits first."}, [58]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Do with northern Azshara's blood elf quests after accepting from Archmage Xylem."}, [59]={hint="Bring 10 Glittering Dust to Archmage Xylem.", tag="Optional", desc="Do with northern Azshara's blood elf quests after accepting from Archmage Xylem."}, [60]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Do with northern Azshara's blood elf quests after accepting from Archmage Xylem."}, [61]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional"}, [62]={hint="Collect 6 Enchanted Coral and return them to Archmage Xylem.", tag="Optional"}, [63]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional"}, [64]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Run Sunken Temple on the next Eastern Kingdoms trip.", star={"Fire Ruby", {"MAGE"}}}, [65]={hint="Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara.", tag="Optional, Target: Timbermaw Shaman / Blackmaw Shaman", desc="Kill Blackmaw Shamans for drops to avoid losing Timbermaw reputation."}, [66]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="See Sanath Lim-yo at the foot of the mountain (28.11, 50.09) to reach Xylem's tower."}, [67]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional"}, [68]={hint="Bring 10 Encoded Fragments to Archmage Xylem in Azshara.", tag="Optional"}, [69]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional"}, [70]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Run Sunken Temple during the Eastern Kingdoms leg.", star={"Duskbat Drape", {"ROGUE"}}}, [71]={npc="Ur'kyo", tgt="Ur'kyo", tag="Optional", desc="See a Priest trainer in Orgrimmar and buy 1 Undeath's Ichor."}, [72]={hint="Seek out Ogtinc in Azshara.", tag="Optional", desc="See a Priest trainer in Orgrimmar and buy 1 Undeath's Ichor."}, [73]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="See a Priest trainer in Orgrimmar and buy 1 Undeath's Ichor."}, [74]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [75]={hint="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Optional"}, [76]={npc="Ogtinc", tgt="Ogtinc", tag="Optional"}, [77]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Buy from players or the AH to skip a Plaguelands detour."}, [78]={hint="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Optional", desc="Buy from players or the AH to skip a Plaguelands detour."}, [79]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Buy from players or the AH to skip a Plaguelands detour."}, [80]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Run Sunken Temple during the Eastern Kingdoms trip.", star={"Blessed Prayer Beads", {"PRIEST"}}}}},
    ["04-39"] = {name="Feralas: Camp Mojache (return)", short="Feralas: Camp Mojache", tips={{k="取捨", text="Turn in Testing the Vessel at Camp Mojache, then do Hippogryph Muisek-Mountain Giant Muisek. Turn in each step to get the next container."}, {k="取捨", text="Skip Natural Materials if you're short on materials. Pair the northern spring side quests with the western giants if you have time."}, {k="提醒", text="Need a little XP? Grind Sprite Darters at 69.45, 44.95 or head to the harpy camp to the northwest.", s={{"Need a little XP?"}, {"Grind Sprite Darters at 69.45, 44.95 or head to the harpy camp to the northwest"}}}}, grind={[1]={mob="Northspring Slayer", note="Normal mobs outside the Northspring harpy camp. Collect drops if you're doing the Northspring quests. For XP alone, skip the return trip and grind at the next stop."}, [2]={mob="Groddoc Thunderer", note="If the harpies are taken, grind normal gorillas to the southeast. Use the open ground to retreat and pull singles from outside."}}, supply={[1]={npc="Shyn"}, [2]={npc="Innkeeper Greul"}, [3]={npc="Cawind Trueaim"}, [4]={npc="Innkeeper Greul"}, [5]={npc="Cawind Trueaim"}, [6]={npc="Tarhus"}}, steps={[1]={text="Fly to Camp Mojache if unlocked. Joining here with no flight path? Fly to Freewind Post, follow the valley west into Feralas and learn the Camp Mojache flight path from Shyn."}, [2]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", desc="Accept on the Camp Mojache/Dire Maul stop. Trap owlbeast souls in the Hinterlands."}, [3]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", desc="Return to the witch doctor for the next quest."}, [4]={hint="Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", desc="Return to the witch doctor for the next quest."}, [5]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", desc="Return to the witch doctor for the next quest."}, [6]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [7]={hint="Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons."}, [8]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [9]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [10]={hint="Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants."}, [11]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [12]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [13]={npc="Talo Thornhoof", tgt="Talo Thornhoof", tag="Optional", desc="Accept when heading to the Northspring harpies if you can handle elites."}, [14]={npc="Talo Thornhoof", tgt="Talo Thornhoof", tag="Optional"}, [15]={hint="Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants."}, [16]={hint="Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", tag="Optional"}, [17]={hint="Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", tag="Optional", desc="Summon at the Northspring Altar."}, [18]={hint="Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", tag="Optional", desc="Accept on the Camp Mojache/Dire Maul stop. Gather as you go. Skip extra backtracking."}, [19]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [20]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", tag="Optional"}, [21]={npc="Talo Thornhoof", tgt="Talo Thornhoof", tag="Optional"}, [22]={npc="Talo Thornhoof", tgt="Talo Thornhoof", tag="Optional"}, [23]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", tag="Optional", desc="Accept after completing Mountain Giant Muisek and Natural Materials."}, [24]={hint="Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", tag="Optional", desc="Accept after completing Mountain Giant Muisek and Natural Materials."}, [25]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i", tag="Optional", desc="Accept after completing Mountain Giant Muisek and Natural Materials."}, [26]={text="Fly from Camp Mojache to Gadgetzan in Tanaris."}}},
    ["04-40"] = {name="Tanaris: Gadgetzan & Broken Pillar", short="Tanaris: Gadgetzan +", tips={{k="取捨", text="Turn in the three quests from Sprinkle's Secret Ingredient through Noggenfogger Elixir in Gadgetzan. Pick up the Un'Goro quests before heading to the Broken Pillar."}, {k="取捨", text="Quest The Stone Circle sends you back to Ratchet. Do just The Sunken Temple and Gahz'ridian on this visit if you prefer. If you take The Stone Circle for the dungeon chain, get the Stone Circle in Ratchet and turn it in on another trip."}, {k="取捨", text="Do Super Sticky and Bungle in the Jungle at Marshal's Refuge after completing the prerequisite for Bungle in the Jungle. Turn in Yuka Screwspigot on the Flame Crest and Blackrock Mountain leg."}, {k="提醒", text="Need XP? Do Gahz'ridian by the Broken Pillar and kill Dunemaul ogres, or find a Zul'Farrak group in Tanaris.", s={{"Need XP?"}, {"Do Gahz'ridian by the Broken Pillar and kill Dunemaul ogres, or find a Zul'Farrak group in Tanaris"}}}}, grind={[1]={mob="Hazzali Swarmer", note="Dense, level-appropriate normal scorpids outside the Gaping Chasm. Stay aboveground to avoid extra pulls near the entrance."}, [2]={mob="Glasshide Petrifier", note="Kill normal lizards along the southern road before the Broken Pillar or Un'Goro. Scattered spawns are less contested than Dunemaul Compound."}}, supply={[1]={npc="Bulkrek Ragefist"}, [2]={npc="Innkeeper Fizzgrimble"}, [3]={npc="Wrinkle Goodsteel"}, [4]={npc="Innkeeper Fizzgrimble"}, [5]={npc="Blizrik Buckshot"}}, steps={[1]={npc="Sprinkle", tgt="Sprinkle", desc="Accept in Tanaris. Gather mushrooms in the Hinterlands. Turn in first at Gadgetzan."}, [2]={npc="Sprinkle", tgt="Sprinkle", desc="Turn in Sprinkle's Secret Ingredient first."}, [3]={hint="Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.", desc="Turn in Sprinkle's Secret Ingredient first."}, [4]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger", desc="Turn in Sprinkle's Secret Ingredient first."}, [5]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [6]={hint="Marin Noggenfogger wants you to speak to him again after he creates his elixir."}, [7]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [8]={hint="Speak to Alchemist Pestlezugg in Gadgetzan.", tag="Optional", desc="Before leaving Orgrimmar for Valormok, see Zilzibin after 32 or Zukk'ash Report."}, [9]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg", tag="Optional"}, [10]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg", tag="Optional", desc="Turn in Horde quest March of the Silithid first. Save the follow-up for Un'Goro."}, [11]={npc="Tran'rek", tgt="Tran'rek", desc="Kill tar mobs on the Marshal's Refuge leg in Un'Goro."}, [12]={text="If you have the Ancient Egg, turn it in at Steamwheedle Port to the east. Otherwise go straight south to the Broken Pillar."}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional", desc="Accept in Tanaris. Get the egg at Jintha'Alor. Yeh'kinya is in Steamwheedle Port."}, [14]={npc="Yorba Screwspigot", tgt="Yorba Screwspigot", tag="Optional", desc="Pick up at Steamwheedle Port. Turn in at Flame Crest on the way to Blackrock Depths."}, [15]={hint="Find Marvon Rivetseeker in Tanaris.", desc="Pick up at Camp Mojache before the Rage Scar Hold loop."}, [16]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [17]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [18]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Optional", desc="Turn in The Sunken Temple first. Get the Stone Circle in Ratchet if you plan to run Sunken Temple."}, [19]={hint="Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", desc="Search around the Broken Pillar first, then sweep the perimeter."}, [20]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [21]={hint="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", tag="Optional", desc="Grab it during any later Ratchet stop."}, [22]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Optional"}, [23]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Optional", desc="Accept only if running Sunken Temple."}, [24]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional", desc="Find Torwa Pathfinder at Un'Goro's southeast entrance. Gather on the next leg."}, [25]={text="Follow the Tanaris road south from the Broken Pillar, then head west into Un'Goro Crater."}}},
    ["05-d23"] = {name="The Temple of Atal'Hakkar", entrance="Swamp of Sorrows (1435), 69.50, 52.50. Marks the outside of the temple.", pickup="Finish 1424 in Stonard and keep The Atal'ai Exile. From Revantusk Village, walk to the exile in the southern Hinterlands. Turn in The Atal'ai Exile and take 1444 and 1446. Get the egg at Jintha'Alor if you've finished the Zul'Farrak tablet chain. Take The Sunken Temple in Feralas. On the Gadgetzan and Dunemaul leg, start the Stone Circle quest with Marvon, get the item in Ratchet, then return to Marvon for both temple quests. Turn in the egg at Steamwheedle Port. Fly Gadgetzan → Ratchet, boat to Booty Bay, then fly to Stonard to turn in 1444 and take 1445 before entering.", pickupS={{"Finish 1424 in Stonard and keep The Atal'ai Exile"}, {"From Revantusk Village, walk to the exile in the southern Hinterlands"}, {"Turn in The Atal'ai Exile and take 1444 and 1446"}, {"Get the egg at Jintha'Alor if you've finished the Zul'Farrak tablet chain"}, {"Take The Sunken Temple in Feralas"}, {"On the Gadgetzan and Dunemaul leg, start the Stone Circle quest with Marvon, get the item in Ratchet, then return to Marvon for both temple quests"}, {"Turn in the egg at Steamwheedle Port"}, {"Fly Gadgetzan → Ratchet, boat to Booty Bay, then fly to Stonard to turn in 1444 and take 1445 before entering"}}, tips={{k="動線", text="Take the right entrance path to the lower ring → check the altar, activate the statues and kill Atal'alarion → clear the six upper balconies → east from the Pit of Sacrifice for Jammal'an → optional Hakkar event west → four dragonkin → Eranikus and the Essence Font. Loot idols from Atal'ai trolls throughout."}, {k="取捨", text="Prioritize the Stonard and Hinterlands chains. Do the Mosh'aru chain if you've already run Zul'Farrak and visited Jintha'Alor. Plan one Ratchet trip for the Stone Circle during the Gadgetzan and Dunemaul leg."}, {k="說明", text="The pin marks the building outside the Pool of Tears. Go down the south stairs into the temple, past the Hall of Masks and the Hall of Ritual, to the portal on the middle level of the Hall of Bones.", s={{"The pin marks the building outside the Pool of Tears"}, {"Go down the south stairs into the temple, past the Hall of Masks and the Hall of Ritual, to the portal on the middle level of the Hall of Bones"}}}}, steps={[1]={npc="Fel'zerul", tgt="Fel'zerul", desc="Start at The Atal'ai Exile if you already did this on the main route."}, [2]={hint="Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts."}, [3]={npc="Fel'zerul", tgt="Fel'zerul"}, [4]={npc="Fel'zerul", tgt="Fel'zerul", preText="Pool of Tears"}, [5]={hint="Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands."}, [6]={npc="Atal'ai Exile", tgt="Atal'ai Exile"}, [7]={npc="Atal'ai Exile", tgt="Atal'ai Exile", preText="The Atal'ai Exile"}, [8]={npc="Atal'ai Exile", tgt="Atal'ai Exile"}, [9]={hint="Return to Fel'Zerul in Stonard."}, [10]={npc="Fel'zerul", tgt="Fel'zerul"}, [11]={npc="Fel'zerul", tgt="Fel'zerul", preText="Return to Fel'Zerul"}, [12]={npc="Witch Doctor Uzer'i", tgt="Witch Doctor Uzer'i"}, [13]={hint="Find Marvon Rivetseeker in Tanaris."}, [14]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [15]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="The Sunken Temple"}, [16]={hint="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."}, [17]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [18]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="The Stone Circle"}, [19]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="The Stone Circle"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Pick up in Steamwheedle Port, then do Feralas. Take The Prophecy of Mosh'aru after turning this in."}, [21]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port."}, [22]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [23]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="Screecher Spirits"}, [24]={hint="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", desc="Save follow-up The Ancient Egg for the Sunken Temple quest The God Hakkar. Zul'Farrak map: Theka (56.70, 31.50), Velratha (34.50, 35.80)."}, [25]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [26]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Jintha'Alor has elite packs. Do this with the Revantusk and Jintha'Alor quests.", preText="The Prophecy of Mosh'aru"}, [27]={hint="Bring the Ancient Egg to Yeh'kinya in Tanaris."}, [28]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [29]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="The Ancient Egg"}, [30]={text="The Temple of Atal'Hakkar entrance"}, [31]={hint="Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", desc="Location: Take the flat right route downstairs. Find the Altar of Hakkar on the ring. Order: Turn in at the altar before accepting step 32."}, [32]={npc="Altar of Hakkar", npcObj=true, tag="Unverified"}, [33]={hint="Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", desc="Use the correct order to avoid triggering a trap. DungeonsForever lower floor: Idol of Hakkar (50.10, 63.10). Location: Activate the six statues on the lower ring, then kill the boss in the center. Order: South → North → Southwest → Southeast → Northwest → Northeast."}, [34]={npc="Idol of Hakkar", npcObj=true, tag="Unverified", desc="DungeonsForever lower floor: Idol of Hakkar (50.10, 63.10)."}, [35]={hint="Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", desc="Location: Kill Atal'ai trolls along the lower ring and upper balconies."}, [36]={hint="The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", desc="DungeonsForever upper boss floor: Jammal'an (73.20, 38.40). Location: Clear six upper balconies, then take the east hall from the Pit of Sacrifice. Order: Kill all six balcony guards to remove the barrier."}, [37]={hint="Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", desc="Take the west passage to Hakkar's room. Get everyone inside before starting. DungeonsForever upper boss floor: Hakkar event (21.20, 45.10). Location: Take the west hall from the Pit of Sacrifice. Group up before using the egg. Order: West hall: Hakkar. East hall: Jammal'an."}, [38]={npc="Essence of Eranikus", npcObj=true, tag="Unverified", desc="Kill the Shade of Eranikus and right-click its drop to start the quest. DungeonsForever upper boss floor: Shade of Eranikus (66.40, 87.40)."}, [39]={hint="Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", desc="DungeonsForever upper boss floor: Essence Font (70.70, 81.50). Location: Kill the four dragonkin bosses. Use the Font in the Dreamer's room. Order: Loot the essence from the final boss. Accept and turn in in the same room."}, [40]={npc="Essence Font", npcObj=true, tag="Unverified", desc="DungeonsForever upper boss floor: Essence Font (70.70, 81.50)."}, [41]={npc="Fel'zerul", tgt="Fel'zerul"}, [42]={npc="Atal'ai Exile", tgt="Atal'ai Exile"}, [43]={npc="Yeh'kinya", tgt="Yeh'kinya"}}},
    ["04-41"] = {name="Un'Goro Crater: Marshal's Refuge", short="Marshal's Refuge", tips={{k="取捨", text="Collect Power Crystals, dinosaur parts, tar, and Bloodpetal flowers as you go. Watch for patrolling devilsaurs near the middle of the crater."}, {k="取捨", text="Save It's a Secret to Everybody for Winterspring and Volcanic Activity and Marvon's Workshop for Ratchet. Save The Bait for Lar'korwi, the three pylons, the gorillas, the Fire Plume Ridge rescue, and It's Dangerous to Go Alone for Marshal's Refuge."}, {k="取捨", text="If you've collected the claws for Bone-Bladed Weapons, turn in to Jes'rimon in Orgrimmar (55.52, 34.08) next time you pass through. Skip Pawn Captures Queen if you don't want to hatch the egg and fight the boss in the south."}, {k="提醒", text="Just short of level 54? Grind tar mobs in the north (51.77, 25.14) or diemetradons east of Marshal's Refuge (50.78, 19.90).", s={{"Just short of level 54?"}, {"Grind tar mobs in the north (51.77, 25.14) or diemetradons east of Marshal's Refuge (50.78, 19.90)"}}}}, danger={[1]="Level 54-55 elite devilsaurs patrol Un'Goro. Follow the east edge north to camp and give them a wide berth."}, grind={[1]={mob="Tar Lurker", note="Normal tar mobs south of camp. Pick up Super Sticky Tar as you go. Pull singles from the water's edge and watch for devilsaur patrols."}, [2]={mob="Un'Goro Thunderer", note="Normal gorillas outside the northeastern cave. Pair with the gorilla quests. Avoid extra pulls inside. Return to the tar pits if the outside is busy."}}, supply={[1]={npc="Gryfe"}, [2]={npc="Gibbert"}, [3]={npc="Nergal"}, [4]={npc="Nergal"}}, steps={[1]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [2]={hint="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."}, [3]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [4]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [5]={hint="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."}, [6]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [7]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", desc="Save for the return to Marshal's Refuge in Un'Goro."}, [8]={hint="Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.", tag="Optional", desc="Do at Valormok only if you picked it up in Orgrimmar."}, [9]={npc="A Wrecked Raft", npcObj=true}, [10]={hint="Look around in the pond for a clue about who this wrecked raft may belong to."}, [11]={npc="A Small Pack", npcObj=true}, [12]={npc="A Small Pack", npcObj=true}, [13]={hint="Examine the items inside the pack and bring them to their owner.", desc="Keep the contents of the bag."}, [14]={text="Go north along the eastern edge to Marshal's Refuge. Avoid the devilsaurs in the middle."}, [15]={node="Marshal's Refuge", desc="Unlock the flight path with Gryfe."}, [16]={npc="Linken", tgt="Linken"}, [17]={npc="Linken", tgt="Linken", desc="Save to turn in to Donova in Winterspring."}, [18]={npc="Williden Marshal", tgt="Williden Marshal"}, [19]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [20]={npc="Shizzle", tgt="Shizzle"}, [21]={npc="Larion", tgt="Larion"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={text="Northern tar mobs → loop around camp → return to camp"}, [24]={hint="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.", desc="Pick up on the Gadgetzan/Broken Pillar leg."}, [25]={hint="Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater."}, [26]={hint="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge."}, [27]={hint="Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."}, [28]={hint="Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater."}, [29]={hint="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.", desc="Do if picked up in Ratchet before Thorium Point. Turn in on the Ratchet return."}, [30]={npc="A Mangled Journal", npcObj=true, tag="Optional", desc="Starts from a drop. Keep moving if it doesn't drop."}, [31]={hint="Return the journal to Williden Marshal somewhere in Un'Goro Crater.", tag="Optional", desc="Starts from a drop. Keep moving if it doesn't drop."}, [32]={npc="Williden Marshal", tgt="Williden Marshal", tag="Optional", desc="Starts from a drop. Keep moving if it doesn't drop."}, [33]={hint="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tag="Optional", desc="Do if accepted earlier in Tanaris. Take one southern loop before leaving."}, [34]={hint="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge."}, [35]={npc="Williden Marshal", tgt="Williden Marshal"}, [36]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [37]={npc="Shizzle", tgt="Shizzle"}, [38]={npc="Larion", tgt="Larion"}, [39]={npc="J.D. Collie", tgt="J.D. Collie"}, [40]={npc="J.D. Collie", tgt="J.D. Collie"}, [41]={npc="J.D. Collie", tgt="J.D. Collie"}, [42]={npc="J.D. Collie", tgt="J.D. Collie"}, [43]={npc="Larion", tgt="Larion", desc="Turn in at Ratchet."}, [44]={text="Fly from Marshal's Refuge to Gadgetzan and turn in any gathering quests there."}, [45]={npc="Tran'rek", tgt="Tran'rek"}, [46]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg", tag="Optional"}, [47]={hint="Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.", tag="Optional", desc="Do alongside the southern hive and flower quests."}, [48]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional"}, [49]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional", desc="Use the quest item and leave. You can skip the elite."}, [50]={hint="Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task.", tag="Optional", desc="Use the quest item and leave. You can skip the elite."}, [51]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional", desc="Use the quest item and leave. You can skip the elite."}, [52]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional", desc="Group for Sunken Temple on the next Eastern Kingdoms trip.", star={"Grizzled Pelt", {"DRUID"}}}, [53]={text="Fly from Gadgetzan to Ratchet, take the boat to Booty Bay, then fly to Kargath in the Badlands. Save the White Ravasaur Claws for Orgrimmar on your way back through Undercity."}}},
    ["04-42"] = {name="Burning Steppes: Flame Crest & Blackrock Mountain", short="Flame Crest +", tips={{k="取捨", text="Pick up Dreadmaul Rock and The Rise of the Machines in Kargath. Unlock the Flame Crest flight path before making a loop through Dreadmaul Rock and the Ruins of Thaurissan."}, {k="取捨", text="Accept Felnok Steelspring now and save the turn-in for Everlook."}, {k="取捨", text="Skip Disharmony of Flame and The Rise of the Machines if short on time. They require a trip into Blackrock Mountain or another Badlands run. Take the follow-up separately if you're running Blackrock Depths."}, {k="提醒", text="Need XP? Grind Dark Iron dwarves and golems around the Ruins of Thaurissan. If running Blackrock Depths with a group, pick up the dungeon quests in Kargath and Flame Crest first.", s={{"Need XP?"}, {"Grind Dark Iron dwarves and golems around the Ruins of Thaurissan"}, {"If running Blackrock Depths with a group, pick up the dungeon quests in Kargath and Flame Crest first"}}}}, danger={[1]="The quarry passage to Blackrock Depths is narrow, and Overmaster Pyron patrols it. Clear normal mobs at the entrance before pulling him.", [2]="Casters and patrols in the Ruins of Thaurissan can pull together. Pull from outside the broken walls and stay clear of patrol crossings."}, grind={[1]={mob="War Reaver", note="Normal golems outside the Ruins of Thaurissan. Follow the outer wall and count kills for the ruins quest. Watch for casters among the rubble."}, [2]={mob="Thaurissan Firewalker", note="Normal dwarves in the same ruins. Collect cloth and count kills. Pull from outside the broken walls to avoid adding casters and patrols."}}, supply={[1]={npc="Vahgruk"}, [2]={npc="Yuka Screwspigot"}, [3]={npc="Gruna"}, [4]={npc="Innkeeper Shul'kar"}, [5]={npc="Sranda"}, [6]={npc="Grawl"}}, steps={[1]={npc="Thal'trak Proudtusk", tgt="Thal'trak Proudtusk", desc="Accept at Kargath. Turn in at Dreadmaul Rock to the east."}, [2]={npc="Hierophant Theodora Mulvadania", tgt="Hierophant Theodora Mulvadania", desc="Accept at Kargath. Kill golems and elementals in Burning Steppes."}, [3]={npc="Thunderheart", tgt="Thunderheart", tag="Optional", desc="Accept at Kargath only if you're heading to Blackrock Mountain."}, [4]={text="Fly from Kargath to Flame Crest if unlocked. Otherwise take Blackrock Mountain through Searing Gorge into Burning Steppes and head east along the north side.", tag="Flight path locked. Travel there on foot the first time."}, [5]={hint="Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", tag="Optional", desc="Watch for patrols outside the dungeon entrance."}, [6]={node="Flame Crest", desc="Unlock the flight path with Vahgruk."}, [7]={hint="Speak with Yuka Screwspigot in the Burning Steppes.", tag="Optional", desc="Turn in only if you picked it up in Steamwheedle Port on the Tanaris leg."}, [8]={npc="Yuka Screwspigot", tgt="Yuka Screwspigot", tag="Optional"}, [9]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [10]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [11]={text="Dreadmaul Rock in the east → Ruins of Thaurissan → Kargath"}, [12]={hint="Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk."}, [13]={npc="Sha'ni Proudtusk", tgt="Sha'ni Proudtusk"}, [14]={npc="Sha'ni Proudtusk", tgt="Sha'ni Proudtusk"}, [15]={hint="Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock."}, [16]={hint="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", desc="Use the quest item first. Kill the target and loot the essence it leaves behind."}, [17]={hint="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes."}, [18]={hint="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.", desc="Kill the targets on the same trip as the tablets."}, [19]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [20]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [21]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", desc="Save to turn in to Felnok Steelspring in Everlook."}, [22]={text="Fly from Flame Crest to Kargath. Turn in Sha'ni's Nose-Ring and the shards. Turn in the Pyron quest if you've finished it."}, [23]={npc="Thal'trak Proudtusk", tgt="Thal'trak Proudtusk"}, [24]={npc="Hierophant Theodora Mulvadania", tgt="Hierophant Theodora Mulvadania"}, [25]={npc="Hierophant Theodora Mulvadania", tgt="Hierophant Theodora Mulvadania", tag="Optional", desc="Go east only for the Blackrock Depths follow-up."}, [26]={hint="Take the Elemental Shard Sample to Lotwil Veriatus.", tag="Optional", desc="Go east only for the Blackrock Depths follow-up."}, [27]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="Optional", desc="Go east only for the Blackrock Depths follow-up."}, [28]={npc="Thunderheart", tgt="Thunderheart", tag="Optional"}, [29]={text="Fly from Kargath to Undercity before crossing Western Plaguelands into Eastern Plaguelands."}}},
    ["05-d24"] = {name="Blackrock Depths", entrance="Searing Gorge (1427), 34.80, 85.30. Marks the approach to Blackrock Mountain.", pickup="Unlock Thorium Point. Visit Yuka and Maxwort at Flame Crest, then fly to Kargath for Thunderheart, the wanted poster, and Vivian. Kill Pyron outside Blackrock Depths and return to Kargath to turn in Disharmony of Flame and take Disharmony of Fire and The Last Element. Reenter Blackrock Mountain from Thorium Point or Flame Crest.", pickupS={{"Unlock Thorium Point"}, {"Visit Yuka and Maxwort at Flame Crest, then fly to Kargath for Thunderheart, the wanted poster, and Vivian"}, {"Kill Pyron outside Blackrock Depths and return to Kargath to turn in Disharmony of Flame and take Disharmony of Fire and The Last Element"}, {"Reenter Blackrock Mountain from Thorium Point or Flame Crest"}}, tips={{k="動線", text="Optional Pyron outside → Ironfury dwarves in the Detention Block and Ring of Law → Incendius at the Black Anvil → Fineous in the Hall of Crafting and the monument for the Shadowforge Key → Heart in the vault and Ribbly and the recipe in the Grim Guzzler, in either order → pass the Seven and the lava bridge for the Core Fragment. Loot elementals and golems throughout."}, {k="取捨", text="Prioritize the Kargath and Flame Crest quests on the first run. Do the vault or the Molten Core entrance if you have time."}, {k="說明", text="Enter Blackrock Mountain from the north. Descend the central chain and pass through the Grinding Quarry, past Overmaster Pyron, to the dungeon portal. You can also enter the mountain from Burning Steppes (29.40, 38.30).", s={{"Enter Blackrock Mountain from the north"}, {"Descend the central chain and pass through the Grinding Quarry, past Overmaster Pyron, to the dungeon portal"}, {"You can also enter the mountain from Burning Steppes (29.40, 38.30)"}}}}, steps={[1]={npc="Yuka Screwspigot", tgt="Yuka Screwspigot"}, [2]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint", tag="Optional", desc="Collect 12 Relic Coffer Keys. Pick up only if your group plans to do the vault."}, [3]={npc="WANTED", npcObj=true}, [4]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave"}, [5]={npc="Thunderheart", tgt="Thunderheart", desc="Enter Blackrock Mountain from the north. Pyron is in the Grinding Quarry."}, [6]={hint="Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment."}, [7]={npc="Thunderheart", tgt="Thunderheart"}, [8]={npc="Thunderheart", tgt="Thunderheart", preText="Disharmony of Flame"}, [9]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave", preText="Disharmony of Flame"}, [10]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright", desc="Go as a ghost to the hanging tomb in Blackrock Mountain to find Forgewright."}, [11]={hint="Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.", desc="The pin marks Franclorn's tomb in Blackrock Mountain. Visit as a ghost."}, [12]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [13]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright", preText="Dark Iron Legacy"}, [14]={npc="Lothos Riftwaker", tgt="Lothos Riftwaker", tag="Optional", desc="Level 55+. Do this on the way past the Seven to the Molten Core portal."}, [15]={text="Blackrock Depths entrance"}, [16]={hint="Venture to Blackrock Depths and destroy the vile aggressors!", desc="Location: Enter the Detention Block and clear guards toward the Ring of Law."}, [17]={hint="Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", desc="Detention Block map: Lord Incendius (56.10, 31.20). Location: Follow the Dark Iron Highway down to the Black Anvil. Kill Incendius."}, [18]={hint="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", desc="Map: Fineous in Hall of Crafting (63.40,20.50); monument (56.10,96.80). Location: Get the hammer in the Hall of Crafting. Take it to the Shrine of Thaurissan. Order: Kill Fineous Darkvire, then click the monument."}, [19]={npc="Monument of Franclorn Forgewright", npcObj=true, tag="Unverified", desc="DungeonsForever map: Monument of Franclorn Forgewright (56.10, 96.80)."}, [20]={hint="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", desc="Location: Kill elementals and golems along the Dark Iron Highway. Pyron is outside."}, [21]={hint="Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", desc="DungeonsForever map: talk to Ribbly by the tables (49.20, 63.90) to start the fight. Location: Cross Shadowforge City to the Grim Guzzler. Find Ribbly by the tables."}, [22]={hint="Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", desc="Clear the mobs around the bar with your group before starting the fight. Break the kegs at 47.60, 57.50. Both factions loot the recipe from the same mob. Location: Break three kegs in the back room of the Grim Guzzler and wait for Hurley."}, [23]={hint="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", tag="Optional", desc="DungeonsForever map: Black Vault (61.30, 68.50), quest The Heart of the Mountain. Location: Open 12 relic coffers in the Black Vault, then loot the Heart in the hidden room."}, [24]={hint="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", tag="Optional", desc="DungeonsForever map: Core Fragment (65.70, 29.60), quest Attunement to the Core. Location: Pass the Seven and cross the lava bridge. The fragment is by the Core portal."}, [25]={npc="Thunderheart", tgt="Thunderheart"}, [26]={npc="Warlord Goretooth", tgt="Warlord Goretooth"}, [27]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave"}, [28]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave"}, [29]={npc="Yuka Screwspigot", tgt="Yuka Screwspigot"}, [30]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint", tag="Optional"}, [31]={npc="Lothos Riftwaker", tgt="Lothos Riftwaker", tag="Optional"}}},
    ["04-43"] = {name="Eastern Plaguelands: Light's Hope Chapel", short="Light's Hope Chapel", tips={{k="取捨", text="Unlock Light's Hope Chapel on your first Eastern Plaguelands visit and pick up the book there. Save the main Tirion, Nathanos, and Darrowshire quests for later."}, {k="取捨", text="Quest Augustus' Receipt Book is a Terrordale detour. Skip it if you're just passing through. If the video shows the book inside the chapel, that's Forever quest A Study of the Light."}, {k="提醒", text="Below level 54? Grind normal plague mobs along the road outside Light's Hope, or normal undead at Felstone Field (around 38, 56) on the next leg.", s={{"Below level 54?"}, {"Grind normal plague mobs along the road outside Light's Hope, or normal undead at Felstone Field (around 38, 56) on the next leg"}}}}, danger={[1]="The undead inside the house and on the stairs can pull together while you're looking for the ledger. Clear downstairs first."}, grind={[1]={mob="Carrion Grub", note="Normal Carrion Grubs southwest of Light's Hope Chapel. Pull singles along the road and collect Slabs of Carrion Worm Meat for Tirion. Avoid higher-level undead packs north."}, [2]={mob="Noxious Plaguebat", note="Normal bats in the clearing west of Light's Hope Chapel. Pair with the plaguebat quest and return to resupply. Shift south if the area is busy."}}, supply={[1]={npc="Georgia"}, [2]={npc="Jessica Chambers"}, [3]={npc="Craftsman Wilhelm"}, [4]={npc="Jessica Chambers"}, [5]={npc="Caretaker Alen"}}, steps={[1]={hint="Bring the Tablet of Markri to Andron Gant in Undercity.", tag="Optional"}, [2]={npc="Andron Gant", tgt="Andron Gant", tag="Optional"}, [3]={text="Head east from outside Undercity through the Bulwark and Western Plaguelands. Follow the southern road east through Eastern Plaguelands and stay out of Stratholme."}, [4]={npc="Augustus the Touched", tgt="Augustus the Touched", tag="Optional", desc="Off the main road. Skip if you're only unlocking the Light's Hope flight path."}, [5]={hint="Bring Augustus' Receipt Book to Augustus the Touched in Terrordale.", tag="Optional", desc="Off the main road. Skip if you're only unlocking the Light's Hope flight path."}, [6]={npc="Augustus the Touched", tgt="Augustus the Touched", tag="Optional", desc="Off the main road. Skip if you're only unlocking the Light's Hope flight path."}, [7]={node="Light's Hope Chapel", desc="Unlock the Horde flight path with Georgia."}, [8]={npc="Book", tgt="Jennea Cannon", npcObj=true, desc="The Forever book is at the back left of the chapel. Turn it in in Undercity."}, [9]={hint="Use/collect: Book", desc="Coordinates from QuestieDB Forever."}, [10]={text="Fly from Light's Hope Chapel to Undercity. Turn in library quests if you have any."}, [11]={npc="Oran Snakewrithe", tgt="Oran Snakewrithe", desc="Oran and Owen Thadd are in Undercity's Magic Quarter. Check which offers the turn-in."}, [12]={hint="Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", tag="Optional, Target: Gasher / Zul'Lor / Gasher / Hukku / Mijan / Hukku / Zolo / Loro / Loro", desc="Bring this along with the other Swamp of Sorrows quests for Sunken Temple."}, [13]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional", desc="Turn in at the north entrance to Blasted Lands. Diamond Flask is a reward choice.", star={"Diamond Flask", {"WARRIOR"}}}, [14]={hint="Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Optional", desc="Group up at Stonard for Sunken Temple. Find Morphaz, the green dragon."}, [15]={hint="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", tag="Optional", desc="Group up at Stonard for Sunken Temple. Find Morphaz, the green dragon."}, [16]={hint="Return the Azure Key to Lord Jorach Ravenholdt.", tag="Optional", desc="Group up at Stonard for Sunken Temple. Find Morphaz, the green dragon."}, [17]={npc="Lord Jorach Ravenholdt", tgt="Lord Jorach Ravenholdt", tag="Optional", desc="Fly Stonard to Tarren Mill, then turn in at the manor. Ebon Mask is a reward option.", star={"Duskbat Drape", {"ROGUE"}}}, [18]={hint="Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.", tag="Optional", desc="Group for Sunken Temple. Tell the party you need the snake statues downstairs."}, [19]={hint="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", tag="Optional", desc="Group up at Stonard for Sunken Temple. Find Morphaz, the green dragon."}, [20]={text="Stay in the Eastern Kingdoms. The next leg goes east from Undercity to the Bulwark."}}},
    ["04-44"] = {name="Western Plaguelands: The Bulwark", short="The Bulwark", tips={{k="交通", text="Walk to the Bulwark. Head west for Tirisfal Glades or Undercity, and take the zeppelin outside Undercity back to Orgrimmar."}, {k="取捨", text="The Felstone Field cauldron and package are at the same farm. Turn in Better Late Than Never and The Jeremiah Blues together when you get back to town."}, {k="取捨", text="Do the first cauldron now. Save Target: Dalson's Tears at Dalson's Tears and the Scholomance quests at Andorhal for the next loop. Do Good Luck Charm (/Two Halves Become One) when you return to Western Plaguelands."}, {k="提醒", text="Below level 55? Grind normal skeletons and ghouls around Felstone Field (around 38, 56). Avoid higher-level elites in Andorhal.", s={{"Below level 55?"}, {"Grind normal skeletons and ghouls around Felstone Field (around 38, 56)"}, {"Avoid higher-level elites in Andorhal"}}}}, danger={[1]="Araj the Summoner is a level 61 elite in central Andorhal. Stick to the edge of town when marking towers and stay out of the square."}, grind={[1]={note="Normal undead at Felstone Field on the cauldron loop. Pull outside the fields, away from the buildings, and keep moving if questers are there."}, [2]={mob="Slavering Ghoul", note="Normal ghouls on the same farm. Kill them between skeleton respawns. Don't chase mobs into Andorhal."}}, supply={[1]={npc="Argent Quartermaster Hasana"}, [2]={npc="Michael Garrett"}, [3]={npc="Innkeeper Norman"}, [4]={npc="Innkeeper Norman"}, [5]={npc="Eleanor Rusk"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezekiel Graves"}}, steps={[1]={text="Leave Undercity and follow the east road through Tirisfal Glades to the Bulwark (83.13, 68.94). Keep the Undercity flight path handy for city turn-ins at the end of this leg."}, [2]={npc="High Executor Derrington", tgt="High Executor Derrington", desc="Take Bottled Flame from the chest by Derington. Bring the Scourge Banner too."}, [3]={hint="Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.", desc="Burn the tent with the Bottled Flame, then use the banner."}, [4]={npc="High Executor Derrington", tgt="High Executor Derrington", desc="Burn the tent with the Bottled Flame, then use the banner."}, [5]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [6]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [7]={hint="Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands."}, [8]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [9]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [10]={text="Go east from the Bulwark to Felstone Field. Take the Scourge Cauldron sample, then check Janice's house and the stables."}, [11]={hint="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", desc="Check that you have the empty vial from the quest giver."}, [12]={npc="Scourge Cauldron", npcObj=true}, [13]={npc="Scourge Cauldron", npcObj=true, desc="Collect the sample, then accept the return quest at the same cauldron."}, [14]={npc="Janice Felstone", tgt="Janice Felstone"}, [15]={hint="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.", desc="Interact with the package inside the stable."}, [16]={npc="Janice's Parcel", npcObj=true}, [17]={npc="Janice's Parcel", npcObj=true, desc="Choose Horde quest Better Late Than Never. Collect the package here and turn it in at Undercity."}, [18]={text="Go east from Felstone Field to Dalson's Tears. Do the farmhouse diary and key now. Save the Scourge Cauldron for next time."}, [19]={npc="Mrs. Dalson's Diary", npcObj=true}, [20]={hint="Complete the quest objectives."}, [21]={npc="Mrs. Dalson's Diary", npcObj=true}, [22]={npc="Outhouse", npcObj=true, desc="Read the journal, then find a Wandering Skeleton. Open the outhouse to spawn the farmer."}, [23]={hint="Loot from: Wandering Skeleton", desc="Read the journal, then find a Wandering Skeleton. Open the outhouse to spawn the farmer."}, [24]={npc="Outhouse", npcObj=true, desc="Read the journal, then find a Wandering Skeleton. Open the outhouse to spawn the farmer."}, [25]={npc="Locked Cabinet", npcObj=true, desc="Clear around the outhouse. Open the cache and turn in right away."}, [26]={hint="Loot from: Farmer Dalson", desc="Clear around the outhouse. Open the cache and turn in right away."}, [27]={npc="Locked Cabinet", npcObj=true, desc="Clear around the outhouse. Open the cache and turn in right away."}, [28]={text="Circle Andorhal, visiting each tower, then return to the Bulwark. Wait for high-level guards to patrol away before approaching the doors."}, [29]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.", desc="Use the torch at the doorway. You can leave the guards inside."}, [30]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [31]={hint="Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."}, [32]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [33]={text="Return to Undercity and turn in the package near the guild registrar."}, [34]={hint="Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration."}, [35]={npc="Royal Overseer Bauhaus", tgt="Royal Overseer Bauhaus"}, [36]={npc="Royal Overseer Bauhaus", tgt="Royal Overseer Bauhaus"}, [37]={hint="Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone. If he is, then perhaps he'd like the package Janice Felstone made for him."}, [38]={npc="Jeremiah Payson", tgt="Jeremiah Payson"}, [39]={npc="Jeremiah Payson", tgt="Jeremiah Payson", desc="Keep the half amulet. Turn in at Felstone Field on the Bulwark visit."}, [40]={npc="Knight of Mourning", tag="Optional, Unverified", desc="After Undercity turn-ins, look southwest before boarding. The knight has several spawns."}, [41]={hint="Speak with the Knight of Mourning to learn more about his unfinished quest.", tag="Optional, Unverified", desc="After Undercity turn-ins, look southwest before boarding. The knight has several spawns."}, [42]={npc="Knight of Mourning", tag="Optional, Unverified", desc="After Undercity turn-ins, look southwest before boarding. The knight has several spawns."}, [43]={npc="Knight of Mourning", tag="Optional, Unverified", desc="Finish The Knight of Mourning. Run Blackmaw Hold after crossing to Orgrimmar. Keep the relic for Tirisfal.", star={"Sword of Mourning", {"PALADIN"}}}, [44]={hint="Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", tag="Optional", desc="Kill spiders, bears, and vultures while doing the Plaguelands farm quests."}, [45]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Fly to Tarren Mill and turn in to Bath'rah before leaving Undercity."}, [46]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Accept with a Sunken Temple group. Finish on the next Eastern Kingdoms visit.", star={"Enamored Water Spirit", {"SHAMAN"}}}, [47]={text="Take the Orgrimmar zeppelin from the tower outside Undercity."}}},
    ["04-45"] = {name="Felwood: South & Bloodvenom Post", short="Felwood: South +", tips={{k="交通", text="Unlock Bloodvenom Post now and leave from there on the next leg. If passing through Splintertree Post, follow the main road around the Alliance town and its guards."}, {k="取捨", text="Kill southern Deadwood furbolgs to start earning Timbermaw reputation. Do Jaedenar, the southern lore quests, and the Jadefire moonwell in one loop."}, {k="取捨", text="Accept Cleansing Felwood and collect the Blood Amber up north. Save the turn-in for your next trip south."}, {k="提醒", text="Below level 55? Grind normal elementals on the edge of Shatter Scar Vale (around 41, 42) or Deadwood furbolgs for Timbermaw reputation.", s={{"Below level 55?"}, {"Grind normal elementals on the edge of Shatter Scar Vale (around 41, 42) or Deadwood furbolgs for Timbermaw reputation"}}}}, danger={[1]="Shatter Scar Vale elementals spawn in pairs along the pit. Pull from the top of the ramp and stay out of the bottom to avoid the next pack."}, grind={[1]={mob="Entropic Beast", note="Normal elementals around Shatter Scar Vale count toward the kill quest. If the entrance is busy, work from the edge inward."}, [2]={mob="Entropic Horror", note="Mix higher-level normal elementals with the other elementals at the same spot. Watch for paired spawns in the narrow terrain."}}, supply={[1]={npc="Brakkar"}, [2]={npc="Altsoba Ragetotem"}, [3]={npc="Bale"}, [4]={npc="Bale"}, [5]={npc="Innkeeper Kaylisk"}, [6]={npc="Innkeeper Kaylisk"}}, steps={[1]={npc="Jes'rimon", tgt="Jes'rimon", tag="Optional", desc="Accept at Valormok. Farm White Ravasaur Claws in Un'Goro."}, [2]={text="Fly to Splintertree Post, follow the road west, then take the north road into Felwood. Stop first at Emerald Sanctuary."}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Maybess Riverbreeze", tgt="Maybess Riverbreeze", desc="Collect Blood Amber in north Felwood. Kill treants next. Turn in back south."}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [6]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [7]={hint="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.", desc="Earn Timbermaw rep. If still hostile, grind at the northern camp later."}, [8]={npc="Grazle", tgt="Grazle"}, [9]={npc="Grazle", tgt="Grazle", desc="Accept now. Turn in at the north end of Felwood on the next leg."}, [10]={text="Follow the main road north through Jaedenar to Bloodvenom Post."}, [11]={node="Bloodvenom Post", desc="Unlock the flight path with Brakkar."}, [12]={hint="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood."}, [13]={npc="Winna Hazzard", tgt="Winna Hazzard"}, [14]={npc="Dreka'Sur", tgt="Dreka'Sur"}, [15]={text="Follow the road north to Shatter Scar Vale for the corruption survey. Loop back to Emerald Sanctuary via the western satyr moonwell and southern orc camp."}, [16]={hint="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", desc="Visit the survey area too. Killing elementals alone won't complete it."}, [17]={hint="Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post.", desc="This moonwell and the one in central Jaedenar are separate objectives."}, [18]={hint="Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.", desc="Target is deep in the south camp. Clear along the ramp before pulling."}, [19]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [20]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [21]={npc="Greta Mosshoof", tgt="Greta Mosshoof", desc="Fill the empty canteen at the central Jaedenar moonwell on your next visit."}, [22]={text="Return to Bloodvenom Post to turn in the water sample and Rell's claw. Restock if needed."}, [23]={npc="Winna Hazzard", tgt="Winna Hazzard"}, [24]={npc="Dreka'Sur", tgt="Dreka'Sur"}, [25]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Turn in to Ogtinc in Azshara before Felwood. Devilsaur Eye is a reward option.", star={"Devilsaur Eye", {"HUNTER"}}}, [26]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Turn in to Xylem in Azshara before Felwood. Fire Ruby is a reward option.", star={"Fire Ruby", {"MAGE"}}}, [27]={npc="Niby the Almighty", tgt="Niby the Almighty", tag="Optional"}, [28]={hint="Speak with Impsy in Felwood.", tag="Optional"}, [29]={npc="Impsy", tgt="Impsy", tag="Optional"}, [30]={npc="Impsy", tgt="Impsy", tag="Optional", desc="Get Jaedenar essence first. Fly to Azshara via Orgrimmar or to Blasted Lands via Stonard."}, [31]={npc="Impsy", tgt="Impsy", tag="Optional", desc="If you took An Imp's Request from a trainer, turn it in first, then accept The Wrong Stuff."}, [32]={hint="Bring a piece of felcloth to Impsy in Felwood.", tag="Optional", desc="If you took An Imp's Request from a trainer, turn it in first, then accept The Wrong Stuff."}, [33]={npc="Impsy", tgt="Impsy", tag="Optional", desc="If you took An Imp's Request from a trainer, turn it in first, then accept The Wrong Stuff."}, [34]={npc="Impsy", tgt="Impsy", tag="Optional"}, [35]={hint="Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.", tag="Optional"}, [36]={npc="Impsy", tgt="Impsy", tag="Optional"}, [37]={npc="Impsy", tgt="Impsy", tag="Optional", desc="Accept if you plan to run Sunken Temple during the Eastern Kingdoms leg.", star={"Soul Harvester", {"WARLOCK"}}}, [38]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional", desc="See Greta at Emerald Sanctuary. Blessed Prayer Beads are a reward choice.", star={"Blessed Prayer Beads", {"PRIEST"}}}}},
    ["04-46"] = {name="Felwood: Bloodvenom Post to Timbermaw Hold", short="Bloodvenom Post +", tips={{k="交通", text="Restock at Bloodvenom Post, then follow the main road north. At the fork inside the tunnel, take the Winterspring exit."}, {k="取捨", text="Do Blood Amber and the Irontree strength quest together in northern Irontree Woods. Grind Deadwood reputation last."}, {k="取捨", text="Keep the items for Cleansing Felwood if you're done. Turn in on your next Emerald Sanctuary visit. Save Seeking Spiritual Aid for Ratchet."}, {k="提醒", text="Reach Unfriendly with Timbermaw Hold to pass safely through the tunnel. If still Hostile or below level 56, grind furbolgs at northern Deadwood Village (around 62, 8).", s={{"Reach Unfriendly with Timbermaw Hold to pass safely through the tunnel"}, {"If still Hostile or below level 56, grind furbolgs at northern Deadwood Village (around 62, 8)"}}}}, danger={[1]="If you're still Hostile with Timbermaw Hold, the tunnel guards can pull in groups. Grind Deadwood furbolgs outside until Unfriendly before going through."}, grind={[1]={mob="Deadwood Avenger", note="Normal furbolgs in northern Deadwood Village. Grind rep and collect feathers before Timbermaw Hold. Clear around the tents first to avoid adds."}, [2]={mob="Deadwood Den Watcher", note="Normal furbolgs near the main road in the same village. Pick off singles by the road if a rep group is there. Leave Timbermaw guards alone."}}, supply={[1]={npc="Brakkar"}, [2]={npc="Altsoba Ragetotem"}, [3]={npc="Bale"}, [4]={npc="Bale"}}, steps={[1]={npc="Winna Hazzard", tgt="Winna Hazzard"}, [2]={npc="Trull Failbane", tgt="Trull Failbane", desc="Kill owlbeasts in Winterspring, then turn in at Bloodvenom Post."}, [3]={text="Go south to Jaedenar's central moonwell, collect water and turn it in at Emerald Sanctuary. Release the kitten at the Jadefire moonwell afterward."}, [4]={hint="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood."}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [6]={npc="Greta Mosshoof", tgt="Greta Mosshoof", desc="Save the turn-in for Islen Waterseer south of Ratchet."}, [7]={hint="Take Winna's kitten to the corrupted moonwell, release it, then bring it back to Winna.", desc="Walk with the kitten. Click it by Winna before turning in."}, [8]={npc="Winna Hazzard", tgt="Winna Hazzard"}, [9]={text="Follow the main road north from Bloodvenom Post through Irontree Woods and Deadwood Village. Find Nafien at the Timbermaw entrance."}, [10]={hint="Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.", desc="Save the items for Maybess when you next visit south Felwood."}, [11]={hint="Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.", tag="If already accepted", desc="Requires pickup at Camp Mojache. Turn in there."}, [12]={hint="Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold."}, [13]={npc="Nafien", tgt="Nafien"}, [14]={npc="Nafien", tgt="Nafien"}, [15]={hint="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", desc="Check Timbermaw rep after the north camp. If hostile, grind Deadwood until Unfriendly."}, [16]={npc="Nafien", tgt="Nafien"}, [17]={npc="Nafien", tgt="Nafien", desc="Take the Winterspring exit from the cave and find Salfa outside."}, [18]={text="At Unfriendly with Timbermaw Hold, enter the tunnel and take the Winterspring exit. Avoid attacking the Timbermaw furbolgs."}}},
    ["04-47"] = {name="Winterspring: Everlook", tips={{k="交通", text="Unlock Everlook's flight path and set your Hearthstone. Fly to Camp Mojache next. If its flight path is locked, fly to Freewind Post and take the road west to Feralas to unlock it."}, {k="取捨", text="Turn in Donova's quests at Frostfire Hot Springs and kill owlbeasts as you go. Do the Everlook yetis and chimaeras on the same loop."}, {k="取捨", text="Ursius is elite, and Winterfall Activity sends you back west to the cave. Do them if you have a group or still need XP."}, {k="取捨", text="Keep the Everlook report and Duke Nicholas's book in your quest log. Turn both in on the next Eastern Kingdoms loop."}, {k="提醒", text="Below level 56? Grind normal yetis east of Everlook (around 64, 40) or furbolgs outside Winterfall Village. Avoid the elite patrol.", s={{"Below level 56?"}, {"Grind normal yetis east of Everlook (around 64, 40) or furbolgs outside Winterfall Village"}, {"Avoid the elite patrol"}}}}, danger={[1]="Ursius, an elite Shardtooth bear, patrols north of Everlook. Give him a wide berth while grinding normal bears. Do his quest with a group.", [2]="Shamans and furbolg patrols can pull together in Winterfall Village. If you need XP, pick off lone guards outside."}, grind={[1]={mob="Ice Thistle Yeti", note="Normal yetis east of Everlook, near supplies. Collect fur as you go. Start at the foot of the mountain if the cave mouth is busy."}, [2]={mob="Winterfall Den Watcher", note="Normal furbolgs outside Winterfall Village for Timbermaw rep and drops. Avoid elite patrols and linked casters inside."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Innkeeper Vizzie"}, [3]={npc="Nixxrak"}, [4]={npc="Innkeeper Vizzie"}, [5]={npc="Wixxrak"}}, steps={[1]={hint="Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.", tag="If accepted on the Bloodvenom Post/Timbermaw Hold leg"}, [2]={npc="Salfa", tgt="Salfa", tag="If accepted on the Bloodvenom Post/Timbermaw Hold leg"}, [3]={npc="Salfa", tgt="Salfa", tag="Optional", desc="Do in Winterfall Village east of Everlook. Turn in on the next trip west to the tunnel."}, [4]={text="Head south from the tunnel to Frostfire Hot Springs and pick up Donova's furbolg quests before going to the western Winterfall camp."}, [5]={hint="Take Linken's Sword to Donova Snowden in Winterspring.", tag="If accepted on the Marshal's Refuge leg"}, [6]={npc="Donova Snowden", tgt="Donova Snowden", tag="If accepted on the Marshal's Refuge leg"}, [7]={npc="Donova Snowden", tgt="Donova Snowden", desc="Get the elixir in north Feralas. Turn in when you return to Frostfire Hot Springs."}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={hint="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics."}, [10]={npc="Empty Firewater Flask", npcObj=true, tag="If it drops", desc="Right-click Empty Firewater Flask to start the chain. Farm Winterfall furbolgs if needed."}, [11]={npc="Donova Snowden", tgt="Donova Snowden"}, [12]={hint="Bring the Empty Firewater Flask to Donova Snowden in Winterspring.", tag="If you have the Firewater Flask"}, [13]={npc="Donova Snowden", tgt="Donova Snowden", tag="If you have the Firewater Flask"}, [14]={npc="Donova Snowden", tgt="Donova Snowden", desc="Save for the next north Felwood trip. Find the cauldron inside the Deadwood tent."}, [15]={text="Head east to Everlook and clear both kinds of wildkin on the way."}, [16]={node="Everlook", desc="Unlock the flight path with Yugrek."}, [17]={text="Set your hearth with Innkeeper Vizzie (61.36, 38.83)."}, [18]={hint="Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts.", tag="If accepted on the Bloodvenom Post/Timbermaw Hold leg", desc="Save the turn-in for your next visit to Bloodvenom Post."}, [19]={hint="Give Tinkee's Letter to Felnok Steelspring.", tag="If accepted on the Flame Crest/Blackrock Mountain leg"}, [20]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="If accepted on the Flame Crest/Blackrock Mountain leg"}, [21]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Requires quest Felnok Steelspring"}, [22]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [23]={npc="Gregor Greystone", tgt="Gregor Greystone", desc="Turn in to Argent Officer Garush at the Bulwark next time."}, [24]={npc="Gregor Greystone", tgt="Gregor Greystone", desc="Save the turn-in for Light's Hope Chapel in Eastern Plaguelands."}, [25]={npc="Jessica Redpath", tgt="Jessica Redpath", desc="Bring the Everlook report too. Turn this in at Darrowshire in Eastern Plaguelands."}, [26]={npc="Storm Shadowhoof", tgt="Storm Shadowhoof", tag="Elite, Optional"}, [27]={text="Clear the yeti cave and surrounding area east of Everlook, then loop north and east if needed."}, [28]={hint="Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.", desc="Bring a yeti horn for the next quest. Pick up Are We There, Yeti? on a later trip."}, [29]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [30]={hint="Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", tag="Requires quest Felnok Steelspring"}, [31]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Requires quest Felnok Steelspring"}, [32]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional", desc="Report back to Tinkee the next time you pass through Burning Steppes."}, [33]={hint="Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius.", tag="Elite, Optional", desc="Group up for the level-56 elite."}, [34]={npc="Storm Shadowhoof", tgt="Storm Shadowhoof", tag="Elite, Optional"}, [35]={hint="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", tag="Return to the cave entrance, Optional"}, [36]={npc="Salfa", tgt="Salfa", tag="Return to the cave entrance, Optional"}}},
    ["05-d25"] = {name="Lower Blackrock Spire", entrance="Searing Gorge (1427), 34.80, 85.30. Marks the approach to Blackrock Mountain.", pickup="Unlock Flame Crest and return at level 55 for both quests from Kibler. See Kilram in Everlook. After crossing to the Eastern Kingdoms, fly to Kargath for quests from Warlord Goretooth, Galamav the Marksman, and Lexlort. Approach Blackrock Mountain from Searing Gorge or Flame Crest and take the shared portal on the upper east balcony. Turn in Warlord's Command in Kargath, then take and keep Eitrigg's Wisdom.", pickupS={{"Unlock Flame Crest and return at level 55 for both quests from Kibler"}, {"See Kilram in Everlook"}, {"After crossing to the Eastern Kingdoms, fly to Kargath for quests from Warlord Goretooth, Galamav the Marksman, and Lexlort"}, {"Approach Blackrock Mountain from Searing Gorge or Flame Crest and take the shared portal on the upper east balcony"}, {"Turn in Warlord's Command in Kargath, then take and keep Eitrigg's Wisdom"}}, tips={{k="動線", text="Lower entrance → Omokk → Vosh'gajin → Bijou and her belongings down the ramp → Voone → eggs and Mother Smolderweb → Halycon and Gizrul → Wyrmthalak. Loot the gems from Omokk, Voone and Wyrmthalak."}, {k="取捨", text="Prioritize the three bosses' documents, worgs, eggs, and Bijou. Skip the seal chain if someone can open the upper door."}, {k="說明", text="Lower Blackrock Spire is available at launch. For the surface entrance, use Burning Steppes (29.40, 38.30). Follow the uphill route inside to the east ledge. After entering, go down to the right.", s={{"Lower Blackrock Spire is available at launch"}, {"For the surface entrance, use Burning Steppes (29.40, 38.30)"}, {"Follow the uphill route inside to the east ledge"}, {"After entering, go down to the right"}}}}, steps={[1]={npc="Kilram", tgt="Kilram"}, [2]={npc="Kibler", tgt="Kibler"}, [3]={npc="Kibler", tgt="Kibler"}, [4]={npc="Warlord Goretooth", tgt="Warlord Goretooth", desc="If no quest window opens, talk to the NPC and use the orders from your bags."}, [5]={npc="Galamav the Marksman", tgt="Galamav the Marksman"}, [6]={npc="Lexlort", tgt="Lexlort"}, [7]={text="Lower Blackrock Spire entrance"}, [8]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional, Unverified", desc="Level 57+. Talk to the Scarshield Infiltrator on the upper balcony: that's Vaelan."}, [9]={hint="Travel to Blackrock Spire and find out what happened to Bijou.", desc="Location: Head down the ramp from Vosh'gajin's room. Look for Bijou on the side platform."}, [10]={npc="Bijou", tgt="Bijou", tag="Unverified"}, [11]={npc="Bijou", tgt="Bijou", tag="Unverified", preText="Operative Bijou"}, [12]={hint="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.", desc="Location: From Bijou's platform, return to the center, then search the lower level."}, [13]={npc="Bijou", tgt="Bijou", tag="Unverified"}, [14]={npc="Bijou", tgt="Bijou", tag="Unverified", preText="Bijou's Belongings"}, [15]={hint="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.", desc="Location: Loot eggs along the webbed tunnels. Clear the spiders around each clutch first."}, [16]={hint="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", desc="DungeonsForever map: Shadow Hunter Vosh'gajin (55.50, 69.40). Location: Pass Omokk and follow the tunnel to Shadow Hunter Vosh'gajin. Order: Kill War Master Voone, then take the ramp in his room to Bijou."}, [17]={hint="Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.", desc="Tell the group to leave a worg pup alive. Keep it out of AoE. Location: Past the spiders and troll fork, enter the wolf room and cage a pup."}, [18]={hint="Slay Halycon, pack mistress of the Bloodaxe worg.", desc="Location: Go right at the fork after the spiders. Take the left side into the wolf den."}, [19]={hint="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", desc="The document can move. Check each of the first three rooms as you reach it. Map: Omokk 35.10,55.30; Voone 52.50,54.90; Wyrmthalak 57.80,60.50. Check each room. Location: Check each of the three bosses' rooms and Urok's tribute pile for the documents. Order: Omokk → Voone → Wyrmthalak."}, [20]={hint="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.", tag="Optional", desc="Agree on gem and seal loot first. For UBRS, only one player needs a finished seal. Map: Omokk 35.10,55.30; Voone 52.50,54.90; Wyrmthalak 57.80,60.50. Check each room. Location: Loot one gem from each boss. Check trash for the Unadorned Seal. Order: Omokk → Voone → Wyrmthalak."}, [21]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional, Unverified"}, [22]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional, Unverified", preText="Seal of Ascension"}, [23]={hint="Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath."}, [24]={npc="Warlord Goretooth", tgt="Warlord Goretooth"}, [25]={npc="Galamav the Marksman", tgt="Galamav the Marksman"}, [26]={npc="Lexlort", tgt="Lexlort"}, [27]={npc="Kibler", tgt="Kibler"}, [28]={npc="Kibler", tgt="Kibler"}, [29]={npc="Kilram", tgt="Kilram"}, [30]={npc="Warlord Goretooth", tgt="Warlord Goretooth", desc="Save for Orgrimmar. See Eitrigg in the Valley of Wisdom.", preText="Warlord's Command"}, [31]={hint="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.", tag="Optional", desc="Group for elites. Stop damage before controlling the dragon."}, [32]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional, Unverified", desc="Find Vaelan inside the Lower Blackrock Spire entrance."}}},
    ["04-48"] = {name="Feralas: Camp Mojache (short visit)", short="Feralas: Camp Mojache", tips={{k="交通", text="Fly Everlook → Camp Mojache → Ratchet. If you're due to turn in at Booty Bay, take the boat from Ratchet."}, {k="取捨", text="Accept The Strength of Corruption on the Camp Mojache and Dire Maul leg, do it in Felwood, then turn it in on your return to camp."}, {k="取捨", text="The coastal quests are west of camp. Don't go looking for the beacon if it hasn't dropped. Add the coast only if you need XP or plan to visit the Twin Colossals."}, {k="提醒", text="There's no separate level target here. If you're still below 56, do the next stop's turn-ins first and catch up later on mobs your level.", s={{"There's no separate level target here"}, {"If you're still below 56, do the next stop's turn-ins first and catch up later on mobs your level"}}}}, danger={[1]="Use Zorbin's Ultra-Shrinker on the giants at the Forgotten Coast before fighting them. Wait for the water elementals to move away and pull one at a time."}, grind={[1]={mob="Northspring Windcaller", note="If you've turned in at Northspring, clear normal harpies outside for quest drops. If you're still far from the next level, grind in Winterspring."}, [2]={mob="Ice Thistle Yeti", note="If below 56, grind here before leaving Everlook. Normal yetis cluster here, and the outer slopes are easier to pull than the cave mouth."}}, supply={[1]={npc="Shyn"}, [2]={npc="Innkeeper Greul"}, [3]={npc="Cawind Trueaim"}, [4]={npc="Innkeeper Greul"}, [5]={npc="Cawind Trueaim"}, [6]={npc="Tarhus"}}, steps={[1]={text="Fly from Everlook to Camp Mojache. Turn in the Felwood side quest you picked up on the Camp Mojache and Rage Scar Hold leg. Head north if you've picked up The Videre Elixir."}, [2]={npc="Talo Thornhoof", tgt="Talo Thornhoof", tag="If done on the Bloodvenom Post/Timbermaw Hold leg"}, [3]={text="If you have The Videre Elixir, follow the road west to the fork, then go toward the Twin Colossals and Ravenwind Ruins."}, [4]={hint="Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", tag="If accepted in Everlook", desc="Get Gregan's elixir for The Videre Elixir. Don't drink it. Take it to Donova in Winterspring."}, [5]={text="Only visit the Forgotten Coast for the optional quests. If you have the Feralas beacon, pick up the Feral Scar Vale cave escort on the way.", tag="Optional"}, [6]={npc="OOX-22/FE Distress Beacon", npcObj=true, tag="Optional", desc="Accept only if you loot the locator from a mob."}, [7]={hint="Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", tag="Optional", desc="Accept only if you loot the locator from a mob."}, [8]={npc="Homing Robot OOX-22/FE", tgt="Homing Robot OOX-22/FE", tag="Optional", desc="Accept only if you loot the locator from a mob."}, [9]={npc="Homing Robot OOX-22/FE", tgt="Homing Robot OOX-22/FE", tag="Optional", desc="Watch for ambushes. Turn in at Booty Bay if you take the Ratchet boat route."}, [10]={hint="Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Watch for ambushes. Turn in at Booty Bay if you take the Ratchet boat route."}, [11]={npc="Zorbin Fandazzle", tgt="Zorbin Fandazzle", tag="Optional"}, [12]={npc="Zorbin Fandazzle", tgt="Zorbin Fandazzle", tag="Optional"}, [13]={hint="Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", tag="Optional", desc="Shrink the giants before killing them or they won't drop the quest item."}, [14]={npc="Zorbin Fandazzle", tgt="Zorbin Fandazzle", tag="Optional"}, [15]={hint="Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", tag="Optional"}, [16]={npc="Zorbin Fandazzle", tgt="Zorbin Fandazzle", tag="Optional"}, [17]={text="Return to Camp Mojache and fly to Ratchet. If you've finished Rescue OOX-22/FE! and want to turn it in, take the boat to Booty Bay and back. Otherwise do your turn-ins in Ratchet."}}},
    ["04-49"] = {name="The Barrens: Ratchet (short visit)", short="Barrens: Ratchet", tips={{k="交通", text="Fly from Ratchet to Orgrimmar, then take the Undercity zeppelin outside town. In Tirisfal Glades, follow the road east to the Bulwark."}, {k="取捨", text="Turn in the Un'Goro ash and workshop quests to Liv if done. Pick up the letter for Felwood from Islen on the coast."}, {k="取捨", text="If you have no Ratchet turn-ins, fly straight from Feralas to Orgrimmar and take the zeppelin."}, {k="提醒", text="Ratchet mobs are low level. Below 56? Grind normal yetis east of Everlook (around 64, 40) before taking the zeppelin, or normal undead at Felstone Field (around 38, 56) on the Bulwark leg.", s={{"Ratchet mobs are low level"}, {"Below 56?"}, {"Grind normal yetis east of Everlook (around 64, 40) before taking the zeppelin, or normal undead at Felstone Field (around 38, 56) on the Bulwark leg"}}}}, grind={[1]={mob="Skeletal Sorcerer", note="Ratchet is just for turn-ins and transit. If below 56, take the zeppelin and grind normal skeletons at Felstone Field. Pull from the field edge and avoid Scarlet patrols."}}, supply={[1]={npc="Bragok"}, [2]={npc="Innkeeper Wiley"}, [3]={npc="Grazlix"}, [4]={npc="Innkeeper Wiley"}, [5]={npc="Jazzik"}, [6]={npc="Horthus"}}, steps={[1]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="If taking the boat via Booty Bay, Optional"}, [2]={text="Turn in the engineering quest in Ratchet, then follow the coast south to Islen Waterseer."}, [3]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix", tag="If you collected all the ash on the Marshal's Refuge leg"}, [4]={hint="Travel to Marvon Rivetseeker's workshop in Ratchet.", tag="If accepted on the Marshal's Refuge leg"}, [5]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix", tag="If accepted on the Marshal's Refuge leg"}, [6]={hint="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.", tag="If accepted on the Bloodvenom Post/Timbermaw Hold leg"}, [7]={npc="Islen Waterseer", tgt="Islen Waterseer", tag="If accepted on the Bloodvenom Post/Timbermaw Hold leg"}, [8]={npc="Islen Waterseer", tgt="Islen Waterseer", tag="Requires quest Seeking Spiritual Aid", desc="Keep the purified water for Greta at Emerald Sanctuary later."}, [9]={text="Fly from Ratchet to Orgrimmar and take the Tirisfal Glades zeppelin. On arrival, follow the east road to the Bulwark."}}},
    ["04-50"] = {name="Western Plaguelands", tips={{k="交通", text="At step 1, head from the zeppelin tower to the Bulwark. After Gahrron's Withering, follow the main road east to Eastern Plaguelands."}, {k="取捨", text="Do the cauldron quests in order. Do both wildlife quests while passing the Writhing Haunt."}, {k="取捨", text="Save Return to the Bulwark for the Bulwark. Do A Plague Upon Thee on the Light's Hope Chapel leg and turn it in back at the Bulwark."}, {k="提醒", text="Continue to Light's Hope Chapel in the level 56-57 range. Pick up Skeletal Fragments by the Bulwark before collecting Skeletal Fragments. If you want your own Scholomance key, turn it in, take Mold Rhymes With..., and bring 2 Thorium Bars to Gadgetzan before entering Un'Goro.", s={{"Continue to Light's Hope Chapel in the level 56-57 range"}, {"Pick up Skeletal Fragments by the Bulwark before collecting Skeletal Fragments"}, {"If you want your own Scholomance key, turn it in, take Mold Rhymes With..., and bring 2 Thorium Bars to Gadgetzan before entering Un'Goro"}}}}, danger={[1]="Scarlet patrols roam north of Dalson's Tears. Pull skeletons from the edge of the field while gathering cauldron materials. Don't cut north through camp."}, grind={[1]={mob="Skeletal Terror", note="Grind normal skeletons at Dalson's Tears for Skeletal Fragments on the cauldron loop. Stay outside and watch for Scarlet patrols to the north."}, [2]={mob="Freezing Ghoul", note="Normal ghouls near the Writhing Haunt are a good level and on the way to the next cauldron. Start at the field edge to avoid the crowded doorway."}}, supply={[1]={npc="Argent Quartermaster Hasana"}}, steps={[1]={text="Fly from Ratchet to Orgrimmar and take the zeppelin to Tirisfal Glades. Follow the main road east from outside Undercity to the Bulwark."}, [2]={hint="Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands."}, [3]={npc="Argent Officer Garush", tgt="Argent Officer Garush"}, [4]={npc="Mickey Levine", tgt="Mickey Levine"}, [5]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [6]={hint="Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."}, [7]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [8]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [9]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [10]={hint="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", desc="Clear normal undead around the cauldron. Approach to spawn the guardian."}, [11]={npc="Scourge Cauldron", npcObj=true}, [12]={npc="Scourge Cauldron", npcObj=true}, [13]={hint="Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."}, [14]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [15]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [16]={hint="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", desc="Clear normal undead around the cauldron. Approach to spawn the guardian."}, [17]={npc="Scourge Cauldron", npcObj=true}, [18]={npc="Scourge Cauldron", npcObj=true}, [19]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [20]={hint="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [21]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [22]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [23]={hint="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [24]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [25]={hint="Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.", desc="Collect on the two-cauldron loop. Turn in with the samples at the Bulwark."}, [26]={hint="Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands."}, [27]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [28]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [29]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [30]={hint="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", desc="Clear normal undead around the cauldron. Approach to spawn the guardian."}, [31]={npc="Scourge Cauldron", npcObj=true}, [32]={npc="Scourge Cauldron", npcObj=true}, [33]={hint="Bring the voodoo feathers to Bath'rah the Windwatcher.", tag="Optional, Target: Gasher / Zul'Lor / Gasher / Hukku / Mijan / Hukku / Zolo / Loro / Loro", desc="Fly from Undercity to Stonard to meet your group."}, [34]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", desc="Turn in to Bath'rah in Alterac. Enamored Water Spirit is a reward choice.", star={"Enamored Water Spirit", {"SHAMAN"}}}, [35]={hint="Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", tag="Optional, Target: Gasher / Zul'Lor / Gasher / Hukku / Mijan / Hukku / Zolo / Loro / Loro", desc="Fly to Stonard from Undercity. Save Impsy's turn-in for Irontree Woods."}}},
    ["04-51"] = {name="Eastern Plaguelands", tips={{k="交通", text="Turn in Duke Nicholas Zverenhoff and pick up Defenders of Darrowshire, then unlock the chapel flight path. At the final step, fly to Undercity and transfer to the zeppelin."}, {k="取捨", text="Turn in A Plague Upon Thee and Auntie Marlene on your return to the Bulwark."}, {k="取捨", text="Duskwing is an elite patrol in Eastern Plaguelands. Skip Duskwing, Oh How I Hate Thee..., as the video does."}, {k="取捨", text="Skip Hameya's Plea if you're in a hurry. It sends you between the crypt and Zul'Mashar. For Of Forgotten Memories, clicking the grave dirt spawns a group of mercenaries."}, {k="提醒", text="Behind on XP? Grind normal bats, hounds, and ghouls around the edge of Plaguewood (around 29, 28). You can wait to reach 57 until before the Frayfeather Highlands leg.", s={{"Behind on XP?"}, {"Grind normal bats, hounds, and ghouls around the edge of Plaguewood (around 29, 28)"}, {"You can wait to reach 57 until before the Frayfeather Highlands leg"}}}}, danger={[1]="Higher-level stitched abominations and patrols roam the Stratholme side of Plaguewood. Stick to the edge when collecting termites or killing ghouls."}, grind={[1]={mob="Cannibal Ghoul", note="Normal undead outside Plaguewood. Pair with the quests for residents' souls. Avoid higher-level stitched abominations and patrols."}, [2]={mob="Frenzied Plaguehound", note="Normal plaguehounds off the road in the same area. They're a good level and easy to pull in the open. Switch to the outer loop if the undead are busy."}}, supply={[1]={npc="Georgia"}, [2]={npc="Jessica Chambers"}, [3]={npc="Craftsman Wilhelm"}, [4]={npc="Jessica Chambers"}, [5]={npc="Caretaker Alen"}}, steps={[1]={text="Cross the western border and find Tirion along the Thondroril River. Pick up his quests, then head south to the main road."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={npc="Nathanos Blightcaller", tgt="Nathanos Blightcaller"}, [6]={npc="Nathanos Blightcaller", tgt="Nathanos Blightcaller"}, [7]={hint="Find Pamela Redpath in Darrowshire."}, [8]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [9]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [10]={hint="Find Pamela's doll.", desc="Clear the entrance first. Ghosts may spawn when you loot the parts."}, [11]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [12]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [13]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [14]={hint="Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", desc="The rot lasts about 10 minutes. Grind it on the spot once you have enough."}, [15]={hint="Find Carlin Redpath."}, [16]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [17]={hint="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."}, [18]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff"}, [19]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [20]={text="Unlock Light's Hope Chapel with Georgia (70.53, 47.55) if needed. Then head north for a loop through Plaguewood."}, [21]={hint="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.", desc="Check termite mounds along Plaguewood's edge. Avoid elites by Stratholme."}, [22]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."}, [23]={hint="Slay 30 Plaguebats and return to Tirion Fordring."}, [24]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat."}, [25]={hint="Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished."}, [26]={hint="Free 15 Darrowshire Spirits and return to Carlin Redpath.", desc="Click each spawned soul after the kill. Kills alone don't count."}, [27]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [28]={npc="Nathanos Blightcaller", tgt="Nathanos Blightcaller"}, [29]={npc="Nathanos Blightcaller", tgt="Nathanos Blightcaller"}, [30]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [31]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [32]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [33]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Complete Tirion's three hunting quests to unlock this one."}, [34]={hint="Listen to what Tirion Fordring has to say.", desc="Complete Tirion's three hunting quests to unlock this one."}, [35]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Complete Tirion's three hunting quests to unlock this one."}, [36]={text="After the loop, fly from Light's Hope Chapel to Undercity and take the Orgrimmar zeppelin."}}},
    ["05-d27"] = {name="Stratholme: Undead", entrance="Eastern Plaguelands (The Lost Supplies), Undead side entrance, about 43.50, 19.40.", pickup="Visit Betina, Leonid, and Caretaker Alen at Light's Hope Chapel. Head west to see Egan in Terrordale before entering through the side gate. If your group has cleared from the front gate, save follow-up The Active Agent for this run.", pickupS={{"Visit Betina, Leonid, and Caretaker Alen at Light's Hope Chapel"}, {"Head west to see Egan in Terrordale before entering through the side gate"}, {"If your group has cleared from the front gate, save follow-up The Active Agent for this run"}}, tips={{k="動線", text="Service gate → Aurius in the chapel → Baroness Anastari, Nerub'enkan and Maleki in the three ziggurats. Check for the data → Ramstein in the Slaughterhouse → Baron Rivendare, then speak to Aurius. Loot flesh and Holy Water and free Spectral Citizens on the way."}, {k="取捨", text="Collect the flesh, Holy Water, and Egan's souls on one run. If doing only one wing, skip the Aurius chain that requires the Medallion of Faith first."}, {k="說明", text="Five-player dungeon. Bring the Key to the City for the Service Entrance. On your first run, go through from the front gate and get the key from Barthilas.", s={{"Five-player dungeon"}, {"Bring the Key to the City for the Service Entrance"}, {"On your first run, go through from the front gate and get the key from Barthilas"}}}, {k="提醒", text="Five-player dungeon. Bring the Key to the City for the Service Entrance. On your first run, go through from the front gate and get the key from Barthilas.", s={{"Five-player dungeon"}, {"Bring the Key to the City for the Service Entrance"}, {"On your first run, go through from the front gate and get the key from Barthilas"}}}}, steps={[1]={npc="Betina Bigglezink", tgt="Betina Bigglezink", desc="If you've turned this in, accept The Active Agent on this run."}, [2]={npc="Betina Bigglezink", tgt="Betina Bigglezink", desc="Turn in The Flesh Does Not Lie first. Save this for the next run if it isn't unlocked yet.", preText="The Flesh Does Not Lie"}, [3]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered"}, [4]={npc="Caretaker Alen", tgt="Caretaker Alen"}, [5]={hint="Find Egan. You only know that he was last seen around Stratholme."}, [6]={npc="Egan", tgt="Egan"}, [7]={npc="Egan", tgt="Egan", desc="Get Egan's Blaster.", preText="The Restless Souls"}, [8]={text="Stratholme: Undead entrance"}, [9]={hint="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", desc="Location: Enter the service gate and loot flesh from the undead along the streets."}, [10]={hint="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", desc="Location: Search all three ziggurats. The data is in a small box in one of them. Order: Check each tower after defeating the boss guarding its entrance."}, [11]={hint="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", desc="Location: Check wooden supply crates along the streets. Clear nearby mobs first."}, [12]={hint="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!", desc="Location: Find Spectral Citizens and use the Blaster twice on each target."}, [13]={npc="Aurius", tgt="Aurius", tag="Unverified", desc="Loot the medallion from Malor's Strongbox, then go to the service gate chapel."}, [14]={hint="Use/collect: Malor's Strongbox", desc="Location: Enter the service gate. Look for the burning chapel by the entrance."}, [15]={npc="Aurius", tgt="Aurius", tag="Unverified"}, [16]={npc="Aurius", tgt="Aurius", tag="Unverified", desc="Give him the medallion and accept the quest before fighting Baron Rivendare.", preText="The Medallion of Faith"}, [17]={hint="Complete the quest objectives.", desc="Map: Baron Rivendare (38.90, 20.40). Talk to Aurius in the room afterward. Location: Clear the ziggurats and Slaughterhouse. Find Aurius in Rivendare's room. Order: After the kill, find Aurius in the same room."}, [18]={npc="Aurius", tgt="Aurius", tag="Unverified", desc="Turn in to Aurius in Rivendare's room (38.90, 20.40). Pickup: service gate chapel."}, [19]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [20]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [21]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered"}, [22]={npc="Egan", tgt="Egan"}}},
    ["05-d26"] = {name="Stratholme: Live", entrance="Eastern Plaguelands (The Lost Supplies), main portal, about 27.10, 10.70.", pickup="Visit the Duke and Smokey at Light's Hope Chapel, then follow the main road northwest to the front gate. For Tirion's painting, finish the hunting quests first. Continue through the southern crypt and northern valley, see the painter on Caer Darrow, then return to Eastern Plaguelands.", pickupS={{"Visit the Duke and Smokey at Light's Hope Chapel, then follow the main road northwest to the front gate"}, {"For Tirion's painting, finish the hunting quests first"}, {"Continue through the southern crypt and northern valley, see the painter on Caer Darrow, then return to Eastern Plaguelands"}}, tips={{k="動線", text="Main gate → tobacco shop in Market Row → Scarlet Bastion. Skip Cannon Master Willey if desired. In Archivist Galford's room, retrieve the painting and burn the records. Kill Balnazzar for a full clear."}, {k="取捨", text="Pick up the tobacco and archive quests. Add Of Love and Family if you've finished Tirion's earlier chain. Get the prerequisites before heading in if you only want one run."}, {k="說明", text="Five-player dungeon. Bring the Scarlet Key for the Bastion gate. Below level 58, pick up the quests and group later. Use the Service Entrance for the undead wing.", s={{"Five-player dungeon"}, {"Bring the Scarlet Key for the Bastion gate"}, {"Below level 58, pick up the quests and group later"}, {"Use the Service Entrance for the undead wing"}}}, {k="提醒", text="Five-player dungeon. Bring the Scarlet Key for the Bastion gate. Below level 58, pick up the quests and group later. Use the Service Entrance for the undead wing.", s={{"Five-player dungeon"}, {"Bring the Scarlet Key for the Bastion gate"}, {"Below level 58, pick up the quests and group later"}, {"Use the Service Entrance for the undead wing"}}}}, steps={[1]={npc="Smokey LaRue", tgt="Smokey LaRue"}, [2]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", desc="Kill the Archivist and burn the records on the same run."}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg."}, [4]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [6]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg."}, [7]={hint="Slay 30 Plaguebats and return to Tirion Fordring."}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [9]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg."}, [10]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat."}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [12]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg.", preText="Demon Dogs, Blood Tinged Skies, Carrion Grubbage"}, [13]={hint="Listen to what Tirion Fordring has to say."}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [15]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg.", preText="Redemption"}, [16]={hint="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [18]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg.", preText="Of Forgotten Memories"}, [19]={hint="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [21]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Optional Tirion chain. Skip if done on the Light's Hope Chapel leg.", preText="Of Lost Honor"}, [22]={hint="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."}, [23]={npc="Artist Renfray", tgt="Artist Renfray"}, [24]={npc="Artist Renfray", tgt="Artist Renfray", preText="Of Love and Family"}, [25]={text="Stratholme: Live entrance"}, [26]={hint="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", desc="Location: Enter the main gate and open the tobacco shop's crate in Market Row."}, [27]={hint="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", desc="DungeonsForever map: Archivist (27.10, 75.10). The records are in his room. Location: Kill Galford in the Scarlet Bastion archives, then burn the records."}, [28]={hint="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.", desc="Map: Archivist (27.10, 75.10). The painting is in the same room. Location: Check the painting of two moons on the wall of the Scarlet archives."}, [29]={npc="Smokey LaRue", tgt="Smokey LaRue"}, [30]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff"}, [31]={npc="Tirion Fordring", tgt="Tirion Fordring"}}},
    ["04-52"] = {name="Moonglade", tips={{k="交通", text="At step 2, fly to Thunder Bluff. At step 7, fly to Felwood and go through Timbermaw Hold. Unlock the flight path in southwest Moonglade, then walk into Winterspring."}, {k="取捨", text="Accept Wasteland and A Reliquary of Purity first. The follow-up quests at Southwind Village share the same area."}, {k="取捨", text="Turn in Mystery Goo at Everlook. Pick up A Reliquary of Purity at Cenarion Hold and save the turn-in for Nighthaven."}, {k="提醒", text="If Timbermaw furbolgs still attack you, kill Deadwood furbolgs outside or finish the reputation quests from the Emerald Sanctuary and Bloodvenom Post leg through Everlook. Pick up the Everlook quests once through the tunnel.", s={{"If Timbermaw furbolgs still attack you, kill Deadwood furbolgs outside or finish the reputation quests from the Emerald Sanctuary and Bloodvenom Post leg through Everlook"}, {"Pick up the Everlook quests once through the tunnel"}}}}, danger={[1]="Check your Timbermaw reputation before taking the tunnel from Moonglade to Winterspring. If Hostile, go around or return to Felwood to raise it."}, grind={[1]={mob="Deadwood Avenger", note="After Nighthaven turn-ins, go through Timbermaw Hold to the Felwood entrance. Grind dense normal Deadwood furbolgs for rep. Avoid Timbermaw guards and pulls inside tents."}, [2]={mob="Winterfall Den Watcher", note="If you're through the hold, kill normal furbolgs along the Winterspring road. Grind a little near Donova or find the main packs east of Everlook."}}, supply={[1]={npc="Faustron"}, [2]={npc="Meliri"}, [3]={npc="Dargon"}, [4]={npc="Daeolyn Summerleaf"}}, steps={[1]={npc="Cenarion Emissary Blackhoof", tgt="Cenarion Emissary Blackhoof"}, [2]={text="Fly from Orgrimmar to Thunder Bluff. Pick up the courier's lead-in at the base, then find the Arch Druid on Elder Rise."}, [3]={npc="Bluff Runner Windstrider", tgt="Bluff Runner Windstrider", desc="Horde breadcrumb to Nighthaven. Go straight to Hamuul if you've done The New Frontier or The New Frontier."}, [4]={hint="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", desc="Horde breadcrumb to Nighthaven. Go straight to Hamuul if you've done The New Frontier or The New Frontier."}, [5]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem", desc="Horde breadcrumb to Nighthaven. Go straight to Hamuul if you've done The New Frontier or The New Frontier."}, [6]={npc="Arch Druid Hamuul Runetotem", tgt="Arch Druid Hamuul Runetotem"}, [7]={text="Fly to Bloodvenom Post. Go north through Deadwood Village to the cauldron (60.20, 5.84), then take the Timbermaw Hold fork to Moonglade."}, [8]={hint="Search the Deadwood furbolg camp in northern Felwood for a clue."}, [9]={npc="Deadwood Cauldron", npcObj=true}, [10]={npc="Deadwood Cauldron", npcObj=true}, [11]={hint="Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold."}, [12]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [13]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [14]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [15]={node="Moonglade", desc="Unlock the Horde flight path with Faustron in southwest Moonglade."}, [16]={hint="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", tag="Optional, Unverified", desc="Lv 55-60. Enter through the north Azshara cave. Save the relic for Tirisfal."}, [17]={text="Cross Timbermaw Hold again to reach Winterspring."}}},
    ["04-53"] = {name="Winterspring", tips={{k="交通", text="At step 1, stop at Frostfire Hot Springs after leaving Timbermaw Hold. At the last step, pick a flight route based on whether you're detouring to Frayfeather Highlands."}, {k="取捨", text="Do Meet at the Grave in Gadgetzan. Farm the item for Toxic Horrors in Irontree Woods, then turn it in at Frostfire Hot Springs."}, {k="取捨", text="Quest Are We There, Yeti? takes you through three zones along this route. Use the Mechanical Yeti in Everlook first."}, {k="提醒", text="Below level 57? Grind normal yetis on Ice Thistle Hills (around 66, 43) or hippogryphs in Frayfeather Highlands.", s={{"Below level 57?"}, {"Grind normal yetis on Ice Thistle Hills (around 66, 43) or hippogryphs in Frayfeather Highlands"}}}}, danger={[1]="The Ice Thistle Hills cave is narrow. Level 57-58 yetis can pull together around the bends. Grind outside the entrance if you just need XP."}, grind={[1]={mob="Ice Thistle Matriarch", note="Normal yetis outside the Ice Thistle Hills cave drop the quest horns. Use the outer slope if it's busy. Watch for extra pulls inside."}, [2]={mob="Ice Thistle Patriarch", note="Higher-level normal yetis in the same area are good through 57. Let a teammate clear narrow passages to avoid double pulls."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Innkeeper Vizzie"}, [3]={npc="Nixxrak"}, [4]={npc="Innkeeper Vizzie"}, [5]={npc="Wixxrak"}}, steps={[1]={text="Head east from Timbermaw Hold. Visit Donova at Frostfire Hot Springs before entering Everlook."}, [2]={hint="Report back to Donova Snowden with your findings."}, [3]={npc="Donova Snowden", tgt="Donova Snowden"}, [4]={npc="Donova Snowden", tgt="Donova Snowden"}, [5]={npc="Donova Snowden", tgt="Donova Snowden"}, [6]={npc="Donova Snowden", tgt="Donova Snowden"}, [7]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [8]={hint="Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.", desc="Only the cave's adult matriarchs and patriarchs drop it. Skip the lower-level yetis."}, [9]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [10]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", desc="Use the Mechanical Yeti on Legacki in Everlook (61.54, 38.61), then on two in Un'Goro."}, [11]={text="Fly to Camp Mojache only for the optional egg or a ready Dire Maul group. Otherwise fly straight from Everlook to Gadgetzan."}}},
    ["04-54"] = {name="Feralas", tips={{k="交通", text="Step 1 is a stop for the egg on the way south. Fly to Gadgetzan at step 2."}, {k="取捨", text="Skip the one-time The Super Egg-O-Matic turn-in if you've already done it, or if you're level 57 and want to save travel time. Fly straight to Gadgetzan."}, {k="提醒", text="Below level 57? Grind normal hippogryphs in Frayfeather Highlands (around 57, 76), or kill Ice Thistle yetis by Everlook before flying.", s={{"Below level 57?"}, {"Grind normal hippogryphs in Frayfeather Highlands (around 57, 76), or kill Ice Thistle yetis by Everlook before flying"}}}}, grind={[1]={mob="Ice Thistle Matriarch", note="The Feralas stop is just for the hippogryph egg. If below 57, grind the higher-level Ice Thistle yetis before leaving Everlook. The cave mouth may be busy."}}, supply={[1]={npc="Shyn"}, [2]={npc="Innkeeper Greul"}, [3]={npc="Cawind Trueaim"}, [4]={npc="Innkeeper Greul"}, [5]={npc="Cawind Trueaim"}, [6]={npc="Tarhus"}}, steps={[1]={text="Take the south road from Camp Mojache to the Frayfeather Highlands. Loot one Hippogryph Egg (55.91, 76.03 or 58.62, 75.53), then return to the flight master.", tag="Optional"}, [2]={text="If you collected an egg, return to Camp Mojache and fly to Gadgetzan. If you skipped Feralas, start the Marshal's Refuge leg from Gadgetzan."}}},
    ["05-d30"] = {name="Dire Maul: North", entrance="Feralas (1444), 62.50, 24.90. North wing portal.", pickup="Group up and gather materials at Camp Mojache, then head west. Most north wing quests are inside. Get the Crescent Key in the east wing or bring someone who has it. Buy your class book at the Auction House if needed.", pickupS={{"Group up and gather materials at Camp Mojache, then head west"}, {"Most north wing quests are inside"}, {"Get the Crescent Key in the east wing or bring someone who has it"}, {"Buy your class book at the Auction House if needed"}}, tips={{k="動線", text="Full clear: Guard Mol'dar → Stomper Kreeg → Guard Fengus → trap by Knot → Captain Kromcrush → King Gordok. Tribute: leave guards alive, find Knot and fix the trap, then see Kreeg after killing the king. The courtyard side door leads to the Library for class books."}, {k="取捨", text="While leveling, favor a group that can finish in one run. If you're waiting on Tribute materials, keep questing."}, {k="說明", text="For a Tribute run, leave the guards and Kreeg alive. Talk to them after killing King Gordok. Tell the group first if you want a standard full clear.", s={{"For a Tribute run, leave the guards and Kreeg alive"}, {"Talk to them after killing King Gordok"}, {"Tell the group first if you want a standard full clear"}}}, {k="提醒", text="For a Tribute run, leave the guards and Kreeg alive. Talk to them after killing King Gordok. Tell the group first if you want a standard full clear.", s={{"For a Tribute run, leave the guards and Kreeg alive"}, {"Talk to them after killing King Gordok"}, {"Tell the group first if you want a standard full clear"}}}}, steps={[1]={text="Dire Maul: North entrance"}, [2]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Unverified", desc="Bring 4 Bolts of Runecloth, 8 Rugged Leather and 2 Rune Thread. Loot 1 Ogre Tannin."}, [3]={hint="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", desc="Location: Loot tannin upstairs past Fengus. Find Knot by the trap."}, [4]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Unverified"}, [5]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Unverified", desc="Only do with a Gordok Shackle Key. Tribute runs skip guards that can drop it."}, [6]={hint="Loot from: Gordok Brute, Gordok Mage-Lord, Gordok Captain", desc="Location: Past Fengus's courtyard, use the key on Knot next to the broken trap."}, [7]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Unverified"}, [8]={npc="Stomper Kreeg", tgt="Stomper Kreeg", tag="Unverified", desc="Get King of the Gordok on the tribute run, then talk to Stomper Kreeg. Map: Stomper Kreeg (60.90, 67.80). Talk to him after becoming king."}, [9]={hint="Complete the quest objectives.", desc="Map: Stomper Kreeg (60.90, 67.80). Talk to him after becoming king. Location: Become king, then backtrack to Stomper Kreeg near the entrance. Order: Go back and talk after the tribute run."}, [10]={npc="Stomper Kreeg", tgt="Stomper Kreeg", tag="Unverified", desc="After the tribute run, stay inside to turn in to Kreeg. Map: Stomper Kreeg (60.90, 67.80). Talk to him after becoming king."}, [11]={npc="Garona: A Study on Stealth and Treachery", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [12]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [13]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Unverified"}, [14]={npc="Codex of Defense", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [15]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [16]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Unverified"}, [17]={npc="The Arcanist's Cookbook", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [18]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [19]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Unverified"}, [20]={npc="The Light and How to Swing It", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [21]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [22]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Unverified"}, [23]={npc="Harnessing Shadows", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [24]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [25]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Unverified"}, [26]={npc="The Greatest Race of Hunters", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [27]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [28]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Unverified"}, [29]={npc="Holy Bologna: What the Light Won't Tell You", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [30]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [31]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Unverified"}, [32]={npc="Frost Shock and You", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [33]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [34]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Unverified"}, [35]={npc="The Emerald Dream", npcObj=true, tag="Unverified", desc="Loot the class book from bosses or book piles, or buy one. Use it before the Library."}, [36]={hint="Return the book to its rightful owners.", desc="Location: Enter the north courtyard. Take the locked side door and tunnel to the Library."}, [37]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Unverified"}}},
    ["05-d29"] = {name="Dire Maul: West", entrance="Feralas (1444), 60.30, 30.20. Portal on the west side of the courtyard.", pickup="Visit Sage Korolusk at Camp Mojache and pick up Elven Legends at level 54. Fly to camp and follow the main road west. Check that someone has the Crescent Key, or run the east wing first.", pickupS={{"Visit Sage Korolusk at Camp Mojache and pick up Elven Legends at level 54"}, {"Fly to camp and follow the main road west"}, {"Check that someone has the Crescent Key, or run the east wing first"}}, tips={{k="動線", text="West gate → clear the garden pylons → Tendris Warpwood → see the Ancient upstairs and clear the remaining pylons, with Kalendris and Illyanna optional → Immol'thar in the prison → Prince Tortheldrin in the Library. Turn in to the Ancient, then return to the Library for the chest and remains."}, {k="取捨", text="Do Elven Legends, The Madness Within, and The Treasure of the Shen'dralar on one run. Save the enchantment materials and longer multi-dungeon chains for a gear run."}, {k="說明", text="Five-player dungeon. Get the Crescent Key from Pusillin in the east wing. Clear all five pylons before Immol'thar. See the north wing notes for the library class books.", s={{"Five-player dungeon"}, {"Get the Crescent Key from Pusillin in the east wing"}, {"Clear all five pylons before Immol'thar"}, {"See the north wing notes for the library class books"}}}, {k="提醒", text="Five-player dungeon. Get the Crescent Key from Pusillin in the east wing. Clear all five pylons before Immol'thar. See the north wing notes for the library class books.", s={{"Five-player dungeon"}, {"Get the Crescent Key from Pusillin in the east wing"}, {"Clear all five pylons before Immol'thar"}, {"See the north wing notes for the library class books"}}}}, steps={[1]={npc="Sage Korolusk", tgt="Sage Korolusk", desc="Pick up in Camp Mojache. Reach the Library through West or the North shortcut."}, [2]={text="Dire Maul: West entrance"}, [3]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", tag="Unverified", desc="Talk to the Shen'dralar Ancient on the upper level of Dire Maul West first."}, [4]={hint="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.", desc="Clear all five pylons first. Map: Immol'thar (35.00,57.60), Prince (62.20,22.70). Location: Clear five pylons, then go through the locked door to Immol'thar and the Prince. Order: Five pylons → Immol'thar → the prince in the library."}, [5]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", tag="Unverified"}, [6]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", tag="Unverified", desc="Turn in to the Ancient, then accept the follow-up. Do it on the same run as The Madness Within.", preText="The Madness Within"}, [7]={hint="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", desc="Location: Go from Immol'thar's cage to the Library. Check under the stairs for the chest."}, [8]={npc="Treasure of the Shen'dralar", npcObj=true, tag="Unverified"}, [9]={hint="Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", desc="Location: Follow the hall from the cage to the Library. Look for remains by the shelves."}, [10]={npc="Sage Korolusk", tgt="Sage Korolusk"}}},
    ["05-d28"] = {name="Dire Maul: East", entrance="Feralas (1444), 64.80, 30.20. Portal in the recess along the arena's east wall.", pickup="At level 54, take Camp Mojache from Warcaller Gorlach when passing through Orgrimmar on the Valormok leg. Turn in to Talo and take Lethtendris's Web at Camp Mojache. Fly to Camp Mojache and visit Azj'Tordin at Lariss Pavilion. For A Reliquary of Purity, pick it up in Moonglade, collect the reliquary at Southwind Village, and turn it in at Nighthaven to unlock Shards of the Felvine. Save that chain for a later run if needed.", pickupS={{"At level 54, take Camp Mojache from Warcaller Gorlach when passing through Orgrimmar on the Valormok leg"}, {"Turn in to Talo and take Lethtendris's Web at Camp Mojache"}, {"Fly to Camp Mojache and visit Azj'Tordin at Lariss Pavilion"}, {"For A Reliquary of Purity, pick it up in Moonglade, collect the reliquary at Southwind Village, and turn it in at Nighthaven to unlock Shards of the Felvine"}, {"Save that chain for a later run if needed"}}, tips={{k="動線", text="Chase Pusillin from the entrance and fight him at the end → Lethtendris and Hydrospawn on the side paths → Zevrim Thornhoof at the satyr altar → Alzzin the Wildshaper. Enter the Library from West or North."}, {k="取捨", text="Get the Crescent Key in Dire Maul East. Talo's and Pusillin's quests are the quickest to pair. If Shards of the Felvine is still locked, don't cross two zones for the reliquary."}, {k="說明", text="Five-player dungeon. Use the east entrance. Don't skip Pusillin on a boss run. Keep the key for the west and north wings.", s={{"Five-player dungeon"}, {"Use the east entrance"}, {"Don't skip Pusillin on a boss run"}, {"Keep the key for the west and north wings"}}}, {k="提醒", text="Five-player dungeon. Use the east entrance. Don't skip Pusillin on a boss run. Keep the key for the west and north wings.", s={{"Five-player dungeon"}, {"Use the east entrance"}, {"Don't skip Pusillin on a boss run"}, {"Keep the key for the west and north wings"}}}}, steps={[1]={npc="Warcaller Gorlach", tgt="Warcaller Gorlach", desc="Skip the city breadcrumb by taking Lethtendris's Web directly from Thalo."}, [2]={hint="Speak with Talo Thornhoof at Camp Mojache in Feralas."}, [3]={npc="Talo Thornhoof", tgt="Talo Thornhoof"}, [4]={npc="Talo Thornhoof", tgt="Talo Thornhoof", desc="Horde quest. The Camp Mojache lead-in is optional."}, [5]={npc="Azj'Tordin", tgt="Azj'Tordin", desc="Find Lariss Pavilion north of Camp Mojache."}, [6]={npc="Rabine Saturna", tgt="Rabine Saturna", desc="Already on the main route at stops 52, 56, and 59. Skip if turned in."}, [7]={hint="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."}, [8]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [9]={npc="Rabine Saturna", tgt="Rabine Saturna", desc="Bring the Reliquary of Purity. If A Reliquary of Purity isn't done, save this for the next run.", preText="A Reliquary of Purity"}, [10]={text="Dire Maul: East entrance"}, [11]={hint="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.", desc="Map: meet Pusillin at 74.40, 44.00. Talk to him at each stop to chase him. Location: Talk to Pusillin at the east entrance and chase him to the end. Order: Talk to them at each stop to start the fight."}, [12]={hint="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", desc="DungeonsForever map: Lethtendris (44.00, 47.40). Location: Take the upper passage from the garden to Lethtendris's platform."}, [13]={hint="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.", desc="Map: Alzzin (56.40, 28.10). The Felvine Shard is nearby. Location: Follow the last tunnel to Alzzin. Kill him, then loot and seal the shard."}, [14]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Unverified", desc="At 60, pick up from Lydros in the Library on the West or North run, then do East."}, [15]={hint="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", desc="DungeonsForever map: Hydrospawn (56.50, 68.50). Location: Take the lower waterway in Dire Maul East. Kill Hydrospawn by the pool."}, [16]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [17]={npc="Talo Thornhoof", tgt="Talo Thornhoof"}, [18]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [19]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Unverified", desc="Return to the Library and turn in to learn the highest rank of Conjure Water."}}},
    ["04-55"] = {name="Un'Goro Crater", tips={{k="交通", text="Pass through Gadgetzan at steps 1 and 11, and use the Mechanical Yeti along the way. At the last step, take the northwest slope into Silithus."}, {k="取捨", text="Turn in The New Springs at Frostfire Hot Springs and Are We There, Yeti? at Everlook. Save Linken's Memory for Irontree Woods."}, {k="取捨", text="Go for The Super Egg-O-Matic only if you picked up an egg and can still turn it in. Otherwise, don't backtrack."}, {k="提醒", text="This leg is still for levels 57-59. If behind on XP, grind normal elementals on Fire Plume Ridge or gorillas to the north. Watch for devilsaurs on the flats.", s={{"This leg is still for levels 57-59"}, {"If behind on XP, grind normal elementals on Fire Plume Ridge or gorillas to the north"}, {"Watch for devilsaurs on the flats"}}}}, danger={[1]="Level 54-56 elite devilsaurs patrol the flats south of Fire Plume Ridge. Scout the route before escorting Ringo and stick to the slope."}, grind={[1]={mob="Living Blaze", note="Higher-level normal elementals at Fire Plume Ridge. Pair with the volcano quest. Pull along the slope and avoid devilsaur patrols on the plain."}, [2]={mob="Tar Lord", note="Normal tar mobs near Marshal's Refuge. Do a few laps for the last bit of XP. Pull singles from the pool edge."}}, supply={[1]={npc="Gryfe"}, [2]={npc="Gibbert"}, [3]={npc="Nergal"}, [4]={npc="Nergal"}, [5]={npc="Innkeeper Fizzgrimble"}}, steps={[1]={text="Finish the graveyard turn-ins in Gadgetzan first. If you're on the Mechanical Yeti quest, use it in town before taking the south road."}, [2]={npc="Egg-O-Matic", npcObj=true, tag="Optional", desc="Use an egg from the Frayfeather Highlands in Feralas. Skip if already done."}, [3]={hint="Use/collect: Hippogryph Egg", tag="Optional"}, [4]={npc="Egg-O-Matic", npcObj=true, tag="Optional"}, [5]={hint="Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.", desc="Drinking it kills you. Talk while dead, then resurrect at the graveyard."}, [6]={npc="Gaeriyan", tgt="Gaeriyan"}, [7]={npc="Gaeriyan", tgt="Gaeriyan"}, [8]={hint="Resurrect, then look for the gravestone that Gaeriyan told you to find."}, [9]={npc="A Conspicuous Gravestone", npcObj=true}, [10]={npc="A Conspicuous Gravestone", npcObj=true}, [11]={text="Use the Mechanical Yeti on Sprinkle in Gadgetzan (51.06, 26.87), then take the south road into Un'Goro."}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [13]={hint="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."}, [14]={hint="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", desc="Open Torwa's pouch. Set down the meat, then use the pheromones to lure Lar'korwi."}, [15]={hint="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", tag="Target: Un'Goro Gorilla / Un'Goro Gorilla / Un'Goro Stomper / Un'Goro Thunderer"}, [16]={hint="Discover the location of the Northern Crystal Pylon in Un'Goro Crater."}, [17]={hint="Deliver Linken's Superior Sword to Linken in Un'Goro Crater."}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={hint="Find J.D. Collie in the cave at Marshal's Refuge."}, [21]={npc="J.D. Collie", tgt="J.D. Collie"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [24]={hint="Take Umi's Mechanical Yeti and scare her friends with it:", desc="Use the yeti on Quixxil here after the first two targets. Turn in at Frostwhisper Gorge."}, [25]={hint="Discover the location of the Western Crystal Pylon."}, [26]={npc="Krakle", tgt="Krakle"}, [27]={hint="Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.", desc="Wait for the reaction to count. Stay out of the lava."}, [28]={hint="Find Ringo at Fire Plume Ridge."}, [29]={npc="Ringo", tgt="Ringo"}, [30]={npc="Ringo", tgt="Ringo", desc="Clear the cave entrance before escorting. Wake Ringo with Spraggle's Canteen."}, [31]={hint="Lead Ringo to Spraggle Frock at Marshal's Refuge."}, [32]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [33]={npc="J.D. Collie", tgt="J.D. Collie"}, [34]={npc="J.D. Collie", tgt="J.D. Collie"}, [35]={npc="J.D. Collie", tgt="J.D. Collie"}, [36]={npc="J.D. Collie", tgt="J.D. Collie"}, [37]={hint="Speak with J.D. Collie in a moment."}, [38]={npc="J.D. Collie", tgt="J.D. Collie"}, [39]={npc="Krakle", tgt="Krakle"}, [40]={npc="Krakle", tgt="Krakle"}, [41]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [42]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [43]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [44]={hint="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", desc="Clear the gorillas at the cave entrance. U'cha is a normal mob."}, [45]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [46]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional", desc="Turn in to Torwa via the southeast entrance. Choose leather armor or a staff.", star={"Grizzled Pelt", {"DRUID"}}}, [47]={text="Use Un'Goro's northwest ramp into Silithus. Follow the road to Cenarion Hold."}}},
    ["05-d31"] = {name="The Shaper's Terrace", entrance="Un'Goro Crater (To The Hinterlands), 48.10, 6.10. Marks the Titan structure. Exact portal coords unknown.", pickup="On the way to Moonglade, stop by Mayena Earthseeker in northwest Mulgore while passing through Thunder Bluff. Back at Marshal's Refuge, take the stone stairs north to the titan structure. Pickup NPCs for the other two quests are unverified.", pickupS={{"On the way to Moonglade, stop by Mayena Earthseeker in northwest Mulgore while passing through Thunder Bluff"}, {"Back at Marshal's Refuge, take the stone stairs north to the titan structure"}, {"Pickup NPCs for the other two quests are unverified"}}, tips={{k="動線", text="Entrance → collect four crystal colors through the titan ruins → handle the pool objectives by the Colorless Crystal. The full order for the titan dragon, Bolt, Vitrix and Nanaya remains unconfirmed."}, {k="取捨", text="Pick up Crystalline Elements first. If there are no other quests at camp, enter with your group."}, {k="說明", text="New five-player dungeon in Forever. Go uphill north of Marshal's Refuge. Use Power Crystals from Un'Goro at the titan gate. The outer entrance landmark is around 48.10, 6.10. The exact portal spot is unverified.", s={{"New five-player dungeon in Forever"}, {"Go uphill north of Marshal's Refuge"}, {"Use Power Crystals from Un'Goro at the titan gate"}, {"The outer entrance landmark is around 48.10, 6.10"}, {"The exact portal spot is unverified"}}}, {k="提醒", text="New five-player dungeon in Forever. Go uphill north of Marshal's Refuge. Use Power Crystals from Un'Goro at the titan gate. The outer entrance landmark is around 48.10, 6.10. The exact portal spot is unverified.", s={{"New five-player dungeon in Forever"}, {"Go uphill north of Marshal's Refuge"}, {"Use Power Crystals from Un'Goro at the titan gate"}, {"The outer entrance landmark is around 48.10, 6.10"}, {"The exact portal spot is unverified"}}}}, steps={[1]={npc="Mayena Earthseeker", tgt="Mayena Earthseeker", desc="Pick up on the western bluff in Thunder Bluff. NPCs are from player records."}, [2]={npc="Chemist Fuely", tgt="Chemist Fuely", tag="Unverified", desc="Pickup NPC and coordinates are unconfirmed. Check the quest prompts outside."}, [3]={npc="Master Apothecary Faranell", tgt="Master Apothecary Faranell", tag="Unverified", desc="Pickup NPC and coordinates are unconfirmed."}, [4]={text="The Shaper's Terrace entrance"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="Unverified", desc="Location: Follow the titan ruins and loot all four crystal colors from elementals."}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="Unverified", desc="Location: Find Seeping Slimes inside. Their exact pool location is unconfirmed."}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="Location: Look on the ground around the Colorless Crystal for a depleted fragment."}, [8]={npc="Mayena Earthseeker"}, [9]={npc="Chemist Fuely", tgt="Chemist Fuely", tag="Unverified"}, [10]={tag="Unverified"}}},
    ["04-56"] = {name="Silithus", tips={{k="交通", text="Unlock the Cenarion Hold flight path at step 1. At the final step, take the zeppelin back to the Eastern Kingdoms."}, {k="取捨", text="Save A Reliquary of Purity and Umber, Archivist for the Moonglade turn-in."}, {k="取捨", text="Skip Noggle's Lost Satchel and Wanted - Deathclasp, Terror of the Sands if you're leveling. Quest Noggle's Lost Satchel sends you back to the far south, and Wanted - Deathclasp, Terror of the Sands requires an elite kill."}, {k="取捨", text="The video's Duskwing quest (Duskwing, Oh How I Hate Thee...) is in Eastern Plaguelands. Skip the elite group quests in Silithus as well."}, {k="提醒", text="Head to the Bulwark even if below level 59. To grind first, kill normal scorpids and spiders northeast of Cenarion Hold (around 55, 29) or Twilight cultists to the southwest (around 38, 44).", s={{"Head to the Bulwark even if below level 59"}, {"To grind first, kill normal scorpids and spiders northeast of Cenarion Hold (around 55, 29) or Twilight cultists to the southwest (around 38, 44)"}}}}, danger={[1]="Reaching the top of the Southwind Village tower triggers a silithid swarm. Clear the tower and stairs first so you have a way out."}, grind={[1]={mob="Twilight Avenger", note="Normal Twilight cultists outside the camp are good XP and drop Twilight gear. Pair with the cultist quests. Clear from the edge if others are farming gear."}, [2]={mob="Dredge Striker", note="Normal mobs in the clearing northeast of Cenarion Hold are slightly lower-level but dense. Farm on the material-gathering route if the Twilight camp is busy."}}, supply={[1]={npc="Runk Windtamer"}, [2]={npc="Calandrath"}, [3]={npc="Vargus"}, [4]={npc="Calandrath"}, [5]={npc="Calandrath"}, [6]={npc="Khur Hornstriker"}}, steps={[1]={node="Cenarion Hold", desc="Unlock the Horde flight path with Runk Windtamer at Cenarion Hold."}, [2]={text="Set your hearth at the inn (51.89, 39.16) if you want to use it after Valor's Rest."}, [3]={hint="Talk to Windcaller Proudhorn at Cenarion Hold in Silithus."}, [4]={npc="Windcaller Proudhorn", tgt="Windcaller Proudhorn"}, [5]={npc="Beetix Ficklespragg", tgt="Beetix Ficklespragg"}, [6]={npc="Windcaller Proudhorn", tgt="Windcaller Proudhorn"}, [7]={npc="Geologist Larksbane", tgt="Geologist Larksbane"}, [8]={npc="Bor Wildmane", tgt="Bor Wildmane"}, [9]={hint="Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task."}, [10]={hint="Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers."}, [11]={hint="Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter."}, [12]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [13]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [14]={hint="Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments."}, [15]={hint="Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold."}, [16]={npc="Beetix Ficklespragg", tgt="Beetix Ficklespragg"}, [17]={npc="Windcaller Proudhorn", tgt="Windcaller Proudhorn"}, [18]={npc="Geologist Larksbane", tgt="Geologist Larksbane"}, [19]={npc="Bor Wildmane", tgt="Bor Wildmane"}, [20]={npc="Beetix Ficklespragg", tgt="Beetix Ficklespragg"}, [21]={npc="Windcaller Proudhorn", tgt="Windcaller Proudhorn"}, [22]={npc="Geologist Larksbane", tgt="Geologist Larksbane"}, [23]={hint="Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers."}, [24]={hint="Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs."}, [25]={hint="Take the restored tablet to Hermit Ortell in Silithus."}, [26]={npc="Hermit Ortell", tgt="Hermit Ortell"}, [27]={hint="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."}, [28]={hint="Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", desc="Undead can spawn a silithid when killed. Kill it before the next pull."}, [29]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [30]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [31]={hint="Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity. Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", desc="Clear the tower stairs before opening the object. Watch your line of sight."}, [32]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [33]={npc="Layo Starstrike", tgt="Layo Starstrike"}, [34]={text="Return to Cenarion Hold. Hearth if bound here."}, [35]={npc="Beetix Ficklespragg", tgt="Beetix Ficklespragg"}, [36]={npc="Windcaller Proudhorn", tgt="Windcaller Proudhorn"}, [37]={text="Fly from Cenarion Hold to Orgrimmar, then take the Tirisfal zeppelin from Durotar."}}},
    ["04-57"] = {name="Western Plaguelands", tips={{k="交通", text="Enter the Bulwark at step 1. At the last step, take the zeppelin outside Undercity."}, {k="取捨", text="Do Felstone Field and Andorhal on the same loop. Turn in the termite quest on your way back."}, {k="取捨", text="Chromie's remaining quests send you back to Eastern Plaguelands. Save them for a return trip."}, {k="提醒", text="Below level 59? Grind normal undead outside eastern Andorhal (around 46, 64) or at the plagued farms before heading to Felwood.", s={{"Below level 59?"}, {"Grind normal undead outside eastern Andorhal (around 46, 64) or at the plagued farms before heading to Felwood"}}}}, danger={[1]="Andorhal Town Hall is near Araj the Summoner, a level 61 elite. Follow the outside walls when looking for the Annals of Darrowshire."}, grind={[1]={mob="Searing Ghoul", note="Normal undead on Andorhal's east edge. Grind here before returning to the farm. Avoid elites and packs in the buildings."}, [2]={mob="Haunting Vision", note="Higher-level normal wraiths at Gahrron's Withering. Use this spot if you're still east. Loop the edge to avoid linking mobs indoors."}}, supply={[1]={npc="Argent Quartermaster Hasana"}, [2]={npc="Michael Garrett"}, [3]={npc="Innkeeper Norman"}, [4]={npc="Innkeeper Norman"}, [5]={npc="Eleanor Rusk"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezekiel Graves"}}, steps={[1]={text="Go from the Tirisfal zeppelin tower to the Bulwark, then through Felstone Field, Andorhal and Northridge Lumber Camp."}, [2]={hint="Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."}, [3]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [4]={npc="Mickey Levine", tgt="Mickey Levine"}, [5]={npc="High Executor Derrington", tgt="High Executor Derrington", star={"Valiant Shortsword", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="Complete the quest objectives."}, [7]={npc="High Executor Derrington", tgt="High Executor Derrington", star={"Valiant Shortsword", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="Mickey Levine", tgt="Mickey Levine"}, [9]={hint="Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm."}, [10]={npc="Janice Felstone", tgt="Janice Felstone"}, [11]={npc="Janice Felstone", tgt="Janice Felstone"}, [12]={hint="Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.", desc="The ghoul patrols the farm. Check the south side first."}, [13]={npc="Janice Felstone", tgt="Janice Felstone"}, [14]={hint="Speak with Marlene, south of the Ruins of Andorhal."}, [15]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [16]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [17]={hint="Bring Joseph's Wedding Ring to Chromie.", desc="An elite lich is in central Andorhal. Stay on the outskirts on your way to the inn."}, [18]={npc="Chromie", tgt="Chromie"}, [19]={npc="Chromie", tgt="Chromie"}, [20]={npc="Chromie", tgt="Chromie"}, [21]={hint="Bring the Annals of Darrowshire to Chromie in Andorhal.", desc="Check the cover. Fake books can spawn enemies. Avoid the elites in the center."}, [22]={hint="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites."}, [23]={npc="Chromie", tgt="Chromie"}, [24]={npc="Chromie", tgt="Chromie"}, [25]={npc="Chromie", tgt="Chromie"}, [26]={hint="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands."}, [27]={npc="Chromie", tgt="Chromie"}, [28]={hint="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."}, [29]={npc="Termite Barrel", npcObj=true}, [30]={npc="Termite Barrel", npcObj=true}, [31]={hint="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades.", desc="Opening the barrel draws enemies. Leave right after opening it."}, [32]={npc="Mickey Levine", tgt="Mickey Levine"}, [33]={npc="Knight of Mourning", tag="Optional, Unverified", desc="See the Knight of Mourning in southwest Tirisfal. Sword of Mourning is a reward choice.", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="Return to the Undercity zeppelin tower. Take the Orgrimmar zeppelin and continue to Felwood."}}},
    ["05-d32"] = {name="Scholomance", entrance="Western Plaguelands (Threat From the Sea), about 68.90, 72.80. Underground entrance at Caer Darrow.", pickup="At the Bulwark, take Barov Family Fortune from Alexi and start the key chain. Pick up Plagued Hatchlings at Light's Hope Chapel. Follow the southern road from the Bulwark to Caer Darrow and see Eva before entering. To make your own key, turn in Skeletal Fragments at the Bulwark, take the mold quest, then visit Gadgetzan and Fire Plume Ridge before returning to the Bulwark.", pickupS={{"At the Bulwark, take Barov Family Fortune from Alexi and start the key chain"}, {"Pick up Plagued Hatchlings at Light's Hope Chapel"}, {"Follow the southern road from the Bulwark to Caer Darrow and see Eva before entering"}, {"To make your own key, turn in Skeletal Fragments at the Bulwark, take the mold quest, then visit Gadgetzan and Fire Plume Ridge before returning to the Bulwark"}}, tips={{k="動線", text="Entrance bridge → deed in the first hall → another past the summoning chamber → ossuary for Rattlegore and hatchlings → deed in Ras Frostwhisper's room → final deed and Krastinov downstairs → Darkmaster Gandling."}, {k="取捨", text="Do the four deeds, plague hatchlings, and the professor on one run. If someone can open the door, everyone else can skip the key materials chain."}, {k="說明", text="Five-player dungeon. Have the keyholder open the outer door. The quests after the professor, Krastinov's Bag of Horrors and Kirtonos the Herald, require repeat runs. Save them for a group that can run again.", s={{"Five-player dungeon"}, {"Have the keyholder open the outer door"}, {"The quests after the professor, Krastinov's Bag of Horrors and Kirtonos the Herald, require repeat runs"}, {"Save them for a group that can run again"}}}, {k="提醒", text="Five-player dungeon. Have the keyholder open the outer door. The quests after the professor, Krastinov's Bag of Horrors and Kirtonos the Herald, require repeat runs. Save them for a group that can run again.", s={{"Five-player dungeon"}, {"Have the keyholder open the outer door"}, {"The quests after the professor, Krastinov's Bag of Horrors and Kirtonos the Herald, require repeat runs"}, {"Save them for a group that can run again"}}}}, steps={[1]={npc="Alexi Barov", tgt="Alexi Barov", desc="Pick up early at the Bulwark once you reach level 52."}, [2]={npc="Betina Bigglezink", tgt="Betina Bigglezink", desc="Find Bettina at Light's Hope Chapel."}, [3]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", desc="Find Eva outside the door at Caer Darrow."}, [4]={npc="High Executor Derrington", tgt="High Executor Derrington", desc="Only do if you need your own Scholomance key. Skip if done at the Bulwark."}, [5]={hint="Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent."}, [6]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [7]={npc="High Executor Derrington", tgt="High Executor Derrington", desc="Already on the main route at the Bulwark in Western Plaguelands.", preText="Scarlet Diversions"}, [8]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it."}, [9]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [10]={npc="High Executor Derrington", tgt="High Executor Derrington", desc="You can turn this in early at the Bulwark.", preText="All Along the Watchtowers"}, [11]={hint="Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."}, [12]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [13]={npc="Apothecary Dithers", tgt="Apothecary Dithers", desc="Skip these three if done at the Bulwark. Take the mould if making your own key.", preText="Scholomance"}, [14]={hint="Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands."}, [15]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [16]={npc="Apothecary Dithers", tgt="Apothecary Dithers", desc="Bring two Thorium Bars before leaving Gadgetzan for Marshal's Refuge.", preText="Skeletal Fragments"}, [17]={hint="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."}, [18]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel"}, [19]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", desc="Do it with the Fire Plume Ridge quests on the Marshal's Refuge leg.", preText="Mold Rhymes With..."}, [20]={hint="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key."}, [21]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [22]={npc="Apothecary Dithers", tgt="Apothecary Dithers", desc="Do it during the Andorhal leg from the Bulwark if you have a group.", preText="Fire Plume Forged"}, [23]={hint="Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands."}, [24]={npc="Apothecary Dithers", tgt="Apothecary Dithers"}, [25]={npc="High Executor Derrington", tgt="High Executor Derrington", preText="Araj's Scarab"}, [26]={hint="Complete the quest objectives."}, [27]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [28]={text="Scholomance entrance"}, [29]={hint="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", desc="Location: Search the first hall, past the summoning room, then Ras's and Barov's rooms. Order: Southshore → Tarren Mill → Brill → Caer Darrow."}, [30]={hint="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", desc="Location: Pass the summoning room and kill hatchlings in Rattlegore's ossuary."}, [31]={hint="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", desc="Map: Krastinov (88.80, 45.50). Eva's and Lucien's remains are in the room. Location: Find Krastinov in the last six rooms. Burn both sets of remains in his room. Order: The remains are in the same room."}, [32]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", desc="Take The Bag of Horrors from Eva for next time. On a first run, just turn in."}, [33]={npc="Alexi Barov", tgt="Alexi Barov"}, [34]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}}},
    ["04-58"] = {name="Felwood", tips={{k="交通", text="At step 1, head north from Ashenvale. At the last step, go through Timbermaw Hold to Moonglade."}, {k="取捨", text="Quest A Final Blow requires another trip deep into Shadow Hold for three targets. Skip it if the solo run isn't worth the time."}, {k="取捨", text="Bring Toxic Horrors to Frostfire Hot Springs in Winterspring to turn in."}, {k="提醒", text="Below level 60? Grind Toxic Horrors and Irontree treants in Irontree Woods (around 49, 25), or catch up in Winterspring.", s={{"Below level 60?"}, {"Grind Toxic Horrors and Irontree treants in Irontree Woods (around 49, 25), or catch up in Winterspring"}}}}, danger={[1]="The braziers in Shadow Hold are scattered through narrow tunnels. Clear each section before dousing its brazier. Retrace your steps to get out."}, grind={[1]={mob="Toxic Horror", note="Normal elementals by the Irontree Woods pool. Collect Toxic Horror Droplets as you go. They're good for a small XP gap. Move on to Winterspring if the pool is busy."}, [2]={mob="Warpwood Shredder", note="Normal treants by the northern road. Switch here if the pool is busy and continue along the road to Timbermaw Hold. Watch for casters inside camp."}}, supply={[1]={npc="Innkeeper Kaylisk"}, [2]={npc="Innkeeper Kaylisk"}, [3]={npc="Brakkar"}, [4]={npc="Altsoba Ragetotem"}, [5]={npc="Bale"}, [6]={npc="Bale"}}, steps={[1]={text="Fly from Orgrimmar to Splintertree Post. Follow the main road north into Felwood and stop at Emerald Sanctuary and along the nearby road."}, [2]={npc="Maybess Riverbreeze", tgt="Maybess Riverbreeze"}, [3]={hint="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={hint="Find Eridan Bluewind in southern Felwood."}, [6]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [7]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [8]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [9]={hint="Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.", desc="Clear the passage first. Map pins may overlap inside the cave."}, [10]={hint="Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", desc="Loot Silver Claws from wolves and bears. Kill Irontree treants for the heart."}, [11]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [12]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [13]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional", desc="Return deep into Shadow Hold with a partner or if you can pull mobs one at a time."}, [14]={hint="Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.", tag="Optional", desc="The guards are close to the lord. Clear the nearby patrol first."}, [15]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional"}, [16]={npc="Trull Failbane", tgt="Trull Failbane"}, [17]={hint="Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring."}, [18]={npc="Impsy", tgt="Impsy", tag="Optional", desc="Soul Harvester is one of the reward choices.", star={"Soul Harvester", {"WARLOCK"}}}, [19]={hint="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.", tag="Optional", desc="Return to Impsy if you collected everything on the legs at stops 45, 52, and 57."}, [20]={npc="Impsy", tgt="Impsy", tag="Optional"}, [21]={npc="Impsy", tgt="Impsy", tag="Optional", desc="Group up for the elite. Turn in to Niby to unlock Inferno."}, [22]={hint="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.", tag="Optional", desc="Group up for the elite. Turn in to Niby to unlock Inferno."}, [23]={npc="Niby the Almighty", tgt="Niby the Almighty", tag="Optional", desc="Group up for the elite. Turn in to Niby to unlock Inferno."}, [24]={text="Go north into Timbermaw Hold and take the Moonglade exit."}}},
    ["04-59"] = {name="Moonglade", tips={{k="交通", text="Walk to Nighthaven at step 1. At the last step, head to Frostfire Hot Springs or Everlook, depending on your quests."}, {k="取捨", text="Do both Nighthaven NPC handoffs on one village visit."}, {k="取捨", text="Save Shards of the Felvine for a Dire Maul East run."}, {k="提醒", text="This leg is still for levels 59-60. Go straight to Frostwhisper Gorge when you're done.", s={{"This leg is still for levels 59-60"}, {"Go straight to Frostwhisper Gorge when you're done"}}}}, danger={[1]="Check Timbermaw reputation before crossing from Moonglade into Winterspring. If still Hostile, raise your reputation on the Felwood side before entering the tunnel."}, grind={[1]={mob="Rabid Shardtooth", note="After Moonglade turn-ins, cross through the hold and grind normal bears near the north mouth of Frostwhisper Gorge. They're close to 60. Avoid the elites below."}}, supply={[1]={npc="Meliri"}, [2]={npc="Dargon"}, [3]={npc="Daeolyn Summerleaf"}, [4]={npc="Faustron"}}, steps={[1]={text="Leave Timbermaw Hold and follow the main road to Nighthaven. Turn in both items from Silithus."}, [2]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [3]={hint="Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade."}, [4]={npc="Umber", tgt="Umber"}, [5]={npc="Umber", tgt="Umber"}, [6]={hint="Speak with Rabine Saturna in the village of Nighthaven, Moonglade."}, [7]={npc="Rabine Saturna", tgt="Rabine Saturna"}, [8]={npc="Umber", tgt="Umber"}, [9]={hint="Complete the quest objectives."}, [10]={npc="Umber", tgt="Umber"}, [11]={text="With The New Springs or Toxic Horrors, go back through Timbermaw Hold to the Winterspring hot springs. If you have neither and are skipping Donova, fly to Everlook from Faustron (32.09, 66.61)."}}},
    ["04-60"] = {name="Winterspring", tips={{k="交通", text="Stop at Frostfire Hot Springs first. After turning in the Everlook yeti quests, head south and grind outside the gorge's north entrance."}, {k="取捨", text="Look for lone couriers for Winterfall Runners. Exploration quest Strange Sources is on the way to the video's grind spot."}, {k="取捨", text="Quest High Chief Winterfall has an elite target. Grind normal bears instead if solo."}, {k="提醒", text="Below level 60? Follow the video and grind bears north of Frostwhisper Gorge. QuestieDB lists normal Crazed Shardtooth spawns around 57.63, 70.83 and 66.68, 70.57. Avoid elites at the bottom.", s={{"Below level 60?"}, {"Follow the video and grind bears north of Frostwhisper Gorge"}, {"QuestieDB lists normal Crazed Shardtooth spawns around 57.63, 70.83 and 66.68, 70.57"}, {"Avoid elites at the bottom"}}}}, danger={[1]="Level 59-60 elite Frostmaul giants roam Frostwhisper Gorge. Pull bears one at a time along the slope at the north entrance and don't drag them into the gorge.", [2]="Level 57-60 elite Hederine Slayers roam Darkwhisper Gorge. Trigger Strange Sources at the north entrance, then return to the road."}, grind={[1]={mob="Rabid Shardtooth", note="Normal melee bears west of the north mouth of Frostwhisper Gorge. Pull singles and skin them. Rotate east after clearing. Avoid the elites below."}, [2]={mob="Rabid Shardtooth", note="Normal bears east of the gorge's north mouth. Switch here if the west side is busy or hasn't respawned. Pull uphill to the road away from the elites."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Innkeeper Vizzie"}, [3]={npc="Nixxrak"}, [4]={npc="Innkeeper Vizzie"}, [5]={npc="Wixxrak"}}, steps={[1]={text="From Timbermaw Hold, see Donova at the hot springs. Turn in the Marshal's Refuge and Irontree Woods quests, then head to Everlook and the southern valley. If you flew straight to Everlook and are skipping the hot springs quests, start with Umi."}, [2]={hint="Travel to Winterspring and speak with Donova Snowden."}, [3]={npc="Donova Snowden", tgt="Donova Snowden"}, [4]={npc="Donova Snowden", tgt="Donova Snowden"}, [5]={npc="Donova Snowden", tgt="Donova Snowden"}, [6]={npc="Donova Snowden", tgt="Donova Snowden"}, [7]={hint="Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.", desc="Find a lone courier near Timbermaw's entrance or the Deadwood cauldron."}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={npc="Donova Snowden", tgt="Donova Snowden", tag="Optional", desc="Group up for the level-59 elite and nearby furbolgs."}, [10]={hint="Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.", tag="Optional", desc="Clear the outer mobs first. Follow up if the letter drops and you need the chain."}, [11]={npc="Crudely-written Log", npcObj=true, tag="Optional", desc="Right-click the journal if High Chief Winterfall drops it."}, [12]={hint="Bring the Crudely-written Log to Donova Snowden in Winterspring.", tag="Optional"}, [13]={npc="Donova Snowden", tgt="Donova Snowden", tag="Optional"}, [14]={npc="Donova Snowden", tgt="Donova Snowden", tag="Optional"}, [15]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [16]={hint="Follow Donova Snowden's instructions, then report back.", desc="Stop at the gorge entrance. Avoid the elites deeper inside."}, [17]={npc="Donova Snowden", tgt="Donova Snowden"}, [18]={text="Below level 60? Grind normal Crazed Shardtooth bears outside the gorge's north entrance."}}},
    ["05-d34"] = {name="Upper Blackrock Spire", entrance="Searing Gorge (1427), 34.80, 85.30. Marks the approach to Blackrock Mountain.", pickup="At level 55, fly from Everlook to Orgrimmar and take the zeppelin to the Eastern Kingdoms. Do Lower Blackrock Spire quest Warlord's Command, then take Eitrigg's Wisdom from Warlord Goretooth in Kargath. After Ratchet, see Eitrigg and Thrall in the Valley of Wisdom and keep For The Horde!. At level 57, take Vivian Lagrave and the Darkstone Tablet in the Undercity Apothecarium, then fly to Kargath to turn in to Vivian and take The Darkstone Tablet. Have at least one party member finish Seal of Ascension → Seal of Ascension and bring the seal. If someone already has it, go straight to Upper Blackrock Spire.", pickupS={{"At level 55, fly from Everlook to Orgrimmar and take the zeppelin to the Eastern Kingdoms"}, {"Do Lower Blackrock Spire quest Warlord's Command, then take Eitrigg's Wisdom from Warlord Goretooth in Kargath"}, {"After Ratchet, see Eitrigg and Thrall in the Valley of Wisdom and keep For The Horde!"}, {"At level 57, take Vivian Lagrave and the Darkstone Tablet in the Undercity Apothecarium, then fly to Kargath to turn in to Vivian and take The Darkstone Tablet"}, {"Have at least one party member finish Seal of Ascension → Seal of Ascension and bring the seal"}, {"If someone already has it, go straight to Upper Blackrock Spire"}}, tips={{k="動線", text="Clear the seven runes → Pyroguard Emberseer → tablet in the rookery → Blackhand Hall → Rend and Gyth in the arena → forge, with The Beast optional → General Drakkisath at the throne and his brand behind him."}, {k="取捨", text="Pick up the Kargath and Orgrimmar quests first. Do Blackhand's Command only if you need the raid attunement."}, {k="說明", text="Use the shared entrance with Lower Blackrock Spire. Go up to the left to find the locked upper door. Bring someone with the Seal of Ascension. Launch guides show the gate order. If the jumps block your path, use the outer upper walkway.", s={{"Use the shared entrance with Lower Blackrock Spire"}, {"Go up to the left to find the locked upper door"}, {"Bring someone with the Seal of Ascension"}, {"Launch guides show the gate order"}, {"If the jumps block your path, use the outer upper walkway"}}}}, steps={[1]={npc="Warlord Goretooth", tgt="Warlord Goretooth", desc="If no quest window opens, talk to the NPC and use the orders from your bags."}, [2]={hint="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", desc="The document can move. Check each of the first three rooms as you reach it. Map: Omokk 35.10,55.30; Voone 52.50,54.90; Wyrmthalak 57.80,60.50. Check each room."}, [3]={npc="Warlord Goretooth", tgt="Warlord Goretooth"}, [4]={npc="Warlord Goretooth", tgt="Warlord Goretooth", preText="Warlord's Command"}, [5]={hint="Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall."}, [6]={npc="Thrall", tgt="Thrall"}, [7]={npc="Thrall", tgt="Thrall", preText="Eitrigg's Wisdom"}, [8]={npc="Apothecary Zinge", tgt="Apothecary Zinge", tag="Optional", desc="Pick up at 57 in Undercity's Apothecarium. Skip this lead if you have The Darkstone Tablet."}, [9]={hint="Speak with Shadowmage Vivian Lagrave.", tag="Optional"}, [10]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave", tag="Optional"}, [11]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave", desc="Pick up from Vivian if offered. Otherwise start with Vivian Lagrave and the Darkstone Tablet in Undercity."}, [12]={npc="Blackhand's Command", npcObj=true, tag="Optional", desc="Loot and use the quartermaster's letter outside Blackrock Spire for BWL access."}, [13]={text="Upper Blackrock Spire entrance"}, [14]={hint="Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", desc="Upper Blackrock Spire map 3: Warchief Rend Blackhand (48.60, 25.60). Location: Pass the rookery to Blackhand Hall. Enter the arena north gate to trigger Rend. Order: Take the tablet from the hatchery before the arena."}, [15]={hint="Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", desc="Stay on the path and avoid the eggs. Broken eggs spawn whelps. Location: After Pyroguard Emberseer, enter the rookery. Check the floor by the wall. Order: Do this before the arena in step 13."}, [16]={hint="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.", tag="Optional", desc="UBRS map 3: General Drakkisath (34.80, 50.10). The Brand is behind him. Location: Leave the arena's south gate and pass the forge. The brand is behind the boss. Order: Kill Drakkisath, then click the Brand behind him."}, [17]={npc="Drakkisath's Brand", npcObj=true, tag="Optional, Unverified"}, [18]={npc="Thrall", tgt="Thrall"}, [19]={npc="Shadowmage Vivian Lagrave", tgt="Shadowmage Vivian Lagrave"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="Winterspring 66.60, 84.40", pickup="Take Beneath Nordrassil from Jediga in Valormok and Claws That Rend, Tusks that Gore from Ogtinc. Return to Azshara for Ekkal at level 55. When you return to Kalimdor through Ratchet, fly to Elder Rise in Thunder Bluff, turn in Jediga's letter, and take Get to the Roots of It. Visit Muln Earthfury in Mulgore. Fly to Valormok and enter via the Azshara tunnel. Save Get to the Roots of It and Blackmaw Magic for the next Thunder Bluff and Mulgore visit.", pickupS={{"Take Beneath Nordrassil from Jediga in Valormok and Claws That Rend, Tusks that Gore from Ogtinc"}, {"Return to Azshara for Ekkal at level 55"}, {"When you return to Kalimdor through Ratchet, fly to Elder Rise in Thunder Bluff, turn in Jediga's letter, and take Get to the Roots of It"}, {"Visit Muln Earthfury in Mulgore"}, {"Fly to Valormok and enter via the Azshara tunnel"}, {"Save Get to the Roots of It and Blackmaw Magic for the next Thunder Bluff and Mulgore visit"}}, tips={{k="動線", text="Loot Blackmaw Pouches in the entrance tunnels → gather Nordrassil Rootcaps underground → branches for Withermaw and Bonesnout the Unbroken → Elder Shaman Bloodmane for the ritual totem. Exact forks and boss order are unconfirmed."}, {k="取捨", text="Do the Ogtinc and Ruins of Eldarath preparations as you pass. Complete the Horde rootcap chain in one Thunder Bluff visit."}, {k="說明", text="The portal pin appears on the Winterspring map. Enter the furbolg tunnel in Azshara (38.70, 33.40) and follow it to the portal. Don't look for it on the Winterspring surface.", s={{"The portal pin appears on the Winterspring map"}, {"Enter the furbolg tunnel in Azshara (38.70, 33.40) and follow it to the portal"}, {"Don't look for it on the Winterspring surface"}}}}, steps={[1]={npc="Jediga", tgt="Jediga", tag="Unverified"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff.", tag="Unverified"}, [3]={npc="Nara Wildmane", tgt="Nara Wildmane", tag="Unverified"}, [4]={npc="Nara Wildmane", tgt="Nara Wildmane", tag="Unverified", preText="Beneath Nordrassil"}, [5]={npc="Ogtinc", tgt="Ogtinc"}, [6]={npc="Alaana Stormwalker", tgt="Muln Earthfury", desc="Use the Mulgore map pin on the path to Thunder Bluff."}, [7]={npc="Ekkal", tgt="Ekkal", desc="Ruins of Eldarath, Azshara. Minimum pickup level is from DungeonsForever."}, [8]={text="Blackmaw Hold entrance"}, [9]={hint="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff.", tag="Unverified", desc="Location: Follow the passages to the underground roots and gather rootcaps there."}, [10]={hint="Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc, in Azshara.", tag="Target: Giant Bear Withermaw / Bonesnout the Unbroken, Unverified", desc="Location: Find Withermaw and Bonesnout the Unbroken in the tunnels. Fork unconfirmed."}, [11]={hint="Recover a Blackmaw Ritual Totem from Blackmaw Hold.", tag="Unverified", desc="Location: Follow the boss route to Elder Shaman Bloodmane and loot his ritual totem."}, [12]={hint="Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara.", desc="Location: Clear corrupted Blackmaw furbolgs in the living quarters and loot pouches."}, [13]={npc="Ogtinc", tgt="Ogtinc"}, [14]={npc="Ekkal", tgt="Ekkal"}, [15]={npc="Nara Wildmane"}, [16]={desc="QuestieDB lists Muln Earthfury in Mulgore. The turn-in NPC and coords are unconfirmed."}}},
  },
  quests = {
    [2] = {n="Sharptalon's Claw", d="Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale."},
    [10] = {n="The Scrimshank Redemption", d="Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", objs={"Scrimshank's Surveying Gear"}},
    [23] = {n="Ursangous's Paw", d="Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale."},
    [24] = {n="Shadumbra's Head", d="Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale."},
    [25] = {n="Stonetalon Standstill", d="Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.\nScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.\nReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.", tgo={{"Befouled Water Elemental"}}},
    [27] = {n="A Lesson to Learn", d="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."},
    [28] = {n="Trial of the Lake", d="Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", objs={"Shrine Of Remulos"}},
    [30] = {n="Trial of the Sea Lion", d="Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", objs={"Shrine Of Remulos"}},
    [31] = {n="Aquatic Form", d="Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion."},
    [32] = {n="Rise of the Silithid", d="Take the report to Zilzibin Drumlore in Orgrimmar."},
    [63] = {n="Call of Water", d="Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", tgo={{"Corrupt Minor Manifestation of Water"}}},
    [82] = {n="Noxious Lair Investigation", d="Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", tgo={{"Centipaar Wasp", "Centipaar Stinger", "Centipaar Swarmer"}}},
    [96] = {n="Call of Water", d="Bring the Shard of Water to Islen Waterseer in the Barrens."},
    [99] = {n="Arugal's Folly", d="Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.", tgo={{"Pyrewood Watcher", "Moonrage Watcher", "Moonrage Sentry"}}},
    [100] = {n="Call of Water", d="Speak to the Minor Manifestation of Water in Silverpine Forest."},
    [110] = {n="Insect Part Analysis", d="Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts."},
    [113] = {n="Insect Part Analysis", d="Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested."},
