    [2283] = {n="Necklace Recovery", d="Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", tgo={{"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}}},
    [2284] = {n="Necklace Recovery, Take 2", d="Find a clue as to the gems' whereabouts in the depths of Uldaman."},
    [2318] = {n="Translating the Journal", d="Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."},
    [2338] = {n="Translating the Journal", d="Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."},
    [2339] = {n="Find the Gems and Power Source", d="Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", tgo={{}, {"Grimlok"}, {}, {"Archaedas"}}, objs={"Shadowforge Cache", "Conspicuous Urn"}},
    [2340] = {n="Deliver the Gems", d="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."},
    [2341] = {n="Necklace Recovery, Take 3", d="Visit Jarkal Mossmeld in Kargath to see if he was successful."},
    [2342] = {n="Reclaimed Treasures", d="Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", objs={"Garrett Family Chest"}},
    [2378] = {n="Find the Shattered Hand", d="Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."},
    [2379] = {n="Zando'zan", d="Speak with Zando'zan at the Cleft of Shadow."},
    [2381] = {n="Plundering the Plunderers", d="Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!", tgo={{"Polly"}}},
    [2382] = {n="Wrenix of Ratchet", d="Travel to Ratchet and speak with Wrenix the Wretched."},
    [2383] = {n="Simple Parchment", d="Read the Simple Parchment and speak to Frang in the Valley of Trials."},
    [2418] = {n="Power Stones", d="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", tgo={{"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}, {"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}}},
    [2458] = {n="Deep Cover", d="Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."},
    [2460] = {n="The Shattered Salute", d="Perform the Shattered Salute on Shenthul.", tgo={{"Shenthul"}}},
    [2478] = {n="Mission: Possible But Not Probable", d="Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", tgo={{"Mutated Venture Co. Drone"}, {"Venture Co. Lookout"}, {"Venture Co. Patroller"}, {"Grand Foreman Puzik Gallywix"}, {"Foreman Silixiz"}, {}}, objs={"Gallywix's Lockbox"}},
    [2479] = {n="Hinott's Assistance", d="Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"},
    [2480] = {n="Hinott's Assistance", d="Wait for Serge Hinott to complete the cure."},
    [2521] = {n="To Serve Kum'isha", d="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", tgo={{"Dreadmaul Ogre", "Dreadmaul Ogre Mage", "Dreadmaul Brute"}}},
    [2581] = {n="Snickerfang Jowls", d="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", tgo={{"Starving Snickerfang", "Snickerfang Hyena", "Ravage"}, {"Ashmane Boar", "Helboar", "Grunter"}, {"Scorpok Stinger", "Clack the Reaver"}}},
    [2583] = {n="A Boar's Vitality", d="Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", tgo={{"Ashmane Boar", "Helboar", "Grunter"}, {"Scorpok Stinger", "Clack the Reaver"}, {"Redstone Basilisk", "Redstone Crystalhide", "Deatheye"}}},
    [2585] = {n="The Decisive Striker", d="Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", tgo={{"Scorpok Stinger", "Clack the Reaver"}, {"Black Slayer", "Bonepicker"}, {"Ashmane Boar", "Helboar", "Grunter"}}},
    [2601] = {n="The Basilisk's Bite", d="Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", tgo={{"Redstone Basilisk", "Redstone Crystalhide", "Deatheye"}, {"Black Slayer", "Bonepicker"}}},
    [2603] = {n="Vulture's Vigor", d="Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", tgo={{"Black Slayer", "Bonepicker"}, {"Starving Snickerfang", "Snickerfang Hyena", "Ravage"}}},
    [2605] = {n="The Thirsty Goblin", d="Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", tgo={{"Thistleshrub Dew Collector"}}},
    [2606] = {n="In Good Taste", d="Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan."},
    [2641] = {n="Sprinkle's Secret Ingredient", d="Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", objs={"Violet Tragan"}},
    [2661] = {n="Delivery for Marin", d="Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan."},
    [2662] = {n="Noggenfogger Elixir", d="Marin Noggenfogger wants you to speak to him again after he creates his elixir."},
    [2741] = {n="The Super Egg-O-Matic", d="Use/collect: Hippogryph Egg", objs={"Hippogryph Egg"}},
    [2766] = {n="Find OOX-22/FE!", d="Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale."},
    [2767] = {n="Rescue OOX-22/FE!", d="Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay."},
    [2768] = {n="Divino-matic Rod", d="Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", tgo={{"Sergeant Bly"}}, star={"Masons Fraternity Ring", {"ROGUE", "HUNTER", "DRUID"}}},
    [2770] = {n="Gahz'rilla", d="Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", tgo={{"Gahz'rilla"}}},
    [2781] = {n="WANTED: Caliph Scorpidsting", d="Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", tgo={{"Caliph Scorpidsting"}}},
    [2822] = {n="The Mark of Quality", d="Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", tgo={{"Feral Scar Yeti", "Hulking Feral Scar", "Enraged Feral Scar"}}},
    [2841] = {n="Rig Wars", d="Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", tgo={{}, {"Mekgineer Thermaplugg"}}, objs={"Thermaplugg's Safe"}},
    [2842] = {n="Chief Engineer Scooty", d="Speak with Scooty in Booty Bay."},
    [2843] = {n="Gnomer-gooooone!", d="Wait for Scooty to calibrate the Goblin Transponder.", tgo={{"Scooty"}}},
    [2846] = {n="Tiara of the Deep", d="Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", tgo={{"Hydromancer Velratha"}}},
    [2862] = {n="War on the Woodpaw", d="Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", tgo={{"Woodpaw Mongrel", "Woodpaw Trapper", "Woodpaw Brute"}}},
    [2863] = {n="Alpha Strike", d="Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", tgo={{"Woodpaw Alpha"}}},
    [2865] = {n="Scarab Shells", d="Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", tgo={{"Scarab"}}},
    [2873] = {n="Stoley's Shipment", d="Bring Stoley's Shipment to Stoley in Steamwheedle Port.", objs={"Stolen Cargo"}},
    [2874] = {n="Deliver to MacKinley", d="Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay."},
    [2875] = {n="WANTED: Andre Firebeard", d="Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.", tgo={{"Andre Firebeard"}}},
    [2876] = {n="Ship Schedules", d="Report the Ship Schedules to an authority in Steamwheedle Port."},
    [2902] = {n="Woodpaw Investigation", d="Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache."},
    [2903] = {n="The Battle Plans", d="Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache."},
    [2904] = {n="A Fine Mess", d="Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay."},
    [2945] = {n="Grime-Encrusted Ring", d="Figure out a way to remove the grime from the Grime-Encrusted Ring."},
    [2949] = {n="Return of the Ring", d="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."},
    [2973] = {n="A New Cloak's Sheen", d="Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", tgo={{"Sprite Darter", "Captured Sprite Darter"}}},
    [2974] = {n="A Grim Discovery", d="Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", tgo={{"Grimtotem Raider", "Grimtotem Naturalist", "Grimtotem Shaman"}}},
    [2975] = {n="The Ogres of Feralas", d="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.", tgo={{"Gordunni Ogre"}, {"Gordunni Ogre Mage"}, {"Gordunni Brute"}}},
    [2976] = {n="A Grim Discovery", d="Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar."},
    [2978] = {n="The Gordunni Scroll", d="Bring the Gordunni Scroll to Rok Orhan in Camp Mojache."},
    [2979] = {n="Dark Ceremony", d="Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.", tgo={{"Gordunni Mage-Lord"}}},
    [2980] = {n="The Ogres of Feralas", d="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.", tgo={{"Gordunni Shaman"}, {"Gordunni Warlock"}, {"Gordunni Mauler"}}},
    [2983] = {n="Call of Fire", d="Find Kranal Fiss in the Barrens."},
    [2984] = {n="Call of Fire", d="Find Kranal Fiss in the Barrens."},
    [2987] = {n="Gordunni Cobalt", d="Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", objs={"Gordunni Dirt Mound"}},
    [2996] = {n="Seeking Strahad", d="Speak to Strahad Farsan in Ratchet."},
    [3001] = {n="Seeking Strahad", d="Find Strahad Farsan in Ratchet."},
    [3002] = {n="The Gordunni Orb", d="Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar."},
    [3042] = {n="Troll Temper", d="Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", tgo={{"Sandfury Shadowcaster", "Sandfury Blood Drinker", "Sandfury Witch Doctor"}}},
    [3062] = {n="Dark Heart", d="Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", tgo={{"Edana Hatetalon"}}},
    [3063] = {n="Vengeance on the Northspring", d="Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", tgo={{"Northspring Harpy"}, {"Northspring Roguefeather"}, {"Northspring Slayer"}, {"Northspring Windcaller"}}},
    [3065] = {n="Simple Tablet", d="Read the Simple Tablet and speak to Frang in the Valley of Trials."},
    [3082] = {n="Etched Tablet", d="Speak to Jen'shan in the Valley of Trials."},
