    [3086] = {n="Glyphic Tablet", d="Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
    [3087] = {n="Etched Parchment", d="Read the Etched Parchment and speak to Jen'shan in the Valley of Trials."},
