    [3089] = {n="Rune-Inscribed Parchment", d="Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials."},
    [3090] = {n="Tainted Parchment", d="Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials."},
    [3091] = {n="Simple Note", d="Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache."},
    [3092] = {n="Etched Note", d="Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa."},
    [3093] = {n="Rune-Inscribed Note", d="Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache."},
    [3094] = {n="Verdant Note", d="Read the Verdant Note and speak to Gart Mistrunner in Camp Narache."},
    [3095] = {n="Simple Scroll", d="Read the Simple Scroll and speak to Dannal Stern in Deathknell."},
    [3096] = {n="Encrypted Scroll", d="Read the Encrypted Scroll and speak to David Trias in Deathknell."},
    [3097] = {n="Hallowed Scroll", d="Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell."},
    [3098] = {n="Glyphic Scroll", d="Read the Glyphic Scroll and speak to Isabella in the church in Deathknell."},
    [3099] = {n="Tainted Scroll", d="Read the Tainted Scroll and speak to Maximillion in Deathknell."},
    [3121] = {n="A Strange Request", d="Take the Shrunken Head to Neeru Fireblade in Orgrimmar."},
    [3122] = {n="Return to Witch Doctor Uzer'i", d="Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas."},
    [3123] = {n="Testing the Vessel", d="Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.\nBring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.", tgo={{"Vicious Owlbeast", "Primitive Owlbeast", "Savage Owlbeast"}}},
    [3124] = {n="Hippogryph Muisek", d="Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", tgo={{"Frayfeather Hippogryph", "Frayfeather Stagwing", "Frayfeather Skystormer"}}},
    [3125] = {n="Faerie Dragon Muisek", d="Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", tgo={{"Sprite Dragon", "Sprite Darter"}}},
    [3126] = {n="Treant Muisek", d="Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", tgo={{"Wandering Forest Walker"}}},
    [3127] = {n="Mountain Giant Muisek", d="Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", tgo={{"Land Walker", "Cliff Giant", "Zapped Land Walker"}}},
    [3128] = {n="Natural Materials", d="Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", tgo={{"Wandering Forest Walker"}, {"Sprite Dragon", "Sprite Darter", "Land Walker"}, {"Vicious Owlbeast", "Primitive Owlbeast", "Savage Owlbeast"}, {"Vicious Owlbeast", "Primitive Owlbeast", "Savage Owlbeast"}}},
    [3129] = {n="Weapons of Spirit", d="Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons."},
    [3161] = {n="Gahz'ridian", d="Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", objs={"Gahz'ridian"}},
    [3221] = {n="Speak with Renferrel", d="Speak with Apothecary Renferrel at the Sepulcher."},
    [3261] = {n="Jorn Skyseer", d="Speak with Jorn Skyseer at Camp Taurajo."},
    [3281] = {n="Stolen Silver", d="Bring the Stolen Silver to Gazrog in the Crossroads.", objs={"Stolen Silver"}},
    [3301] = {n="Mura Runetotem", d="Speak with Mura Runetotem in the Sepulcher."},
    [3341] = {n="Bring the End", d="Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", tgo={{"Amnennar the Coldbringer"}}},
    [3362] = {n="Thistleshrub Valley", d="Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", tgo={{"Gnarled Thistleshrub"}, {"Thistleshrub Rootshaper"}}},
    [3369] = {n="In Nightmares", d="Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise."},
